        #region Providers

        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult ListActiveProviders()
        {
            List<RateSettingPackage.ProviderPackage> providers = null;
            List<string> list = new List<string>
            {
                "Provider Id (RS),Provider Id (ARUM),Provider Number,Provider Name (RS),Provider Name (ARUM)"
            };

            try
            {
                // Get active providers
                providers = GetActiveProviders(null);

                using (ProjectSpecificDbContext db = new ProjectSpecificDbContext(Functions.DatabaseConnection))
                {
                    List<RateProvider> rateProviders = db.RateProviders.AsNoTracking().ToList();

                    foreach (RateSettingPackage.ProviderPackage provider in providers)
                    {
                        List<RateProvider> matchProviders =
                            rateProviders.Where(x => x.ProviderNumber == provider.ProviderNumber).ToList();
                        if (matchProviders.Count == 0)
                        {
                            list.Add(
                                $",{provider.ProviderId},\"{provider.ProviderNumber}\",,\"{provider.ProviderName}\"");
                        }
                        else if (matchProviders.Count > 1 || matchProviders.First().ProviderId != provider.ProviderId)
                        {
                            foreach (RateProvider p in matchProviders)
                            {
                                list.Add(
                                    $"{p.ProviderId},{provider.ProviderId},\"{provider.ProviderNumber}\",\"{p.ProviderName}\",\"{provider.ProviderName}\"");
                            }
                        }
                    }
                }

                if (list.Count > 1)
                {
                    System.IO.File.WriteAllLines(
                        Path.Combine(Path.GetTempPath(),
                            $"OHFI Provider Mismatches {DateTime.Now.ToString("yyyy-MM-dd")}.csv"), list.ToArray());
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    Message = e.Message
                }, JsonRequestBehavior.AllowGet);
            }

            return Json(new
            {
                Success = true,
                Data = list.ToArray()
            }, JsonRequestBehavior.AllowGet);
        }

        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult Providers()
        {
            ProviderViewModel providerViewModel = GetProviderViewModel();
            return PartialView("Provider/_Providers", providerViewModel);
        }

        [HttpPost]
        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult Providers(ProviderViewModel um)
        {
            ProviderViewModel providerViewModel = GetProviderViewModel(um);
            return Json(providerViewModel, JsonRequestBehavior.AllowGet);
        }

        private ProviderViewModel GetProviderViewModel(ProviderViewModel um = null)
        {
            ProviderViewModel providerViewModel = new ProviderViewModel();
            providerViewModel.ProviderInfos = new List<ProviderInfoViewModel>();
            List<SelectListItem> items = new List<SelectListItem>
            {
                new SelectListItem { Text = "Active", Value = "2", Selected = ((um?.ProviderType ?? "2") == "2") },
                new SelectListItem { Text = "All", Value = "1", Selected = ((um?.ProviderType ?? "") == "1") },
                new SelectListItem { Text = "Closed", Value = "3", Selected = ((um?.ProviderType ?? "") == "3") }
            };

            bool? activeState = true;
            if (um != null)
            {
                switch (um.ProviderType)
                {
                    case "2":
                        activeState = true;
                        break;
                    case "3":
                        activeState = false;
                        break;
                    case "1":
                    default:
                        activeState = null;
                        break;
                }
            }

            providerViewModel.ProviderFilterType = items;
            // TODO - Needs to be from the the DB
            ARUMApplicationServiceProxy _arumApplicationClient =
                ARUMApplication.GetARUMApplicationProxy(RetrieveSession.Classification);
            IAllProviders providers = _arumApplicationClient.GetAllActiveProvidersWithOptions(
                RetrieveSession.Classification.ARUMToken,
                false, true, false, true, false, false, false, "ratesetting.providers");

            var providersViewModel = providers.lstProviders
                .Where(x => RateProviderBL.SelectByProviderEffectiveDate(activeState, x.EffectiveDates))
                .Select(x => new ProviderInfoViewModel
                {
                    ProviderNumber = ClientMapping.MapInternalIdToClientId(x.ProviderID.ToString(), "provider"),
                    ProviderName = x.Name,
                    ProviderMedicaidNumber = x.Identifiers.FirstOrDefault(i => i.Type == "MCAID")?.Value ?? "NA",
                    ProviderMedicareNumber = x.Identifiers.FirstOrDefault(i => i.Type == "MEDICAREID")?.Value ?? "NA",
                    NPINumber = x.Identifiers.FirstOrDefault(i => i.Type == "NPI")?.Value ?? "NA",
                    EffectiveDate = x.HasEffectiveDates
                        ? x.EffectiveDates.OrderByDescending(ED => ED.DateEffective)?.Select(i => i.DateEffective)
                            .FirstOrDefault()
                        : null,
                    ClosureDate = x.HasEffectiveDates
                        ? x.EffectiveDates.OrderByDescending(ED => ED.DateEffective)?.Select(i => i.EndDate)
                            ?.FirstOrDefault()
                        : null
                })
                .OrderBy(p => p.ProviderName)
                .ToList();

            providerViewModel.ProviderInfos = providersViewModel;
            providerViewModel.TimeZoneOffset = TimeZoneInfo.Local.GetUtcOffset(DateTime.UtcNow).Hours;

            providers.lstProviders.Clear();

            return providerViewModel;
        }

        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult ProviderDetails(string id)
        {
            string provIdString = ClientMapping.GetInternalIdFromClientId(id, "provider");
            int provId = 0;
            if (!int.TryParse(provIdString, out provId))
            {
                return PartialView(new ProviderInfoViewModel());
            }

            MSLC.ProviderProxy.Interfaces.IArumDetailedProvider arum_provider =
                _providerServiceProxy.GetProviderInfoByARUMProviderID(RetrieveSession.Classification.ARUMToken, provId,
                    "Rate/Provider");

            ProviderInfoViewModel providerViewModel = new ProviderInfoViewModel
            {
                ProviderNumber = id, // this is still a mapped value.
                ProviderName = arum_provider.Provider.Name
            };

            Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT] = provId;
            providerViewModel.NPINumber = arum_provider.Identifiers.FirstOrDefault(i => i.Type == "NPI") != null
                ? arum_provider.Identifiers.FirstOrDefault(i => i.Type == "NPI").Value
                : string.Empty;

            return PartialView(providerViewModel);
        }

