        #region Provider General Information

        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult ProviderGeneralInformation()
        {
            ProviderGeneralInformationViewModel generalInformationViewModel = new ProviderGeneralInformationViewModel();
            IAddressCodeFunctions addressCodeFunctions =
                CostReportBL.GetInstanceAddressCodeFunctions(RetrieveSession.Classification);

            if (Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT] != null)
            {
                int providerID = (int)Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT];
                string provIdMapped = ClientMapping.MapInternalIdToClientId(providerID.ToString(), "provider");
                string countyCode = string.Empty;
                string county = string.Empty;
                MSLC.ProviderProxy.Interfaces.IArumDetailedProvider arum_provider =
                    _providerServiceProxy.GetProviderInfoByARUMProviderID(RetrieveSession.Classification.ARUMToken,
                        providerID, "Rate/Provider");
                //  TODO - Re-visit after NFOFI-2054 is complete to Make changes the way the EffectiveDates are read.

                ProviderHelper.SynchronizeProviderWithARUM(RetrieveSession.Classification.ARUMToken, arum_provider);

                if (arum_provider.EffectiveDates != null && arum_provider.EffectiveDates.Count > 0)
                {
                    var effectiveDateRecs =
                        arum_provider.EffectiveDates.OrderByDescending(ED => ED.EffectiveDate).ToList();
                    DateTime? effectiveDate = effectiveDateRecs.Select(x => x.EffectiveDate).FirstOrDefault();
                    DateTime? endDate = effectiveDateRecs.Select(x => x.EndDate).FirstOrDefault();
                    generalInformationViewModel.EffectiveDate =
                        effectiveDate != null ? effectiveDate.Value.ToShortDateString() : "";
                    generalInformationViewModel.ClosureDate = endDate != null ? endDate.Value.ToShortDateString() : "";
                    countyCode = effectiveDateRecs.Select(x => x.County).FirstOrDefault();
                    countyCode = int.TryParse(countyCode, out int val) ? val.ToString() : string.Empty;
                }

                if (arum_provider != null)
                {
                    #region Provider General Info

                    generalInformationViewModel.Name = arum_provider.Provider.Name;

                    generalInformationViewModel.NPINumber =
                        arum_provider.Identifiers.FirstOrDefault(i => i.Type == "NPI")?.Value ?? string.Empty;
                    generalInformationViewModel.MedicareID =
                        arum_provider.Identifiers.FirstOrDefault(i => i.Type == "MEDICAREID")?.Value ?? string.Empty;
                    generalInformationViewModel.MedicaidID =
                        arum_provider.Identifiers.FirstOrDefault(i => i.Type == "MCAID")?.Value ?? string.Empty;
                    generalInformationViewModel.FederalTaxId = arum_provider.Identifiers
                                                                   .FirstOrDefault(i =>
                                                                       i.Type.ToUpper() == "FEDTAXID" ||
                                                                       i.Type.ToUpper() == "FEDERAL TAX ID NUMBER" &&
                                                                       i.Value != string.Empty)?.Value.FormatUSTaxId();
                    generalInformationViewModel.FacilityType = arum_provider.ProviderAttributes
                        .FirstOrDefault(i => i.AttributeKey == "PROV_TYPE_CDE_DESC")?.AttributeValue ?? string.Empty;
                    generalInformationViewModel.FacilitySubType = arum_provider.ProviderAttributes
                        .FirstOrDefault(i => i.AttributeKey == "PROV_SPEC_CDE_DESC")?.AttributeValue ?? string.Empty;
                    generalInformationViewModel.RiskStatus =
                        arum_provider.ProviderAttributes.FirstOrDefault(i => i.AttributeKey == "REVIEW_TYPE_DESC")
                            ?.AttributeValue ?? string.Empty;
                    generalInformationViewModel.Ownership =
                        arum_provider.ProviderAttributes
                            .FirstOrDefault(i => i.AttributeKey == "PROV_OWNERSHIP_TYPE_DESC")?.AttributeValue ??
                        string.Empty;

                    #endregion

                    #region Get PeerGroup Info, County & Beds Count

                    if (!string.IsNullOrWhiteSpace(countyCode))
                    {
                        county = addressCodeFunctions.GetCountyNameByCountyCode(Convert.ToInt32(countyCode));
                    }

                    int licensedBeds = RateBL.GetLastLicensedBeds(providerID);
                    int certifiedBeds = RateBL.GetLastCertifiedBedCount(providerID);
                    List<DatabaseLookupValue> dbLookups =
                        DatabaseLookupVariableBL.GetAnnualRED(AnnualRateSettingEnum.PeerGroupFiveA);

                    generalInformationViewModel.County = $"{county} ({countyCode})";
                    generalInformationViewModel.CertifiedBeds = certifiedBeds;
                    generalInformationViewModel.LicensedBeds = licensedBeds;

                    // Get Calculation data.
                    var details = RateBL.GetProviderGeneralInfoDetails(providerID);

                    switch (SimplifiedType)
                    {
                        case "NF":
                            if (!string.IsNullOrWhiteSpace(details.PeerGroup))
                            {
                                generalInformationViewModel.AncillaryPeerGroup = details.PeerGroup;
                                generalInformationViewModel.CapitalPeerGroup = details.PeerGroup;
                            }
                            else
                            {
                                if (!string.IsNullOrWhiteSpace(county))
                                {
                                    // Get the peer groups
                                    generalInformationViewModel.AncillaryPeerGroup =
                                        RateBL.GetNfPeerGroupAncillaryByCounty("OH", county, licensedBeds);
                                    generalInformationViewModel.CapitalPeerGroup =
                                        generalInformationViewModel
                                            .AncillaryPeerGroup; // Same value - why call twice? :)
                                }
                            }

                            if (!string.IsNullOrWhiteSpace(details.DirectCarePeerGroup))
                            {
                                generalInformationViewModel.DirectCarePeerGroup = details.DirectCarePeerGroup;
                            }
                            else
                            {
                                if (!string.IsNullOrWhiteSpace(county))
                                {
                                    // Get the peer groups
                                    generalInformationViewModel.DirectCarePeerGroup =
                                        RateBL.GetNfPeerGroupDirectCareByCounty("OH", county, licensedBeds);
                                }
                            }

                            break;

                        case "ICF":
                            if (!string.IsNullOrWhiteSpace(details.PeerGroup))
                            {
                                generalInformationViewModel.IndirectCarePeerGroup = details.PeerGroup;
                            }
                            else
                            {
                                // Get the peer groups
                                generalInformationViewModel.IndirectCarePeerGroup =
                                    RateBL.GetIcfPeerGroup(certifiedBeds, dbLookups, providerID.ToString());
                            }

                            if (!string.IsNullOrWhiteSpace(details.DirectCarePeerGroup))
                            {
                                generalInformationViewModel.DirectCarePeerGroup = details.DirectCarePeerGroup;
                            }
                            else
                            {
                                // Get the peer groups
                                generalInformationViewModel.DirectCarePeerGroup =
                                    RateBL.GetIcfPeerGroup(certifiedBeds, dbLookups, providerID.ToString());
                            }

                            break;
                    }

                    #endregion

                    #region Get ARUM Affiliates Info

                    MSLC.ProviderProxy.Interfaces.IArumAffiliateList arum_Affiliates =
                        _providerServiceProxy.GetAllAffiliates(RetrieveSession.Classification.ARUMToken,
                            "Rate/Provider");
                    int affiliateId = arum_provider.Affiliates.Select(x => x.AffiliateID).FirstOrDefault();
                    MSLC.ProviderProxy.Interfaces.IArumAffiliateObject arum_Affiliate =
                        _providerServiceProxy.GetFullAffiliateByAffiliateID(RetrieveSession.Classification.ARUMToken,
                            affiliateId, "Rate/Provider");
                    if (arum_Affiliate != null)
                    {
                        generalInformationViewModel.HomeMedicaidId = arum_Affiliate.AffiliateObject.Identifiers
                            .FirstOrDefault(i => i.Type == "HOME_NUM")?.Value ?? string.Empty;

                        //Pull the updated MRDD number value from the affiliate attributes; if not available, pull it from the affiliate identifiers.
                        generalInformationViewModel.MRDDNumber =
                            arum_Affiliate.AffiliateObject.Attributes
                                .FirstOrDefault(i => i.AttributeKey == "HOME_MRDD_NUM")?.AttributeValue ??
                            arum_Affiliate.AffiliateObject.Identifiers.FirstOrDefault(i => i.Type == "MRDD")?.Value ??
                            string.Empty;

                        //Pull the updated ODH number value from the affiliate attributes; if not available, pull it from the affiliate identifiers.
                        generalInformationViewModel.ODHID =
                            CostReportBL.GetODHFromAffiliate(_providerServiceProxy, arum_Affiliate);

                        generalInformationViewModel.PracticeType = arum_Affiliate.AffiliateObject.Attributes
                                                                       .FirstOrDefault(i =>
                                                                           i.AttributeKey == "PRACTICE_TYPE_DESC")
                                                                       ?.AttributeValue ??
                                                                   string.Empty;
                    }

                    #endregion

                    #region Get ARUM Provider Status Info

                    ICodes arum_Codes =
                        _applicationServiceProxy.GetAllCodes(RetrieveSession.Classification.ARUMToken, "Rate/Provider");
                    MSLC.ProviderProxy.Interfaces.IArumProviderStatusList arum_Status =
                        _providerServiceProxy.GetAllProviderStatusesByProviderID(
                            RetrieveSession.Classification.ARUMToken, providerID, "Rate/Provider");
                    if (arum_Status.ProviderStatuses?.Any() ?? false)
                    {
                        string providerStatus = arum_Status.ProviderStatuses
                            .Where(x => x.IsActive == true && x.Type.ToUpper() == "MEDICAID")?
                            .OrderByDescending(x => x.EffectiveDate)
                            .ThenByDescending(x => x.CreateDate)
                            .Select(x => x.Status)
                            .FirstOrDefault();

                        if (!string.IsNullOrWhiteSpace(providerStatus))
                        {
                            generalInformationViewModel.Status =
                                arum_Codes.lstCodes.FirstOrDefault(x => x.Value == providerStatus)?.Name;
                        }
                    }

                    #endregion

                    #region Get ARUM Provider CHOP Info

                    MSLC.ProviderProxy.Interfaces.IArumChowReviewChain arum_CHOP =
                        _providerServiceProxy.GetChowReviewChainByNewProviderID(
                            RetrieveSession.Classification.ARUMToken, providerID, "Rate/Provider");

                    if (arum_CHOP.ChowReviews.Count() != 0)
                    {
                        MSLC.ProviderProxy.Interfaces.Models.ChowReview chowReviewsTo = arum_CHOP.ChowReviews
                            .Where(x => x.OldProviderID == providerID)
                            .OrderByDescending(x => x.ApproveDate)
                            .FirstOrDefault();

                        generalInformationViewModel.CHOPToProviderNumber = string.Empty;
                        generalInformationViewModel.CHOPFromProviderNumber = string.Empty;

                        if (chowReviewsTo != null)
                        {
                            MSLC.ProviderProxy.Interfaces.IArumDetailedProvider arum_NewProvider =
                                _providerServiceProxy.GetProviderInfoByARUMProviderID(
                                    RetrieveSession.Classification.ARUMToken, chowReviewsTo.NewProviderID.Value,
                                    "Rate/Provider");
                            if (arum_NewProvider != null)
                            {
                                generalInformationViewModel.CHOPToProviderNumber = arum_NewProvider.Identifiers
                                    .FirstOrDefault(i => i.Type == "MCAID")?.Value ?? string.Empty;
                            }
                        }

                        MSLC.ProviderProxy.Interfaces.Models.ChowReview chowReviewsFrom = arum_CHOP.ChowReviews
                            .Where(x => x.NewProviderID == providerID)
                            .OrderByDescending(x => x.ApproveDate)
                            .FirstOrDefault();

                        if (chowReviewsFrom != null)
                        {
                            MSLC.ProviderProxy.Interfaces.IArumDetailedProvider arum_OldProvider =
                                _providerServiceProxy.GetProviderInfoByARUMProviderID(
                                    RetrieveSession.Classification.ARUMToken, chowReviewsFrom.OldProviderID.Value,
                                    "Rate/Provider");
                            if (arum_OldProvider != null)
                            {
                                generalInformationViewModel.CHOPFromProviderNumber = arum_OldProvider.Identifiers
                                    .FirstOrDefault(i => i.Type == "MCAID")?.Value ?? string.Empty;
                            }
                        }
                    }

                    #endregion

                    #region Get RateSetting Provider Attributes

                    List<ProviderAttributeViewModel> lstAttributes = new List<ProviderAttributeViewModel>();

                    var attributeList = RateBL.GetProviderAttributes(providerID);
                    foreach (var attribute in attributeList)
                    {
                        lstAttributes.Add(new ProviderAttributeViewModel
                        {
                            ProviderAttributeId =
                                ClientMapping.MapInternalIdToClientId(attribute.ProviderAttributeId.ToString(),
                                    "provattr"),
                            ProviderId = provIdMapped,
                            Name = attribute.Key,
                            StartDate = attribute.StartDate,
                            EndDate = attribute.EndDate,
                            IsEnabled = attribute.IsEnabled,
                        });
                    }

                    generalInformationViewModel.ProviderAttributes = lstAttributes;

                    #endregion
                }
            }

            return PartialView("Provider/_GeneralInfo", generalInformationViewModel);
        }

        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult GetAttribute(string attributeId)
        {
            ProviderAttributeViewModel lstAttributes = new ProviderAttributeViewModel();

            int dbAttributeId = 0;
            if (int.TryParse(ClientMapping.GetInternalIdFromClientId(attributeId, "provattr"), out int i))
            {
                dbAttributeId = i;
            }

            if (dbAttributeId <= 0)
            {
                return PartialView("Provider/_EditRateAttributes", lstAttributes);
            }

            if (Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT] != null)
            {
                int providerID = (int)Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT];
                var attributeData = RateBL.GetProviderAttributes(providerID, dbAttributeId);
                lstAttributes = new ProviderAttributeViewModel
                {
                    ProviderAttributeId =
                        ClientMapping.MapInternalIdToClientId(attributeData.ProviderAttributeId.ToString(), "provattr"),
                    ProviderId = ClientMapping.MapInternalIdToClientId(providerID.ToString(), "provider"),
                    Name = attributeData.Key,
                    StartDate = attributeData.StartDate,
                    EndDate = attributeData.EndDate,
                    IsEnabled = attributeData.IsEnabled,
                };
            }

            return PartialView("Provider/_EditRateAttributes", lstAttributes);
        }

        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult SaveProviderAttribute(ProviderAttributeViewModel providerAttributeView)
        {
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;

            if (Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT] != null)
            {
                int providerID = (int)Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT];

                int attrId = 0;
                if (int.TryParse(
                        ClientMapping.GetInternalIdFromClientId(providerAttributeView.ProviderAttributeId, "provattr"),
                        out int i))
                {
                    attrId = i;
                }

                if (providerAttributeView != null)
                {
                    RateProviderAttribute providerAttribute = new RateProviderAttribute
                    {
                        ProviderAttributeId = attrId,
                        ProviderId = providerID,
                        Key = providerAttributeView.Name,
                        StartDate = providerAttributeView.StartDate,
                        EndDate = providerAttributeView.EndDate,
                        IsEnabled = providerAttributeView.IsEnabled,
                        CreatedOn = DateTime.UtcNow,
                        CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                        LastUpdatedOn = DateTime.UtcNow,
                        LastUpdatedBy = $"{myUser.FirstName} {myUser.LastName}"
                    };

                    RateBL.SaveProviderAttributes(providerAttribute);
                }

                var providerAttributesData = RateBL.GetProviderAttributes(providerID);

                string provIdMapped = ClientMapping.MapInternalIdToClientId(providerID.ToString(), "provider");
                List<ProviderAttributeViewModel> providerAttributes = new List<ProviderAttributeViewModel>();
                foreach (var data in providerAttributesData)
                {
                    providerAttributes.Add(new ProviderAttributeViewModel
                    {
                        ProviderAttributeId =
                            ClientMapping.MapInternalIdToClientId(data.ProviderAttributeId.ToString(), "provattr"),
                        ProviderId = provIdMapped,
                        Name = data.Key,
                        StartDate = data.StartDate,
                        EndDate = data.EndDate,
                        IsEnabled = data.IsEnabled,
                    });
                }

                return Json(new
                {
                    Success = true,
                    ProviderAttributes = providerAttributes
                },
                    JsonRequestBehavior.AllowGet);
            }

            return Json(new { Success = false },
                JsonRequestBehavior.AllowGet);
        }

        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult EnableDisableProviderAttribute(string attributeId, bool isEnabled)
        {
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;

            if (Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT] != null)
            {
                int providerID = (int)Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT];
                string provIdMapped = ClientMapping.MapInternalIdToClientId(providerID.ToString(), "provider");

                if (!string.IsNullOrWhiteSpace(attributeId))
                {
                    int attrId = 0;
                    if (int.TryParse(ClientMapping.GetInternalIdFromClientId(attributeId, "provattr"), out int i))
                    {
                        attrId = i;

                        var providerAttribute = RateBL.GetProviderAttributes(providerID, attrId);
                        providerAttribute.IsEnabled = isEnabled;
                        providerAttribute.LastUpdatedOn = DateTime.UtcNow;
                        providerAttribute.LastUpdatedBy = $"{myUser.FirstName} {myUser.LastName}";
                        RateBL.SaveProviderAttributes(providerAttribute);
                    }
                }

                var providerAttributesData = RateBL.GetProviderAttributes(providerID);

                List<ProviderAttributeViewModel> providerAttributes = new List<ProviderAttributeViewModel>();
                foreach (var data in providerAttributesData)
                {
                    providerAttributes.Add(new ProviderAttributeViewModel
                    {
                        ProviderAttributeId =
                            ClientMapping.MapInternalIdToClientId(data.ProviderAttributeId.ToString(), "provattr"),
                        ProviderId = provIdMapped,
                        Name = data.Key,
                        StartDate = data.StartDate,
                        EndDate = data.EndDate,
                        IsEnabled = data.IsEnabled,
                    });
                }

                return Json(new
                {
                    Success = true,
                    ProviderAttributes = providerAttributes
                },
                    JsonRequestBehavior.AllowGet);
            }

            return Json(new { Success = false },
                JsonRequestBehavior.AllowGet);
        }

