        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult ProviderCostReport()
        {
            // Get Provider CostReport Period
            ProviderCostReportViewModel providerCostReportViewModel = new ProviderCostReportViewModel();
            if (Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT] != null)
            {
                int providerID = (int)Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT];
                string provIdMapped = ClientMapping.MapInternalIdToClientId(providerID.ToString(), "provider");

                List<ProjectSpecific.Data.Models.crdata.Period> costReportPeroids = RateBL.GetCostReportPeriodsRO();
                List<SelectListItem> itemList = new List<SelectListItem>();
                foreach (var item in costReportPeroids)
                {
                    itemList.Add(new SelectListItem
                    {
                        Text = item.PeriodCode,
                        Value = ClientMapping.MapInternalIdToClientId(item.PeriodCode.ToString(), "costreportperiod")
                    });
                }

                providerCostReportViewModel.CostReportPeriod = itemList;

                // Cost Report Vesion
                ProjectSpecific.Data.Models.crdata.Period period = costReportPeroids.FirstOrDefault();

                List<SelectListItem> itemCostReportVersionList = new List<SelectListItem>();

                costReportPeroids.Clear();

                providerCostReportViewModel.CostReportVersion = itemCostReportVersionList;
            }

            // Info Tab
            providerCostReportViewModel.CostReportStatus = new List<SelectListItem>();
            var itemUsersList = new List<SelectListItem>();
            providerCostReportViewModel.ExaminerListItem = itemUsersList;
            providerCostReportViewModel.ReviewerListItem = itemUsersList;

            List<ProviderCostReportStatlogViewModel> listsSatlogInfo = new List<ProviderCostReportStatlogViewModel>();
            providerCostReportViewModel.ProviderCostReportStatlogList = listsSatlogInfo;

            return PartialView("Provider/_CostReport", providerCostReportViewModel);
        }

        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult GetCostReportVersion(string periodCode)
        {
            List<ProviderCostReport> costReportVersions = null;

            try
            {
                // Get Provider CostReport Version
                ProviderCostReportViewModel providerCostReportViewModel = new ProviderCostReportViewModel();
                if (Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT] != null)
                {
                    int providerID = (int)Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT];

                    // Cost Report Vesion
                    string period = ClientMapping.GetInternalIdFromClientId(periodCode, "costreportperiod");

                    //Getting the latest cost report for the provider and period specified
                    costReportVersions = RateBL.GetSubmittedCostReports(providerID, period);
                    bool canViewNonAudit = RateSettingProviderCostReportPermissionBL.InfoView();
                    bool canViewAudit = RateSettingProviderCostReportPermissionBL.AuditView();

                    List<SelectListItem> itemCostReportVersionList = new List<SelectListItem>();
                    foreach (var version in costReportVersions)
                    {
                        if (version.CostReportTypeCode.StartsWith("4.9") && !canViewAudit) continue;
                        else if (!version.CostReportTypeCode.StartsWith("4.9") && !canViewNonAudit) continue;
                        itemCostReportVersionList.Add(new SelectListItem
                        {
                            Text = version.CostReportTypeCode + "; " + version.PeriodEnd.ToString("yyyy-MM-dd") + "; " +
                                   version.Version,
                            Value = ClientMapping.MapInternalIdToClientId(version.ProviderCostReportId.ToString(),
                                "costreport")
                        });
                    }

                    providerCostReportViewModel.CostReportVersion = itemCostReportVersionList;
                }

                // Info Tab
                providerCostReportViewModel.CostReportStatus = new List<SelectListItem>();
                var itemUsersList = new List<SelectListItem>();
                providerCostReportViewModel.ExaminerListItem = itemUsersList;
                providerCostReportViewModel.ReviewerListItem = itemUsersList;

                List<ProviderCostReportStatlogViewModel> listsSatlogInfo =
                    new List<ProviderCostReportStatlogViewModel>();
                providerCostReportViewModel.ProviderCostReportStatlogList = listsSatlogInfo;

                return Json(new
                {
                    Success = true,
                    ProviderCostReportViewModel = providerCostReportViewModel
                },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    message = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }
            finally
            {
                if (costReportVersions != null) costReportVersions.Clear();
            }
        }

        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult GetCostReportInfo(string providerCostReportId)
        {
            List<CostReportStatus> costReportStatusList = null;
            List<Users> usersList = null;
            List<Users> examinerUsersList = null;
            List<Users> reviewerUsersList = null;
            List<ProviderCostReportStatlog> statlogList = null;

            try
            {
                // Get Provider CostReport Info
                ProviderCostReportViewModel providerCostReportViewModel = new ProviderCostReportViewModel();
                if (Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT] != null)
                {
                    int providerID = (int)Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT];
                    int dbproviderCostReportId = 0;
                    if (int.TryParse(ClientMapping.GetInternalIdFromClientId(providerCostReportId, "costreport"),
                            out int i))
                    {
                        dbproviderCostReportId = i;
                    }

                    if (dbproviderCostReportId == 0)
                    {
                        return Json(new { Success = false, Message = "Invalid cost report selected." });
                    }

                    ProviderCostReport costReportInfo = RateBL.GetCostReportInfo(providerID, dbproviderCostReportId);
                    // Info Tab
                    providerCostReportViewModel.BeginDate = costReportInfo.PeriodBegin.ToShortDateString();
                    providerCostReportViewModel.EndDate = costReportInfo.PeriodEnd.ToShortDateString();
                    providerCostReportViewModel.CostReportStatusId =
                        ClientMapping.MapInternalIdToClientId(costReportInfo.CostReportStatusId.ToString(),
                            "costreportstatus");
                    providerCostReportViewModel.ExaminerUserId =
                        ClientMapping.MapInternalIdToClientId(costReportInfo.ExaminerUserId.ToString(), "user");
                    providerCostReportViewModel.ReviewerUserId =
                        ClientMapping.MapInternalIdToClientId(costReportInfo.ReviewerUserId.ToString(), "user");
                    providerCostReportViewModel.IsCostReportLocked =
                        CostReportHistoryBL.CheckLockedStatus(dbproviderCostReportId);

                    costReportStatusList = RateBL.GetCostReportStatuses();
                    List<SelectListItem> itemCostReportStatusList = new List<SelectListItem>();
                    foreach (var costReportStatus in costReportStatusList)
                    {
                        itemCostReportStatusList.Add(new SelectListItem
                        {
                            Text = costReportStatus.Status,
                            Value = ClientMapping.MapInternalIdToClientId(costReportStatus.CostReportStatusId.ToString(), "costreportstatus")
                        });
                    }
                    providerCostReportViewModel.CostReportStatus = itemCostReportStatusList;

                    #region Populate Examiner and Reviewer Dropdowns

                    //Get user list
                    usersList = RateBL.GetAllUsers();
                    providerCostReportViewModel.ExaminerListItem =
                        // Examiner list is limited to staff or selected user
                        usersList.Where(x => (x.ActiveFlag && x.Mnemonic == "Staff") ||
                                             x.UserId == costReportInfo.ExaminerUserId)
                            .Select(user => new SelectListItem()
                            {
                                Text = user.FirstName + " " + user.LastName,
                                Value = ClientMapping.MapInternalIdToClientId(user.UserId.ToString(), "user")
                            }).ToList();

                    providerCostReportViewModel.ReviewerListItem =
                        usersList.Where(x => x.ActiveFlag ||
                                             x.UserId == costReportInfo.ExaminerUserId)
                            .Select(user => new SelectListItem()
                            {
                                Text = user.FirstName + " " + user.LastName,
                                Value = ClientMapping.MapInternalIdToClientId(user.UserId.ToString(), "user")
                            }).ToList();

                    #endregion

                    providerCostReportViewModel.SetPermissions(costReportInfo.CostReportTypeCode);
                    if (providerCostReportViewModel.CanViewStatlog)
                    {
                        List<ProviderCostReportStatlogViewModel> listsSatlogInfo =
                             new List<ProviderCostReportStatlogViewModel>();
                        ProviderCostReportStatlogViewModel statlogInfo;
                        statlogList = RateBL.GetProviderCostReportStatlog(dbproviderCostReportId);
                        if (statlogList != null && statlogList.Count > 0)
                        {
                            foreach (var statlog in statlogList) listsSatlogInfo.Add(new ProviderCostReportStatlogViewModel(statlog, providerCostReportViewModel.CanEditStatlog));
                        }
                        providerCostReportViewModel.ProviderCostReportStatlogList = listsSatlogInfo;
                    }
                }

                return Json(new
                {
                    Success = true,
                    ProviderCostReportViewModel = providerCostReportViewModel
                },
                       JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    message = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }
            finally
            {
                if (costReportStatusList != null) costReportStatusList.Clear();
                if (usersList != null) usersList.Clear();
                if (examinerUsersList != null) examinerUsersList.Clear();
                if (reviewerUsersList != null) reviewerUsersList.Clear();
                if (statlogList != null) statlogList.Clear();
            }
        }

        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult SaveCostReportInfo(string providerCostReportId, string costReportStatusId, string examinerId,
            string reviewerId,
            string costReportStatus, string examinerUser, string reviewerUser, string oldCostReportStatus,
            string oldExaminerUser, string oldReviewerUser)
        {
            List<ProviderCostReportStatlog> statlogList = null;

            try
            {
                MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
                int dbproviderCostReportId = 0;
                if (int.TryParse(ClientMapping.GetInternalIdFromClientId(providerCostReportId, "costreport"),
                        out int i))
                {
                    dbproviderCostReportId = i;
                }

                // Default to on hold in case it is incorrect.
                int? dbcostReportStatusId = (int)CostReportStatusEnum.OnHold;
                if (int.TryParse(ClientMapping.GetInternalIdFromClientId(costReportStatusId, "costreportstatus"),
                        out int statusId))
                {
                    dbcostReportStatusId = statusId;
                }

                int? dbexaminerId = null;
                if (int.TryParse(ClientMapping.GetInternalIdFromClientId(examinerId, "user"), out int examinerUserId))
                {
                    dbexaminerId = examinerUserId;
                }

                int? dbreviewerId = null;
                if (int.TryParse(ClientMapping.GetInternalIdFromClientId(reviewerId, "user"), out int reviewerUserId))
                {
                    dbreviewerId = reviewerUserId;
                }

                if (dbreviewerId != null && dbreviewerId == dbexaminerId)
                {
                    return Json(new
                    {
                        Success = false,
                        message = "Examiner and Reviewer can't be the same, please make another selection."
                    },
                        JsonRequestBehavior.AllowGet);
                }

                if (dbproviderCostReportId == 0)
                {
                    return Json(new
                    {
                        Success = false,
                        Message = "Unable to resolve provider cost report identifier."
                    }, JsonRequestBehavior.AllowGet);
                }

                RateBL.SaveCostReportInfo(
                    $"{RetrieveSession.Classification?.StateAbbreviation}_{SimplifiedType}",
                    dbproviderCostReportId, dbcostReportStatusId, dbexaminerId, dbreviewerId);

                if ((costReportStatus != "") && (costReportStatus != oldCostReportStatus))
                {
                    //Cost Report Version: (for example: 4.1; 12 - 31 - 2021; 2022 - 03 - 16 16:40:39) Status was changed from ____ to  _____ by User name on Date(MM/ DD / YYYY).
                    //Cost Report Version: (for example: 4.1; 12 - 31 - 2021; 2022 - 03 - 16 16:40:39) Status was changed from Cleared to  Obsolete by System on Date(MM / DD / YYYY).
                    string statusMessage = "Status was changed from " + oldCostReportStatus + " to " +
                                           costReportStatus + " by " + myUser.Email + " on Date(" +
                                           DateTime.Now.ToString("MM/dd/yyyy") + ")";

                    RateBL.SaveCostReportStatlog(new ProviderCostReportStatlog
                    {
                        CRID = dbproviderCostReportId,
                        EventDate = DateTime.Now,
                        Stamp = DateTime.Now,
                        EventName = statusMessage,
                        UserId = myUser.Email,
                        CreatedOn = DateTime.Now,
                        CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                        LastUpdatedOn = DateTime.Now,
                        LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}"
                    });
                }

                if ((examinerUser != "") && (examinerUser != oldExaminerUser))
                {
                    //Cost Report Review Assignment Examiner was changed from ________ to _________ by User Name on Date(MM/ DD / YYYY)
                    var examinerStatusMessage = "Cost Report Review Assignment Examiner was changed from " +
                                                oldExaminerUser + " to " + examinerUser + " by " + myUser.Email +
                                                " on Date(" + DateTime.Now.ToString("MM/dd/yyyy") + ")";
                    RateBL.SaveCostReportStatlog(new ProviderCostReportStatlog
                    {
                        CRID = dbproviderCostReportId,
                        EventDate = DateTime.Now,
                        Stamp = DateTime.Now,
                        EventName = examinerStatusMessage,
                        UserId = myUser.Email,
                        CreatedOn = DateTime.Now,
                        CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                        LastUpdatedOn = DateTime.Now,
                        LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}"
                    });
                }

                if ((reviewerUser != "") && (reviewerUser != oldReviewerUser))
                {
                    //Cost Report Review Assignment Reviewer was changed from ________ to _________ by User Name on Date(MM/ DD / YYYY)
                    string reviewerStatusMessage = "Cost Report Review Assignment Reviewer was changed from " +
                                                   oldReviewerUser + " to " + reviewerUser + " by " + myUser.Email +
                                                   " on Date(" + DateTime.Now.ToString("MM/dd/yyyy") + ")";

                    RateBL.SaveCostReportStatlog(new ProviderCostReportStatlog
                    {
                        CRID = dbproviderCostReportId,
                        EventDate = DateTime.Now,
                        Stamp = DateTime.Now,
                        EventName = reviewerStatusMessage,
                        UserId = myUser.Email,
                        CreatedOn = DateTime.Now,
                        CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                        LastUpdatedOn = DateTime.Now,
                        LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}"
                    });
                }


                ProviderCostReportViewModel providerCostReportViewModel = new ProviderCostReportViewModel();
                statlogList = RateBL.GetProviderCostReportStatlog(dbproviderCostReportId);

                providerCostReportViewModel.ProviderCostReportStatlogList = statlogList?
                    .Select(statlog => new ProviderCostReportStatlogViewModel
                    {
                        ProviderCostReportStatlogId = ClientMapping.MapInternalIdToClientId(
                            statlog.ProviderCostReportStatlogId.ToString(), "costreportstatlog"),
                        CRID = ClientMapping.MapInternalIdToClientId(statlog.CRID.ToString(), "costreport"),
                        EventDate = statlog.EventDate.ToString("MM/dd/yyyy"),
                        EventName = statlog.EventName,
                        UserId = statlog.UserId,
                        Notes = statlog.Notes
                    }).ToList() ?? new List<ProviderCostReportStatlogViewModel>();

                return Json(new
                {
                    Success = true,
                    ProviderCostReportViewModel = providerCostReportViewModel
                },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    message = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }
            finally
            {
                if (statlogList != null) statlogList.Clear();
            }
        }

        public JsonResult GetAuditCostReportInfo(string providerCostReportId)
        {
            if (!RateSettingProviderCostReportPermissionBL.AuditView())
                return Json(new { Success = false, Message = "Invalid Access." });

            try
            {
                int providerID = (int)Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT];
                int dbproviderCostReportId = 0;
                if (int.TryParse(ClientMapping.GetInternalIdFromClientId(providerCostReportId, "costreport"), out int i))
                    dbproviderCostReportId = i;

                if (dbproviderCostReportId == 0)
                    return Json(new { Success = false, Message = "Invalid cost report selected." });

                AuditorInfo info = CostReportAuditBL.GetCostReportAuditInfo(dbproviderCostReportId);
                ReasonForChangeComment comment = CostReportAuditBL.GetUnknownReasonForChange(info.AuditTypeId, dbproviderCostReportId);
                ProviderCostReport costReportInfo = RateBL.GetCostReportInfo(providerID, dbproviderCostReportId);
                List<AuditUser> users = CostReportAuditBL.GetActiveCRAuditStaffTable();
                List<AuditType> types = CostReportAuditBL.GetAuditTypes();
                List<ReasonForChange> reasons = info.AuditTypeId.HasValue ? CostReportAuditBL.GetActiveReasonsForChangeByAuditType(info.AuditTypeId.Value, dbproviderCostReportId)
                    : new List<ReasonForChange>();
                List<ProviderCostReportStatlog> statlogList = RateBL.GetProviderCostReportStatlog(dbproviderCostReportId);

                List<CostReportStatus> costReportStatusList = RateBL.GetAuditCostReportStatuses();
                List<SelectListItem> itemCostReportStatusList = new List<SelectListItem>();
                if (costReportInfo.CostReportStatusId == null)
                {
                    itemCostReportStatusList.Add(new SelectListItem()
                    {
                        Text = CostReportStatusEnum.AuditOpen.GetDescription(),
                        Value = string.Empty
                    });
                }
                else
                {
                    foreach (var costReportStatus in costReportStatusList)
                    {
                        itemCostReportStatusList.Add(new SelectListItem
                        {
                            Text = costReportStatus.Status,
                            Value = ClientMapping.MapInternalIdToClientId(costReportStatus.CostReportStatusId.ToString(), "costreportstatus")
                        });
                    }
                }

                AuditCostReportViewModel model = new AuditCostReportViewModel(info, comment, costReportInfo, users, types, reasons, statlogList);
                model.CostReportStatus = itemCostReportStatusList;
                return Json(new { Success = true, Data = model }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    message = e.Message
                },
               JsonRequestBehavior.AllowGet);
            }
        }

