        public JsonResult GetReasonForChange(string auditTypeClientCode, string providerCostReport)
        {
            try
            {
                string internalAuditTypeId = ClientMapping.GetInternalIdFromClientId(auditTypeClientCode, "auditTypeId");
                string internalProviderCostReportId = ClientMapping.GetInternalIdFromClientId(providerCostReport, "costreport");

                int auditTypeCode = 0;
                if (!string.IsNullOrWhiteSpace(internalAuditTypeId)) auditTypeCode = int.Parse(internalAuditTypeId);

                int costReportId = 0;
                if (!string.IsNullOrWhiteSpace(internalProviderCostReportId)) costReportId = int.Parse(internalProviderCostReportId);

                AuditorInfo info = CostReportAuditBL.GetCostReportAuditInfo(costReportId);
                List<ReasonForChange> reasonForChangeDataList = CostReportAuditBL.GetActiveReasonsForChangeByAuditType(auditTypeCode, costReportId);
                ReasonForChangeOptionsModel model = new ReasonForChangeOptionsModel(info, reasonForChangeDataList);

                return Json(new
                {
                    Success = true,
                    ReasonForChangeViewModel = model
                },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception ex)
            {
                _logger.Error(ex, ex.Message);

                return Json(new
                {
                    Success = false,
                    message = ex.Message
                },
                    JsonRequestBehavior.AllowGet);
            }
        }

        public JsonResult SaveAuditCostReport(AuditCostReportViewModel auditViewModel, AuditCostReportViewModel oldModel)
        {
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
            try
            {
                int dbCostReportStatusId = 0;
                if (int.TryParse(ClientMapping.GetInternalIdFromClientId(auditViewModel.CostReportStatusId, "costreportstatus"), out int statusId))
                    dbCostReportStatusId = statusId;

                AuditorInfo auditorInfo = auditViewModel.GetEntity();


                // Update ProviderCostreport Table to Update CostReportStatusId 
                // Non-submitted Audit Cost Reports will have the status Id null and trying to update that will throw an exception
                if (!string.IsNullOrEmpty(auditViewModel.CostReportStatusId))
                    RateBL.UpdateCostReportStatus(auditorInfo.CRID, dbCostReportStatusId);

                // Save AuditorInfo
                RateBL.SaveAuditorInfo(auditorInfo, auditViewModel.ReasonForChangeComment);
                // Current date string for messages
                string currentDate = DateTime.Now.ToString("MM/dd/yyyy");
                //1.Cost Report Status changed
                if (auditViewModel.CostReportStatusName != oldModel.CostReportStatusName && auditViewModel.CostReportStatusName != CostReportStatusEnum.AuditOpen.GetDescription())
                {
                    RateBL.SaveCostReportStatlog(new ProviderCostReportStatlog
                    {
                        CRID = auditorInfo.CRID,
                        EventDate = DateTime.Now,
                        Stamp = DateTime.Now,
                        EventName = $"Status was changed from {oldModel.CostReportStatusName} to {auditViewModel.CostReportStatusName} by {myUser.FirstName} {myUser.LastName} on {currentDate}",
                        UserId = myUser.Email,
                        CreatedOn = DateTime.UtcNow,
                        CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                        LastUpdatedOn = DateTime.UtcNow,
                        LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}",
                    });
                }

                if (oldModel.IsContractAudit != auditViewModel.IsContractAudit)
                {
                    if (auditViewModel.IsContractAudit)
                    {   // NFOFI-6463: If change was to check contract audit, use selected message
                        //2.Contract Audit selected 
                        RateBL.SaveCostReportStatlog(new ProviderCostReportStatlog
                        {
                            CRID = auditorInfo.CRID,
                            EventDate = DateTime.Now,
                            Stamp = DateTime.Now,
                            EventName =
                                $"Contract Audit box was selected by {myUser.FirstName} {myUser.LastName} on {currentDate}",
                            UserId = myUser.Email,
                            CreatedOn = DateTime.UtcNow,
                            CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                            LastUpdatedOn = DateTime.UtcNow,
                            LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}",
                        });
                    }
                    else
                    {   // NFOFI-6463: If change was to uncheck contract audit, use changed message
                        // 3. Contract Audit was changed
                        RateBL.SaveCostReportStatlog(new ProviderCostReportStatlog
                        {
                            CRID = auditorInfo.CRID,
                            EventDate = DateTime.Now,
                            Stamp = DateTime.Now,
                            EventName =
                            $"Contract Audit selection was changed by {myUser.FirstName} {myUser.LastName} on {currentDate}",
                            UserId = myUser.Email,
                            CreatedOn = DateTime.UtcNow,
                            CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                            LastUpdatedOn = DateTime.UtcNow,
                            LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}",
                        });
                    }
                }

                //* 4-13,
                //15* Audit Type was changed
                //16* Reason for Change was changed
                //Array of string-type changes (excluding booleans)
                var stringFieldChanges = new (string Old, string Current, string Name)[]
                {
                    (Old: oldModel.ContractorName, Current: auditViewModel.ContractorName, Name: "Contract Name"),
                    (Old: oldModel.Auditor1Id, Current: auditViewModel.Auditor1Id, Name: "Auditor 1 Assigned"),
                    (Old: oldModel.Auditor2Id, Current: auditViewModel.Auditor2Id, Name: "Auditor 2 Assigned"),
                    (Old: oldModel.PeerAuditorId, Current: auditViewModel.PeerAuditorId, Name: "Peer Review Auditor Assigned"),
                    (Old: oldModel.FieldAuditor1Id, Current: auditViewModel.FieldAuditor1Id, Name: "Field Auditor 1 Assigned"),
                    (Old: oldModel.FieldAuditor2Id, Current: auditViewModel.FieldAuditor2Id, Name: "Field Auditor 2 Assigned"),
                    (Old: oldModel.FieldAuditor3Id, Current: auditViewModel.FieldAuditor3Id, Name: "Field Auditor 3 Assigned"),
                    (Old: oldModel.FieldAuditor4Id, Current: auditViewModel.FieldAuditor4Id, Name: "Field Auditor 4 Assigned"),
                    (Old: oldModel.FieldAuditor5Id, Current: auditViewModel.FieldAuditor5Id, Name: "Field Auditor 5 Assigned"),
                    (Old: oldModel.FieldAuditor6Id, Current: auditViewModel.FieldAuditor6Id, Name: "Field Auditor 6 Assigned"),
                    (Old: oldModel.AuditTypeId, Current: auditViewModel.AuditTypeId, Name: "Audit Type"),
                    (Old: oldModel.ReasonForChangeId, Current: auditViewModel.ReasonForChangeId, Name: "Reason for Change"),
                };

                foreach (var auditor in stringFieldChanges)
                {
                    if (!(string.IsNullOrWhiteSpace(auditor.Old) && string.IsNullOrWhiteSpace(auditor.Current)))
                    {
                        if (auditor.Old != auditor.Current)
                        {
                            RateBL.SaveCostReportStatlog(new ProviderCostReportStatlog
                            {
                                CRID = auditorInfo.CRID,
                                EventDate = DateTime.Now,
                                Stamp = DateTime.Now,
                                EventName =
                                $"{auditor.Name} was changed by {myUser.FirstName} {myUser.LastName} on {currentDate}",
                                UserId = myUser.Email,
                                CreatedOn = DateTime.UtcNow,
                                CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                                LastUpdatedOn = DateTime.UtcNow,
                                LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}",
                            });
                        }
                    }
                }

                //14* Completion Date was changed
                DateTime? newDate = null;
                DateTime? oldDate = null;
                if (DateTime.TryParse(auditViewModel.CompletionDate, out DateTime result))
                    newDate = result;
                if (DateTime.TryParse(oldModel.CompletionDate, out DateTime result1))
                    oldDate = result1;

                if (newDate != oldDate)
                {
                    RateBL.SaveCostReportStatlog(new ProviderCostReportStatlog
                    {
                        CRID = auditorInfo.CRID,
                        EventDate = DateTime.Now,
                        Stamp = DateTime.Now,
                        EventName =
