        public JsonResult GetReviewCostReportStatlog(string providerCostReportStatlogId, string costReportId)
        {
            try
            {
                if (!RateSettingProviderCostReportPermissionBL.StatlogView(GetCRTypeForSelectedRateCostReport(costReportId)))
                    throw new InvalidAccessException("Invalid Access");

                MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
                ProviderCostReportReviewViewModel
                    providerCostReportReviewInfo = new ProviderCostReportReviewViewModel();

                int dbProviderCostReportStatlogId = 0;
                if (int.TryParse(
                        ClientMapping.GetInternalIdFromClientId(providerCostReportStatlogId, "costreportstatlog"),
                        out int i))
                {
                    dbProviderCostReportStatlogId = i;
                }

                ProviderCostReportReview review =
                    RateBL.GetProviderCostReportStatlogReview(dbProviderCostReportStatlogId);
                if (review != null)
                {
                    providerCostReportReviewInfo.ProviderCostReportReviewId =
                        ClientMapping.MapInternalIdToClientId(review.ProviderCostReportReviewId.ToString(),
                            "costreportreview");
                    providerCostReportReviewInfo.ProviderCostReportStatlogId =
                        ClientMapping.MapInternalIdToClientId(review.ProviderCostReportStatlogId.ToString(),
                            "costreportstatlog");
                    providerCostReportReviewInfo.RevDate = DateTime.Now.ToShortDateString();
                    providerCostReportReviewInfo.RevNotes = review.RevNotes;
                    providerCostReportReviewInfo.RevUserId = myUser.Email;
                }
                else
                {
                    providerCostReportReviewInfo.ProviderCostReportReviewId =
                        ClientMapping.MapInternalIdToClientId("0", "costreportreview");
                    providerCostReportReviewInfo.ProviderCostReportStatlogId =
                        ClientMapping.MapInternalIdToClientId("0", "costreportstatlog");
                    providerCostReportReviewInfo.RevDate = DateTime.Now.ToShortDateString();
                    providerCostReportReviewInfo.RevNotes = "";
                    providerCostReportReviewInfo.RevUserId = myUser.Email;
                }

                return Json(new
                {
                    Success = true,
                    ProviderCostReportReviewViewModel = providerCostReportReviewInfo
                },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    message = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }
        }

        private string GetCRTypeForSelectedRateCostReport(string providerCostReportId)
        {
            int providerID = (int)Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT];
            int dbproviderCostReportId = 0;
            if (int.TryParse(ClientMapping.GetInternalIdFromClientId(providerCostReportId, "costreport"),
                    out int i))
            {
                dbproviderCostReportId = i;
            }

            if (dbproviderCostReportId == 0)
            {
                return string.Empty;
            }

            ProviderCostReport costReportInfo = RateBL.GetCostReportInfo(providerID, dbproviderCostReportId);
            return costReportInfo?.CostReportTypeCode;
