        [ARUMFeatureActionFilter(RateSettingPermissions.ProvRatesView)]
        public ActionResult Rates()
        {
            //ProviderRatesViewModel rateViewModel = new ProviderRatesViewModel();
            PeriodViewModel periodViewModel = new PeriodViewModel();
            List<SelectListItem> items = new List<SelectListItem>();
            List<ProjectSpecific.Data.Models.crdata.Period> periods = null;

            if (Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT] != null)
            {
                int providerID = (int)Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT];
                Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT] = providerID;

                periods = RedDateBL.GetPeriods();

                foreach (var period in periods)
                {
                    items.Add(new SelectListItem
