        [ARUMFeatureActionFilter(RateSettingPermissions.ProvRatesView)]
        public JsonResult GetRatePackages(string reportPeriod, int fiscalYear)
        {
            try
            {
                int providerID = (int)Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT];
                List<RatePackageViewModel> ratePackageViewModel = new List<RatePackageViewModel>();
                RateTypePeriodVersionViewModel typePeriodVersionView = new RateTypePeriodVersionViewModel();

                // As long as role name matches the name of the Rate Type this will work
                typePeriodVersionView.RateTypes = RedDateBL.GetAllRateTypes()
                    .Where(x => RateSettingProviderRatesPermissionBL.Create(x.Name))
                    .Select(x => new SelectItemList { value = x.RateTypeId.ToString(), text = x.Name }).ToList();

                typePeriodVersionView.CostReportPeriods = RedDateBL.GetPeriods().Select(x => new SelectItemList
                { value = x.FiscalYear.ToString(), text = x.PeriodCode }).ToList();
                // SP to Get CostReportVersion
                typePeriodVersionView.CostReportVersions = RedDateBL
                    .GetCostReportPeriodsVersions(reportPeriod, providerID)
                    .Select(x => new SelectItemList { value = x.Value, text = x.Text }).ToList();

                MSLC.ProviderProxy.Interfaces.IArumChowReviewChain arum_CHOP =
                    _providerServiceProxy.GetChowReviewChainByNewProviderID(RetrieveSession.Classification.ARUMToken,
                        providerID, "Rate/Provider");
                if (arum_CHOP.ChowReviews.Count() != 0)
                {
                    MSLC.ProviderProxy.Interfaces.Models.ChowReview chowReviews = arum_CHOP.ChowReviews
                        .Where(x => x.NewProviderID == providerID)
                        .OrderByDescending(x => x.ApproveDate)
                        .FirstOrDefault();
                    if (chowReviews != null)
                    {
                        typePeriodVersionView.CostReportVersions.AddRange(RedDateBL
                            .GetCostReportPeriodsVersions(reportPeriod, chowReviews.OldProviderID.Value)
                            .Select(x => new SelectItemList { value = x.Value, text = x.Text }).ToList());
                    }
                }

                var ratePackages = RedDateBL.GetProviderRatePackageDetails(providerID, fiscalYear);
                foreach (var ratePackage in ratePackages)
                {
                    ratePackageViewModel.Add(new RatePackageViewModel
                    {
                        RatePackageId =
                            ClientMapping.MapInternalIdToClientId(ratePackage.RatePackageId.ToString(), "ratepackage"),
                        ProviderCostReportId =
                            ClientMapping.MapInternalIdToClientId(ratePackage.ProviderCostReportId.ToString(),
                                "costreport"),
                        RateTypeId =
                            ClientMapping.MapInternalIdToClientId(ratePackage.RateTypeId.ToString(), "ratetype"),
                        ProviderId =
                            ClientMapping.MapInternalIdToClientId(ratePackage.ProviderId.ToString(), "provider"),
                        ProviderName = ratePackage.ProviderName,
                        ProviderNumber = ratePackage.ProviderNumber,
                        RateEffectiveDate = ratePackage.RateEffectiveDate.HasValue
                            ? ratePackage.RateEffectiveDate.Value.ToShortDateString()
                            : string.Empty,
                        RateType = ratePackage.RateType,
                        PeriodCode = ratePackage.PeriodCode,
                        CostReportVersion = ratePackage.CostReportVersion,
                        FinalRateAmount = ratePackage.FinalRateAmount,
                        Issuance = ratePackage.Issuance.HasValue
                            ? ratePackage.Issuance.Value.ToShortDateString()
                            : string.Empty,
                        Messages = ratePackage.Messages,
                        IsFinalized = IsRatePackageFinalized(ratePackage),
                        HLOARate = ratePackage.HLOARate,
                        LLOARate = ratePackage.LLOARate
                    });
                }

                if (ratePackages != null)
                {
                    ratePackages.ForEach(x => x.Dispose());
                    ratePackages.Clear();
                }

                return Json(new
                {
                    Success = true,
                    RateTypePeriodVersion = typePeriodVersionView,
                    RatePackagesViewModel = ratePackageViewModel
                },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, message = e.Message },
                    JsonRequestBehavior.AllowGet);
            }
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.ProvRatesView)]
        public JsonResult GetPeriodCostReportVersion(string reportPeriod, string rateType)
        {
            try
            {
                int rateTypeId = 0;
                int providerID = (int)Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT];
                RateTypePeriodVersionViewModel typePeriodVersionView = new RateTypePeriodVersionViewModel();

                if (!int.TryParse(ClientMapping.GetInternalIdFromClientId(rateType, "ratetype"), out rateTypeId) ||
                    rateTypeId == 0)
                {
                    throw new InvalidRateTypeException("Unable to find specified rate type.");
                }

                if (rateTypeId == (int)RateTypeEnumExtended.CHOP_SPEC)
                {
                    MSLC.ProviderProxy.Interfaces.IArumChowReviewChain arum_CHOP =
                        _providerServiceProxy.GetChowReviewChainByNewProviderID(
                            RetrieveSession.Classification.ARUMToken, providerID, "Rate/Provider");
                    if (arum_CHOP.ChowReviews.Count() != 0)
                    {
                        MSLC.ProviderProxy.Interfaces.Models.ChowReview chowReviews = arum_CHOP.ChowReviews
                            .Where(x => x.NewProviderID == providerID)
                            .OrderByDescending(x => x.ApproveDate)
                            .FirstOrDefault();
                        if (chowReviews != null)
                        {
                            typePeriodVersionView.CostReportVersions = RedDateBL
                                .GetCostReportPeriodsVersions(reportPeriod, chowReviews.OldProviderID.Value)
                                .Select(x => new SelectItemList { value = x.Value, text = x.Text }).ToList();
                        }
                    }
                }
                else
                {
                    Dictionary<int, string[]> rateTypesCostReports = new Dictionary<int, string[]>();
                    rateTypesCostReports[(int)RateTypeEnumExtended.Standard] =
                        new string[] { "4.1", "4.2", "4.3", "4.6", "4.8" };
                    rateTypesCostReports[(int)RateTypeEnumExtended.AUDIT_INITIAL] = new string[] { "4.90" };
                    rateTypesCostReports[(int)RateTypeEnumExtended.AUDIT_REVISED] = new string[] { "4.91" };
                    rateTypesCostReports[(int)RateTypeEnumExtended.AUDIT_FINAL] = new string[] { "4.92" };

                    //Get options for cost reports from dictionary, check if any of the texts start with any of the strings from array
                    typePeriodVersionView.CostReportVersions = RedDateBL
                        .GetCostReportPeriodsVersions(reportPeriod, providerID)
                        .Where(x => rateTypesCostReports[rateTypeId].Any(y => x.Text.StartsWith(y)))
                        .Select(x => new SelectItemList { value = x.Value, text = x.Text }).ToList();
                }

                return Json(new
                {
                    Success = true,
                    RateTypePeriodVersion = typePeriodVersionView
                },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, message = e.Message },
                    JsonRequestBehavior.AllowGet);
            }
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.ProvRatesCreate)]
        public JsonResult SaveRatePackages(string rateEffectiveDate, string rateType, string providerCostReportId,
            string ratePackageId, string periodCode, int fiscalYear)
        {
            List<ProviderRatePackage> ratePackages = null;
            try
            {
                int rateTypeId = 0;
                if (!int.TryParse(ClientMapping.GetInternalIdFromClientId(rateType, "ratetype"), out rateTypeId))
                    throw new InvalidRateTypeException("Unable to find specified rate type.");

                if (!RateSettingProviderRatesPermissionBL.Create(RateTypeEnumExtended.GetDescription(rateTypeId)))
                    throw new InvalidRequestException("Invalid Request");

                MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
                int providerID = (int)Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT];
                DateTime redDate = !string.IsNullOrWhiteSpace(rateEffectiveDate)
                    ? Convert.ToDateTime(rateEffectiveDate)
                    : DateTime.Now;
                int ratePackId = 0;
                int provCostReportId = 0;
                CalculationSet calculationSet = RedDateBL.GetCalculationSet(redDate);

                if (!int.TryParse(ClientMapping.GetInternalIdFromClientId(ratePackageId, "ratepackage"),
                        out ratePackId))
                {
                    throw new RatePackageNotFoundException("Unable to find specified rate package.");
                }

                if (rateTypeId == (int)RateTypeEnumExtended.Standard
                    || rateTypeId == (int)RateTypeEnumExtended.CHOP_SPEC
                    || rateTypeId == (int)RateTypeEnumExtended.AUDIT_INITIAL
                    || rateTypeId == (int)RateTypeEnumExtended.AUDIT_REVISED
                    || rateTypeId == (int)RateTypeEnumExtended.AUDIT_FINAL)
                {
                    if (!int.TryParse(ClientMapping.GetInternalIdFromClientId(providerCostReportId, "costreport"),
                            out provCostReportId) || provCostReportId == 0)
                    {
                        throw new CostReportNotFoundException("Unable to find specified Provider Cost Report Id.");
                    }
                }

                //MSLC.ProviderProxy.Interfaces.IArumDetailedProvider arum_provider = _providerServiceProxy.GetProviderInfoByARUMProviderID(RetrieveSession.Classification.ARUMToken, providerID, "Rate/Provider");
                //if (arum_provider.EffectiveDates != null && arum_provider.EffectiveDates.Count > 0)
                //{
                //    var effectiveDateRecs = arum_provider.EffectiveDates.OrderByDescending(ED => ED.EffectiveDate).ToList();
                //    DateTime? effectiveDate = effectiveDateRecs.Select(x => x.EffectiveDate).FirstOrDefault();
                //    DateTime? endDate = effectiveDateRecs.Select(x => x.EndDate).FirstOrDefault();
                //    if (endDate != null && redDate >= endDate)
                //    {
                //        throw new Exception("Unable to create a rate after the provider's closure date");
                //    }

                //    if (effectiveDate != null && redDate <= effectiveDate)
                //    {
                //        throw new Exception("Unable to create a rate before the provider's intial cerfication date");
                //    }
                //}

                RatePackage providerRatePackage = new RatePackage
                {
                    RatePackageId = ratePackId,
                    ProviderId = providerID,
                    RateTypeId = rateTypeId,
                    RateCostReportId =
                        0, //  RateCostReportId is set to 0 initially as it is updated in BL before save/ update
                    //  This update is done in BL as EF dbcontext refence is required to verify the related tables.
                    //  Refer BL logic.
                    RateEffectiveDate = redDate,
                    RulesDate = calculationSet.RuleDate,
                    LockedDate = null,
                    ReleaseDate = null,
                    LookupDate = DateTime.Now,
                    CalculationSetId = calculationSet.CalculationSetId,
                    NotApplicable = false,
                    ReIssueFlag = false,
                    CreatedOn = DateTime.Now,
                    CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                    LastUpdatedOn = DateTime.Now,
                    LastUpdatedBy = $"{myUser.FirstName} {myUser.LastName}",
                    RateAdjustmentSetId = null,
                    RateAmount = null,
                    Messages = string.Empty,
                    RateAdjustmentManual = null,
                    FinalRateAmount = null,
                    IsBaseYear = false,
                };

                //// Attempt to maek sure that the provider exists, and is ready to save. If not,
                //// then an error will show and there's nothing we can do about it here.
                //IArumDetailedProvider provider = _providerServiceProxy.GetProviderInfoByARUMProviderID(RetrieveSession.Classification.ARUMToken, providerID, "RateProvider");
                //MSLC.ProviderProxy.Interfaces.Models.ProviderEffectiveDate effDate = provider.EffectiveDates.FirstOrDefault(x => x.IsActive && x.EffectiveDate <= redDate && (x.EffectiveDate == null || x.EffectiveDate >= redDate));
                //if (effDate != null)
                //{
                //    RedDateBL.SaveRateProvider(new RateProvider {
                //        ProviderId = providerID,
                //        ProviderName = provider.Provider.Name,
                //        ProviderNumber = provider.Provider.MCAID
                //    }, true);
                //}
                //else
                //{
                //    RedDateBL.SaveRateProvider(new RateProvider
                //    {
                //        ProviderId = providerID,
                //        ProviderName = provider.Provider.Name,
                //        ProviderNumber = provider.Provider.MCAID
                //    }, false);
                //}

                RedDateBL.SaveRatePackages(providerRatePackage, provCostReportId, periodCode,
                    out List<RatePackage> newRatePackages);

                if (rateTypeId == (int)RateTypeEnumExtended.CHOP)
                {
                    foreach (RatePackage ratePackage in newRatePackages)
                    {
                        MSLC.ProviderProxy.Interfaces.IArumDetailedProvider arum_provider =
                            _providerServiceProxy.GetProviderInfoByARUMProviderID(
                                RetrieveSession.Classification.ARUMToken, ratePackage.ProviderId, "Rate/Provider");
                        MSLC.ProviderProxy.Interfaces.Models.ProviderEffectiveDate effDate = arum_provider
                            .EffectiveDates
                            .FirstOrDefault(x => x.EffectiveDate <= ratePackage.RateEffectiveDate
                                                 && (x.EndDate == null || x.EndDate >= ratePackage.RateEffectiveDate));

                        MSLC.ProviderProxy.Interfaces.IArumChowReviewChain arum_CHOP =
                            _providerServiceProxy.GetChowReviewChainByNewProviderID(
                                RetrieveSession.Classification.ARUMToken, ratePackage.ProviderId, "Rate/Provider");

                        if (arum_CHOP == null)
                        {
                            ratePackage.Messages =
                                AppendRateResponseMessage(ratePackage.Messages, RateBL.sChopNotFoundMesage);
                            ratePackage.FinalRateAmount = 0;
                            if (!ratePackage.LockedDate.HasValue) ratePackage.LockedDate = DateTime.Now;
                            continue;
                        }

                        // Ensure, if there is CHOP data, that this is before the RED being created on this screen.
                        MSLC.ProviderProxy.Interfaces.Models.ChowReview anyChopsBeforePeriodEnd = arum_CHOP.ChowReviews
                            .Where(x => x.NewProviderID == ratePackage.ProviderId)
                            .FirstOrDefault();

                        if (anyChopsBeforePeriodEnd == null)
                        {
                            ratePackage.Messages =
                                AppendRateResponseMessage(ratePackage.Messages, RateBL.sInvalidChopDateMessage);
                            ratePackage.FinalRateAmount = 0;
                            if (!ratePackage.LockedDate.HasValue) ratePackage.LockedDate = DateTime.Now;
                            continue;
                        }

                        ratePackage.RateTypeId = (int)RateTypeEnumExtended.CHOP;
                        // Get last rate for old provider id from database (RedDateBL call), and update this ratepackage object with the values.
                        if (!RateBL.LinkChopRatePackage(anyChopsBeforePeriodEnd.OldProviderID.Value, ratePackage,
                                effDate.EffectiveDate))
                        {
                            ratePackage.Messages =
                                AppendRateResponseMessage(ratePackage.Messages, RateBL.sChopRateLockedMessage);
                            ratePackage.FinalRateAmount = 0;
                            if (!ratePackage.LockedDate.HasValue) ratePackage.LockedDate = DateTime.Now;
                        }
                    }

                    if (newRatePackages.Count > 0) RateBL.SaveNewRatePackages(newRatePackages);
                }

                List<RatePackageViewModel> ratePackageViewModels = new List<RatePackageViewModel>();
                ratePackages = RedDateBL.GetProviderRatePackageDetails(providerID, fiscalYear);
                foreach (var ratePackage in ratePackages)
                {
                    ratePackageViewModels.Add(new RatePackageViewModel
                    {
                        RatePackageId =
                            ClientMapping.MapInternalIdToClientId(ratePackage.RatePackageId.ToString(), "ratepackage"),
                        ProviderCostReportId =
                            ClientMapping.MapInternalIdToClientId(ratePackage.ProviderCostReportId.ToString(),
                                "costreport"),
                        RateTypeId =
                            ClientMapping.MapInternalIdToClientId(ratePackage.RateTypeId.ToString(), "ratetype"),
                        ProviderName = ratePackage.ProviderName,
                        ProviderNumber = ratePackage.ProviderNumber,
                        RateEffectiveDate = ratePackage.RateEffectiveDate.HasValue
                            ? ratePackage.RateEffectiveDate.Value.ToShortDateString()
                            : string.Empty,
                        RateType = ratePackage.RateType,
                        PeriodCode = ratePackage.PeriodCode,
                        CostReportVersion = ratePackage.CostReportVersion,
                        RateAmount = ratePackage.RateAmount,
                        FinalRateAmount = ratePackage.FinalRateAmount,
                        Issuance = ratePackage.Issuance.HasValue
                            ? ratePackage.Issuance.Value.ToShortDateString()
                            : string.Empty,
                        Messages = ratePackage.Messages,
                        IsFinalized = IsRatePackageFinalized(ratePackage)
                    });
                }

                return Json(new
                {
                    Success = true,
                    RatePackagesViewModel = ratePackageViewModels
                }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, message = e.Message },
                    JsonRequestBehavior.AllowGet);
            }
            finally
            {
                if (ratePackages != null)
                {
                    ratePackages.ForEach(x => x.Dispose());
                    ratePackages.Clear();
                }
            }
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.ProvRatesView)]
        public ActionResult GetProviderRatesDetails(string ratePackageId)
        {
            List<ProviderRateInfoDetails> providerRatesDetails = null;

            try
