                ProviderRatesViewModel providerRatesViewModel = new ProviderRatesViewModel();
                List<ProviderRatesInfoViewModel>
                    providerRatesInfoViewModelList = new List<ProviderRatesInfoViewModel>();

                int rpId = 0;
                if (!int.TryParse(ClientMapping.GetInternalIdFromClientId(ratePackageId, "ratepackage"), out rpId) ||
                    rpId == 0)
