                    Success = true,
                    ProviderRatesViewModel = providerRatesViewModel
                },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, message = e.Message },
                    JsonRequestBehavior.AllowGet);
            }
            finally
            {
                if (providerRatesDetails != null)
                {
                    providerRatesDetails.ForEach(x => x.Dispose());
                    providerRatesDetails.Clear();
                }
            }
        }

        public ActionResult DeleteRatePackage(List<RatePackageViewModel> ratePackageData)
        {
            try
            {
                var invalidOption = ratePackageData.FirstOrDefault(x => !RateSettingProviderRatesPermissionBL.Delete(x.RateType));
                if (invalidOption != null)
                {
                    throw new InvalidRequestException($"Invalid Request");
                }

                foreach (RatePackageViewModel packageData in ratePackageData)
                {
                    if (packageData.RatePackageId == null || packageData.RatePackageId == "0")
                    {
                        continue;
                    }

                    int ratePackageId = 0;
                    if (!int.TryParse(ClientMapping.GetInternalIdFromClientId(packageData.RatePackageId, "ratepackage"),
                            out ratePackageId))
                    {
                        throw new RatePackageNotFoundException("Unable to find specified rate package.");
                    }

                    int providerCostReportId = 0;
                    if (!int.TryParse(
                            ClientMapping.GetInternalIdFromClientId(packageData.ProviderCostReportId, "costreport"),
                            out providerCostReportId))
                    {
                        throw new CostReportNotFoundException("Unable to find specified cost report for rate package.");
                    }

                    RedDateBL.DeleteRatePackage(ratePackageId);
                }

                return Json(new { Success = true }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
            finally
            {
                if (ratePackageData != null)
                {
                    ratePackageData.ForEach(x => x.Dispose());
                    ratePackageData.Clear();
                }
            }
        }

