            foreach (var rate in redDates)
            {
                ItemList.Add(new SelectListItem
                {
                    Text = rate.StartDate.ToString("MM/dd/yyyy"),
                    Value = ClientMapping.MapInternalIdToClientId(rate.DatabaseLookupVariableId.ToString(), "dblookup"),
                });
            }

            annualRateSettingViewModel.RedDate = null;
            annualRateSettingViewModel.RedDateList = ItemList;
            annualRateSettingViewModel.AnnualRateSettingDetailViewModel = new AnnualRateSettingDetailViewModel();

            annualRateSettingViewModel.HeaderText = AnnualRateSettingEnum.AnnualRateSettingDetails.GetDescription();
            annualRateSettingViewModel.DateText =
                AnnualRateSettingEnum.AnnualRateSettingDetails.GetDateType().GetDateMnemonic();

            redDates.Clear();

            return PartialView("AnnualRateSetting/_AnnualRateSettingDetails", annualRateSettingViewModel);
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult AddRed(RateEffectiveDateListing model)
        {
            List<DatabaseLookupValue> redDates = null;

            try
            {
                MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
                var addRED = RedDateBL.GetAllRedDbLookups().Where(x => x.StartDate == model.RateEffectiveDate).ToList();

                if (addRED.Count > 0)
                {
                    return Json(new { Success = false, Message = "RED Date Already Exists.", rpt = addRED },
                        JsonRequestBehavior.AllowGet);
                }

                RedDateBL.AddDbLookupRED(model, $"{myUser.FirstName} {myUser.LastName}");
                RateParametersTableViewModel modelRPT = new RateParametersTableViewModel();
                List<SelectListItem> ItemList = new List<SelectListItem>();

                List<RateEffectiveDateListing> rateEffectiveDates = new List<RateEffectiveDateListing>();
                redDates = RedDateBL.GetAllRedDbLookups();
                foreach (var rate in redDates)
                {
                    ItemList.Add(new SelectListItem
                    {
                        Text = rate.StartDate.ToString("MM/dd/yyyy"),
                        Value = ClientMapping.MapInternalIdToClientId(rate.DatabaseLookupVariableId.ToString(),
                            "dblookup"),
                    });
                }

                modelRPT.RedDateList = ItemList;
                return Json(new
                {
                    Success = true,
                    rpt = modelRPT
                },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, message = e.Message },
                    JsonRequestBehavior.AllowGet);
            }
            finally
            {
                if (redDates != null) redDates.Clear();
            }
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult GetREDRateInfo(DateTime redDate)
        {
            List<DatabaseLookupValue> redRateInfo = null;

            try
            {
                // Accommodate issues with time zones
                redDate = new DateTime(redDate.Year, redDate.Month, redDate.Day);

                List<DatabaseLookupValueViewModel> lstRateParameters = new List<DatabaseLookupValueViewModel>();
                AnnualRateSettingViewModel annualRateSettingViewModel = new AnnualRateSettingViewModel();
                MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;

                redRateInfo =
                    RedDateBL.GetREDRateTextBox(redDate, nameof(AnnualRateSettingEnum.AnnualRateSettingDetails));

                if (redRateInfo != null)
                {
                    foreach (DatabaseLookupValue rateParam in redRateInfo)
                    {
                        lstRateParameters.Add(new DatabaseLookupValueViewModel
                        {
                            DatabaseLookupVariableId =
                                ClientMapping.MapInternalIdToClientId(rateParam.DatabaseLookupVariableId.ToString(),
                                    "dblookup"),
                            StartDate = rateParam.StartDate,
                            DisplayName = rateParam.DisplayName,
