            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message });
            }
            finally
            {
                if (redRateInfo != null) redRateInfo.Clear();
            }
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult GetProvidersByRefreshList(DateTime redDate)
        {
            List<RateSettingPackage.ProviderPackage> providers = null;

            try
            {
                // Accommodate issues with time zones
                redDate = new DateTime(redDate.Year, redDate.Month, redDate.Day);

                MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;

                DateTime cutoffDate = DatabaseLookupGroupBL.GetDatabaseLookupCostReportCutoff(redDate);

                // Get Providers based on start and terms at the cutoff date.
                providers = GetActiveProviders(redDate);

                List<RatePackage> newRatePackages;

                switch (SimplifiedType)
                {
                    case "NF":
                        RateBL.RefreshProviderRatesForRED(redDate, cutoffDate, providers,
                            $"{myUser.FirstName} {myUser.LastName}", out newRatePackages);

                        ARUMApplicationServiceProxy _arumApplicationClient =
                            ARUMApplication.GetARUMApplicationProxy(new ClassificationDTO { ARUMToken = Guid.Empty });

                        //foreach (RatePackage ratepackage in newRatePackages)
                        for (int i = newRatePackages.Count - 1; i >= 0; i--)
                        {
                            RatePackage ratepackage = newRatePackages[i];

                            MSLC.ProviderProxy.Interfaces.IArumChowReviewChain arum_CHOP =
                                _providerServiceProxy.GetChowReviewChainByNewProviderID(
                                    RetrieveSession.Classification.ARUMToken, ratepackage.ProviderId, "Rate/Provider");
                            // Ensure, if there is CHOP data, that this is after the cost report end date - which would make this the "first" time the provider is rated, even if it is chopped later in the year.
                            MSLC.ProviderProxy.Interfaces.Models.ChowReview anyChopsBeforePeriodEnd = arum_CHOP
                                .ChowReviews
                                .FirstOrDefault(x => x.NewProviderID == ratepackage.ProviderId);

                            if (arum_CHOP == null || anyChopsBeforePeriodEnd == null)
                            {
                                // This is a new provider facility!
                                ratepackage.RateTypeId = (int)RateTypeEnumExtended.NewFacility;
                            }
                            else
                            {
                                RateSettingPackage.ProviderPackage provider = providers
                                    .FirstOrDefault(x => x.ProviderId == ratepackage.ProviderId);
                                RateSettingPackage.ProviderPackage.ProviderEffectiveDate effDate = provider
                                   .EffectiveDates
                                   .FirstOrDefault(x =>
                                       x.DateEffective <= redDate && (x.EndDate is null || x.EndDate >= redDate));

                                // If approval date is AFTER the RED, this is a new facility that WILL become a CHOP later... :O
                                if (effDate.DateEffective > redDate)
                                    ratepackage.RateTypeId = (int)RateTypeEnumExtended.NewFacility;
                                else
                                {
                                    // Check if this is valid - it may be that this provider should have a cost report for this RED even if
                                    // it was a CHOP recently...
                                    switch (RateBL.GetChopSourceFromDates(redDate, effDate.DateEffective.Value))
                                    {
                                        case ChopSourceEnum.BASE_YEAR_MEDIANS:
                                        case ChopSourceEnum.PRIOR_PROVIDER_DATA:
                                            // Both of these are valid for CHOP rate type.
                                            ratepackage.RateTypeId = (int)RateTypeEnumExtended.CHOP;
                                            // Get last rate for old provider id from database (RedDateBL call), and update this ratepackage object with the values.
                                            if (!RateBL.LinkChopRatePackage(anyChopsBeforePeriodEnd.OldProviderID.Value,
                                                    ratepackage, effDate.DateEffective))
                                            {
                                                ratepackage.Messages = AppendRateResponseMessage(ratepackage.Messages,
                                                    RateBL.sChopRateLockedMessage);
                                                ratepackage.FinalRateAmount = 0;
                                                if (!ratepackage.LockedDate.HasValue)
                                                    ratepackage.LockedDate = DateTime.Now;
                                            }

                                            break;

                                        default:
                                            // This should have a cost report by now. :(
                                            // Just like a provider that had previous cost reports, but none for this period, remove it (do not add)!
                                            newRatePackages.Remove(ratepackage);
                                            RedDateBL.DeleteRatePackage(ratepackage.RatePackageId);
                                            break;
                                    }
                                }
                            }
                        }

                        break;

                    case "ICF":
                        OperationEngineIcfRateSetting engine =
                            new OperationEngineIcfRateSetting(RateBL.GetContextInstance());
                        engine.providerLists.Add(new ProviderList
                        {
                            Type = "ICF",
                            Providers = providers
                        });
                        newRatePackages =
                            engine.RefreshListRED(redDate, cutoffDate, $"{myUser.FirstName} {myUser.LastName}");
                        break;

                    default:
                        throw new UnknownServiceClassificationException("Unknown serice classification");
                }

                if (newRatePackages.Count > 0) RateBL.SaveNewRatePackages(newRatePackages);

                // Pull all rates (new and skipped) from database.
                AnnualRateSettingViewModel annualRateSettingViewModel = GetREDProviderInfo(redDate);
                return Json(new
                {
                    Success = true,
                    AnnualRateSettingViewModel = annualRateSettingViewModel
                },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message });
            }
            finally
            {
                if (providers != null)
                {
                    providers.ForEach(x => x.Dispose());
                    providers.Clear();
                }
            }
        }

