        public JsonResult GenerateCMIOverrideReport(string fiscalYear, string annualRateSettingEnum)
        {
            try
            {
                DateTime currDate = DateTime.Now;
                DateTime dateTime = new DateTime();

                if (!string.IsNullOrEmpty(fiscalYear))
                {
                    switch (annualRateSettingEnum)
                    {
                        case nameof(AnnualRateSettingEnum.SemiAnnualCaseMixScores):
                        case nameof(AnnualRateSettingEnum.QuarterlyCaseMixScores):
                        case nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM):
                        case nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY):
                            if (SimplifiedType == "NF")
                            {
                                if (!DateTime.TryParse(fiscalYear, out dateTime))
                                {
                                    return Json(new
                                    {
                                        Success = false,
                                        Message = "Invalid input of fiscal year; please enter a valid quaterly date."
                                    }, JsonRequestBehavior.AllowGet);
                                }
                            }
                            else
                            {
                                dateTime = new DateTime(int.Parse(fiscalYear), 07, 01);
                            }

                            break;

                        case nameof(AnnualRateSettingEnum.AnnualCaseMixScores):
                            // Validate input
                            if (!int.TryParse(fiscalYear, out int year))
                            {
                                return Json(new
                                {
                                    Success = false,
                                    Message = "Invalid input of fiscal year; please simply enter the year number."
                                }, JsonRequestBehavior.AllowGet);
                            }

                            dateTime = new DateTime(int.Parse(fiscalYear), 01, 01);
                            break;

                        default:
                            throw new Exception("Invalid type for operation.");
                    }
                }

                var filenameLiteral = annualRateSettingEnum;
                if (filenameLiteral == nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY))
                {
                    filenameLiteral = nameof(AnnualRateSettingEnum.QuarterlyCaseMixScores);
                }

                string fullPath = "";
                var fileName =
                    $"{SimplifiedType}_CMIOverrideReport_{filenameLiteral}_Run_{currDate:yyyyMMdd}.xlsx"
                        .ToSafeFileName();
                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    //Save the file to the path of the current user's temporary folder
                    fullPath = Path.Combine(Path.GetTempPath(), fileName);
                    //Instantiate the excel application object.
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;

                    //The workbook is created
                    IWorkbook workbook = application.Workbooks.Create(1);

                    //The first worksheet object in the worksheets collection is accessed
                    IWorksheet worksheet = workbook.Worksheets[0];

                    var row = 1;
                    worksheet.Range[row, 3].Text = "CMI Override Report";

                    row++;
                    int col = 1;
                    DataTable dataTable = new DataTable();
                    var groupDataTable = RateBL.GenerateCMIOverrideReport(dateTime, annualRateSettingEnum, SimplifiedType);

                    if (groupDataTable.Rows.Count == 0)
                    {
                        throw new Exception(" No records met the criteria for the report.");
                    }

                    if (groupDataTable.Columns.Count > 0)
                    {
                        AnnualRateSettingEnum inputAsEnum =
                            (AnnualRateSettingEnum)Enum.Parse(typeof(AnnualRateSettingEnum), annualRateSettingEnum);
                        //Getting the Enum Description 
                        string enumDescription = inputAsEnum.GetDescription();

                        if (row == 2)
                        {
                            foreach (DataColumn column in groupDataTable.Columns)
                            {
                                worksheet.Range[row, col].Text = (column.ColumnName);
                                worksheet.Range[row, col].WrapText = true;
                                col++;
                            }
                        }

                        int j = 0;
                        foreach (DataRow rowData in groupDataTable.Rows)
                        {
                            row++;
                            col = 1;
                            worksheet.Range[row, col].Text = Convert.ToDateTime(groupDataTable.Rows[j][col - 1])
                                .ToString("MM/dd/yyyy");
                            col++;
                            worksheet.Range[row, col].Text = groupDataTable.Rows[j][col - 1].ToString();
                            col++;
                            worksheet.Range[row, col].Text = enumDescription;
                            col++;
                            worksheet.Range[row, col].Number = Convert.ToDouble(groupDataTable.Rows[j][col - 1]);
                            col++;
                            //PDPM Quarterly Case Mix Scores have an extra column that needs to be accounted for compared to the others
                            if (annualRateSettingEnum == nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM))
                            {
                                worksheet.Range[row, col].Number = Convert.ToDouble(groupDataTable.Rows[j][col - 1]);
                                col++;
                            }

                            worksheet.Range[row, col].Number = Convert.ToInt32(groupDataTable.Rows[j][col - 1]);
                            col++;
                            worksheet.Range[row, col].Text = Convert.ToDateTime(groupDataTable.Rows[j][col - 1])
                                .ToString("MM/dd/yyyy hh:mm:ss tt");
                            col++;
                            j++;
                        }
                    }

                    worksheet.UsedRange.AutofitRows();
                    worksheet.UsedRange.AutofitColumns();
                    worksheet.UsedRange.CellStyleName = CreateExcelStyle(workbook, "BodyStyle"); //bodyStyleName;
                    worksheet.Columns[0].NumberFormat = @"mm\/dd\/yyyy";
                    worksheet.Columns[1].NumberFormat = "0000000";
                    worksheet.Columns[3].NumberFormat = "0.0000";

                    //PDPM Quarterly Case Mix Scores have an extra column that needs to be accounted for compared to the others
                    string cellRange = string.Empty;
                    if (annualRateSettingEnum == nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM))
                    {
                        cellRange = "A1:G1";
                        worksheet.Columns[4].NumberFormat = "0.0000";
                        worksheet.Columns[5].NumberFormat = "0";
                        worksheet.Columns[6].NumberFormat = @"mm\/dd\/yyyy h:mm:ss";
                        worksheet.SetColumnWidth(3, 11);
                        worksheet.SetColumnWidth(4, 11);
                        worksheet.SetColumnWidth(5, 11);
                        worksheet.SetColumnWidth(6, 11);
                    }
                    else
                    {
                        cellRange = "A1:F1";
                        worksheet.Columns[4].NumberFormat = "0";
                        worksheet.Columns[5].NumberFormat = @"mm\/dd\/yyyy h:mm:ss";
                        worksheet.SetColumnWidth(4, 11);
                        worksheet.SetColumnWidth(5, 11);
                    }

                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;
                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.PageSetup.FitToPagesWide = 1;
                    worksheet.Rows[1].CellStyleName = CreateExcelStyle(workbook, "HeaderStyle"); //headerStyleName;
                    worksheet.Rows[0].CellStyleName = CreateExcelStyle(workbook, "TitleStyle"); //titleStyleName;

                    //Merge the Cells
                    worksheet.Range[cellRange].Merge();
                    worksheet.Range[cellRange].HorizontalAlignment = ExcelHAlign.HAlignCenter;
                    worksheet.Range[3, 1].FreezePanes();

                    if (worksheet.Rows.Length > 2)
                    {
                        worksheet.Range[3, 1].FreezePanes();
                    }

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;
                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create, FileAccess.ReadWrite))
                    {
                        report.WriteTo(fileStream);
                    }
                }

                return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message });
            }
        }

