        #region Active Provider Details Report

        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult GenerateActiveProviderDetailsReport()
        {
            try
            {
                DateTime currDate = DateTime.Now;
                List<DatabaseLookupGroup> lookupGroups = null;
                List<DatabaseLookupGroupData> dbLookupGroupData = null;
                List<Provider> providersViewModel = null;
                //IAllProviders providers = null;

                string fullPath = "";
                var fileName = $"{SimplifiedType}_Active_Providers_Run_{currDate:yyyyMMdd}.xlsx".ToSafeFileName();
                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    //Save the file to the path of the current user's temporary folder
                    fullPath = Path.Combine(Path.GetTempPath(), fileName);
                    //Instantiate the excel application object.
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;

                    //The workbook is created
                    IWorkbook workbook = application.Workbooks.Create(1);

                    //The first worksheet object in the worksheets collection is accessed
                    IWorksheet worksheet = workbook.Worksheets[0];
                    var row = 1;

                    // Use the new call to providers. It pulls back only the information needed and runs very fast.
                    // Note that this routine pulls back ALL providers, so it can be used to find related providers.
                    var providers = GetAllProviderList(RetrieveSession.Classification.ARUMToken, false, true, false,
                            true, true, false, false, true, true, "RateController.GenerateActiveProviderDetailsReport")
                        .lstProviders;
                    providersViewModel = providers
                        // NOTE: this method will always return active providers...
                        .Where(x => RateProviderBL.SelectByProviderEffectiveDate(true, x.EffectiveDates))
                        .OrderBy(x => x.MCAID)
                        .ToList();
                    List<Provider> allProviders = new List<Provider>();
                    allProviders.AddRange(providers);

                    switch (SimplifiedType)
                    {
                        case "NF":
                            worksheet.Range[row, 1].Text = "Nursing Facility Active Provider Details";
                            row++;
                            lookupGroups =
                                RateBL.GetDatabaseLookupGroupList(AnnualRateSettingEnum.SemiAnnualCaseMixScores);
                            dbLookupGroupData =
                                RateBL.GetDatabaseLookupGroupDataList(AnnualRateSettingEnum.SemiAnnualCaseMixScores);
                            CreateNFAPDHeaders(worksheet, row);
                            CreateNFAPDItem(worksheet, providersViewModel, allProviders, lookupGroups,
                                dbLookupGroupData, row);
                            break;
                        case "ICF":
                            worksheet.Range[row, 1].Text = "ICF IID Active Provider Details";
                            row++;
                            lookupGroups = RateBL.GetDatabaseLookupGroupList(AnnualRateSettingEnum.AnnualCaseMixScores);
                            dbLookupGroupData =
                                RateBL.GetDatabaseLookupGroupDataList(AnnualRateSettingEnum.AnnualCaseMixScores);
                            CreateICFAPDHeaders(worksheet, row);
                            CreateICFAPDItem(worksheet, providersViewModel, lookupGroups, dbLookupGroupData, row);
                            break;
                        default:
                            break;
                    }

                    worksheet.UsedRange.AutofitRows();
                    worksheet.UsedRange.AutofitColumns();
                    worksheet.UsedRange.CellStyleName = CreateExcelStyle(workbook, "BodyStyle"); //bodyStyleName;
                    worksheet.Columns[0].NumberFormat = "0000000";
                    worksheet.Columns[6].NumberFormat = "000000000";

                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;
                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.PageSetup.FitToPagesWide = 1;
                    worksheet.Rows[1].CellStyleName = CreateExcelStyle(workbook, "HeaderStyle"); //headerStyleName;
                    worksheet.Rows[0].CellStyleName = CreateExcelStyle(workbook, "TitleStyle"); //titleStyleName;

                    if (SimplifiedType == "NF")
                    {
                        //Merge the Cells
                        worksheet.Range["A1:J1"].Merge();
                        worksheet.Columns[3].NumberFormat = @"mm\/dd\/yyyy";
                        worksheet.Columns[4].NumberFormat = "0";
                        worksheet.Columns[8].NumberFormat = "#;#";
                        worksheet.Columns[9].NumberFormat = "#;#";
                    }
                    else if (SimplifiedType == "ICF")
                    {
                        //Merge the Cells
                        worksheet.Range["A1:H1"].Merge();
                        worksheet.Columns[2].NumberFormat = @"mm\/dd\/yyyy";
                        worksheet.Columns[4].NumberFormat = "#;#";
                        worksheet.Columns[5].NumberFormat = "#;#";
                        worksheet.Columns[6].NumberFormat = "#;#";
                        worksheet.Columns[7].NumberFormat = "#;#";
                    }

                    if (worksheet.Rows.Length > 2)
                    {
                        worksheet.Range[3, 1].FreezePanes();
                    }


                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;
                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create, FileAccess.ReadWrite))
                    {
                        report.WriteTo(fileStream);
                    }
                }

                return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message });
            }
        }

