        public void CreateICFAPDItem(IWorksheet workSheet, List<Provider> providers,
            List<DatabaseLookupGroup> lookupGroups, List<DatabaseLookupGroupData> dbLookupGroupData,
            int row)
        {
            IAddressCodeFunctions addressCodeFunctions =
                CostReportBL.GetInstanceAddressCodeFunctions(RetrieveSession.Classification);

            var activeStatuses = new List<string>
            {
                "CHA",
                "IEN",
                "WDG",
                "REN"
            };

            foreach (var arum_provider in providers)
            {
                var arum_Status = _providerServiceProxy.GetAllProviderStatusesByProviderID(
                    RetrieveSession.Classification.ARUMToken, arum_provider.ProviderID, "Rate/CreateICFAPDItem");
                if (arum_Status.ProviderStatuses.Any())
                {
                    var providerStatusRec = arum_provider
                        .ProviderStatuses
                        .Where(x => x.IsActive && x.Type.ToUpper() == "MEDICAID")
                        .OrderByDescending(x => x.EffectiveDate)
                        .FirstOrDefault();
                    if (providerStatusRec == null || !activeStatuses.Contains(providerStatusRec.Status.ToUpper()))
                    {
                        // All statuses will be represented in these records, so this is not an error.
                        continue;
                    }
                }
                else
                {
                    continue;
                }

                row++;

                if (arum_provider != null)
                {
                    DateTime? initialCertificationDate = null;
                    var countyCode = "";
                    var peerGroup = "";
                    int costReportYear = 0;
                    var annualScores = "";
                    if (arum_provider.EffectiveDates != null && arum_provider.EffectiveDates.Count > 0)
                    {
                        var effectiveDateRec = arum_provider.EffectiveDates
                            .OrderByDescending(x => x.DateEffective).FirstOrDefault();
                        DateTime? effectiveDate = effectiveDateRec.DateEffective;
                        initialCertificationDate = effectiveDate;
                        countyCode = arum_provider.EffectiveDates.Select(x => x.County).FirstOrDefault();
                    }

                    #region Get PeerGroup Info & Beds Count

                    string county = addressCodeFunctions.GetCountyNameByCountyCode(Convert.ToInt32(countyCode));
                    int certifiedBeds = RateBL.GetLastCertifiedBedCount(arum_provider.ProviderID);
                    int licensedBeds = RateBL.GetLastLicensedBeds(arum_provider.ProviderID);

                    // Get Calculation data.
                    var details = RateBL.GenerateActiveProviderDetailsReport(arum_provider.MCAID);

                    if (details != null && details.Rows.Count >= 1)
                    {
                        if (!string.IsNullOrWhiteSpace(details.Rows[0]["PeerGroup"].ToString()))
                        {
                            peerGroup = details.Rows[0]["PeerGroup"].ToString();
                        }

                        if (!string.IsNullOrWhiteSpace(details.Rows[0]["CostReportYearEnd"].ToString()))
                        {
                            costReportYear = Convert.ToDateTime(details.Rows[0]["CostReportYearEnd"].ToString()).Year;
                            annualScores = RateBL.GetCMIScores(new DateTime(costReportYear, 01, 01),
                                arum_provider.MCAID, lookupGroups, dbLookupGroupData,
                                AnnualRateSettingEnum.AnnualCaseMixScores);
                        }
                    }
                    else
                    {
                        List<DatabaseLookupValue> dbLookups =
                            DatabaseLookupVariableBL.GetAnnualRED(AnnualRateSettingEnum.PeerGroupFiveA);
                        // Get the peer groups
                        peerGroup = RateBL.GetIcfPeerGroup(certifiedBeds, dbLookups, arum_provider.MCAID.ToString());
                    }

                    #endregion

                    #region Print info in excel

                    int column = 1;
                    workSheet.Range[row, column].Text = arum_provider.MCAID.ToString();
                    workSheet.Range[row, column].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                    column++;
                    workSheet.Range[row, column].Text = arum_provider.Name;
                    workSheet.Range[row, column].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                    column++;
                    workSheet.Range[row, column].Text = initialCertificationDate != null
                        ? Convert.ToDateTime(initialCertificationDate).ToString("MM/dd/yyyy")
                        : "";
                    column++;
                    workSheet.Range[row, column].Text = county;
                    column++;
                    workSheet.Range[row, column].Text =
                        arum_provider.ProviderAttributes.FirstOrDefault(i => i.AttributeKey == "REVIEW_TYPE")
                            ?.AttributeValue ?? string.Empty;
                    column++;
                    workSheet.Range[row, column].Text = peerGroup;
                    column++;
                    if (certifiedBeds == 0)
                        workSheet.Range[row, column].Text = "";
                    else
                        workSheet.Range[row, column].Number = certifiedBeds;
                    column++;
                    if (licensedBeds == 0)
                        workSheet.Range[row, column].Text = "";
                    else
                        workSheet.Range[row, column].Number = licensedBeds;
                    column++;

                    #endregion
                }
            }
