        #region Annual Rate Packages Report

        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult AnnualRatePackagesReport()
        {
            AnnualRateSettingViewModel annualRateSettingViewModel = new AnnualRateSettingViewModel();
            List<SelectListItem> periodItems = new List<SelectListItem>();

            List<int> sfys = RedDateBL.GetRedDateYears();

            foreach (var sfy in sfys)
            {
                periodItems.Add(new SelectListItem
                {
                    Text = sfy.ToString(), // This needs to be the SFY, which is the year of the end of the fiscal span.
                    Value = sfy.ToString()
                });
            }

            sfys.Clear();

            annualRateSettingViewModel.RedDateList = new List<SelectListItem>();
            annualRateSettingViewModel.PeriodList = periodItems;
            return PartialView("Report/_AnnualRatePackagesReport", annualRateSettingViewModel);
        }

        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult GetRedDatesForSFY(string sfy)
        {
            List<SelectListItem> list = new List<SelectListItem>();
            try
            {
                if (string.IsNullOrWhiteSpace(sfy))
                    throw new ArgumentException($"Invalid SFY, please try again.");

                if (!int.TryParse(sfy, out int i))
                    throw new ArgumentException($"Invalid SFY {sfy}, please try again.");

                DateTime start = new DateTime(i - 1, 7, 1);
                DateTime end = new DateTime(i, 6, 30);

                List<DatabaseLookupValue> redDates = RedDateBL.GetAllRedDbLookups();
                foreach (var rate in redDates)
                {
                    if (start <= rate.StartDate && rate.StartDate <= end)
                    {
                        list.Add(new SelectListItem
                        {
                            Text = rate.StartDate.ToString("MM/dd/yyyy"),
                            Value = ClientMapping.MapInternalIdToClientId(rate.DatabaseLookupVariableId.ToString(), "dblookup"),
                        });
                    }
                }
                redDates.Clear();

                return Json(new { Success = true, data = list }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message });
            }
        }

        public ActionResult GetProviderInfoBySelectedRED(DateTime redDate)
        {
            List<RatePackageInformationDetails> providerList = null;

            try
            {
                // Accommodate issues with time zones
                redDate = new DateTime(redDate.Year, redDate.Month, redDate.Day);

                AnnualRateSettingViewModel annualRateSettingViewModel = new AnnualRateSettingViewModel();
                MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
                if (myUser == null || !myUser.Roles.Any())
                {
                    return RedirectToAction("Login", "Home");
                }

                List<RatePackageViewModel> listProviders = new List<RatePackageViewModel>();
                RatePackageViewModel providerInfoVM;
                providerList = RedDateBL.GetREDProviderRateInfo(redDate).Where(x => x.FinalRateAmount != null).ToList();
                if (providerList != null && providerList.Count > 0)
                {
                    foreach (RatePackageInformationDetails model in providerList)
                    {
                        providerInfoVM = new RatePackageViewModel
                        {
                            RatePackageId =
                                ClientMapping.MapInternalIdToClientId(model.RatePackageId.ToString(), "ratepackage"),
                            RateTypeId = ClientMapping.MapInternalIdToClientId(model.RateTypeId.ToString(), "ratetype"),
                            RateType = RateTypeEnumExtended.GetDescription(model.RateTypeId),
                            Rate = model.Rate,
                            FinalRateAmount = model.FinalRateAmount,
                            Issuance =
                                model.Issuance.HasValue ? model.Issuance.Value.ToShortDateString() : string.Empty,
                            ProviderName = model.ProviderName,
                            ProviderNumber = model.ProviderNumber,
                            ProviderId = ClientMapping.MapInternalIdToClientId(model.ProviderId.ToString(), "provider"),
                            RateEffectiveDate = model.RateEffectiveDate.HasValue
                                ? model.RateEffectiveDate.Value.ToShortDateString()
                                : string.Empty
                        };
                        listProviders.Add(providerInfoVM);
                    }
                }

                providerList.Clear();

                List<Column> cols = new List<Column>();
                cols.Add(new Column() { Field = "ProviderNumber", HeaderText = "Prov Num", Width = "50" });
                cols.Add(new Column() { Field = "ProviderName", HeaderText = "Prov Name", Width = "100" });
                cols.Add(new Column() { Field = "RateType", HeaderText = "Rate Type", Width = "50" });
                cols.Add(new Column() { Field = "FinalRateAmount", HeaderText = "Rate", Width = "50" });
                cols.Add(new Column() { Field = "Issuance", HeaderText = "Issuance", Width = "50" });

                annualRateSettingViewModel.GridColumns = cols;
                annualRateSettingViewModel.RatePackageViewModelList = listProviders;
                return Json(new
                {
                    Success = true,
                    AnnualRateSettingViewModel = annualRateSettingViewModel
                },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.ProvRatesGenRatePackage)]
        public JsonResult GenerateAnnualRatePackages(List<RatePackageViewModel> providerData)
        {
            try
            {
                var myUser = RetrieveSession.ARUMUser;
                DateTime currDate = DateTime.Now;

                //add file names to the array.
                List<string> fileList = new List<string>();
                var reportList = new List<string>();

                // Get internal ids for all of the rate packages specified.
                foreach (RatePackageViewModel provider in providerData)
                {
                    //initialize for Table of Content
                    int curPageNo = 0;
                    int startSch6_22PageNo = 0;
                    int endSch6_22PageNo = 0;
                    int sch6_23PageNo = 0;
                    int startSch6_3PageNo = 0;
                    int endSch6_3PageNo = 0;
                    int sch9PageNo = 0;
                    //initialize for ICF New Facility RP8
                    bool hasTransferredBeds = false;
                    int rp8StartLineNo = 0;

                    if (!DateTime.TryParse(provider.RateEffectiveDate, out DateTime docEffectiveDate))
                        throw new ArgumentException("Invalid input of effective date; please enter a valid effective date.");

                    int ratePackageId = 0;
                    if (int.TryParse(ClientMapping.GetInternalIdFromClientId(provider.RatePackageId, "ratepackage"),
                            out int i))
                    {
                        ratePackageId = i;
                    }

                    if (i == 0) continue; // Skip any invalid rate packages

                    int rateTypeId = 0;
                    if (int.TryParse(ClientMapping.GetInternalIdFromClientId(provider.RateTypeId, "ratetype"),
                            out int r))
                    {
                        rateTypeId = r;
                    }

                    int providerId = 0;
                    if (int.TryParse(ClientMapping.GetInternalIdFromClientId(provider.ProviderId, "provider"),
                            out int p))
                    {
                        providerId = p;
                    }

                    var reportDataList = RateBL.GetRatePackageReportDataRO(ratePackageId);

                    var ratePackageReportTemplateLocation = "";
                    string initialCertificationDate =
                        reportDataList.FirstOrDefault(x => x.CalcName == "InitialCertificationDate")?.DataValue ??
                        string.Empty;
                    if (!DateTime.TryParse(initialCertificationDate, out DateTime initiCertDate))
                        throw new ArgumentException("Invalid Initial Certification Date.");

                    int pageNo = 0;
                    switch (SimplifiedType)
                    {
                        case "NF":
                            switch (rateTypeId)
                            {
                                case (int)RateTypeEnumExtended.Standard:
                                    ratePackageReportTemplateLocation =
                                        ARUMConfigurationOHFI.StandardRatePackageReportTemplateLocation(RetrieveSession
                                            .Classification);
                                    break;

                                case (int)RateTypeEnumExtended.CHOP:
                                    //When RedDate = Initial certification date use "OhioNFCHOPInitCertRatePackageReportTemplate".
                                    //For a 01/01/ RedDate if the initial certification date is after the previous 07/01/ but before the  01/01/ RedDate 
                                    //then use "OhioNFCHOPInitCertRatePackageReportTemplate".For example if the initial certification date is 8/1 /2025 the 1/1/2026
                                    //would use "OhioNFCHOPInitCertRatePackageReportTemplate".

                                    //Otherwise for 01/01/ RedDate use "OhioNFCHOPRatePackageReportTemplate".For example if initial certification date is 06/25/2025 the 01/01/2026
                                    //would use "OhioNFCHOPRatePackageReportTemplate".
                                    //For 07/01/ rate always use "OhioNFCHOPRatePackageReportTemplate".

                                    if ((initiCertDate == docEffectiveDate) || (docEffectiveDate.Month == 1 &&
                                            docEffectiveDate.Day == 1 &&
                                            initiCertDate > new DateTime(docEffectiveDate.Year - 1, 7, 1) &&
                                            (initiCertDate < new DateTime(docEffectiveDate.Year, 1, 1))))
                                    {
                                        // CHOP Initial Certification Rate package
                                        ratePackageReportTemplateLocation =
                                            ARUMConfigurationOHFI.CHOPInitCertRatePackageReportTemplateLocation(
                                                RetrieveSession.Classification);
                                    }
                                    else
                                    {
                                        // CHOP Rate package 
                                        ratePackageReportTemplateLocation =
                                            ARUMConfigurationOHFI.CHOPRatePackageReportTemplateLocation(RetrieveSession
                                                .Classification);
                                    }

                                    break;

                                case (int)RateTypeEnumExtended.NewFacility:
                                    // if the InitialCertificationDate and RedDate do not have their day and month to be 7/1 or 1/1 and if the InitialCertificationDate matches  
                                    // with the RedDate then "OhioNFNewFacilityInitCertRatePackageReportTemplate" report will be generated. 
                                    // In all other cases, "OhioNFNewFacilityRatePackageReportTemplate" report will be generated.
                                    if (!(initiCertDate.Day == 1 && initiCertDate.Month == 7) &&
                                        !(initiCertDate.Day == 1 && initiCertDate.Month == 1)
                                        && !(docEffectiveDate.Day == 1 && docEffectiveDate.Month == 7) &&
                                        !(docEffectiveDate.Day == 1 && docEffectiveDate.Month == 1)
                                        && (initiCertDate == docEffectiveDate))
                                    {
                                        // New Facility Initial Certification Rate package 
                                        ratePackageReportTemplateLocation =
                                            ARUMConfigurationOHFI.NewFacilityInitCertRatePackageReportTemplateLocation(
                                                RetrieveSession.Classification);
                                    }
                                    else
                                    {
                                        if (docEffectiveDate.Year < 2026)
                                        {
                                            // New Facility Rate package 
                                            ratePackageReportTemplateLocation =
                                                ARUMConfigurationOHFI.NewFacilityRatePackageReportTemplateLocation(
                                                    RetrieveSession.Classification);
                                        }
                                        else
                                        {
                                            if (initiCertDate >= new DateTime(2026, 1, 1))
                                            {
                                                // New Facility Rate package with "NoPhaseInTemplate" 
                                                ratePackageReportTemplateLocation =
                                                    ARUMConfigurationOHFI
                                                        .NewFacilityRatePackageReportNoPhaseInTemplateLocation(
                                                            RetrieveSession.Classification);
                                            }
                                            else
                                            {
                                                // New Facility Rate package with "PhaseInTemplate" 
                                                ratePackageReportTemplateLocation =
                                                    ARUMConfigurationOHFI
                                                        .NewFacilityRatePackageReportWithPhaseInTemplateLocation(
                                                            RetrieveSession.Classification);
                                            }
                                        }
                                    }

                                    break;
                            }

                            //Getting the template file based on EffectiveDate
                            ratePackageReportTemplateLocation = RateBL.GetRatePackageTemplateLocation("NF",
                                ratePackageReportTemplateLocation, docEffectiveDate);

                            break;

                        case "ICF":
                            switch (rateTypeId)
                            {
                                case (int)RateTypeEnumExtended.Standard:
                                    ratePackageReportTemplateLocation =
                                        ARUMConfigurationOHFI.StandardRatePackageReportTemplateLocation(RetrieveSession
                                            .Classification);
                                    break;

                                case (int)RateTypeEnumExtended.CHOP:
                                    // CHOP Initial Certification Rate package
                                    ratePackageReportTemplateLocation =
                                        ARUMConfigurationOHFI.CHOPInitCertRatePackageReportTemplateLocation(
                                            RetrieveSession.Classification);
                                    break;

                                case (int)RateTypeEnumExtended.CHOP_SPEC:
                                    // CHOP SPECIAL Rate package 
                                    ratePackageReportTemplateLocation =
                                        ARUMConfigurationOHFI.CHOPRatePackageReportTemplateLocation(RetrieveSession
                                            .Classification);
                                    break;

                                case (int)RateTypeEnumExtended.NewFacility:
                                    bool isCertifiedBeds = false;
                                    bool isTransferredBeds = false;
                                    int certifiedBedsCount =
                                        RateBL.GetCertifiedBedCountByDate(providerId, docEffectiveDate);
                                    int sfyYear = docEffectiveDate.Month < 7
                                        ? docEffectiveDate.Year
                                        : docEffectiveDate.Year + 1;
                                    DateTime redDate = new DateTime(sfyYear, 07, 01);
                                    int transferredBedsCount = RateBL.GetAllCertifiedBedTransfers(providerId)
                                        ?.Where(x => x.EffectiveDate >= DateTime.Parse(initialCertificationDate)
                                                     && x.EffectiveDate < redDate
                                                     && !x.BedsOnHold)
                                        .Sum(x => x.CertifiedBedsTransferred) ?? 0;

                                    if (certifiedBedsCount > 0 && transferredBedsCount > 0)
                                    {
                                        if (certifiedBedsCount == transferredBedsCount)
                                            isTransferredBeds = true;
                                    }
                                    else if (certifiedBedsCount > 0)
                                    {
                                        isCertifiedBeds = true;
                                    }

                                    // if the InitialCertificationDate and RedDate do not have their month and day to be 7 / 1 
                                    // and if the InitialCertificationDate matches with the RedDate 
                                    if (!(initiCertDate.Day == 1 && initiCertDate.Month == 7) &&
                                        !(docEffectiveDate.Day == 1 && docEffectiveDate.Month == 7)
                                        && (initiCertDate == docEffectiveDate))
                                    {
                                        if (isCertifiedBeds)
                                        {
                                            // New Facility Initial Certification Rate package with Existing Beds(CertifiedBeds) only
                                            ratePackageReportTemplateLocation =
                                                ARUMConfigurationOHFI
                                                    .NewFacilityRatePackageReportInitCertSch3ETemplateLocation(
                                                        RetrieveSession.Classification);
                                        }
                                        else if (isTransferredBeds)
                                        {
                                            // New Facility Initial Certification Rate package with Transferred Beds only
                                            ratePackageReportTemplateLocation =
                                                ARUMConfigurationOHFI
                                                    .NewFacilityRatePackageReportInitCertSch3TemplateLocation(
                                                        RetrieveSession.Classification);
                                            hasTransferredBeds = true;
                                            rp8StartLineNo = 20;
                                        }
                                        else
                                        {
                                            // New Facility Initial Certification Rate package with Existing Beds(CertifiedBeds)/Transferred Beds
                                            ratePackageReportTemplateLocation =
                                                ARUMConfigurationOHFI
                                                    .NewFacilityRatePackageReportInitCertTemplateLocation(
                                                        RetrieveSession.Classification);
                                            hasTransferredBeds = true;
                                            rp8StartLineNo = 29;
                                        }
                                    }
                                    else
                                    {
                                        if (isCertifiedBeds)
                                        {
                                            // New Facility Rate package with Existing Beds(CertifiedBeds) only
                                            ratePackageReportTemplateLocation =
                                                ARUMConfigurationOHFI.NewFacilityRatePackageReportSch3ETemplateLocation(
                                                    RetrieveSession.Classification);
                                        }
                                        else if (isTransferredBeds)
                                        {
                                            // New Facility Rate package with Transferred Beds only
                                            ratePackageReportTemplateLocation =
                                                ARUMConfigurationOHFI.NewFacilityRatePackageReportSch3TemplateLocation(
                                                    RetrieveSession.Classification);
                                            hasTransferredBeds = true;
                                            rp8StartLineNo = 20;
                                        }
                                        else
                                        {
                                            // New Facility Rate package with Existing Beds(CertifiedBeds)/Transferred Beds
                                            ratePackageReportTemplateLocation =
                                                ARUMConfigurationOHFI.NewFacilityRatePackageReportTemplateLocation(
                                                    RetrieveSession.Classification);
                                            hasTransferredBeds = true;
                                            rp8StartLineNo = 29;
                                        }
                                    }

                                    break;
                            }

                            // Getting the template file based on EffectiveDate
                            ratePackageReportTemplateLocation = RateBL.GetRatePackageTemplateLocation("ICF",
                                ratePackageReportTemplateLocation, docEffectiveDate);

                            // Set page number based on EffectiveDate
                            if (docEffectiveDate >= new DateTime(2023, 7, 1))
                                pageNo = 13;
                            else
                                pageNo = 12;

                            break;
                    }

                    if (string.IsNullOrEmpty(ratePackageReportTemplateLocation))
                    {
                        throw new GlobalApplicationSettingsException($"Rate Setting Template Location for Rate Type Code [{rateTypeId}] not configured in Global Application Settings.");
                    }

                    var fileName =
                        $"RP_P{provider.ProviderNumber}_Eff_{docEffectiveDate:yyyyMMdd}_Run_{currDate:yyyyMMdd}.pdf"
                            .ToSafeFileName();

                    //Save the file to the path of the current user's temporary folder
                    var filePath = Path.Combine(Path.GetTempPath(), fileName);

                    string sCurrentDirectory = AppDomain.CurrentDomain.BaseDirectory;
                    string sFile = System.IO.Path.Combine(sCurrentDirectory, ratePackageReportTemplateLocation);
                    string sFilePath = Path.GetFullPath(sFile);

                    //Checking the template file for the EffectiveDate
                    if (!System.IO.File.Exists(sFilePath))
                    {
                        throw new FileNotFoundException($"Rate Setting Template file [{ratePackageReportTemplateLocation}] could not be found.");
                    }

                    using (ExcelEngine excelEngine = new ExcelEngine())
                    using (MemoryStream ExcelMemStream = new MemoryStream())
                    using (FileStream file = new FileStream(sFilePath, FileMode.Open, FileAccess.Read))
                    {
                        //Open existing Excel template
                        file.CopyTo(ExcelMemStream);
                        Syncfusion.XlsIO.IApplication application = excelEngine.Excel;

                        ExcelMemStream.Position = 0;
                        IWorkbook workbook = application.Workbooks.Open(ExcelMemStream, ExcelOpenType.Automatic,
                            ExcelParseOptions.Default);

                        //var reportDataList = RateBL.GetRatePackageReportDataRO(ratePackageId);

                        var ratePackageReportDataList = reportDataList
                            .Where(d => !string.IsNullOrWhiteSpace(d.CalcName))
                            .ToList();


                        List<string> workSheetName = new List<string>();
                        //string[] workSheetName = null;
                        for (int j = 0; j < workbook.Worksheets.Count; j++)
                        {
                            workSheetName.Add(workbook.Worksheets[j].Name);
                        }

                        foreach (var wsName in workSheetName)
                        {
                            IWorksheet sheet = workbook.Worksheets[wsName];
                            if (sheet == null) continue;

                            if ((SimplifiedType == "ICF") && !(rateTypeId == (int)RateTypeEnumExtended.NewFacility))
                            {
                                switch (sheet.Name)
                                {
                                    case "RP15":
                                        UpdateorDeleteExcelRowsforRP15(workbook, sheet, ratePackageReportDataList,
                                            "CapitalChangeAddition", 16);
                                        break;
                                    case "RP16":
                                        UpdateorDeleteExcelRowsforRP16(workbook, sheet, ratePackageReportDataList,
                                            "CapitalChangeRenovation", 16, 119);
                                        break;
                                    case "RP18":
                                        UpdateorDeleteExcelRowsforRP18(workbook, sheet, ratePackageReportDataList,
                                            "CapitalChangeSecondary", 16);
                                        break;
                                    case "RP21":
                                        curPageNo = pageNo;
                                        UpdateorDeleteExcelRowsforRP21(workbook, sheet, ratePackageReportDataList, 16,
                                            ref pageNo);
                                        if (pageNo > curPageNo)
                                            startSch6_22PageNo = pageNo;
                                        break;
                                    case "RP22":
                                        UpdateorDeleteExcelRowsforRP22(workbook, sheet, ratePackageReportDataList,
                                            "C1Data", 15, 223, ref pageNo);
                                        if (pageNo > curPageNo)
                                            endSch6_22PageNo = pageNo;
                                        break;
                                    case "RP22P1":
                                        curPageNo = pageNo;
                                        UpdateorDeleteExcelRowsforRP22P1(workbook, sheet, ratePackageReportDataList, 16,
                                            ref pageNo);
                                        if (pageNo > curPageNo)
                                            endSch6_22PageNo = pageNo;
                                        break;
                                    case "RP23":
                                        curPageNo = pageNo;
                                        UpdateorDeleteExcelRowsforRP23(workbook, sheet, ratePackageReportDataList, 14,
                                            ref pageNo);
                                        if (pageNo > curPageNo)
                                            sch6_23PageNo = pageNo;
                                        break;
                                    case "RP24":
                                        curPageNo = pageNo;
                                        UpdateorDeleteExcelRowsforRP24(workbook, sheet, ratePackageReportDataList, 16,
                                            ref pageNo);
                                        if (pageNo > curPageNo)
                                            startSch6_3PageNo = pageNo;
                                        break;
                                    case "RP25":
                                        UpdateorDeleteExcelRowsforRP25(workbook, sheet, ratePackageReportDataList,
                                            "C2Data", 15, ref pageNo);
                                        break;
                                    case "RP26":
                                        curPageNo = pageNo;
                                        UpdateorDeleteExcelRowsforRP26(workbook, sheet, ratePackageReportDataList, 16,
                                            ref pageNo);
                                        if (pageNo > curPageNo)
                                            endSch6_3PageNo = pageNo;
                                        break;
                                    default:
                                        foreach (var ratePackageReportData in ratePackageReportDataList)
                                        {
                                            //Replaces the given string with another string
                                            sheet.Replace("{" + ratePackageReportData.CalcName + "}",
                                                ratePackageReportData.DataValue);
                                        }

                                        if (sheet.Name == "RP27")
                                        {
                                            //Replaces the Page Number {PageNo} 
                                            pageNo++;
                                            sheet.Replace("{PageNo}", "Page " + pageNo);
                                            sch9PageNo = pageNo;
                                        }

                                        break;
                                }
                            }
                            else if ((SimplifiedType == "ICF") && (rateTypeId == (int)RateTypeEnumExtended.NewFacility) &&
                                hasTransferredBeds)
                            {
                                switch (sheet.Name)
                                {
                                    case "RP8":
                                        UpdateorDeleteExcelRowsforRP8(workbook, sheet, ratePackageReportDataList,
                                            "TransferredBedInformation", rp8StartLineNo);
                                        break;
                                    default:
                                        foreach (var ratePackageReportData in ratePackageReportDataList)
                                        {
                                            //Replaces the given string with another string
                                            sheet.Replace("{" + ratePackageReportData.CalcName + "}",
                                                ratePackageReportData.DataValue);
                                        }

                                        break;
                                }
                            }
                            else
                            {
                                foreach (var ratePackageReportData in ratePackageReportDataList)
                                {
                                    //Replaces the given string with another string
                                    sheet.Replace("{" + ratePackageReportData.CalcName + "}",
                                        ratePackageReportData.DataValue);
                                }
                            }
                        }

                        if (SimplifiedType == "ICF")
                        {
                            //Updating the page number in the Table of Contents work sheet
                            IWorksheet sheetRP3 = workbook.Worksheets["RP3"];
                            if (!(rateTypeId == (int)RateTypeEnumExtended.NewFacility) && sheetRP3 != null)
                            {
                                if (startSch6_22PageNo != 0)
                                {
                                    if (endSch6_22PageNo > startSch6_22PageNo)
                                        sheetRP3.Replace("{Sch6_22PageNo}",
                                            startSch6_22PageNo + " - " + endSch6_22PageNo);
                                    else
                                        sheetRP3.Replace("{Sch6_22PageNo}", startSch6_22PageNo);
                                }
                                else
                                    sheetRP3.Replace("{Sch6_22PageNo}", "Not Applicable");

                                if (sch6_23PageNo != 0)
                                {
                                    sheetRP3.Replace("{Sch6_23PageNo}", sch6_23PageNo);
                                }
                                else
                                    sheetRP3.Replace("{Sch6_23PageNo}", "Not Applicable");

                                if (startSch6_3PageNo != 0)
                                {
                                    if (endSch6_22PageNo > startSch6_22PageNo)
                                        sheetRP3.Replace("{Sch6_3PageNo}", startSch6_3PageNo + " - " + endSch6_3PageNo);
                                    else
                                        sheetRP3.Replace("{Sch6_3PageNo}", startSch6_3PageNo);
                                }
                                else
                                    sheetRP3.Replace("{Sch6_3PageNo}", "Not Applicable");

                                if (sch9PageNo != 0)
                                {
                                    sheetRP3.Replace("{Sch9PageNo}", sch9PageNo);
                                }
                                else
                                    sheetRP3.Replace("{Sch9PageNo}", "Not Applicable");
                            }
                        }


                        //Initialize XlsIO renderer.
                        XlsIORenderer renderer = new XlsIORenderer();

                        //Convert Excel document into PDF document 
                        PdfDocument pdfDocument = renderer.ConvertToPDF(workbook);

                        Stream stream = new FileStream(filePath, FileMode.Create, FileAccess.ReadWrite);
                        pdfDocument.Save(stream);

                        ExcelMemStream.Dispose();
                        stream.Dispose();
                        workbook.Close();
                    }

                    fileList.Add(fileName);
                }

                if (fileList.Count > 0)
                {
                    string zipRatePackageReportFileName =
                        $"RatePackageReport_{currDate:MMddyyyy}_{currDate:HHmmss}.zip"; //Zip file name
                    var zipFileName = ZipFiles(fileList, zipRatePackageReportFileName);
                    DeleteFiles(fileList);
                    fileList.Clear();
                    return Json(new { Success = true, fileName = HttpUtility.UrlEncode(zipFileName) });
                }
                else
                    return Json(new { Success = false, Message = "Error in generating rate packages." });
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
            finally
            {
                if (providerData != null)
                {
                    providerData.ForEach(x => x.Dispose());
                    providerData.Clear();
                }
            }
        }


