        public static void UpdateorDeleteExcelRowsforRP8(IWorkbook workbook, IWorksheet sheet,
            List<RatePackageReportItem> ratePackageReportDataList, string name, int startLineNo)
        {
            string[] transferredBedGridArray = new string[] { "A", "B", "C", "D", "E", "F", "G", "H", "I", "J", "K" };
            List<int> list = new List<int>();

            var data = ratePackageReportDataList.Where(d => d.CalcName.Contains(name)).ToList();
            if (data.Count > 0)
            {
                foreach (var d in data)
                {
                    string subs = d.CalcName.Substring(name.Length);
                    string[] substrings = subs.Split('_');
                    list.Add(int.Parse(substrings[0]));
                }

                var dataList = list.Distinct()
                    .OrderBy(x => x)
                    .ToList();

                foreach (var l in dataList)
                {
                    sheet.InsertRow(startLineNo, 1, ExcelInsertOptions.FormatAsBefore);
                    sheet.SetRowHeight(startLineNo, 26.25);
                    foreach (var bedArray in transferredBedGridArray)
                    {
                        switch (bedArray)
                        {
                            case "A":
                                sheet.Range[bedArray + startLineNo].Value =
                                    data.FirstOrDefault(x =>
                                        x.CalcName == $"TransferredBedInformation{l}_ProviderNumber")?.DataValue ??
                                    string.Empty;
                                break;
                            case "B":
                                sheet.Range[bedArray + startLineNo].Value =
                                    data.FirstOrDefault(x =>
                                        x.CalcName == $"TransferredBedInformation{l}_EffectiveDate")?.DataValue ??
                                    string.Empty;
                                break;
                            case "C":
                                sheet.Range[bedArray + startLineNo].Value =
                                    data.FirstOrDefault(x =>
                                        x.CalcName == $"TransferredBedInformation{l}_CostPerCaseMixUnit")?.DataValue ??
                                    string.Empty;
                                break;
                            case "D":
                                sheet.Range[bedArray + startLineNo].Value = data.FirstOrDefault(x =>
                                        x.CalcName == $"TransferredBedInformation{l}_DirectCareMaximumCostLimit")
                                    ?.DataValue ?? string.Empty;
                                break;
                            case "E":
                                sheet.Range[bedArray + startLineNo].Value =
                                    data.FirstOrDefault(x =>
                                            x.CalcName == $"TransferredBedInformation{l}_DirectCareCostOrLimit")
                                        ?.DataValue ?? string.Empty;
                                break;
                            case "F":
                                sheet.Range[bedArray + startLineNo].Value =
                                    "N/A"; //data.FirstOrDefault(x => x.CalcName == $"TransferredBedInformation{l}_ActualQuarterlyScoreforNewFacility")?.DataValue ?? string.Empty;
                                break;
                            case "G":
                                sheet.Range[bedArray + startLineNo].Value =
                                    "N/A"; //data.FirstOrDefault(x => x.CalcName == $"TransferredBedInformation{l}_CurrentFYInflationFactor")?.DataValue ?? string.Empty;
                                break;
                            case "H":
                                sheet.Range[bedArray + startLineNo].Value =
                                    "N/A"; //data.FirstOrDefault(x => x.CalcName == $"TransferredBedInformation{l}_PriorFYInflationFactor")?.DataValue ?? string.Empty;
                                break;
                            case "I":
                                sheet.Range[bedArray + startLineNo].Value =
                                    data.FirstOrDefault(x =>
                                            x.CalcName == $"TransferredBedInformation{l}_DirectCarePerDiemRate")
                                        ?.DataValue ?? string.Empty;
                                break;
                            case "J":
                                sheet.Range[bedArray + startLineNo].Value = data.FirstOrDefault(x =>
                                        x.CalcName == $"TransferredBedInformation{l}_CertifiedBedsTransferred")
                                    ?.DataValue ?? string.Empty;
                                break;
                            case "K":
                                sheet.Range[bedArray + startLineNo].Value = data.FirstOrDefault(x =>
                                        x.CalcName == $"TransferredBedInformation{l}_NumberofBedsTimesPerDiem")
                                    ?.DataValue ?? string.Empty;
                                break;
                        }
                    }

                    sheet.Range[startLineNo, 1].NumberFormat = "0000000";
                    sheet.Range[startLineNo, 2].NumberFormat = @"mm\/dd\/yyyy";
