        /// <summary>
        /// This routine will remove any and all blank rows with a given range in a worksheet
        /// </summary>
        /// <param name="sheet">The worksheet to be processed</param>
        /// <param name="validBottom">What you think the bottom row is: UsedRange.LastRow</param>
        /// <param name="assumedLastRow">What you think the actual last row is (includes formatting)</param>
        /// <returns>The spreadsheet</returns>
        public IWorksheet RemoveBlankRowsFromPage(IWorksheet sheet, int validBottom, int assumedLastRow)
        {
            IRange usedRange = sheet.UsedRange; // UsedRange = rows with Valid data.
            int blankRowCount = 0;

            try
            {
                for (int row = validBottom; row <= assumedLastRow; row++)
                {
                    if (sheet[row, 1, row, usedRange.LastColumn].IsBlank)
                        blankRowCount++;
                    else if (blankRowCount > 0)
                    {
                        int BlankRowStart = row - blankRowCount + 1;
                        sheet.DeleteRow(BlankRowStart, blankRowCount);
                        row -= blankRowCount;
                        assumedLastRow -= blankRowCount;
                        blankRowCount = 0;
                    }

                    if (blankRowCount > 0 && row == assumedLastRow)
                    {
                        int BlankRowStart = row - blankRowCount + 1;
                        sheet.DeleteRow(BlankRowStart, blankRowCount);
                        row -= blankRowCount;
                        assumedLastRow -= blankRowCount;
                        blankRowCount = 0;
                    }
                }
            }
            catch (Exception e)
            {
                // An invalid cell has been encountered. Given the nature of this routine,
                // which simply removes unwanted blank rows, continue processing.
                _logger.Error(e, e.Message);
            }

            return sheet;
        }

