        public static CountResult GetC1orC2DataCount(List<RatePackageReportItem> ratePackageReportDataList, string para,
            Dictionary<string, string> calcKeyHeader, Dictionary<string, string> calcKeyDate, int hCount, int dCount)
        {
            var cData = ratePackageReportDataList.Where(d => d.CalcName.Contains(para)).ToList();
            if (cData.Count > 0)
            {
                foreach (var c in cData)
                {
                    int firstUnderscoreIndex = c.CalcName.IndexOf('_');
                    string calcKeyPart = c.CalcName.Substring(0, firstUnderscoreIndex);
                    string calcKeyPartTwo = c.CalcName.Substring(firstUnderscoreIndex + 1);
                    if (calcKeyPartTwo.StartsWith("Dates"))
                    {
                        calcKeyDate[c.CalcName] = c.DataValue;
                    }
                    else
                    {
                        calcKeyHeader[c.CalcName] = c.DataValue;
                    }
                }

                hCount = calcKeyHeader.Keys
                    .Select(k => int.Parse(k.Substring(6).Split('_')[0]))
                    .Distinct()
                    .OrderByDescending(x => x)
                    .FirstOrDefault();

                dCount = calcKeyDate.Keys
                    .Select(k => int.Parse(k.Substring(13).Split('_')[0]))
                    .Distinct()
                    .OrderByDescending(x => x)
                    .FirstOrDefault();
            }

            return new CountResult
            {
                CalcKeyHeader = calcKeyHeader,
                CalcKeyDate = calcKeyDate,
                HCount = hCount,
                DCount = dCount
            };
        }

