        public static void UpdateorDeleteExcelRowsforRP22(IWorkbook workbook, IWorksheet sheet,
            List<RatePackageReportItem> ratePackageReportDataList, string name, int startLineNo, int endLineNo,
            ref int pageNo)
        {
            string[] realtedFacilityGridArray = new string[] { "A", "C", "D", "E", "F", "G", "H", "J" };
            string[] subTotalGridArray = new string[] { "A", "H", "J" };
            Dictionary<string, string> realtedFacilityMain = new Dictionary<string, string>();
            Dictionary<string, string> realtedFacilitySub = new Dictionary<string, string>();
            Dictionary<string, string> realtedFacilityChild = new Dictionary<string, string>();
            int c1HeaderCount = -1;
            int c1DateCnt = -1;
            int c1RealtedFacilityCnt = -1;
            //int c1Counter = 1;
            int rpsStartLineNo = 16;

            var c1RealtedFacilityData = ratePackageReportDataList.Where(d => d.CalcName.Contains("C1Data")).ToList();
            if (c1RealtedFacilityData.Count > 0)
            {
                int cnt = 1;
                int cnt1 = 1;
                IWorksheet newRP22Worksheet = GenerateDynamicWorKSheet(workbook, sheet, "RP22-", cnt);

                foreach (var c1 in c1RealtedFacilityData)
                {
                    //string calcKeyPart = "";
                    string calcKeyPartTwo = "";
                    string calcKeyPartThree = "";
                    int firstUnderscoreIndex = c1.CalcName.IndexOf('_');
                    int secondUnderscoreIndex = 0;
                    if (firstUnderscoreIndex != -1)
                    {
                        //calcKeyPart = c1.CalcName.Substring(0, firstUnderscoreIndex);
                        calcKeyPartTwo = c1.CalcName.Substring(firstUnderscoreIndex + 1);
                        secondUnderscoreIndex = calcKeyPartTwo.IndexOf('_');
                    }

                    if (secondUnderscoreIndex != -1)
                    {
                        calcKeyPartThree = calcKeyPartTwo.Substring(secondUnderscoreIndex + 1);
                    }

                    if (calcKeyPartThree.StartsWith("RelatedFacilities"))
                    {
                        realtedFacilityChild[c1.CalcName] = c1.DataValue;
                    }
                    else if (calcKeyPartTwo.StartsWith("Date"))
                    {
                        realtedFacilitySub[c1.CalcName] = c1.DataValue;
                    }
                    else
                    {
                        realtedFacilityMain[c1.CalcName] = c1.DataValue;
                    }
                }

                c1HeaderCount = realtedFacilityMain.Keys
                    .Select(k => int.Parse(k.Substring(6).Split('_')[0]))
                    .Distinct()
                    .OrderByDescending(x => x).FirstOrDefault();

                for (int i = 0; i <= c1HeaderCount; i++)
                {
                    c1DateCnt = realtedFacilitySub.Keys
                        .Where(x => x.StartsWith($"C1Data{i}"))
                        .Select(k => int.Parse(k.Substring(13).Split('_')[0]))
                        .Distinct()
                        .OrderByDescending(x => x).FirstOrDefault();

                    for (int j = 0; j <= c1DateCnt; j++)
                    {
                        if (sheet.Name == "RP22")
                        {
                            c1RealtedFacilityCnt = realtedFacilityChild.Keys
                                .Where(x => x.StartsWith($"C1Data{i}_Dates{j}"))
                                .Select(k => int.Parse(k.Substring(32).Split('_')[0]))
                                .Distinct()
                                .OrderByDescending(x => x)
                                .FirstOrDefault();

                            for (int k = 0; k <= c1RealtedFacilityCnt; k++)
                            {
                                string timeSliceSchedule = "6.22-";
                                newRP22Worksheet.InsertRow(rpsStartLineNo, 1, ExcelInsertOptions.FormatAsBefore);
                                newRP22Worksheet.Range[$"C{rpsStartLineNo}:G{rpsStartLineNo}"].CellStyle.ColorIndex =
                                    ExcelKnownColors.None;
                                foreach (var c1Array in realtedFacilityGridArray)
                                {
                                    switch (c1Array)
                                    {
                                        case "A":
                                            newRP22Worksheet.Range[c1Array + rpsStartLineNo].Value =
                                                $"{timeSliceSchedule}{cnt1}";
                                            newRP22Worksheet.Range[$"{c1Array}{rpsStartLineNo}:B{rpsStartLineNo}"]
                                                .Merge();
                                            break;
                                        case "C":
                                            newRP22Worksheet.Range[c1Array + rpsStartLineNo].Value =
                                                realtedFacilityChild.FirstOrDefault(x =>
                                                        x.Key == $"C1Data{i}_Dates{j}_RelatedFacilities{k}_PROV_NUM")
                                                    .Value == null
                                                    ? "None"
                                                    : realtedFacilityChild.FirstOrDefault(x =>
                                                            x.Key ==
                                                            $"C1Data{i}_Dates{j}_RelatedFacilities{k}_PROV_NUM")
                                                        .Value;
                                            break;
                                        case "D":
                                            newRP22Worksheet.Range[c1Array + rpsStartLineNo].Value = realtedFacilitySub
                                                .FirstOrDefault(x => x.Key == $"C1Data{i}_Dates{j}_BEG_DATE").Value;
                                            break;
                                        case "E":
                                            newRP22Worksheet.Range[c1Array + rpsStartLineNo].Value = realtedFacilitySub
                                                .FirstOrDefault(x => x.Key == $"C1Data{i}_Dates{j}_END_DATE").Value;
                                            break;
                                        case "F":
                                            newRP22Worksheet.Range[c1Array + rpsStartLineNo].Value =
                                                realtedFacilityChild.FirstOrDefault(x =>
                                                        x.Key ==
                                                        $"C1Data{i}_Dates{j}_RelatedFacilities{k}_EMP_BEG_DATE")
                                                    .Value == null
                                                    ? ""
                                                    : realtedFacilityChild.FirstOrDefault(x =>
                                                        x.Key ==
                                                        $"C1Data{i}_Dates{j}_RelatedFacilities{k}_EMP_BEG_DATE").Value;
                                            break;
                                        case "G":
                                            newRP22Worksheet.Range[c1Array + rpsStartLineNo].Value =
                                                realtedFacilityChild.FirstOrDefault(x =>
                                                        x.Key ==
                                                        $"C1Data{i}_Dates{j}_RelatedFacilities{k}_EMP_END_DATE")
                                                    .Value == null
                                                    ? ""
                                                    : realtedFacilityChild.FirstOrDefault(x =>
                                                        x.Key ==
                                                        $"C1Data{i}_Dates{j}_RelatedFacilities{k}_EMP_END_DATE").Value;
                                            break;
                                        case "H":
                                            newRP22Worksheet.Range[c1Array + rpsStartLineNo].Value =
                                                realtedFacilityChild.FirstOrDefault(x =>
                                                        x.Key ==
                                                        $"C1Data{i}_Dates{j}_RelatedFacilities{k}_HOURS_WORKED_WKLY")
                                                    .Value == null
                                                    ? "0.00"
                                                    : realtedFacilityChild.FirstOrDefault(x =>
                                                            x.Key ==
                                                            $"C1Data{i}_Dates{j}_RelatedFacilities{k}_HOURS_WORKED_WKLY")
                                                        .Value;
                                            break;
                                        case "J":
                                            newRP22Worksheet.Range[c1Array + rpsStartLineNo].Value =
                                                realtedFacilityChild.FirstOrDefault(x =>
                                                        x.Key ==
                                                        $"C1Data{i}_Dates{j}_RelatedFacilities{k}_CertifiedFacilityBeds")
                                                    .Value == null
                                                    ? "0"
                                                    : realtedFacilityChild.FirstOrDefault(x =>
                                                            x.Key ==
                                                            $"C1Data{i}_Dates{j}_RelatedFacilities{k}_CertifiedFacilityBeds")
                                                        .Value;
                                            break;
                                    }
                                }

                                newRP22Worksheet.Range[rpsStartLineNo, 1].NumberFormat = "Text";
                                newRP22Worksheet.Range[rpsStartLineNo, 2].NumberFormat = "Text";
                                newRP22Worksheet.Range[rpsStartLineNo, 3].NumberFormat = "0000000";
                                newRP22Worksheet.Range[rpsStartLineNo, 4].NumberFormat = @"mm\/dd\/yyyy";
                                newRP22Worksheet.Range[rpsStartLineNo, 5].NumberFormat = @"mm\/dd\/yyyy";
                                newRP22Worksheet.Range[rpsStartLineNo, 6].NumberFormat = @"mm\/dd\/yyyy";
                                newRP22Worksheet.Range[rpsStartLineNo, 7].NumberFormat = @"mm\/dd\/yyyy";
                                newRP22Worksheet.Range[rpsStartLineNo, 8].NumberFormat = @"#,##0.00_); (#,##0.00)";
                                newRP22Worksheet.Range[rpsStartLineNo, 8].HorizontalAlignment = ExcelHAlign.HAlignRight;
                                RemoveBorderForColumn(newRP22Worksheet, 8, "right");
                                newRP22Worksheet.Range[rpsStartLineNo, 9].NumberFormat = @"#,##0.00_); (#,##0.00)";
                                RemoveBorderForColumn(newRP22Worksheet, 9, "left");
                                newRP22Worksheet.Range[rpsStartLineNo, 10].NumberFormat = @"#,##0_); (#,##0)";
                                newRP22Worksheet.Range[rpsStartLineNo, 10].HorizontalAlignment =
                                    ExcelHAlign.HAlignRight;
                                newRP22Worksheet.Range[rpsStartLineNo, 10].ColumnWidth = 11;
                                newRP22Worksheet.Range[rpsStartLineNo, 11].NumberFormat = @"#,##0_); (#,##0)";
                                newRP22Worksheet.Range[rpsStartLineNo, 11].ColumnWidth = 5;
                                RemoveBorderForColumn(newRP22Worksheet, 10, "right");
                                RemoveBorderForColumn(newRP22Worksheet, 11, "left");

                                rpsStartLineNo++;
                                if (rpsStartLineNo > 44)
                                {
                                    foreach (var ratePackageReportData in ratePackageReportDataList)
                                    {
                                        //Replaces the given string with another string
                                        newRP22Worksheet.Replace("{" + ratePackageReportData.CalcName + "}",
                                            ratePackageReportData.DataValue);
                                    }

                                    cnt++;
                                    pageNo++;
                                    //Replaces the Page Number {NoOfPages}
                                    newRP22Worksheet.Replace("{NoOfPages}", "Page " + pageNo);
                                    newRP22Worksheet = GenerateDynamicWorKSheet(workbook, sheet, "RP22-", cnt);
                                    rpsStartLineNo = 16;
                                }
                            }

                            newRP22Worksheet.InsertRow(rpsStartLineNo, 1, ExcelInsertOptions.FormatAsBefore);
                            newRP22Worksheet.Range["A" + rpsStartLineNo].Value = "Subtotal";
                            newRP22Worksheet.Range[$"A{rpsStartLineNo}:B{rpsStartLineNo}"].Merge();
                            newRP22Worksheet.Range[$"C{rpsStartLineNo}:G{rpsStartLineNo}"].Merge();
                            newRP22Worksheet.Range[$"C{rpsStartLineNo}:G{rpsStartLineNo}"].CellStyle.ColorIndex =
                                ExcelKnownColors.Black;
                            newRP22Worksheet.Range[$"H{rpsStartLineNo}"].Value =
                                realtedFacilitySub.FirstOrDefault(x =>
                                    x.Key == $"C1Data{i}_Dates{j}_RelatedWeeklyHoursInTheTimeSlice").Value == ""
                                    ? "0.00"
                                    : realtedFacilitySub.FirstOrDefault(x =>
                                        x.Key == $"C1Data{i}_Dates{j}_RelatedWeeklyHoursInTheTimeSlice").Value;
                            newRP22Worksheet.Range[$"J{rpsStartLineNo}"].Value =
                                realtedFacilitySub.FirstOrDefault(x =>
                                    x.Key == $"C1Data{i}_Dates{j}_CertifiedBedsForRelatedFacilities").Value == ""
                                    ? "0"
                                    : realtedFacilitySub.FirstOrDefault(x =>
                                        x.Key == $"C1Data{i}_Dates{j}_CertifiedBedsForRelatedFacilities").Value;
                            newRP22Worksheet.Range[rpsStartLineNo, 8].NumberFormat = @"#,##0.00_); (#,##0.00)";
                            newRP22Worksheet.Range[rpsStartLineNo, 8].HorizontalAlignment = ExcelHAlign.HAlignRight;
                            RemoveBorderForColumn(newRP22Worksheet, 8, "right");
                            RemoveBorderForColumn(newRP22Worksheet, 9, "left");
                            newRP22Worksheet.Range[rpsStartLineNo, 10].NumberFormat = @"#,##0_); (#,##0)";
                            newRP22Worksheet.Range[rpsStartLineNo, 10].HorizontalAlignment = ExcelHAlign.HAlignRight;
                            RemoveBorderForColumn(newRP22Worksheet, 10, "right");
                            RemoveBorderForColumn(newRP22Worksheet, 11, "left");
                            rpsStartLineNo++;
                        }

                        cnt1++;
                    }
                }

                if (c1DateCnt >= 0)
                {
                    rpsStartLineNo += c1DateCnt + 1;
                }

                foreach (var ratePackageReportData in ratePackageReportDataList)
                {
                    //Replaces the given string with another string
                    newRP22Worksheet.Replace("{" + ratePackageReportData.CalcName + "}",
                        ratePackageReportData.DataValue);
                }

                pageNo++;
                //Replaces the Page Number {NoOfPages}
                newRP22Worksheet.Replace("{NoOfPages}", "Page " + pageNo);
            }

            workbook.Worksheets.Remove(sheet);
        }

