                            newRP22Worksheet.InsertRow(rpsStartLineNo, 1, ExcelInsertOptions.FormatAsBefore);
                            newRP22Worksheet.Range["A" + rpsStartLineNo].Value = "Subtotal";
                            newRP22Worksheet.Range[$"A{rpsStartLineNo}:B{rpsStartLineNo}"].Merge();
                            newRP22Worksheet.Range[$"C{rpsStartLineNo}:G{rpsStartLineNo}"].Merge();
                            newRP22Worksheet.Range[$"C{rpsStartLineNo}:G{rpsStartLineNo}"].CellStyle.ColorIndex =
                                ExcelKnownColors.Black;
                            newRP22Worksheet.Range[$"H{rpsStartLineNo}"].Value =
                                realtedFacilitySub.FirstOrDefault(x =>
                                    x.Key == $"C1Data{i}_Dates{j}_RelatedWeeklyHoursInTheTimeSlice").Value == ""
                                    ? "0.00"
                                    : realtedFacilitySub.FirstOrDefault(x =>
                                        x.Key == $"C1Data{i}_Dates{j}_RelatedWeeklyHoursInTheTimeSlice").Value;
                            newRP22Worksheet.Range[$"J{rpsStartLineNo}"].Value =
                                realtedFacilitySub.FirstOrDefault(x =>
                                    x.Key == $"C1Data{i}_Dates{j}_CertifiedBedsForRelatedFacilities").Value == ""
                                    ? "0"
                                    : realtedFacilitySub.FirstOrDefault(x =>
                                        x.Key == $"C1Data{i}_Dates{j}_CertifiedBedsForRelatedFacilities").Value;
                            newRP22Worksheet.Range[rpsStartLineNo, 8].NumberFormat = @"#,##0.00_); (#,##0.00)";
                            newRP22Worksheet.Range[rpsStartLineNo, 8].HorizontalAlignment = ExcelHAlign.HAlignRight;
                            RemoveBorderForColumn(newRP22Worksheet, 8, "right");
                            RemoveBorderForColumn(newRP22Worksheet, 9, "left");
                            newRP22Worksheet.Range[rpsStartLineNo, 10].NumberFormat = @"#,##0_); (#,##0)";
                            newRP22Worksheet.Range[rpsStartLineNo, 10].HorizontalAlignment = ExcelHAlign.HAlignRight;
                            RemoveBorderForColumn(newRP22Worksheet, 10, "right");
                            RemoveBorderForColumn(newRP22Worksheet, 11, "left");
                            rpsStartLineNo++;
                        }

                        cnt1++;
                    }
                }

                if (c1DateCnt >= 0)
                {
                    rpsStartLineNo += c1DateCnt + 1;
                }

                foreach (var ratePackageReportData in ratePackageReportDataList)
                {
                    //Replaces the given string with another string
                    newRP22Worksheet.Replace("{" + ratePackageReportData.CalcName + "}",
                        ratePackageReportData.DataValue);
                }

                pageNo++;
                //Replaces the Page Number {NoOfPages}
                newRP22Worksheet.Replace("{NoOfPages}", "Page " + pageNo);
            }

            workbook.Worksheets.Remove(sheet);
        }

        public static void UpdateorDeleteExcelRowsforRP22P1(IWorkbook workbook, IWorksheet sheet,
            List<RatePackageReportItem> ratePackageReportDataList, int startLineNo, ref int pageNo)
        {
            Dictionary<string, string> calcKeyHeader = new Dictionary<string, string>();
            Dictionary<string, string> calcKeyDate = new Dictionary<string, string>();
            List<int> listHeader = new List<int>();
            List<int> list = new List<int>();
            int hCount = -1;
            int dCount = -1;
            int counter = 1;

            var c1Data = ratePackageReportDataList.Where(d => d.CalcName.Contains("C1Data")).ToList();
            if (c1Data.Count > 0)
            {
                CountResult result = GetC1orC2HeaderCount(ratePackageReportDataList, "C1Data", calcKeyHeader, hCount);
                hCount = result.HCount;
                for (int h = 0; h <= hCount; h++)
                {
                    CountResult resultDates =
                        GetC1orC2DateCount(ratePackageReportDataList, "C1Data" + h, calcKeyDate, dCount);
                    dCount = resultDates.DCount;

                    for (int c = 0; c <= dCount; c++)
                    {
                        IWorksheet newWorksheet = workbook.Worksheets.AddCopyBefore(sheet);
                        GenerateSummaryScheduleCells(sheet, newWorksheet, ratePackageReportDataList, "C1Data", "Dates",
                            h, c, counter);
                        newWorksheet.Name = "RP22P-" + counter;
                        string strName = "";
                        foreach (var ratePackageReportData in ratePackageReportDataList)
                        {
                            if (ratePackageReportData.CalcName.Contains("C1Data" + h + "_FIRST_NAME"))
                            {
                                strName = ratePackageReportData.DataValue;
                            }
                            else if (ratePackageReportData.CalcName.Contains("C1Data" + h + "_LAST_NAME"))
                            {
                                if (strName == "")
                                {
                                    newWorksheet.Replace("{C1Data" + h + "_Name}", ratePackageReportData.DataValue);
                                }
                                else
                                {
                                    strName = strName + " " + ratePackageReportData.DataValue;
                                    newWorksheet.Replace("{C1Data" + h + "_Name}", strName);
                                }
                            }
                            else
                            {
                                newWorksheet.Replace($"{{{ratePackageReportData.CalcName}}}",
                                    ratePackageReportData.DataValue);
                            }
                        }

                        pageNo++;
                        //Replaces the Page Number {NoOfPages}
                        newWorksheet.Replace("{NoOfPages}", "Page " + pageNo);

                        counter++;
                    }
                }
            }

            workbook.Worksheets.Remove(sheet);
        }

