            List<RatePackageReportItem> ratePackageReportDataList, int startLineNo, ref int pageNo)
        {
            string[] c1GridArray = new string[] { "A", "B", "C", "D", "E", "F", "G", "H", "I", "J", "K", "L" };
            Dictionary<string, string> calcKeyHeader = new Dictionary<string, string>();
            Dictionary<string, string> calcKeyDate = new Dictionary<string, string>();
            List<int> listHeader = new List<int>();
            List<int> list = new List<int>();
            int hCount = -1;
            int dCount = -1;
            var c1Data = ratePackageReportDataList.Where(d => d.CalcName.Contains("C1Data")).ToList();
            if (c1Data.Count > 0)
            {
                CountResult result = GetC1orC2HeaderCount(ratePackageReportDataList, "C1Data", calcKeyHeader, hCount);
                hCount = result.HCount;
                //hCount is less than or equal to 0 do not generate this schedule 6.23
                if (hCount > 0)
                {
                    for (int h = 0; h <= hCount; h++)
                    {
                        CountResult resultDates = GetC1orC2DateCount(ratePackageReportDataList, "C1Data" + h,
                            calcKeyDate, dCount);
                        dCount = resultDates.DCount;
                        for (int c = 0; c <= dCount; c++)
                        {
                            sheet.InsertRow(startLineNo, 1, ExcelInsertOptions.FormatAsBefore);
                            foreach (var c1Array in c1GridArray)
                            {
                                switch (c1Array)
                                {
                                    case "A":
                                        string firstName = calcKeyHeader
                                            .FirstOrDefault(x => x.Key == $"C1Data{h}_FIRST_NAME").Value;
                                        string lastName = calcKeyHeader
                                            .FirstOrDefault(x => x.Key == $"C1Data{h}_LAST_NAME").Value;
                                        sheet.Range[c1Array + startLineNo].Value = $"{firstName} {lastName}";
                                        sheet.Range[$"{c1Array}{startLineNo}:B{startLineNo}"].Merge();
                                        break;
                                    case "C":
                                        sheet.Range[c1Array + startLineNo].Value = calcKeyDate
                                            .FirstOrDefault(x => x.Key == $"C1Data{h}_Dates{c}_BEG_DATE").Value;
                                        break;
                                    case "D":
                                        sheet.Range[c1Array + startLineNo].Value = calcKeyDate
                                            .FirstOrDefault(x => x.Key == $"C1Data{h}_Dates{c}_END_DATE").Value;
                                        break;
                                    case "E":
                                        sheet.Range[c1Array + startLineNo].Value = calcKeyDate.FirstOrDefault(x =>
                                                x.Key == $"C1Data{h}_Dates{c}_ProratedAdministratorCompensationAmount")
                                            .Value;
                                        break;
                                    case "G":
                                        sheet.Range[c1Array + startLineNo].Value = "0";
                                        break;
                                    case "I":
                                        sheet.Range[c1Array + startLineNo].Value = calcKeyDate.FirstOrDefault(x =>
                                                x.Key ==
                                                $"C1Data{h}_Dates{c}_IndividualAdministratorCompensationDisallowance")
                                            .Value;
                                        break;
                                    case "K":
                                        sheet.Range[c1Array + startLineNo].Value = calcKeyDate.FirstOrDefault(x =>
                                                x.Key ==
                                                $"C1Data{h}_Dates{c}_FinalAdjustedProratedAdministerCompensationAmount")
                                            .Value;
                                        break;
                                }
                            }

                            sheet.Range[startLineNo, 1].NumberFormat = "Text";
                            sheet.Range[startLineNo, 1].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                            sheet.Range[startLineNo, 2].NumberFormat = "Text";
                            sheet.Range[startLineNo, 3].NumberFormat = @"mm\/dd\/yyyy";
                            sheet.Range[startLineNo, 4].NumberFormat = @"mm\/dd\/yyyy";
                            sheet.Range[startLineNo, 5].NumberFormat = @"\$ #,##0_);\$ (#,##0)";
                            sheet.Range[startLineNo, 5].HorizontalAlignment = ExcelHAlign.HAlignRight;
                            RemoveBorderForColumn(sheet, 5, "right");
                            sheet.Range[startLineNo, 6].NumberFormat = @"\$ #,##0_);\$ (#,##0)";
                            RemoveBorderForColumn(sheet, 6, "left");
                            sheet.Range[startLineNo, 7].NumberFormat = @"#,##0_); (#,##0)";
                            sheet.Range[startLineNo, 7].HorizontalAlignment = ExcelHAlign.HAlignRight;
                            RemoveBorderForColumn(sheet, 7, "right");
                            sheet.Range[startLineNo, 8].NumberFormat = @"#,##0_); (#,##0)";
                            RemoveBorderForColumn(sheet, 8, "left");
                            sheet.Range[startLineNo, 9].NumberFormat = @"\$ #,##0_);\$ (#,##0)";
                            sheet.Range[startLineNo, 9].HorizontalAlignment = ExcelHAlign.HAlignRight;
                            RemoveBorderForColumn(sheet, 9, "right");
                            sheet.Range[startLineNo, 10].NumberFormat = @"\$ #,##0_);\$ (#,##0)";
                            RemoveBorderForColumn(sheet, 10, "left");
                            sheet.Range[startLineNo, 11].NumberFormat = @"\$ #,##0_);\$ (#,##0)";
                            sheet.Range[startLineNo, 11].HorizontalAlignment = ExcelHAlign.HAlignRight;
                            RemoveBorderForColumn(sheet, 11, "right");
                            sheet.Range[startLineNo, 12].NumberFormat = @"\$ #,##0_);\$ (#,##0)";
                            RemoveBorderForColumn(sheet, 12, "left");
                            startLineNo++;
                        }
                    }

                    foreach (var ratePackageReportData in ratePackageReportDataList)
                    {
                        sheet.Replace($"{{{ratePackageReportData.CalcName}}}", ratePackageReportData.DataValue);
                    }

                    pageNo++;
                    //Replaces the Page Number {NoOfPages}
                    sheet.Replace("{NoOfPages}", "Page " + pageNo);
                }
                else
                {
                    workbook.Worksheets.Remove(sheet);
                }
            }
