        public static void UpdateorDeleteExcelRowsforRP25(IWorkbook workbook, IWorksheet sheet,
            List<RatePackageReportItem> ratePackageReportDataList,
            string para, int startLineNo, ref int pageNo)
        {
            string[] realtedFacilityGridArray = new string[] { "A", "B", "D", "E", "F", "G", "H", "J" };
            string[] subTotalGridArray = new string[] { "A", "H", "J" };
            Dictionary<string, string> realtedFacilityMain = new Dictionary<string, string>();
            Dictionary<string, string> realtedFacilitySub = new Dictionary<string, string>();
            Dictionary<string, string> realtedFacilityChild = new Dictionary<string, string>();
            List<int> listC2Header = new List<int>();
            List<int> listDates = new List<int>();
            List<int> listRealtedFacilities = new List<int>();
            int c2HeaderCount = -1;
            int c2DateCnt = -1;
            int c2RealtedFacilityCnt = -1;
            //int c2Counter = 1;
            int rpsStartLineNo = 16;

            var c2RealtedFacilityData = ratePackageReportDataList.Where(d => d.CalcName.Contains("C2Data")).ToList();
            if (c2RealtedFacilityData.Count > 0)
            {
                int cnt = 1;
                int cnt1 = 1;
                IWorksheet newRP25Worksheet = GenerateDynamicWorKSheet(workbook, sheet, "RP25-", cnt);

                foreach (var c2 in c2RealtedFacilityData)
                {
                    //string calcKeyPart = "";
                    string calcKeyPartTwo = "";
                    string calcKeyPartThree = "";
                    int firstUnderscoreIndex = c2.CalcName.IndexOf('_');
                    int secondUnderscoreIndex = 0;
                    if (firstUnderscoreIndex != -1)
                    {
                        //calcKeyPart = c2.CalcName.Substring(0, firstUnderscoreIndex);
                        calcKeyPartTwo = c2.CalcName.Substring(firstUnderscoreIndex + 1);
                        secondUnderscoreIndex = calcKeyPartTwo.IndexOf('_');
                    }

                    if (secondUnderscoreIndex != -1)
                    {
                        calcKeyPartThree = calcKeyPartTwo.Substring(secondUnderscoreIndex + 1);
                    }

                    if (calcKeyPartThree.StartsWith("RelatedFacilities"))
                    {
                        realtedFacilityChild[c2.CalcName] = c2.DataValue;
                    }
                    else if (calcKeyPartTwo.StartsWith("Date"))
                    {
                        realtedFacilitySub[c2.CalcName] = c2.DataValue;
                    }
                    else
                    {
                        realtedFacilityMain[c2.CalcName] = c2.DataValue;
                    }
                }

                c2HeaderCount = realtedFacilityMain.Keys
                    .Select(k => int.Parse(k.Substring(6).Split('_')[0]))
                    .Distinct()
                    .OrderByDescending(x => x)
                    .FirstOrDefault();

                for (int i = 0; i <= c2HeaderCount; i++)
                {
                    c2DateCnt = realtedFacilitySub.Keys
                        .Where(x => x.StartsWith($"C2Data{i}"))
                        .Select(k => int.Parse(k.Substring(13).Split('_')[0]))
                        .Distinct()
                        .OrderByDescending(x => x)
                        .FirstOrDefault();

                    for (int j = 0; j <= c2DateCnt; j++)
                    {
                        if (sheet.Name == "RP25")
                        {
                            c2RealtedFacilityCnt = realtedFacilityChild.Keys
                                .Where(x => x.StartsWith($"C2Data{i}_Dates{j}"))
                                .Select(k => int.Parse(k.Substring(32).Split('_')[0]))
                                .Distinct()
                                .OrderByDescending(x => x)
                                .FirstOrDefault();

                            for (int k = 0; k <= c2RealtedFacilityCnt; k++)
                            {
                                string timeSliceSchedule = "6.3-";
                                newRP25Worksheet.InsertRow(rpsStartLineNo, 1, ExcelInsertOptions.FormatAsBefore);
                                newRP25Worksheet.Range[$"B{rpsStartLineNo}:G{rpsStartLineNo}"].CellStyle.ColorIndex =
                                    ExcelKnownColors.None;
                                foreach (var c2Array in realtedFacilityGridArray)
                                {
                                    switch (c2Array)
                                    {
                                        case "A":
                                            newRP25Worksheet.Range[c2Array + rpsStartLineNo].Value =
                                                $"{timeSliceSchedule}{cnt1}";
                                            break;
                                        case "B":
                                            var b = realtedFacilityChild.FirstOrDefault(x =>
                                                x.Key == $"C2Data{i}_Dates{j}_RelatedFacilities{k}_PROV_NUM");
                                            newRP25Worksheet.Range[c2Array + rpsStartLineNo].Value =
                                                b.Equals(default(KeyValuePair<string, string>)) ? "None" : b.Value;
                                            newRP25Worksheet.Range[$"{c2Array}{rpsStartLineNo}:C{rpsStartLineNo}"]
                                                .Merge();
                                            break;
                                        case "D":
                                            newRP25Worksheet.Range[c2Array + rpsStartLineNo].Value = realtedFacilitySub
                                                .FirstOrDefault(x => x.Key == $"C2Data{i}_Dates{j}_BEG_DATE").Value;
                                            break;
                                        case "E":
                                            newRP25Worksheet.Range[c2Array + rpsStartLineNo].Value = realtedFacilitySub
                                                .FirstOrDefault(x => x.Key == $"C2Data{i}_Dates{j}_END_DATE").Value;
                                            break;
                                        case "F":
                                            var f = realtedFacilityChild.FirstOrDefault(x =>
                                                x.Key == $"C2Data{i}_Dates{j}_RelatedFacilities{k}_EMP_BEG_DATE");
                                            newRP25Worksheet.Range[c2Array + rpsStartLineNo].Value =
                                                f.Equals(default(KeyValuePair<string, string>)) ? "" : f.Value;
                                            break;
                                        case "G":
                                            var g = realtedFacilityChild.FirstOrDefault(x =>
                                                x.Key == $"C2Data{i}_Dates{j}_RelatedFacilities{k}_EMP_END_DATE");
                                            newRP25Worksheet.Range[c2Array + rpsStartLineNo].Value =
                                                g.Equals(default(KeyValuePair<string, string>)) ? "" : g.Value;
                                            break;
                                        case "H":
                                            var h = realtedFacilityChild.FirstOrDefault(x =>
                                                x.Key == $"C2Data{i}_Dates{j}_RelatedFacilities{k}_HOURS_WORKED_WKLY");
                                            newRP25Worksheet.Range[c2Array + rpsStartLineNo].Value =
                                                h.Equals(default(KeyValuePair<string, string>)) ? "0.00" : h.Value;
                                            break;
                                        case "J":
                                            var rec = realtedFacilityChild.FirstOrDefault(x =>
                                                x.Key ==
                                                $"C2Data{i}_Dates{j}_RelatedFacilities{k}_CertifiedFacilityBeds");
                                            newRP25Worksheet.Range[c2Array + rpsStartLineNo].Value =
                                                rec.Equals(default(KeyValuePair<string, string>)) ? "0" : rec.Value;
                                            break;
                                    }
                                }

                                newRP25Worksheet.Range[rpsStartLineNo, 1].NumberFormat = "Text";
                                newRP25Worksheet.Range[rpsStartLineNo, 2].NumberFormat = "0000000";
                                newRP25Worksheet.Range[rpsStartLineNo, 3].NumberFormat = "0000000";
                                newRP25Worksheet.Range[rpsStartLineNo, 4].NumberFormat = @"mm\/dd\/yyyy";
                                newRP25Worksheet.Range[rpsStartLineNo, 5].NumberFormat = @"mm\/dd\/yyyy";
                                newRP25Worksheet.Range[rpsStartLineNo, 6].NumberFormat = @"mm\/dd\/yyyy";
                                newRP25Worksheet.Range[rpsStartLineNo, 7].NumberFormat = @"mm\/dd\/yyyy";
                                newRP25Worksheet.Range[rpsStartLineNo, 8].NumberFormat = @"#,##0.00_); (#,##0.00)";
                                newRP25Worksheet.Range[rpsStartLineNo, 8].HorizontalAlignment = ExcelHAlign.HAlignRight;
                                RemoveBorderForColumn(newRP25Worksheet, 8, "right");
                                newRP25Worksheet.Range[rpsStartLineNo, 9].NumberFormat = @"#,##0.00_); (#,##0.00)";
                                RemoveBorderForColumn(newRP25Worksheet, 9, "left");
                                newRP25Worksheet.Range[rpsStartLineNo, 10].NumberFormat = @"#,##0_); (#,##0)";
                                newRP25Worksheet.Range[rpsStartLineNo, 10].HorizontalAlignment =
                                    ExcelHAlign.HAlignRight;
                                newRP25Worksheet.Range[rpsStartLineNo, 10].ColumnWidth = 11;
                                newRP25Worksheet.Range[rpsStartLineNo, 11].NumberFormat = @"#,##0_); (#,##0)";
                                newRP25Worksheet.Range[rpsStartLineNo, 11].ColumnWidth = 5;
                                RemoveBorderForColumn(newRP25Worksheet, 10, "right");
                                RemoveBorderForColumn(newRP25Worksheet, 11, "left");

                                rpsStartLineNo++;
                                if (rpsStartLineNo > 44)
                                {
                                    foreach (var ratePackageReportData in ratePackageReportDataList)
                                    {
                                        //Replaces the given string with another string
                                        newRP25Worksheet.Replace("{" + ratePackageReportData.CalcName + "}",
                                            ratePackageReportData.DataValue);
                                    }

                                    cnt++;
                                    pageNo++;
                                    //Replaces the Page Number {NoOfPages}
                                    newRP25Worksheet.Replace("{NoOfPages}", "Page " + pageNo);
                                    newRP25Worksheet = GenerateDynamicWorKSheet(workbook, sheet, "RP25-", cnt);
                                    rpsStartLineNo = 16;
                                }
                            }

                            newRP25Worksheet.InsertRow(rpsStartLineNo, 1, ExcelInsertOptions.FormatAsBefore);
                            newRP25Worksheet.Range["A" + rpsStartLineNo].Value = "Subtotal";
                            newRP25Worksheet.Range[$"B{rpsStartLineNo}:G{rpsStartLineNo}"].Merge();
                            newRP25Worksheet.Range[$"B{rpsStartLineNo}:G{rpsStartLineNo}"].CellStyle.ColorIndex =
                                ExcelKnownColors.Black;
                            newRP25Worksheet.Range[$"H{rpsStartLineNo}"].Value =
                                realtedFacilitySub.FirstOrDefault(x =>
                                    x.Key == $"C2Data{i}_Dates{j}_RelatedWeeklyHoursInTheTimeSlice").Value == ""
                                    ? "0.00"
                                    : realtedFacilitySub.FirstOrDefault(x =>
                                        x.Key == $"C2Data{i}_Dates{j}_RelatedWeeklyHoursInTheTimeSlice").Value;
                            newRP25Worksheet.Range[$"J{rpsStartLineNo}"].Value =
                                realtedFacilitySub.FirstOrDefault(x =>
                                    x.Key == $"C2Data{i}_Dates{j}_CertifiedBedsForRelatedFacilities").Value == ""
                                    ? "0"
                                    : realtedFacilitySub.FirstOrDefault(x =>
                                        x.Key == $"C2Data{i}_Dates{j}_CertifiedBedsForRelatedFacilities").Value;
                            newRP25Worksheet.Range[rpsStartLineNo, 8].NumberFormat = @"#,##0.00_); (#,##0.00)";
                            newRP25Worksheet.Range[rpsStartLineNo, 8].HorizontalAlignment = ExcelHAlign.HAlignRight;
                            RemoveBorderForColumn(newRP25Worksheet, 8, "right");
                            RemoveBorderForColumn(newRP25Worksheet, 9, "left");
                            newRP25Worksheet.Range[rpsStartLineNo, 10].NumberFormat = @"#,##0_); (#,##0)";
                            newRP25Worksheet.Range[rpsStartLineNo, 10].HorizontalAlignment = ExcelHAlign.HAlignRight;
                            RemoveBorderForColumn(newRP25Worksheet, 10, "right");
                            RemoveBorderForColumn(newRP25Worksheet, 11, "left");
                            rpsStartLineNo++;
                        }

                        cnt1++;
                    }
                }

                if (c2DateCnt >= 0)
                {
                    rpsStartLineNo += c2DateCnt + 1;
                }

                foreach (var ratePackageReportData in ratePackageReportDataList)
                {
                    //Replaces the given string with another string
                    newRP25Worksheet.Replace("{" + ratePackageReportData.CalcName + "}",
                        ratePackageReportData.DataValue);
                }

                pageNo++;
                //Replaces the Page Number {NoOfPages}
                newRP25Worksheet.Replace("{NoOfPages}", "Page " + pageNo);
            }

            workbook.Worksheets.Remove(sheet);
        }

