                                newRP25Worksheet.Range[rpsStartLineNo, 1].NumberFormat = "Text";
                                newRP25Worksheet.Range[rpsStartLineNo, 2].NumberFormat = "0000000";
                                newRP25Worksheet.Range[rpsStartLineNo, 3].NumberFormat = "0000000";
