                                RemoveBorderForColumn(newRP25Worksheet, 8, "right");
                                newRP25Worksheet.Range[rpsStartLineNo, 9].NumberFormat = @"#,##0.00_); (#,##0.00)";
                                RemoveBorderForColumn(newRP25Worksheet, 9, "left");
                                newRP25Worksheet.Range[rpsStartLineNo, 10].NumberFormat = @"#,##0_); (#,##0)";
                                newRP25Worksheet.Range[rpsStartLineNo, 10].HorizontalAlignment =
                                    ExcelHAlign.HAlignRight;
                                newRP25Worksheet.Range[rpsStartLineNo, 10].ColumnWidth = 11;
                                newRP25Worksheet.Range[rpsStartLineNo, 11].NumberFormat = @"#,##0_); (#,##0)";
                                newRP25Worksheet.Range[rpsStartLineNo, 11].ColumnWidth = 5;
                                RemoveBorderForColumn(newRP25Worksheet, 10, "right");
                                RemoveBorderForColumn(newRP25Worksheet, 11, "left");

                                rpsStartLineNo++;
                                if (rpsStartLineNo > 44)
                                {
                                    foreach (var ratePackageReportData in ratePackageReportDataList)
                                    {
                                        //Replaces the given string with another string
                                        newRP25Worksheet.Replace("{" + ratePackageReportData.CalcName + "}",
