                                    }

                                    cnt++;
                                    pageNo++;
                                    //Replaces the Page Number {NoOfPages}
                                    newRP25Worksheet.Replace("{NoOfPages}", "Page " + pageNo);
                                    newRP25Worksheet = GenerateDynamicWorKSheet(workbook, sheet, $"RP25-{index}-", cnt);
                                    rpsStartLineNo = 16;
                                }
                            }

                            newRP25Worksheet.InsertRow(rpsStartLineNo, 1, ExcelInsertOptions.FormatAsBefore);
                            newRP25Worksheet.Range["A" + rpsStartLineNo].Value = "Subtotal";
                            newRP25Worksheet.Range[$"B{rpsStartLineNo}:G{rpsStartLineNo}"].Merge();
                            newRP25Worksheet.Range[$"B{rpsStartLineNo}:G{rpsStartLineNo}"].CellStyle.ColorIndex =
                                ExcelKnownColors.Black;
                            newRP25Worksheet.Range[$"H{rpsStartLineNo}"].Value =
                                realtedFacilitySub.FirstOrDefault(x =>
                                    x.Key == $"C2Data{i}_Dates{j}_RelatedWeeklyHoursInTheTimeSlice").Value == ""
                                    ? "0.00"
                                    : realtedFacilitySub.FirstOrDefault(x =>
                                        x.Key == $"C2Data{i}_Dates{j}_RelatedWeeklyHoursInTheTimeSlice").Value;
                            newRP25Worksheet.Range[$"J{rpsStartLineNo}"].Value =
                                realtedFacilitySub.FirstOrDefault(x =>
                                    x.Key == $"C2Data{i}_Dates{j}_CertifiedBedsForRelatedFacilities").Value == ""
                                    ? "0"
                                    : realtedFacilitySub.FirstOrDefault(x =>
                                        x.Key == $"C2Data{i}_Dates{j}_CertifiedBedsForRelatedFacilities").Value;
                            newRP25Worksheet.Range[rpsStartLineNo, 8].NumberFormat = @"#,##0.00_); (#,##0.00)";
                            newRP25Worksheet.Range[rpsStartLineNo, 8].HorizontalAlignment = ExcelHAlign.HAlignRight;
                            RemoveBorderForColumn(newRP25Worksheet, 8, "right");
                            RemoveBorderForColumn(newRP25Worksheet, 9, "left");
                            newRP25Worksheet.Range[rpsStartLineNo, 10].NumberFormat = @"#,##0_); (#,##0)";
                            newRP25Worksheet.Range[rpsStartLineNo, 10].HorizontalAlignment = ExcelHAlign.HAlignRight;
                            RemoveBorderForColumn(newRP25Worksheet, 10, "right");
                            RemoveBorderForColumn(newRP25Worksheet, 11, "left");
                            rpsStartLineNo++;
                        }

                        cnt1++;
                    }
                }

                if (c2DateCnt >= 0)
                {
                    rpsStartLineNo += c2DateCnt + 1;
                }

                foreach (var ratePackageReportData in ratePackageReportDataList)
                {
                    //Replaces the given string with another string
                    newRP25Worksheet.Replace("{" + ratePackageReportData.CalcName + "}",
                        ratePackageReportData.DataValue);
                }

                pageNo++;
                //Replaces the Page Number {NoOfPages}
                newRP25Worksheet.Replace("{NoOfPages}", "Page " + pageNo);
            }

            workbook.Worksheets.Remove(sheet);
        }

        public static void UpdateorDeleteExcelRowsforRP26(IWorkbook workbook, IWorksheet sheet,
            List<RatePackageReportItem> ratePackageReportDataList, int startLineNo, ref int pageNo)
        {
            Dictionary<string, string> calcKeyHeader = new Dictionary<string, string>();
            Dictionary<string, string> calcKeyDate = new Dictionary<string, string>();
            List<int> listHeader = new List<int>();
            List<int> list = new List<int>();
            int hCount = -1;
            int dCount = -1;
            int counter = 1;

            var C2Data = ratePackageReportDataList.Where(d => d.CalcName.Contains("C2Data")).ToList();
            if (C2Data.Count > 0)
            {
                CountResult result = GetC1orC2HeaderCount(ratePackageReportDataList, "C2Data", calcKeyHeader, hCount);
                hCount = result.HCount;
                for (int h = 0; h <= hCount; h++)
                {
                    CountResult resultDates =
                        GetC1orC2DateCount(ratePackageReportDataList, "C2Data" + h, calcKeyDate, dCount);
                    dCount = resultDates.DCount;

                    for (int c = 0; c <= dCount; c++)
                    {
                        IWorksheet newWorksheet = workbook.Worksheets.AddCopyBefore(sheet);
                        GenerateSummaryScheduleCells(sheet, newWorksheet, ratePackageReportDataList, "C2Data", "Dates",
                            h, c, counter);
                        newWorksheet.Name = "RP26-" + counter;
                        foreach (var ratePackageReportData in ratePackageReportDataList)
                        {
                            newWorksheet.Replace($"{{{ratePackageReportData.CalcName}}}",
                                ratePackageReportData.DataValue);
                        }

                        pageNo++;
                        //Replaces the Page Number {NoOfPages}
                        newWorksheet.Replace("{NoOfPages}", "Page " + pageNo);

                        counter++;
                    }
                }
            }

            workbook.Worksheets.Remove(sheet);
        }

