            return newRp25Worksheet;
        }

        public static void GenerateSummaryScheduleCells(IWorksheet sheet, IWorksheet newWorksheet,
            List<RatePackageReportItem> ratePackageReportDataList,
            string schData, string dateData, int hCounter, int dCounter, int counter)
        {
            string[] dataArray = null;
            if (schData == "C1Data")
            {
                dataArray = new string[]
                {
                    "A15", "F15", "G15", "H15", "I15", "J15", "K15",
                    "D18", "D20", "E20", "H20", "I20", "J20", "K20",
                    "K22", "K23", "K24", "K25", "K26", "K27", "K28",
                    "K29", "K30", "K31", "K32", "K33", "K34", "K35",
                    "K36", "K37", "K38", "K40", "K41", "K42"
                };
            }
            else
            {
                dataArray = new string[]
                {
                    "A15", "D15", "E15", "F15", "G15", "H15", "I15", "J15", "K15",
                    "B18", "D18", "D20", "H20", "I20", "J20", "K20",
                    "K22", "K23", "K24", "K25", "K26", "K27", "K29", "K30",
                    "K31", "K32", "K33", "K34", "K35", "K36", "K37", "K38"
                };
            }


            //var pageList = pageItemList.Where(d => d.CalcName.StartsWith($"{schData}_{dateData}")).ToList();

            foreach (var data in dataArray)
            {
                var dataVal = sheet.Range[data].Value;
                int firstUnderscoreIndex = dataVal.IndexOf('_');
                if (firstUnderscoreIndex > 0)
                {
                    string calcKeyPart = dataVal.Substring(1, firstUnderscoreIndex - 1);
                    string calcKeyPartTwo = dataVal.Substring(firstUnderscoreIndex + 1);
                    if (calcKeyPart == schData)
                    {
                        if (data == "A15")
                            newWorksheet.Range[data].Value = "{" + schData + hCounter + "_Name}";
                        else
                            newWorksheet.Range[data].Value = "{" + schData + hCounter + "_" + calcKeyPartTwo;
                    }
                    else if (calcKeyPart == dateData) //IsNullOrEmpty
                        newWorksheet.Range[data].Value = "{" + schData + hCounter + "_" + dateData + dCounter + "_" +
                                                         calcKeyPartTwo;

                    //else if (!string.IsNullOrWhiteSpace(dateData) && calcKeyPart == dateData) //IsNullOrEmpty
                }
            }

            // loop through the items FOR THIS ENTRY and update the new sheet.
            foreach (var ratePackageReportData in ratePackageReportDataList)
            {
                //Replaces the given string with another string
                newWorksheet.Replace("{" + ratePackageReportData.CalcName + "}", ratePackageReportData.DataValue);
            }

            //Replaces the Summary Schedule 6.22-{counter}/6.3-{counter}
            newWorksheet.Replace("{counter}", counter);
        }

        // Method to remove the border for a specified column in the worksheet
        public static void RemoveBorderForColumn(IWorksheet worksheet, int columnIndex, string border)
        {
            // Get the column range (for all rows in the column)
            IRange columnRange = worksheet.Range[1, columnIndex, worksheet.Rows.Length, columnIndex];

            switch (border)
            {
                case "left":
                    // Set the left border to none for the entire column
                    columnRange.Borders[ExcelBordersIndex.EdgeLeft].LineStyle = ExcelLineStyle.None;
                    break;
                case "right":
                    // Set the right border to none for the entire column
                    columnRange.Borders[ExcelBordersIndex.EdgeRight].LineStyle = ExcelLineStyle.None;
                    break;
            }
        }

        public string CreateExcelStyleForRatePackages(IWorkbook workbook, string styleName)
        {
            // Set up the fonts and stuff
            if (styleName == "BodyStyle")
            {
                IStyle bodyStyle = workbook.Styles.Add(styleName);
                bodyStyle.BeginUpdate();
                bodyStyle.Font.FontName = "Times New Roman";
                bodyStyle.Font.Size = 9;
                bodyStyle.VerticalAlignment = ExcelVAlign.VAlignTop;
                bodyStyle.HorizontalAlignment = ExcelHAlign.HAlignCenter;
                bodyStyle.WrapText = false;
                bodyStyle.EndUpdate();
            }
            else if (styleName == "BlackStyle")
            {
                IStyle bodyStyle = workbook.Styles.Add(styleName);
                bodyStyle.BeginUpdate();
                bodyStyle.Font.FontName = "Times New Roman";
                bodyStyle.Font.Size = 9;
                bodyStyle.Color = Syncfusion.Drawing.Color.Black;
                bodyStyle.EndUpdate();
            }

            return styleName;
        }

        #endregion Annual Rate Packages Report

        #region Final Settlement Report

        [ARUMFeatureActionFilter(RateSettingPermissions.ProvRatesGenFinalSettlement)]
        public JsonResult GenerateFinalSettlement(RatePackageViewModel audit, List<RatePackageViewModel> rawRates,
            string fiscalYear)
        {
            try
            {
                // Create Base Report
                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;

                    // Get Template
                    string templateLocation =
                        FindTemplateLocation(rawRates.OrderBy(x => Convert.ToDateTime(x.RateEffectiveDate))
                            .FirstOrDefault());
                    var sFile = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, templateLocation);
                    string filePath = Path.GetFullPath(sFile);

                    using (FileStream fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
                    {
                        IWorkbook finalSettlementWorkbook = application.Workbooks.Open(fileStream);

                        // Create base template
                        IWorkbook templatePages = application.Workbooks.Create(1);

                        foreach (var sheet in finalSettlementWorkbook.Worksheets)
                        {
                            templatePages.Worksheets.AddCopy(sheet);
                        }

                        if (!int.TryParse(fiscalYear, out var year))
                            throw new Exception("Invalid SFY");

                        Period period = ReportBL.GetPeriodByPeriodCode($"CY{year - 2}");

                        var audits = rawRates.Distinct().Where(x => x.CostReportVersion == audit.CostReportVersion)
                            .GroupBy(x => Convert.ToDateTime(x.RateEffectiveDate))
                            .ToList();
                        audits = audits.Where(x => x.Key >= period.FiscalBegin && x.Key <= period.FiscalEnd)
                            .OrderBy(x => x.Key)
                            .ToList();

                        var earliestAuditGroup = audits.FirstOrDefault();

                        GenerateFinalSettlementReportCP(finalSettlementWorkbook, period,
                            earliestAuditGroup != null ? earliestAuditGroup.FirstOrDefault() : audit);

                        // Check If ICF or NF, remove invalid pages from templatePages, and generate pages
                        templatePages.Worksheets["Sheet1"].Remove();

                        if (RetrieveSession.Classification.Type == "ICF")
                        {
                            templatePages.Worksheets["RP3"].Remove();
                            templatePages.Worksheets["RP1"].Remove();

                            foreach (var worksheet in templatePages.Worksheets)
                            {
                                finalSettlementWorkbook.Worksheets[worksheet.Name].Remove();
                            }

                            // Create ICF pages
                            GenerateICFFinalSettlementPages(application, finalSettlementWorkbook, templatePages,
                                rawRates,
                                audit,
                                period);
                        }
                        else
                        {
                            templatePages.Worksheets["CP"].Remove();
                            templatePages.Worksheets["FS"].Remove();

                            foreach (var worksheet in templatePages.Worksheets)
                            {
                                finalSettlementWorkbook.Worksheets[worksheet.Name].Remove();
                            }

                            // Create NF pages
                            GenerateNFFinalSettlementPages(application, finalSettlementWorkbook, templatePages,
                                rawRates,
                                audit, period);
                        }

                        // Convert Base Report to PDF
                        XlsIORenderer renderer = new XlsIORenderer();

                        var fileName =
                            $"FinalSettlement_{audit.ProviderNumber}_FY{fiscalYear}.pdf"
                                .ToSafeFileName();

                        var pdfFilePath = Path.Combine(Path.GetTempPath(), fileName);

                        using (PdfDocument pdfDocument = renderer.ConvertToPDF(finalSettlementWorkbook))
                        {
                            using (Stream stream = new FileStream(pdfFilePath, FileMode.Create, FileAccess.ReadWrite))
                            {
                                pdfDocument.Save(stream);
                            }

                            finalSettlementWorkbook.Close();
                        }

                        // Return reference to Report
                        return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) });
                    }
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
            finally
            {
                if (rawRates != null && rawRates.Count > 0)
                {
                    rawRates.ForEach(x => x.Dispose());
                    rawRates.Clear();
                }
            }
        }

        private void GenerateFinalSettlementReportCP(IWorkbook parent, Period period, RatePackageViewModel audit)
        {
            List<RatePackageReportItem> ratePackageReportDataList = GetRatePackageReportData(audit.RatePackageId);

            // "D" date format includes the day name, which much be removed.
            string startDate = period.FiscalBegin.ToString("D");
            // remove up to the comma, and then the extra space after.
            startDate = startDate.Substring(startDate.IndexOf(',')).Substring(1);
            // "D" date format includes the day name, which much be removed.
            string endDate = period.FiscalEnd.ToString("D");
            // remove up to the comma, and then the extra space after.
            endDate = endDate.Substring(endDate.IndexOf(',')).Substring(1);

            foreach (var ratePackageReportData in ratePackageReportDataList)
            {
                parent.Worksheets[0].Replace("{" + ratePackageReportData.CalcName + "}",
                    ratePackageReportData.CalcName == "FormattedRatePeriod"
                        ? $"{startDate} through {endDate}"
                        : ratePackageReportData.DataValue
                );
            }
        }

        private void GenerateNFFinalSettlementPages(IApplication application, IWorkbook parent, IWorkbook templatePages,
            List<RatePackageViewModel> rates, RatePackageViewModel audit, Period period)
        {
            GenerateFinalSettlementRateRecalculationPage(parent, rates, audit, period, 16, "NF");

            List<RatePackageReportItem> ratePackageReportDataList = GetRatePackageReportData(audit.RatePackageId);

            foreach (var ratePackageReportData in ratePackageReportDataList)
            {
                parent.Worksheets["FS"].Replace("{" + ratePackageReportData.CalcName + "}",
                    ratePackageReportData.DataValue);
            }

            SortedDictionary<DateTime, RatePackageViewModel> nonAudits = FinalSettlementReportBL.GetNonAuditMonthlyRatePackages(period, rates);
            SortedDictionary<DateTime, RatePackageViewModel> auditRates = FinalSettlementReportBL.GetAuditMonthlyRatePackages(period, audit, rates, nonAudits);
            var newRates = auditRates.Values.Distinct().ToList();

           if (templatePages.Worksheets.Any(x => x.Name.Contains("_")))
                //This filter is used to ensure that only the rates that are of the same RateType as the selected rate are used.
                GenerateCustomNFFinalSettlementPages(application, parent, templatePages, newRates, period);
            else
                //This filter is used to ensure that only the rates that are of the same RateType as the selected rate are used.
                GenerateStandardNFFinalSettlementPages(application, parent, templatePages, newRates, period);
        }

        private void GenerateFinalSettlementRateRecalculationPage(IWorkbook parent, List<RatePackageViewModel> rates,
            RatePackageViewModel audit, Period period, int startLineNo, string type)
        {
            string[] finalRateGridArray = { "B", "D", "F", "H" };

            IWorksheet sheet = type == "NF" ? parent.Worksheets["FS"] : parent.Worksheets["RP3"];
            sheet.DeleteRow(startLineNo, 12);

            foreach (var rate in rates)
            {
              rate.RateTypeId=  ClientMapping.GetInternalIdFromClientId(rate.RateTypeId, "ratetype");
              rate.RatePackageId=  ClientMapping.GetInternalIdFromClientId(rate.RatePackageId, "ratepackage");
            }

            SortedDictionary<DateTime, RatePackageViewModel> nonRes =
                FinalSettlementReportBL.GetNonAuditMonthlyRatePackages(period, rates);
            SortedDictionary<DateTime, RatePackageViewModel> audRes =
                FinalSettlementReportBL.GetAuditMonthlyRatePackages(period, audit, rates, nonRes);

            // Loop through the non-audit months and get the rate for each month.
            foreach (var kvp in nonRes)
            {
                sheet.InsertRow(startLineNo, 1, ExcelInsertOptions.FormatAsBefore);
                sheet.SetRowHeight(startLineNo, 26.25);

                decimal ratePaid = 0;

                // If there is a value, try to use the value.
                if (kvp.Value != null) decimal.TryParse(kvp.Value.FinalRateAmount, out ratePaid);

                // Get corresponding audit rate for the current non-audit month.
                // If one does not exist, it will use the value ratePaid - so that it matches.
                decimal finalRate = ratePaid;
                if (audRes[kvp.Key] != null) decimal.TryParse(audRes[kvp.Key].FinalRateAmount, out finalRate);

                foreach (var finalRateArray in finalRateGridArray)
                {
                    switch (finalRateArray)
                    {
                        case "B":
                            sheet.Range[finalRateArray + startLineNo].Value = kvp.Key.ToString("MMMM").ToUpper();
                            break;
                        case "D":
                            sheet.Range[finalRateArray + startLineNo].Value =
                                (ratePaid).ToString(CultureInfo.CurrentCulture);
                            break;
                        case "F":
                            sheet.Range[finalRateArray + startLineNo].Value =
                                (finalRate).ToString(CultureInfo.CurrentCulture);
                            break;
                        case "H":
                            sheet.Range[finalRateArray + startLineNo].Value = Math.Max(0, ratePaid - finalRate)
                                .ToString(CultureInfo.CurrentCulture);
                            break;
                    }
                }

                sheet.Range[startLineNo, 1].NumberFormat = "Text";
                sheet.Range[startLineNo, 1].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                sheet.Range[startLineNo, 4].NumberFormat = "0.00";
                sheet.Range[startLineNo, 6].NumberFormat = "0.00";
                sheet.Range[startLineNo, 8].NumberFormat = "0.00";
                startLineNo++;
            }
        }

        private void GenerateCustomNFFinalSettlementPages(IApplication application, IWorkbook parent,
            IWorkbook templatePages,
            List<RatePackageViewModel> rates, Period period)
        {
            var destWorkbook = application.Workbooks.Create(1);
            for (int i = 0; i < templatePages.Worksheets.Count; i++)
            {
                IWorksheet t = templatePages.Worksheets[i];
                destWorkbook.Worksheets.AddCopy(t);
            }

            destWorkbook.Worksheets[0].Remove();

            foreach (var template in templatePages.Worksheets)
            {
                if (template.Name.Contains("_7.1"))
                {
                    var rate = rates.FirstOrDefault(x => x.RateEffectiveDate.Contains("7/1"));

                    if (rate != null)
                    {
                        List<RatePackageReportItem> ratePackageReportDataList =
                            GetRatePackageReportData(rate?.RatePackageId);

                        foreach (var ratePackageReportData in ratePackageReportDataList)
                        {
                            destWorkbook.Worksheets[template.Name].Replace("{" + ratePackageReportData.CalcName + "}",
                                ratePackageReportData.DataValue);
                        }
                    }
                    else
                    {
                        destWorkbook.Worksheets[template.Name].Remove();
                    }
                }

                if (!template.Name.Contains("_1.1")) continue;
                {
                    var rate = rates.FirstOrDefault(x => x.RateEffectiveDate.Contains("1/1"));

                    if (rate != null)
                    {
                        List<RatePackageReportItem> ratePackageReportDataList =
                            GetRatePackageReportData(rate?.RatePackageId);

                        foreach (var ratePackageReportData in ratePackageReportDataList)
                        {
                            destWorkbook.Worksheets[template.Name].Replace("{" + ratePackageReportData.CalcName + "}",
                                ratePackageReportData.DataValue);
                        }
                    }
                    else
                    {
                        destWorkbook.Worksheets[template.Name].Remove();
                    }
                }
            }

            for (int i = 0; i < destWorkbook.Worksheets.Count; i++)
            {
                var d = destWorkbook.Worksheets[i];
                parent.Worksheets.AddCopy(d);
            }

            destWorkbook.Close();
        }

        private void GenerateStandardNFFinalSettlementPages(IApplication application, IWorkbook parent,
            IWorkbook templatePages, List<RatePackageViewModel> rates, Period period)
        {
            for (var ri = 0; ri < rates.Count; ri++)
            {
                var destWorkbook = application.Workbooks.Create(1);

                for (int i = 0; i < templatePages.Worksheets.Count; i++)
                {
                    IWorksheet t = templatePages.Worksheets[i];
                    destWorkbook.Worksheets.AddCopy(t);
                }

                destWorkbook.Worksheets[0].Remove();

                if (ri != 0)
                {
                    for (int i = 0; i < templatePages.Worksheets.Count; i++)
                    {
                        destWorkbook.Worksheets[i].Name += $"-{ri}";
                    }

                    foreach (var template in templatePages.Worksheets)
                    {
                        List<RatePackageReportItem> ratePackageReportDataList =
                            GetRatePackageReportData(rates[ri].RatePackageId);
                        foreach (var ratePackageReportData in ratePackageReportDataList)
                        {
                            destWorkbook.Worksheets[template.Name + $"-{ri}"].Replace(
                                "{" + ratePackageReportData.CalcName + "}",
                                ratePackageReportData.DataValue);
                        }
                    }
                }
                else
                {
                    foreach (var template in templatePages.Worksheets)
                    {
                        List<RatePackageReportItem> ratePackageReportDataList =
                            GetRatePackageReportData(rates[0].RatePackageId);
                        foreach (var ratePackageReportData in ratePackageReportDataList)
                        {
                            destWorkbook.Worksheets[template.Name].Replace(
                                "{" + ratePackageReportData.CalcName + "}",
                                ratePackageReportData.DataValue);
                        }
                    }
                }

                for (int i = 0; i < destWorkbook.Worksheets.Count; i++)
                {
                    var d = destWorkbook.Worksheets[i];
                    parent.Worksheets.AddCopy(d);
                }

                destWorkbook.Close();
            }
        }

        /// <summary>
        /// Encapsulate the parsing of the client report Id and retrieving data from BL.
        /// </summary>
        /// <param name="ratePId"></param>
        /// <returns></returns>
        private List<RatePackageReportItem> GetRatePackageReportData(string ratePId)
        {
            int ratePackageId = 0;

            if (int.TryParse(ClientMapping.GetInternalIdFromClientId(ratePId, "ratepackage"),
                    out int id))
            {
                ratePackageId = id;
            }

            return RateBL.GetRatePackageReportDataRO(ratePackageId);
        }

        private void GenerateICFFinalSettlementPages(IApplication application, IWorkbook parent,
            IWorkbook templatePages, List<RatePackageViewModel> rates, RatePackageViewModel audit, Period period)
        {
            GenerateFinalSettlementRateRecalculationPage(parent, rates, audit, period, 16, "ICF");

            List<RatePackageReportItem> ratePackageReportDataList = GetRatePackageReportData(audit.RatePackageId);

            foreach (var ratePackageReportData in ratePackageReportDataList)
            {
                parent.Worksheets["RP3"].Replace("{" + ratePackageReportData.CalcName + "}",
                    ratePackageReportData.DataValue);
            }

            SortedDictionary<DateTime, RatePackageViewModel> nonAudits = FinalSettlementReportBL.GetNonAuditMonthlyRatePackages(period, rates);
            SortedDictionary<DateTime, RatePackageViewModel> auditRates = FinalSettlementReportBL.GetAuditMonthlyRatePackages(period, audit, rates, nonAudits);
            var newRates = auditRates.Values.Distinct().ToList();

            GenerateStandardICFFinalSettlementPages(application, parent, templatePages, newRates, period);
        }

