        private string FindTemplateLocation(RatePackageViewModel rate)
        {
            string ratePackageReportTemplateLocation;
            if (!DateTime.TryParse(rate.RateEffectiveDate, out DateTime docEffectiveDate))
                throw new Exception("Invalid input of effective date; please enter a valid effective date.");

            switch (RetrieveSession.Classification.Type)
            {
                case "ICF":
                    ratePackageReportTemplateLocation = RateBL.GetRatePackageTemplateLocation("ICF",
                        ARUMConfigurationOHFI.FinalSettlementRatePackageReportTemplateLocation(RetrieveSession
                            .Classification), docEffectiveDate);


                    break;
                case "NF":
                    ratePackageReportTemplateLocation = RateBL.GetRatePackageTemplateLocation("NF",
                        ARUMConfigurationOHFI.FinalSettlementRatePackageReportTemplateLocation(RetrieveSession
                            .Classification), docEffectiveDate);
                    break;
                default:
                    throw new Exception(
                        $"Invalid Classification selected.");
            }

            return ratePackageReportTemplateLocation;
        }

