        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult ProviderAddressListReport()
        {
            IAddressCodeFunctions addressCodeFunctions =
                CostReportBL.GetInstanceAddressCodeFunctions(RetrieveSession.Classification);
            var validAddressCodes = addressCodeFunctions.GetCodeList();

            ProviderAddressListReportViewModel providerAddressVM = new ProviderAddressListReportViewModel();

            var list = new List<SelectListItem>();
            list.Add(new SelectListItem { Text = "All", Value = "ALL" });
            foreach (var key in validAddressCodes.Keys)
            {
                list.Add(new SelectListItem
                {
                    Text = validAddressCodes[key],
                    Value = key
                });
            }

            providerAddressVM.StartDate = string.Empty;
            providerAddressVM.AddressTypes = list;
            return PartialView("Report/_ProviderAddressListReport", providerAddressVM);
        }

        [HttpPost]
        public JsonResult GenerateProviderAddressReport(string addressType, string startDate, bool includeInactive)
        {
            var classification = RetrieveSession.Classification;
            var providerAddressVM = new ProviderAddressListReportViewModel();
            IAddressCodeFunctions addressCodeFunctions = CostReportBL.GetInstanceAddressCodeFunctions(classification);

            string fileName = string.Empty;
            string fullPath = string.Empty;

            var activeStatuses = new Dictionary<string, string>
            {
                { "CHA", "ACTIVE - CHOP" },
                { "REN", "ACTIVE - INITIAL REENTRY" },
                { "IEN", "ACTIVE - INITIAL ENTRY" },
                { "WDG", "ACTIVE - WITHDRAWING" },
            };

            var inactiveStatuses = new Dictionary<string, string>
            {
                { "CLD", "CLOSED" },
                { "TRD", "TERMINATED" },
                { "WDN", "WITHDRAWN" },
                { "CHI", "INACTIVE - CHOP" }
            };

            var allStatuses = new Dictionary<string, string>
            {
                { "CHA", "ACTIVE - CHOP" },
                { "REN", "ACTIVE - INITIAL REENTRY" },
                { "IEN", "ACTIVE - INITIAL ENTRY" },
                { "WDG", "ACTIVE - WITHDRAWING" },
                { "CLD", "CLOSED" },
                { "TRD", "TERMINATED" },
                { "WDN", "WITHDRAWN" },
                { "CHI", "INACTIVE - CHOP" }
            };


            try
            {
                using (var excelEngine = new ExcelEngine())
                {
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;
                    IWorkbook workbook = application.Workbooks.Create(1);
                    IWorksheet worksheet = workbook.Worksheets[0];

                    // ------------------------------
                    List<Provider> lstProviders = GetAllProviderList(RetrieveSession.Classification.ARUMToken, false,
                        true, true, true, false, false, false, true,
                        false, "Rate.GetProvividerList").lstProviders;
                    // ------------------------------

                    var allProvidersEffectiveDateRecords = lstProviders.Select(x => x.EffectiveDates).ToList();

                    _ = DateTime.TryParse(startDate, out var startDt);

                    var providersToRemoveFromList = new List<int>();
                    foreach (var effDateRecsForProvider in allProvidersEffectiveDateRecords)
                    {
                        foreach (var effDateRec in effDateRecsForProvider)
                        {
                            if (includeInactive)
                            {
                                if (effDateRec.EndDate < startDt)
                                {
                                    providersToRemoveFromList.Add(effDateRec.ProviderID);
                                }
                            }
                        }
                    }

                    var allProviderIds = lstProviders.Select(x => x.ProviderID).ToList();
                    var providerIdsToProcess = allProviderIds.Except(providersToRemoveFromList).ToList();

                    // Get the final list of Provider Records based on the calculated id's to process
                    var finalProviderList = lstProviders.Where(x => providerIdsToProcess.Contains(x.ProviderID))
                        .OrderBy(x => x.MCAID)
                        .ToList();


                    ICodes arum_Codes =
                        _applicationServiceProxy.GetAllCodes(RetrieveSession.Classification.ARUMToken, "Rate/Provider");

                    var addressTypes = arum_Codes.lstCodes.Where(x => x.Type == "Address").ToList();


                    var row = 1;
                    var providerStatus = string.Empty;
                    var facilityType = string.Empty;
                    var currentAddresses = new List<Addresses>();
                    var addressTypeName = string.Empty;


                    foreach (var currentProvider in finalProviderList)
                    {
                        if (!currentProvider.HasAddresses)
                        {
                            continue;
                        }

                        var arum_Status = currentProvider.ProviderStatuses;
                        if (!arum_Status.Any())
                        {
                            continue;
                        }

                        var providerStatusRec = arum_Status
                            .Where(x => x.IsActive == true
                                        && x.Type.ToUpper() == "MEDICAID")
                            .OrderByDescending(x => x.EffectiveDate)
                            .FirstOrDefault();
                        providerStatus = providerStatusRec.Status;

                        var providerStatusText = string.Empty;

                        if (allStatuses.ContainsKey(providerStatusRec.Status))
                        {
                            providerStatusText = allStatuses[providerStatusRec.Status];
                        }

                        var effectiveDate = providerStatusRec.EffectiveDate;
                        if (!activeStatuses.ContainsKey(providerStatus))
                        {
                            if (includeInactive && !inactiveStatuses.ContainsKey(providerStatus)
                                || effectiveDate < startDt)
                            {
                                continue;
                            }
                        }

                        var countyCode = currentProvider.EffectiveDates?
                            .OrderByDescending(x => x.DateEffective)
                            .FirstOrDefault()?
                            .County;

                        var addressTypeKey = string.Empty;
                        if (addressType.ToUpper() != "ALL")
                        {
                            addressTypeKey = addressTypes.FirstOrDefault(x => x.Value == addressType).Value;
                        }

                        if (addressType.ToUpper() == "ALL")
                        {
                            currentAddresses = currentProvider.Addresses
                                .Where(x => x.IsActive &&
                                            x.Type.ToUpper() != "NA")
                                .OrderByDescending(x => x.CreateDate)
                                .ThenByDescending(x => x.LastModified)
                                .ToList();
                        }
                        else
                        {
                            currentAddresses = currentProvider.Addresses
                                .Where(x => x.IsActive &&
                                            addressCodeFunctions.IsValidCode(x.Type) &&
                                            x.Type.ToUpper() == addressTypeKey.ToUpper() &&
                                            x.Type.ToUpper() != "NA")?
                                .OrderByDescending(x => x.CreateDate)
                                .ThenByDescending(x => x.LastModified)
                                .ToList();
                        }

                        foreach (var address in currentAddresses)
                        {
                            var typeCheck = string.Empty;
                            var addressCode = arum_Codes.lstCodes.Where(x => x.Value == address.Type)
                                ?.FirstOrDefault();
                            if (addressCode != null)
                            {
                                typeCheck = address.Type;
                            }

                            var invalidTypeNames = new List<string> { "MLG", "PHY" };
                            if (invalidTypeNames.Contains(typeCheck))
                            {
                                continue;
                            }

                            var zipCode = address.ZipCode;
                            zipCode = !string.IsNullOrWhiteSpace(address.ZipCode2)
                                ? zipCode += $"-{address?.ZipCode2}"
                                : zipCode;

                            addressTypeName = addressCode.Name;

                            var fullAddress = new AddressFullViewModel
                            {
                                AddressType = addressTypeName,
                                AddressName = currentProvider.Name,
                                AddressLineOne = address.Address1,
                                AddressLineTwo = address.Address2,
                                AddressCity = address.City,
                                AddressState = address.State,
                                AddressZipCode = zipCode,
                                AddressCounty =
                                    addressCodeFunctions.GetCountyNameByCountyCode(Convert.ToInt32(countyCode))
                            };
                            if (!string.IsNullOrWhiteSpace(address.ZipCode2))
                            {
                                zipCode += $"-{address.ZipCode2}";
                            }

                            row = PrintAddressRow(worksheet, currentProvider, fullAddress,
                                providerStatusText, row, effectiveDate);
                        }

                        // CH119 section
                        AddressFullViewModel addresses;

                        if (addressType.ToUpper() == "NA" ||
                            addressType.ToUpper() == "ALL")
                        {
                            var addressTypeID = RateBL.GetAddressTypeId(); // Gets the 119 Notice Type ID
                            if (addressTypeID == 0)
                            {
                                continue;
                            }

                            Address cH119NoticeAddress =
                                RateBL.GetNoticeAddress(currentProvider.ProviderID, addressTypeID);
                            if (cH119NoticeAddress != null)
                            {
                                addresses = new AddressFullViewModel
                                {
                                    AddressType = arum_Codes.lstCodes.SingleOrDefault(x => x.Value == "NA").Name,
                                    AddressName = currentProvider.Name,
                                    AddressLineOne = cH119NoticeAddress.AddressLineOne ?? string.Empty,
                                    AddressLineTwo = cH119NoticeAddress.AddressLineTwo ?? string.Empty,
                                    AddressCity = cH119NoticeAddress.City ?? string.Empty,
                                    AddressState = cH119NoticeAddress.State ?? string.Empty,
                                    AddressZipCode = cH119NoticeAddress?.ZipCode ?? string.Empty,
                                    AddressCounty = cH119NoticeAddress.County ?? string.Empty
                                };

                                row = PrintAddressRow(worksheet, currentProvider, addresses, providerStatusText,
                                    row, effectiveDate);
                            }
                        }
                    }

                    if (worksheet.Rows.Length == 0)
                    {
                        throw new Exception(" No data met the criteria for the report.");
                    }

                    // Set up the fonts and stuff

                    var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var headerStyleName = CreateStyle(workbook, "HeaderStyle", true, 11, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignLeft);
                    var bodyStyleName = CreateStyle(workbook, "BodyStyle", false, 8, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignLeft);

                    worksheet.UsedRange.CellStyleName = bodyStyleName;
                    worksheet.Columns.ToTypedSource();
                    worksheet.Columns[0].NumberFormat = "0000000";
                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;
                    worksheet.PageSetup.FitToPagesWide = 1;
                    worksheet.PageSetup.FitToPagesTall = 0;


                    if (worksheet.Rows.Length > 2)
                    {
                        worksheet.Range["A1:J1"].Merge();
                        worksheet.Rows[0].CellStyleName = titleStyleName;
                        worksheet.Rows[1].CellStyleName = headerStyleName;
                        worksheet.Range[3, 1].FreezePanes();
                    }

                    worksheet.UsedRange.AutofitRows();

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;

                    fileName =
                        $"{SimplifiedType}_ProviderAddressListReport_Run_{DateTime.Now.ToString("yyyyMMdd")}.xlsx"
                            .ToSafeFileName();
                    fullPath = Path.Combine(Path.GetTempPath(), fileName);

