            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    FileName = string.Empty,
                    Message = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }

            return Json(new
            {
                Success = true,
                FileName = fileName,
                Message = string.Empty
            },
                JsonRequestBehavior.AllowGet);
        }

