        [HttpPost]
        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult ClosedFacilitiesReport(string startDate, string endDate, string providerStatus)
        {
            var classification = RetrieveSession.Classification;
            int row = 1;

            var facilityType = string.Empty;
            switch (SimplifiedType)
            {
                case "NF":
                    facilityType = "Nursing Facility";
                    break;
                case "ICF":
                    facilityType = "ICF";
                    break;
                default:
                    throw new Exception($" Unknown Facility Type {SimplifiedType}");
            }

            IWorkbook workbook;
            IWorksheet worksheet;

            string fileName = string.Empty;
            string fullPath = string.Empty;

            var facilityStatusHeading = string.Empty;
            List<string> statusesToPull = new List<string>();
            switch (providerStatus)
            {
                case "0":
                    statusesToPull.Add("CLD");
                    statusesToPull.Add("TRD");
                    statusesToPull.Add("WDN");
                    statusesToPull.Add("CHI");
                    facilityStatusHeading = "ALL";
                    break;
                case "1":
                    statusesToPull.Add("CLD");
                    facilityStatusHeading = "Closed";
                    break;
                case "2":
                    statusesToPull.Add("TRD");
                    facilityStatusHeading = "Terminated";
                    break;
                case "3":
                    statusesToPull.Add("WDN");
                    facilityStatusHeading = "Withdrawn";
                    break;
                case "4":
                    statusesToPull.Add("CHI");
                    facilityStatusHeading = "Inactive-CHOP";
                    break;
                default: throw new Exception("Status Type not found.");
            }

            Dictionary<string, string> statusNamesByKey = new Dictionary<string, string>
            {
                { "0", "ALL" },
                { "CLD", "Closed" },
                { "TRD", "Terminated" },
                { "WDN", "Withdrawn" },
                { "CHI", "Inactive-CHOP" }
            };

            try
            {
                var _applicationServiceProxy = ARUMApplication.GetARUMApplicationProxy(RetrieveSession.Classification);

                using (var excelEngine = new ExcelEngine())
                {
                    // ---------------------------------------------
                    // Set up the report
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;
                    workbook = application.Workbooks.Create(1);

                    worksheet = workbook.Worksheets[0];
                    // ---------------------------------------------

                    var closedFacilities = GetClosedFacilityList(startDate, endDate);

                    var facilityStatus = string.Empty;
                    var facilityStatusEffDate = string.Empty;

                    foreach (var currentFacility in closedFacilities)
                    {
                        var currentProvider = currentFacility.Provider;

                        if (!statusesToPull.Contains(currentFacility.Status))
                        {
                            continue;
                        }

                        facilityStatus = statusNamesByKey[currentFacility.Status];
                        facilityStatusEffDate = currentFacility?.StatusEffectiveDate.ToShortDateString() ?? "N/A";

                        row = PrintClosedFacilityRow(workbook, worksheet, currentProvider, facilityType,
                            facilityStatusEffDate, row, startDate, endDate, facilityStatus, facilityStatusHeading);
                    }

                    var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var headerStyleName = CreateStyle(workbook, "HeaderStyle", true, 11, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var bodyStyleName = CreateStyle(workbook, "BodyStyle", false, 8, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignLeft);

                    if (worksheet.Rows.Length == 0)
                    {
                        throw new Exception(" No data met the criteria for the report.");
                    }

                    worksheet.UsedRange.CellStyleName = bodyStyleName;
                    worksheet.Columns[0].NumberFormat = "0000000";

                    if (worksheet.Rows.Length > 3)
                    {
                        worksheet.Rows[1].CellStyleName = headerStyleName;
                        worksheet.Rows[1].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                        worksheet.Rows[2].CellStyleName = headerStyleName;
                        worksheet.Rows[2].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                        worksheet.Rows[4].CellStyleName = headerStyleName;
                    }

                    worksheet.Rows[0].CellStyleName = titleStyleName;
                    worksheet.Range["A1:D1"].Merge();
                    worksheet.Range["A2:D2"].Merge();
                    worksheet.Range["A3:D3"].Merge();
                    worksheet.Range["A1:D1"].HorizontalAlignment = ExcelHAlign.HAlignCenter;
                    worksheet.Range["A1:D1"].VerticalAlignment = ExcelVAlign.VAlignCenter;
                    worksheet.Range[6, 1].FreezePanes();
                    worksheet.UsedRange.AutofitRows();
                    worksheet.UsedRange.AutofitColumns();
                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.PageSetup.FitToPagesWide = 1;
                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;

                    fileName = $"{SimplifiedType}_ClosedFacilitiesReport_Run_{DateTime.Now.ToString("yyyyMMdd")}.xlsx";
                    fullPath = Path.Combine(Path.GetTempPath(), fileName);

                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    FileName = string.Empty,
                    Message = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }

            return Json(new
            {
                Success = true,
                FileName = fileName,
                Message = string.Empty
            },
                JsonRequestBehavior.AllowGet);
        }

