        private List<ProviderStatus> GetClosedFacilityList(string startDate, string endDate)
        {
            Dictionary<string, string> statusNamesByKey = new Dictionary<string, string>
            {
                { "ALL", "ALL" },
                { "CLD", "Closed" },
                { "TRD", "Terminated" },
                { "WDN", "Withdrawn" },
                { "CHI", "Inactive-CHOP" }
            };

            _ = DateTime.TryParse(startDate, out var startDt);
            _ = DateTime.TryParse(endDate, out var endDt);

            var providerList =
                GetAllProviderList(
                        RetrieveSession.Classification.ARUMToken,
                        false, false, false, false, false,
                        false, false, true, false, "ClosedFacilitiesReport.GetClosedFacilityProviderList")
                    .lstProviders?
                    .OrderBy(x => x.MCAID)
                    .ToList();

            if (providerList == null)
            {
                throw new Exception($" Providers not found.");
            }

            var providerStatuses = new List<ProviderStatus>();
            foreach (var provider in providerList)
            {
                var arum_Statuses = provider.ProviderStatuses;

                var providerStatusRec = arum_Statuses
                    .Where(x => x.Type.ToUpper() == "MEDICAID" &&
                                x.IsActive == true
                                && x.EffectiveDate <= endDt
                                && x.EffectiveDate >= startDt)
                    .OrderByDescending(x => x.EffectiveDate)
                    .Select(x => new ProviderStatus
                    {
                        Provider = provider,
                        StatusEffectiveDate = x.EffectiveDate,
                        Status = x.Status
                    }
                    )
                    .FirstOrDefault();

                if (!statusNamesByKey.ContainsKey(providerStatusRec?.Status ?? "NoRecord"))
                {
                    continue;
                }

                providerStatuses.Add(providerStatusRec);
            }

            return providerStatuses;
        }

        private class ProviderStatus
        {
            public Provider Provider { get; set; }
            public string Status { get; set; }
            public DateTime StatusEffectiveDate { get; set; }
        }

