        [HttpPost]
        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult NewFacilitiesReport(string startDate, string endDate)
        {
            var myUser = RetrieveSession.ARUMUser;
            var classification = RetrieveSession.Classification;
            IAddressCodeFunctions addressCodeFunctions = CostReportBL.GetInstanceAddressCodeFunctions(classification);
            EffectiveDate effectiveDateRecord = null;
            int row = 1;

            var activeStatuses = new List<string>
            {
                "IEN"
            };

            IWorkbook workbook;
            IWorksheet worksheet;

            string fileName = string.Empty;
            string fullPath = string.Empty;

            try
            {
                var facilityTypeHeader = string.Empty;
                var facilityName = string.Empty;

                // Setup values based on connection string information.
                if (SimplifiedType.Contains("ICF"))
                {
                    facilityTypeHeader = "ICF IID";
                }
                else if (SimplifiedType.ToUpper().Contains("NF"))
                {
                    facilityTypeHeader = "Nursing Facility";
                }

                using (var excelEngine = new ExcelEngine())
                {
                    // ---------------------------------------------
                    // Set up the report workbook
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;
                    workbook = application.Workbooks.Create(1);

                    worksheet = workbook.Worksheets[0];
                    // ---------------------------------------------

                    var providerList = GetAllProviderList(RetrieveSession.Classification.ARUMToken, false, true, false,
                        true, false, false, false, true, false, "RateController.NewFacilitiesReport").lstProviders;
                    if (providerList == null)
                    {
                        throw new Exception(" Providers not found.");
                    }

                    providerList = providerList.OrderBy(x => x.MCAID).ToList();
                    var providerStatusText = string.Empty;

                    _ = DateTime.TryParse(startDate, out var startEffDate);
                    _ = DateTime.TryParse(endDate, out var effDateEnd);

                    foreach (var currentProvider in providerList)
                    {
                        effectiveDateRecord = SelectProviderEffectiveDate("WithinRange", currentProvider.EffectiveDates,
                            startEffDate, effDateEnd);
                        if (effectiveDateRecord?.DateEffective == null)
                        {
                            continue;
                        }

                        var arum_Status = currentProvider.ProviderStatuses;
                        if (arum_Status.Any())
                        {
                            var providerStatusRec = arum_Status
                                .Where(x => x.IsActive && x.Type.ToUpper() == "MEDICAID")
                                .OrderByDescending(x => x.ProviderStatusID)
                                .FirstOrDefault();
                            if (providerStatusRec == null ||
                                !activeStatuses.Contains(providerStatusRec.Status.ToUpper()))
                            {
                                // All statuses will be represented in these records, so this is not an error.
                                continue;
                            }

                            providerStatusText = providerStatusRec.Status;
                        }
                        else
                        {
                            continue;
                        }

                        facilityName = currentProvider.Name;
                        var county = string.Empty;
                        if (effectiveDateRecord.County != null)
                        {
                            county = addressCodeFunctions.GetCountyNameByCountyCode(
                                Convert.ToInt32(effectiveDateRecord?.County));
                        }

                        int licensedBeds = RateBL.GetLastLicensedBeds(currentProvider.ProviderID);
                        int certifiedBeds = RateBL.GetLastCertifiedBedCount(currentProvider.ProviderID);
                        var providerEffDate = effectiveDateRecord.DateEffective ?? DateTime.Now;

                        row = PrintNewFacilityRow(worksheet, currentProvider,
                            providerEffDate, row, startDate, endDate, certifiedBeds, licensedBeds, county,
                            providerStatusText, facilityTypeHeader);
                    }

                    if (worksheet.Rows.Length == 0)
                    {
                        throw new Exception(" No data met the criteria for the report.");
                    }

                    var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var headerStyleName = CreateStyle(workbook, "HeaderStyle", true, 11, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var bodyStyleName = CreateStyle(workbook, "BodyStyle", false, 8, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignLeft);
                    var numberStyleName = CreateStyle(workbook, "NumberStyle", false, 8, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignRight);

                    worksheet.UsedRange.CellStyleName = bodyStyleName;
                    worksheet.UsedRange.AutofitRows();
                    worksheet.UsedRange.AutofitColumns();
                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;
                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.Columns[0].NumberFormat = "0000000";
                    worksheet.Columns[3].CellStyleName = numberStyleName;
                    worksheet.Columns[4].CellStyleName = numberStyleName;
                    worksheet.SetColumnWidth(1, 10);
                    worksheet.SetColumnWidth(6, 10);

                    worksheet.Range["A1:F1"].Merge();
                    worksheet.Range["A2:F2"].Merge();
                    worksheet.Range["A3:F3"].Merge();
                    worksheet.Rows[0].CellStyleName = titleStyleName;

                    if (worksheet.Rows.Length > 5)
                    {
                        worksheet.Rows[1].CellStyleName = titleStyleName;
                        worksheet.Range["A2"].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                        worksheet.Rows[2].CellStyleName = headerStyleName;
                        worksheet.Range["A3"].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                        worksheet.Rows[4].CellStyleName = headerStyleName;
                        worksheet.Range[6, 1].FreezePanes();
                    }


                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;

                    fileName = $"{SimplifiedType}_NewFacilityReport_Run_{DateTime.Now.ToString("yyyyMMdd")}.xlsx";
                    fullPath = Path.Combine(Path.GetTempPath(), fileName);

                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    FileName = string.Empty,
                    Message = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }

            return Json(new
            {
                Success = true,
                FileName = fileName,
                Message = string.Empty
            },
                JsonRequestBehavior.AllowGet);
        }


