        {
            Dictionary<int, (DateTime EffectiveDate, DateTime? EffectiveDateEnd)> providerEffDates =
                new Dictionary<int, (DateTime EffectiveDate, DateTime? EffectiveDateEnd)>();

            List<string> validStatuses = new List<string>
            {
                "CHA",
                "IEN",
                "WDG",
                "REN",
                "CLD",
                "TRD",
                "WDN",
                "CHI"
            };

            var myUser = RetrieveSession.ARUMUser;
            var classification = RetrieveSession.Classification;
            IAddressCodeFunctions addressCodeFunctions = CostReportBL.GetInstanceAddressCodeFunctions(classification);

            var reportType = string.Empty;
            var fileName = string.Empty;
            var fullPath = string.Empty;

            IWorkbook workbook;
            IWorksheet worksheet;

            DateTime startEffDate;
            DateTime endEffDate;

            int row = 1;

            try
            {
                using (var excelEngine = new ExcelEngine())
                {
                    // ---------------------------------------------
                    // Set up the report
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;
                    workbook = application.Workbooks.Create(1);

                    worksheet = workbook.Worksheets[0];

                    IAllProviders allArum_Providers =
                        _applicationServiceProxy.GetAllActiveProvidersWithOptions(
                            classification.ARUMToken,
                            false, true, false, true, false,
                            true, true, "Rate/MedicareNumberReport");
                    if (!allArum_Providers.Result.Successful)
                    {
                        throw new Exception($" Providers not found. {allArum_Providers.Result.Message}.");
                    }

                    var arumAffiliates = GetAllAffiliatesList(RetrieveSession.Classification.ARUMToken, false, true,
                        false, false, false, "RateController.LicensedBedCountReport");

                    List<County> counties = addressCodeFunctions.GetCounties();

                    foreach (var currentProvider in allArum_Providers.lstProviders.OrderBy(x => x.MCAID))
                    {
                        var providerStatusText = string.Empty;

                        _ = DateTime.TryParse(startDate, out startEffDate);
                        _ = DateTime.TryParse(endDate, out endEffDate);

                        var validEffectiveDateRecord = SelectProviderEffectiveDate("WithinRange",
                            currentProvider.EffectiveDates,
                            startEffDate, endEffDate);
                        if (validEffectiveDateRecord == null)
                        {
                            continue;
                        }

                        // Get the Provider Status
                        MSLC.ProviderProxy.Interfaces.IArumProviderStatusList arum_Status;
                        arum_Status = _providerServiceProxy.GetAllProviderStatusesByProviderID(
                            classification.ARUMToken, currentProvider.ProviderID, "Rate/MedicareNumberReport");
                        if (arum_Status.ProviderStatuses.Any())
                        {
