                            continue;
                        }

                        var medicareId = currentProvider.Identifiers
                                             ?.FirstOrDefault(x => x.Type.ToUpper() == "MEDICAREID")?.Value.PadLeft(7)
                                         ?? string.Empty;

                        var medicaidId = currentProvider.MCAID.PadLeft(7) ?? string.Empty;

                        var effDateStart = validEffectiveDateRecord.DateEffective ?? DateTime.Now;
                        var effDateEnd = validEffectiveDateRecord.EndDate ?? DateTime.Now;

                        var county =
                            counties.FirstOrDefault(x => x.Number == Convert.ToInt32(validEffectiveDateRecord.County))
                                ?.Name ?? string.Empty;

                        var licenseNumber = currentProvider.ProviderAttributes?
                            .FirstOrDefault(x => x.AttributeKey.ToUpper() == "PROV_LICENSE_ID")?.AttributeValue;

                        int licensedBeds = RateBL.GetLastLicensedBeds(currentProvider.ProviderID);
                        int certifiedBeds = RateBL.GetLastCertifiedBedCount(currentProvider.ProviderID);
                        var federalIdNumber = currentProvider.Identifiers?
                            .FirstOrDefault(x =>
                                x.IsActive == true &&
                                (x.Type.ToUpper() == "FEDTAXID" || x.Type.ToUpper() == "FEDERAL TAX ID NUMBER") &&
                                x.Value != string.Empty)?.Value.FormatUSTaxId();

                        var odhNumber = GetARUMOdhNumber(currentProvider, arumAffiliates);

                        string peerGroup = String.Empty;
                        var details = RateBL.GetProviderGeneralInfoDetails(currentProvider.ProviderID);
                        switch (SimplifiedType)
                        {
                            case "NF":
                                if (!string.IsNullOrWhiteSpace(details.PeerGroup))
                                {
                                    peerGroup = details.PeerGroup;
                                }
                                else
                                {
                                    if (!string.IsNullOrWhiteSpace(county))
                                    {
                                        peerGroup = RateBL.GetNfPeerGroupAncillaryByCounty("OH", county, licensedBeds);
                                    }
                                }

                                reportType = "NF";

                                break;

                            case "ICF":
                                if (!string.IsNullOrWhiteSpace(details.PeerGroup))
                                {
                                    peerGroup = details.PeerGroup;
                                }
                                else
                                {
                                    if (!string.IsNullOrWhiteSpace(county))
                                    {
                                        List<DatabaseLookupValue> dbLookups =
                                            DatabaseLookupVariableBL.GetAnnualRED(AnnualRateSettingEnum.PeerGroupFiveA);
                                        peerGroup = RateBL.GetIcfPeerGroup(certifiedBeds, dbLookups,
                                            currentProvider.ProviderID.ToString());
                                    }
                                }

                                reportType = "ICF";

                                break;
                        }

                        row = PrintMedicareNumberReport(worksheet, medicaidId,
                            effDateStart, row, startDate, endDate, odhNumber, county,
                            medicareId, licenseNumber, federalIdNumber, effDateEnd, peerGroup, currentProvider.Name);
                    }


                    var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var headerStyleName = CreateStyle(workbook, "HeaderStyle", true, 11, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignLeft);
                    var bodyStyleName = CreateStyle(workbook, "BodyStyle", false, 8, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignLeft);

                    if (worksheet.Rows.Length == 0)
                    {
                        throw new Exception(" No records met the criteria for the report.");
                    }

                    worksheet.UsedRange.CellStyleName = bodyStyleName;
                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;

                    worksheet.Columns[0].NumberFormat = "0000000";
                    worksheet.Columns[1].NumberFormat = "0000000";
                    worksheet.Columns[2].NumberFormat = "0";
                    worksheet.Columns[4].NumberFormat = "0";

                    if (worksheet.Rows.Length >= 3)
                    {
                        worksheet.Range["A2:J2"].CellStyleName = headerStyleName;
                        worksheet.Range[3, 1].FreezePanes();
                    }

                    if (worksheet.Rows.Length >= 1)
                    {
                        worksheet.Range["A1:J1"].CellStyleName = titleStyleName;
                        worksheet.Range["A1:J1"].Merge();
                        worksheet.Range["A1:J1"].HorizontalAlignment = ExcelHAlign.HAlignCenter;
                        worksheet.Range["A1:J1"].VerticalAlignment = ExcelVAlign.VAlignCenter;
                    }

                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;

                    worksheet.UsedRange.AutofitRows();
                    worksheet.UsedRange.AutofitColumns();
                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.PageSetup.FitToPagesWide = 1;

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;

                    fileName = $"{SimplifiedType}_ProviderMedicareNumberReport_Run_{DateTime.Now.ToString("yyyyMMdd")}.xlsx";
                    fullPath = Path.Combine(Path.GetTempPath(), fileName);

                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    Filename = string.Empty,
                    Message = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }

            return Json(new
            {
                Success = true,
                FileName = fileName,
                Message = string.Empty
            },
                JsonRequestBehavior.AllowGet);
        }


        public int PrintMedicareNumberReport(IWorksheet worksheet, string medicaidId,
            DateTime effectiveDate, int row, string startDate, string endDate, string ODHNumber,
            string county, string medicareId, string licenseNumber,
            string federalIdNumber, DateTime? effectiveDateEnd, string ancillaryPeerGroup, string name)
        {
            int column;
            if (row == 1)
            {
                // Print the headings
                column = 1;
                worksheet.Range[row, column].Text = $"Provider Medicare Number Report from {startDate} to {endDate}";
                row++;

                column = 1;
                worksheet.Range[row, column].Text = "Medicare Number";
                worksheet.SetColumnWidth(column, 10);
                column++;

                worksheet.Range[row, column].Text = "Provider Number";
                column++;

                worksheet.Range[row, column].Text = "ODH Number";
                column++;

                worksheet.Range[row, column].Text = "Federal ID Number";
                column++;

                worksheet.Range[row, column].Text = "License Number";
                column++;

                worksheet.Range[row, column].Text = "Provider Name";
                column++;

                worksheet.Range[row, column].Text = "County";
                column++;

                worksheet.Range[row, column].Text = "Certification Date";
                column++;

                worksheet.Range[row, column].Text = "Inactive Date";
                column++;

                worksheet.Range[row, column].Text = "Peer Group";
            }

            row++;
            column = 1;
            worksheet.Range[row, column].Text = medicareId;
            column++;
            worksheet.Range[row, column].Text = medicaidId;
            column++;
            worksheet.Range[row, column].Text = ODHNumber;
            column++;
            worksheet.Range[row, column].Text = federalIdNumber;
            column++;
            worksheet.Range[row, column].Text = licenseNumber;
            column++;
            worksheet.Range[row, column].Text = name;
            column++;
            worksheet.Range[row, column].Text = county;
            column++;
            worksheet.Range[row, column].Text = effectiveDate.ToShortDateString();
            column++;
            worksheet.Range[row, column].Text = (effectiveDateEnd ?? DateTime.MaxValue).ToShortDateString();
            column++;
            worksheet.Range[row, column].Text = ancillaryPeerGroup;

            return row;
        }

