        [HttpPost]
        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult CertifiedBedCountReport(string asOfEffectiveDate)
        {
            IAddressCodeFunctions addressCodeFunctions = CostReportBL.GetInstanceAddressCodeFunctions(RetrieveSession.Classification);
            var facilityType = SimplifiedType;
            var facilityTypeHeading = string.Empty;
            switch (facilityType)
            {
                case "NF":
                    facilityTypeHeading = "Nursing Facility";
                    break;
                case "ICF":
                    facilityTypeHeading = "ICF IID";
                    break;
                default:
                    throw new Exception($" Invalid Facility Type: {facilityType}.");
            }

            var currDate = DateTime.Now;

            var fileName = $"{facilityType}_CertifiedBedCountReport_{currDate:yyyyMMdd}.xlsx".ToSafeFileName();
            var fullPath = Path.Combine(Path.GetTempPath(), fileName);

            IWorkbook workbook;
            IWorksheet worksheet;

            var activeStatusList = new List<string>
            {
                "CHA",
                "IEN",
                "WDG",
                "REN"
            };

            int row = 1;

            try
            {
                _ = DateTime.TryParse(asOfEffectiveDate, out var asofEffDate);

                using (var excelEngine = new ExcelEngine())
                {
                    // ---------------------------------------------
                    // Set up the report
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;
                    workbook = application.Workbooks.Create(1);

                    worksheet = workbook.Worksheets[0];

                    var allArum_Providers = GetAllProviderList(RetrieveSession.Classification.ARUMToken, false, false,
                        false, true, false, false, false, true, false,
                        "RateController.CertifiedBedCountReport");
                    if (!allArum_Providers.Result.Successful)
                    {
                        throw new Exception($" Providers not found. {allArum_Providers.Result.Message}.");
                    }

                    var arumProviders = allArum_Providers.lstProviders.OrderBy(x => x.MCAID).ToList();

                    foreach (var currentProvider in arumProviders)
                    {
                        var effectiveDateRec = SelectProviderEffectiveDate("ActiveBeforeAsOf",
                            currentProvider.EffectiveDates, asofEffDate);
                        if (effectiveDateRec == null)
                        {
                            continue;
                        }

                        if (!IsProviderStatusActive(activeStatusList, currentProvider)) continue;

                        var countyName = string.Empty;
                        var providerNumber = currentProvider.MCAID;
                        var providerName = currentProvider.Name;
                        var countyCode = effectiveDateRec.County;
                        if (!string.IsNullOrWhiteSpace(countyCode))
                        {
                            countyName = addressCodeFunctions.GetCountyNameByCountyCode(Convert.ToInt32(countyCode));
                        }

                        var activeCertifiedBedStatusList = new List<string> { "ACTUAL", "ACTIVE", "PENDING" };
                        var certifiedBed = RateBL.GetCertifiedBeds(currentProvider.ProviderID)
                            .Where(x => x.EffectiveDate <= asofEffDate && x.Status != null)
                            .OrderByDescending(y => y.EffectiveDate)
                            .FirstOrDefault();

                        if (certifiedBed != null)
                        {
                            if (!activeCertifiedBedStatusList.Contains(certifiedBed.Status.ToUpper()))
                            {
                                continue;
                            }
                        }

                        var certBedVM = MapCertifiedBedsToViewModel(certifiedBed);

                        row = PrintCertifiedBedCountReport(worksheet, row, currentProvider.MCAID,
                            asofEffDate.ToShortDateString(), certBedVM.EffectiveDate, currentProvider.Name,
                            facilityTypeHeading, certBedVM.MedicaidNF, certBedVM.DualSNFNF, certBedVM.Total,
                            countyCode, countyName);
                    }

                    if (worksheet.Rows.Length == 0)
                    {
                        throw new Exception(" No data met the criteria for the report.");
                    }

                    var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var headerStyleName = CreateStyle(workbook, "HeaderStyle", true, 11, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var bodyStyleName = CreateStyle(workbook, "BodyStyle", false, 8, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);


                    worksheet.UsedRange.CellStyleName = bodyStyleName;
                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;

                    worksheet.Columns[0].NumberFormat = "0000000";

                    if (worksheet.Rows.Length >= 3)
                    {
                        if (facilityType == "NF")
                        {
                            worksheet.Range["A1:H1"].CellStyleName = titleStyleName;
                            worksheet.Range["A2:H2"].CellStyleName = titleStyleName;
                            worksheet.Range["A1:H1"].Merge();
                            worksheet.Range["A2:H2"].Merge();
                            worksheet.Range["A2:H2"].CellStyleName = headerStyleName;
                            worksheet.Range["A2:H2"].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                            worksheet.Range["A3:H3"].CellStyleName = headerStyleName;
                            worksheet.Columns[3].NumberFormat = "0";
                            worksheet.Columns[4].NumberFormat = "0";
                            worksheet.Columns[5].NumberFormat = "0";
                        }
                        else
                        {
                            if (facilityType == "ICF")
                            {
                                worksheet.Range["A1:F1"].CellStyleName = headerStyleName;
                                worksheet.Range["A2:F2"].CellStyleName = headerStyleName;
                                worksheet.Range["A1:F1"].Merge();
                                worksheet.Range["A2:F2"].Merge();
                                worksheet.Range["A2:F2"].CellStyleName = titleStyleName;
                                worksheet.Range["A2:F2"].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                                worksheet.Range["A3:F3"].CellStyleName = titleStyleName;
                                worksheet.Columns[3].NumberFormat = "0";
                            }
                        }

                        worksheet.Range[4, 1].FreezePanes();
                    }

                    worksheet.Columns[1].CellStyle.HorizontalAlignment = ExcelHAlign.HAlignLeft;

                    worksheet.UsedRange.AutofitRows();
                    worksheet.UsedRange.AutofitColumns();
                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;

                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.PageSetup.FitToPagesWide = 1;

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;

                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    Filename = string.Empty,
                    Message = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }

            return Json(new
            {
                Success = true,
                FileName = fileName,
                Message = string.Empty
            },
                JsonRequestBehavior.AllowGet);
        }

