                    worksheet.SetColumnWidth(column, 9);
                    column++;

                    worksheet.Range[row, column].Text = "Dual SNF/NF";
                    column++;

                    worksheet.Range[row, column].Text = "Total NF Certified";
                    column++;
                }
                else
                {
                    if (facilityTypeHeading == "ICF IID")
                    {
                        column = 1;
                        worksheet.Range[row, column].Text = "Provider Number";
                        column++;

                        worksheet.Range[row, column].Text = "Provider Name";
                        column++;

                        worksheet.Range[row, column].Text = "County Code";
                        column++;

                        worksheet.Range[row, column].Text = "County Name";
                        column++;

                        worksheet.Range[row, column].Text = "Effective Date";
                        column++;

                        worksheet.Range[row, column].Text = "Total ICFIID Certified";
                        column++;
                    }
                    else
                    {
                        throw new Exception($" Facility Type {facilityTypeHeading} not found for report. ");
                    }
                }
            }

            row++;
            if (facilityTypeHeading == "Nursing Facility")
            {
                column = 1;
                worksheet.Range[row, column].Text = providerNumber;
                column++;
                worksheet.Range[row, column].Text = providerName;
                column++;
                worksheet.Range[row, column].Text = countyCode;
                column++;
                worksheet.Range[row, column].Text = countyName;
                column++;
                worksheet.Range[row, column].Text = effectiveDate.ToShortDateString();
                column++;
                worksheet.Range[row, column].Number = medicaid;
                column++;
                worksheet.Range[row, column].Number = dual;
                column++;
                worksheet.Range[row, column].Number = total;
                column++;
            }
            else
            {
                if (facilityTypeHeading == "ICF IID")
                {
                    column = 1;
                    worksheet.Range[row, column].Text = providerNumber;
                    column++;
                    worksheet.Range[row, column].Text = providerName;
                    column++;
                    worksheet.Range[row, column].Text = countyCode;
                    column++;
                    worksheet.Range[row, column].Text = countyName;
                    column++;
                    worksheet.Range[row, column].Text = effectiveDate.ToShortDateString();
                    column++;
                    worksheet.Range[row, column].Number = total;
                    column++;
                }
            }

            return row;
        }

