        [HttpPost]
        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult LicensedBedCountReport(string asOfEffectiveDate)
        {
            var currDate = DateTime.Now;

            var facilityType = SimplifiedType;
            IAddressCodeFunctions addressCodeFunctions = CostReportBL.GetInstanceAddressCodeFunctions(RetrieveSession.Classification);

            var fileName = $"{facilityType}_LicensedBedCountReport_Run_{currDate:yyyyMMdd}.xlsx".ToSafeFileName();
            var fullPath = Path.Combine(Path.GetTempPath(), fileName);

            IWorkbook workbook;
            IWorksheet worksheet;

            List<string> activeStatusList = new List<string>
            {
                "CHA",
                "IEN",
                "WDG",
                "REN"
            };
            int row = 1;

            try
            {
                _ = DateTime.TryParse(asOfEffectiveDate, out var asofEffDate);

                using (var excelEngine = new ExcelEngine())
                {
                    // ---------------------------------------------
                    // Set up the report
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;
                    workbook = application.Workbooks.Create(1);

                    worksheet = workbook.Worksheets[0];

                    var allArum_Providers = GetAllProviderList(RetrieveSession.Classification.ARUMToken, false, true,
                        false, true, false, true, false, true, false, "RateController.LicensedBedCountReport");
                    if (!allArum_Providers.Result.Successful)
                    {
                        throw new Exception($" Providers not found. {allArum_Providers.Result.Message}.");
                    }

                    var arumAffiliates = GetAllAffiliatesList(RetrieveSession.Classification.ARUMToken, false, true,
                        false, false, false, "RateController.LicensedBedCountReport");

                    var arumProviders = allArum_Providers.lstProviders.OrderBy(x => x.MCAID).ToList();
                    foreach (var currentProvider in arumProviders)
                    {
                        var effectiveDateRec = SelectProviderEffectiveDate("ActiveBeforeAsOf",
                            currentProvider.EffectiveDates, asofEffDate);
                        if (effectiveDateRec == null)
                        {
                            continue;
                        }

                        if (!IsProviderStatusActive(activeStatusList, currentProvider)) continue;

                        var activeLicensedBedStatusList = new List<string> { "ACTIVE", "ACTUAL", "PENDING" };
                        var licensedBed = RateBL.GetLicensedBeds(currentProvider.ProviderID)
                            .Where(x => x.EffectiveDate <= asofEffDate && x.Status != null)?
                            .OrderByDescending(y => y.EffectiveDate)?
                            .FirstOrDefault();

                        if (licensedBed != null &&
                            !activeLicensedBedStatusList.Contains(licensedBed.Status.ToUpper()))
                        {
                            continue;
                        }

                        LicensedBedsViewModel licensedBedsViewModel;
                        licensedBedsViewModel = MapLicensedBedsToViewModel(licensedBed);

                        string countyName = string.Empty;
                        var odhNumber = GetARUMOdhNumber(currentProvider, arumAffiliates);
                        var countyCode = effectiveDateRec.County;
                        if (!string.IsNullOrWhiteSpace(countyCode))
                        {
                            countyName = addressCodeFunctions.GetCountyNameByCountyCode(Convert.ToInt32(countyCode));
                        }

                        string providerNumber = currentProvider.MCAID;
                        string name = currentProvider.Name;
                        string effectiveDate = licensedBedsViewModel.EffectiveDate.ToShortDateString();
                        string facilityTypeHeading = string.Empty;
                        int nf = licensedBedsViewModel?.BedCountNF ?? 0;
                        int regHospital = licensedBed?.BedCountRegisteredHospital ?? 0;
                        int other = licensedBedsViewModel?.BedCountOther ?? 0;
                        int icfiid = licensedBedsViewModel?.BedCountICF ?? 0;
                        int resCare = licensedBedsViewModel?.ResidentialCare ?? 0;
                        int outOfService = licensedBedsViewModel?.OutOfService ?? 0;
                        int onHold = licensedBedsViewModel?.OnHold ?? 0;
                        int total = 0;

                        switch (facilityType)
                        {
                            case "NF":
                                total = licensedBed?.TotalLicBeds ?? 0;
                                facilityTypeHeading = "Nursing Facility";
                                break;
                            case "ICF":
                                total = licensedBed?.TotalProjBeds ?? 0;
                                facilityTypeHeading = "ICF";
                                break;
                            default:
                                throw new Exception($"Invalid Facility Type: {facilityType}");
                        }

                        row = PrintLicensedBedCountReport(worksheet, row, odhNumber, providerNumber, name,
                            effectiveDate, nf, regHospital, other,
                            icfiid, resCare, outOfService, onHold, total, asOfEffectiveDate, facilityTypeHeading,
                            countyCode, countyName);
                    }

                    if (worksheet.Rows.Length == 0)
                    {
                        throw new Exception(" No data met the criteria for the report.");
                    }

                    var bodyStyleName = CreateStyle(workbook, "BodyStyle", false, 10, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);

                    worksheet.UsedRange.CellStyleName = bodyStyleName;
                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.PageSetup.FitToPagesWide = 1;

                    var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var headerStyleName = CreateStyle(workbook, "HeaderStyle", true, 11, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    worksheet.Range["A1:L1"].CellStyleName = titleStyleName;
                    worksheet.Range["A2:B2"].CellStyleName = headerStyleName;


                    if (worksheet.Rows.Length >= 3)
                    {
                        worksheet.Range["A2:B2"].CellStyleName = headerStyleName;
                        worksheet.Range["A2:B2"].CellStyle.HorizontalAlignment = ExcelHAlign.HAlignLeft;
                        worksheet.Range["A2:B2"].CellStyle.WrapText = false;

                        if (facilityType == "NF")
                        {
                            worksheet.Range["A3:N3"].CellStyleName = headerStyleName;
                            worksheet.Range["A1:N1"].Merge();
                            worksheet.Range["A2:N2"].Merge();
                            worksheet.Range["A1:N1"].CellStyleName = titleStyleName;
                        }
                        else if (facilityType == "ICF")
                        {
                            worksheet.Range["A3:N3"].CellStyleName = headerStyleName;
                            worksheet.Range["A1:N1"].Merge();
                            worksheet.Range["A2:N2"].Merge();
                            worksheet.Range["A1:N1"].CellStyleName = titleStyleName;
                        }

                        worksheet.Range[4, 1].FreezePanes();
                    }

                    worksheet.Columns[2].CellStyle.HorizontalAlignment = ExcelHAlign.HAlignLeft;

                    worksheet.UsedRange.AutofitRows();
                    worksheet.UsedRange.AutofitColumns();
                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;

                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    Filename = string.Empty,
                    Message = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }

            return Json(new
            {
                Success = true,
                FileName = fileName,
                Message = string.Empty
            },
                JsonRequestBehavior.AllowGet);
        }

        public int PrintLicensedBedCountReport(IWorksheet worksheet, int row, string odhNumber, string providerNumber,
            string name, string effectiveDate,
            int nf, int regHospital, int other, int icfiid, int resCare, int outOfService, int onHold, int total,
            string asOfEffectiveDate, string facilityTypeHeading, string countyCode, string countyName)
        {
            int column = 0;
