        #region Certified and Licensed Bed Count Report

        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult CurrentCertifiedAndLicensedBedCountReport()
        {

            var facilityType = SimplifiedType;
            var currDate = DateTime.Now;

            var fileName = $"{facilityType}_CurrrentCertifiedAndLicensedBedCountReport_Run_{currDate:yyyyMMdd}.xlsx"
                .ToSafeFileName();
            var fullPath = Path.Combine(Path.GetTempPath(), fileName);

            IWorkbook workbook;
            IWorksheet worksheet;

            int row = 1;

            List<string> activeStatuses = new List<string>
            {
                "CHA",
                "IEN",
                "WDG",
                "REN"
            };

            try
            {
                using (var excelEngine = new ExcelEngine())
                {
                    // ---------------------------------------------
                    // Set up the report
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;
                    workbook = application.Workbooks.Create(1);

                    worksheet = workbook.Worksheets[0];

                    var allArum_Providers = GetAllProviderList(RetrieveSession.Classification.ARUMToken, false, true,
                        false, true, false,
                        true, false, true, false, "RateController/CurrentCertifiedAndLicensedBedCountReport");
                    if (!allArum_Providers.Result.Successful)
                    {
                        throw new Exception($" Providers not found. {allArum_Providers.Result.Message}.");
                    }

                    var arumAffiliates = GetAllAffiliatesList(RetrieveSession.Classification.ARUMToken, false, true,
                        false, false, false, "RateController.LicensedBedCountReport");

                    foreach (var currentProvider in allArum_Providers.lstProviders.OrderBy(x => x.MCAID))
                    {
                        var effectiveDate = SelectProviderEffectiveDate("AllActive", currentProvider.EffectiveDates);
                        var providerStatus = currentProvider.ProviderStatuses
                            .Where(x => x.IsActive == true
                                        && x.Type.ToUpper() == "MEDICAID")
                            .OrderByDescending(x => x.EffectiveDate)
                            .FirstOrDefault()?
                            .Status;
                        if (effectiveDate == null || providerStatus == null ||
                            !activeStatuses.Contains(providerStatus.ToUpper()))
                        {
                            continue;
                        }

                        var statusCriteria = new List<string> { "Actual", "Active" };

                        var licensedBed = RateBL.GetLicensedBeds(currentProvider.ProviderID)
                            .Where(x => statusCriteria.Contains(x.Status) &&
                                        x.EffectiveDate <= DateTime.Now)
                            .OrderByDescending(x => x.EffectiveDate)?
                            .FirstOrDefault();
                        if (!statusCriteria.Contains(licensedBed?.Status))
                        {
                            licensedBed = null;
                        }

                        var certifiedBed = RateBL.GetCertifiedBeds(currentProvider.ProviderID)
                            .Where(x => x.EffectiveDate <= DateTime.Now && x.Status != null)
                            .OrderByDescending(y => y.EffectiveDate)
                            .FirstOrDefault();
                        var certBedVM = MapCertifiedBedsToViewModel(certifiedBed);

                        if (statusCriteria.Contains(certifiedBed?.Status))
                        {
                            certifiedBed = null;
                        }

                        var odhNumber = GetARUMOdhNumber(currentProvider, arumAffiliates);

                        var licensedTotal = 0;
                        var facilityTypeHeading = string.Empty;

                        var providerNumber = currentProvider.MCAID ?? String.Empty;
                        var facilityName = currentProvider.Name;

                        var licensedNF = 0;
                        var licensedRegHosp = 0;
                        var licensedOther = 0;
                        var licensedICF = 0;
                        var licensedResCare = 0;
                        var licensedOnHold = 0;
                        var licensedOutOfService = 0;
                        var licensedEffectiveDate = string.Empty;

                        var certifiedTotal = 0;
                        var certifiedEffectiveDate = string.Empty;
                        int certifiedDual = 0;
                        int certifiedMedicaidNF = 0;
                        // Both ICF and NF
                        if (licensedBed != null)
                        {
                            switch (facilityType)
                            {
                                case "NF":
                                    licensedTotal = licensedBed.TotalLicBeds;
                                    facilityTypeHeading = "Nursing Facility";
                                    break;
                                case "ICF":
                                    licensedTotal = licensedBed.TotalProjBeds;
                                    facilityTypeHeading = "IFC-IID";
                                    break;
                            }

                            licensedNF = licensedBed.BedCountNF;
                            licensedRegHosp = licensedBed.BedCountRegisteredHospital;
                            licensedOther = licensedBed.BedCountOther;
                            licensedICF = licensedBed.BedCountICF;
                            licensedResCare = licensedBed.ResidentialCare;
                            licensedOnHold = licensedBed.OnHold;
                            licensedOutOfService = licensedBed.OutOfService;
                            licensedEffectiveDate = licensedBed.EffectiveDate.ToShortDateString();
                        }

                        if (certBedVM.EffectiveDate != DateTime.MinValue)
                        {
                            certifiedTotal = certBedVM.Total;
                            certifiedEffectiveDate = certBedVM.EffectiveDate.ToShortDateString();
                            certifiedDual = certBedVM.DualSNFNF;
                            certifiedMedicaidNF = certBedVM.MedicaidNF;
                        }


                        row = PrintCertifiedAndLicensedBedCountReport(worksheet, row, odhNumber, providerNumber,
                            facilityName,
                            certifiedEffectiveDate, licensedEffectiveDate, certifiedTotal, licensedTotal, certifiedDual,
                            certifiedMedicaidNF,
                            licensedRegHosp, licensedOther, licensedICF, licensedResCare, licensedOutOfService,
                            licensedOnHold, licensedNF,
                            facilityType, facilityTypeHeading);
                    }

                    if (worksheet.Rows.Length == 0)
                    {
                        throw new Exception(" No data met the criteria for the report.");
                    }

                    var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var headerStyleName = CreateStyle(workbook, "HeaderStyle", true, 11, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var bodyStyleName = CreateStyle(workbook, "BodyStyle", false, 10, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);


                    worksheet.UsedRange.CellStyleName = bodyStyleName;
                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;

                    if (worksheet.Rows.Length >= 3)
                    {
                        if (facilityType == "NF")
                        {
                            worksheet.Range["A1:Q1"].CellStyleName = titleStyleName;
                            worksheet.Range["A2:Q4"].CellStyleName = headerStyleName;
                            worksheet.Range["A1:Q1"].CellStyle.WrapText = false;

                            worksheet.Range["A1:Q1"].Merge();
                            worksheet.Range["A2:Q2"].Merge();
                            worksheet.Range["D3:G3"].Merge();
                            worksheet.Range["I3:Q3"].Merge();
                        }
                        else if (facilityType == "ICF")
                        {
                            worksheet.Range["A1:O1"].CellStyleName = titleStyleName;
                            worksheet.Range["A2:O4"].CellStyleName = headerStyleName;
                            worksheet.Range["A1:O1"].CellStyle.WrapText = false;
                            worksheet.Range["A1:O1"].Merge();
                            worksheet.Range["D3:E3"].Merge();
                            worksheet.Range["H3:O3"].Merge();
                            worksheet.Range["A2:O2"].Merge();
                        }

                        worksheet.Range["A2:B2"].CellStyle.HorizontalAlignment = ExcelHAlign.HAlignLeft;
                        worksheet.Range[5, 1].FreezePanes();
                    }

                    worksheet.Columns[0].NumberFormat = "0000000";
                    worksheet.Columns[1].CellStyle.HorizontalAlignment = ExcelHAlign.HAlignLeft;

                    worksheet.UsedRange.AutofitRows();
                    worksheet.UsedRange.AutofitColumns();

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;

                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    FileName = string.Empty,
                    Message = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }

            return Json(new
            {
                Success = true,
                FileName = fileName,
                Message = string.Empty
            },
                JsonRequestBehavior.AllowGet);
        }

