                        sheetRow.Cells[cell++].Value2 = status.TrackingProviderRecord.ProviderNumber;
                        sheetRow.Cells[cell++].Value2 = status.TrackingProviderRecord.NPI;
                        sheetRow.Cells[cell++].Value2 = status.TrackingProviderRecord.ProviderName;
                        sheetRow.Cells[cell++].Value2 = costReport?.DocumentNumber ?? "";
                        sheetRow.Cells[cell++].Value2 = status.CostReportType;
                        sheetRow.Cells[cell++].Value2 = status.PeerGroup;
                        if (!status.BedCount.HasValue) sheetRow.Cells[cell++].Value2 = "";
                        else sheetRow.Cells[cell++].Value2 = status.BedCount.Value;
                        if (costReport == null) sheetRow.Cells[cell++].Value2 = "";
