                        sheetRow.Cells[cell++].Value2 = status.CostReportType;
                        sheetRow.Cells[cell++].Value2 = status.PeerGroup;
                        if (!status.BedCount.HasValue) sheetRow.Cells[cell++].Value2 = "";
                        else sheetRow.Cells[cell++].Value2 = status.BedCount.Value;
                        if (costReport == null) sheetRow.Cells[cell++].Value2 = "";
                        else sheetRow.Cells[cell++].Value2 = costReport.CertifiedBedDays;
                        if (costReport == null) sheetRow.Cells[cell++].Value2 = "";
                        else sheetRow.Cells[cell++].Value2 = costReport.CertifiedInpatientDays;
                        sheetRow.Cells[cell++].Value2 = status.ExtensionDateRequested.Value.ToShortDateString();
                        sheetRow.Cells[cell++].Value2 = status.ExtensionReasonRequest;
                        if (status.DueDateExtension.HasValue)
                            sheetRow.Cells[cell++].Value2 = status.DueDateExtension.Value.ToShortDateString();
                        else sheetRow.Cells[cell++].Value2 = "Unknown";
                        if (status.CostReportFirstCertificationDate.HasValue)
                        {
                            sheetRow.Cells[cell++].Value2 =
                                status.CostReportFirstCertificationDate.Value.ToShortDateString();
                            TimeSpan daysLate = status.CostReportFirstCertificationDate.Value -
                                                status.DueDateExtension.Value;
                            sheetRow.Cells[cell++].Value2 = daysLate.Days;
                        }
                    }

                    AddWorksheetFooter(sheet,
                        footerLeft,
                        $"\n\n {facilityType} Providers - Extension Granted and Certified Cost Report Late",
                        footerRight);

                    #endregion Tab G

                    #region Tab H

                    tabName = "H";

                    sheet = workbook.Worksheets[tabName];
                    // ensure there is enough room in the worksheet for the records
                    sheet.InsertRow(sheet.UsedRange.LastRow + 1, statuses.Count() + 1);
                    row = 4;
                    if (sheet == null) throw new Exception($"Unable to find Worksheet Tab '{tabName}'");

                    sheet.Replace($"{{CALENDAR_YEAR}}", periodCode);
                    sheet.Replace($"{{FACILITY_TYPE}}", facilityType);

                    // Reset line counter
                    counter = 1;

                    foreach (TrackingProviderStatus status in crExtensionNotFiled)
                    {
                        // Reset cell Counter
                        int cell = 0;

                        // Get the "latest" cost report for this provider that is either
                        // "Cleared" or "On Hold".
                        List<TrackingCostReportStatus> orderedCostReports = costReportStatuses
                            .Where(x =>
                                x.TrackingProviderStatusId == status.TrackingProviderStatusId
                                && (
                                    x.StatusId == (int)CostReportStatusEnum.Cleared
                                    ||
                                    x.StatusId == (int)CostReportStatusEnum.OnHold
                                )
                            )
                            .OrderByDescending(x => x.StatusDate)
                            .ToList();
                        //orderedCostReports.AddRange(providerCostReportStatuses
                        //    .Where(x => x.StatusId == (int)CostReportStatusEnum.Obsolete)
                        //    .OrderByDescending(x => x.SubmitDate));
                        TrackingCostReportStatus costReport = orderedCostReports.FirstOrDefault();

                        IRange sheetRow = sheet.Rows[row++];
                        sheetRow.Cells[cell++].Value2 = counter++;
                        sheetRow.Cells[cell++].Value2 = status.TrackingProviderRecord.ProviderNumber;
                        sheetRow.Cells[cell++].Value2 = status.TrackingProviderRecord.NPI;
                        sheetRow.Cells[cell++].Value2 = status.TrackingProviderRecord.ProviderName;
                        sheetRow.Cells[cell++].Value2 = status.CostReportType;
                        sheetRow.Cells[cell++].Value2 = status.PeerGroup;
                        sheetRow.Cells[cell++].Value2 = status.ExtensionDateRequested.Value.ToShortDateString();
                        sheetRow.Cells[cell++].Value2 = status.ExtensionReasonDecision;
                        sheetRow.Cells[cell++].Value2 = status.DueDateExtension.Value.ToShortDateString();
                        if (status.CostReportFirstCertificationDate.HasValue)
                        {
                            sheetRow.Cells[cell++].Value2 =
                                status.CostReportFirstCertificationDate.Value.ToShortDateString();
                            TimeSpan daysLate = status.CostReportFirstCertificationDate.Value -
                                                status.DueDateExtension.Value;
                            sheetRow.Cells[cell++].Value2 = daysLate.Days;
                        }
                    }

                    AddWorksheetFooter(sheet,
                        footerLeft,
                        $"\n\n {facilityType} Providers - Extension Was Granted And Cost Report Not Received",
                        footerRight);

                    #endregion Tab H

                    #region Tab I

                    tabName = "I";

                    sheet = workbook.Worksheets[tabName];
                    // ensure there is enough room in the worksheet for the records
                    sheet.InsertRow(sheet.UsedRange.LastRow + 1, statuses.Count() + 1);
                    row = 4;
                    if (sheet == null) throw new Exception($"Unable to find Worksheet Tab '{tabName}'");

                    sheet.Replace($"{{CALENDAR_YEAR}}", periodCode);
                    sheet.Replace($"{{FACILITY_TYPE}}", facilityType);

                    // Reset line counter
                    counter = 1;

                    foreach (TrackingProviderStatus status in crFiledCleared)
                    {
                        // Reset cell Counter
                        int cell = 0;

                        // Get the "latest" cost report for this provider that is either
                        // "Cleared" or "On Hold".
                        List<TrackingCostReportStatus> orderedCostReports = costReportStatuses
                            .Where(x =>
                                x.TrackingProviderStatusId == status.TrackingProviderStatusId
                                && (
                                    x.StatusId == (int)CostReportStatusEnum.Cleared
                                    ||
                                    x.StatusId == (int)CostReportStatusEnum.OnHold
                                )
                            )
                            .OrderByDescending(x => x.StatusDate)
                            .ToList();
                        //orderedCostReports.AddRange(providerCostReportStatuses
                        //    .Where(x => x.StatusId == (int)CostReportStatusEnum.Obsolete)
                        //    .OrderByDescending(x => x.SubmitDate));
                        TrackingCostReportStatus costReport = orderedCostReports.FirstOrDefault();

                        IRange sheetRow = sheet.Rows[row++];
                        sheetRow.Cells[cell++].Value2 = counter++;
                        sheetRow.Cells[cell++].Value2 = status.TrackingProviderRecord.ProviderNumber;
                        sheetRow.Cells[cell++].Value2 = status.TrackingProviderRecord.NPI;
                        sheetRow.Cells[cell++].Value2 = status.TrackingProviderRecord.ProviderName;
                        sheetRow.Cells[cell++].Value2 = costReport?.DocumentNumber ?? "";
                        sheetRow.Cells[cell++].Value2 = status.CostReportType;
                        sheetRow.Cells[cell++].Value2 = costReport != null && costReport.StatusDate.HasValue
                            ? costReport.StatusDate.Value.ToShortDateString()
                            : "";
                        sheetRow.Cells[cell++].Value2 = status.PeerGroup;
                        sheetRow.Cells[cell++].Value2 = costReport?.ControlType;
                        if (costReport == null) sheetRow.Cells[cell++].Value2 = "";
                        else sheetRow.Cells[cell++].Value2 = costReport.CertifiedBedDays;
                        if (costReport == null) sheetRow.Cells[cell++].Value2 = "";
                        else sheetRow.Cells[cell++].Value2 = costReport.CertifiedInpatientDays;
                        sheetRow.Cells[cell++].Value2 =
                            $"{costReport?.ExaminerRecord?.FirstName ?? ""} {costReport?.ExaminerRecord?.LastName ?? ""}";
                    }

                    AddWorksheetFooter(sheet,
                        footerLeft,
                        $"\n\n {facilityType} Providers - Cost Report Certified and Status Is Cleared",
                        footerRight);

                    #endregion Tab I

                    #region Tab J

                    tabName = "J";

                    sheet = workbook.Worksheets[tabName];
                    // ensure there is enough room in the worksheet for the records
                    sheet.InsertRow(sheet.UsedRange.LastRow + 1, statuses.Count() + 1);
                    row = 4;
                    if (sheet == null) throw new Exception($"Unable to find Worksheet Tab '{tabName}'");

                    sheet.Replace($"{{CALENDAR_YEAR}}", periodCode);
                    sheet.Replace($"{{FACILITY_TYPE}}", facilityType);

                    // Reset line counter
                    counter = 1;

                    foreach (TrackingProviderStatus status in crFiledOnHold)
                    {
                        // Reset cell Counter
                        int cell = 0;

                        // Get the "latest" cost report for this provider that is either
                        // "Cleared" or "On Hold".
                        List<TrackingCostReportStatus> orderedCostReports = costReportStatuses
                            .Where(x =>
                                x.TrackingProviderStatusId == status.TrackingProviderStatusId
                                && (
                                    x.StatusId == (int)CostReportStatusEnum.Cleared
                                    ||
                                    x.StatusId == (int)CostReportStatusEnum.OnHold
                                )
                            )
                            .OrderByDescending(x => x.StatusDate)
                            .ToList();
                        //orderedCostReports.AddRange(providerCostReportStatuses
                        //    .Where(x => x.StatusId == (int)CostReportStatusEnum.Obsolete)
                        //    .OrderByDescending(x => x.SubmitDate));
                        TrackingCostReportStatus costReport = orderedCostReports.FirstOrDefault();

                        IRange sheetRow = sheet.Rows[row++];
                        sheetRow.Cells[cell++].Value2 = counter++;
                        sheetRow.Cells[cell++].Value2 = status.TrackingProviderRecord.ProviderNumber;
                        sheetRow.Cells[cell++].Value2 = status.TrackingProviderRecord.NPI;
                        sheetRow.Cells[cell++].Value2 = status.TrackingProviderRecord.ProviderName;
                        sheetRow.Cells[cell++].Value2 = costReport?.DocumentNumber ?? "";
                        sheetRow.Cells[cell++].Value2 = status.CostReportType;
                        sheetRow.Cells[cell++].Value2 = costReport != null && costReport.StatusDate.HasValue
                            ? costReport.StatusDate.Value.ToShortDateString()
                            : "";
                        sheetRow.Cells[cell++].Value2 = status.PeerGroup;
                        sheetRow.Cells[cell++].Value2 = costReport?.ControlType;
                        sheetRow.Cells[cell++].Value2 = costReport?.CertifiedBedDays ?? "";
                        sheetRow.Cells[cell++].Value2 = costReport?.CertifiedInpatientDays ?? "";
                        sheetRow.Cells[cell++].Value2 =
                            $"{costReport?.ExaminerRecord?.FirstName ?? ""} {costReport?.ExaminerRecord?.LastName ?? ""}";
                    }

                    AddWorksheetFooter(sheet,
                        footerLeft,
                        $"\n\n {facilityType} Providers - Cost Report Certified And Status Is On-Hold",
                        footerRight);

                    #endregion Tab J

                    workbook.Version = ExcelVersion.Excel2016;
                    using (var fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        //Activate the first worksheet by default
                        workbook.Worksheets[0].Activate();

                        workbook.SaveAs(fileStream, ExcelSaveType.SaveAsXLS);
                    }

                    workbook.Close();
                }

                return Json(new
                {
                    Success = true,
                    fileName = HttpUtility.UrlEncode(fileName)
                }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new
                {
                    Success = false,
                }, JsonRequestBehavior.AllowGet);
            }
        }

        /// <summary>
        /// Add and Replace work sheet footer text with specified text. If text is specified as
        /// null, no replacement will be made (original footer text will remain).
        /// Will accept Excel text hints (some exmamples):
        ///     &[Date]         Current Date
        ///     &[Time]         Current Time
        ///     &[Page]         Current Page Number
        ///     &[Pages]        Total Page Numbers
        /// </summary>
        /// <param name="worksheet">The XlsIo worksheet object.</param>
        /// <param name="textLeft">Text to put in the left footer area.</param>
        /// <param name="textCenter">Text to put in the center footer area.</param>
        /// <param name="textRight">Text to put in the right footer area.</param>
        private void AddWorksheetFooter(IWorksheet worksheet, string textLeft = null,
            string textCenter = null, string textRight = null)
        {
            if (textLeft != null) worksheet.PageSetup.LeftFooter = textLeft;
            if (textCenter != null) worksheet.PageSetup.CenterFooter = textCenter;
            if (textRight != null) worksheet.PageSetup.RightFooter = textRight;
        }

        /// <summary>
        /// Add and Replace work sheet header text with specified text. If text is specified as
        /// null, no replacement will be made (original header text will remain).
        /// Will accept Excel text hints (some exmamples):
        ///     &[Date]         Current Date
        ///     &[Time]         Current Time
        ///     &[Page]         Current Page Number
        ///     &[Pages]        Total Page Numbers
        /// </summary>
        /// <param name="worksheet">The XlsIo worksheet object.</param>
        /// <param name="textLeft">Text to put in the left header area.</param>
        /// <param name="textCenter">Text to put in the center header area.</param>
        /// <param name="textRight">Text to put in the right header area.</param>
        private void AddWorksheetHeader(IWorksheet worksheet, string textLeft = null,
            string textCenter = null, string textRight = null)
        {
            if (textLeft != null) worksheet.PageSetup.LeftHeader = textLeft;
            if (textCenter != null) worksheet.PageSetup.CenterHeader = textCenter;
            if (textRight != null) worksheet.PageSetup.RightHeader = textRight;
        }

