        [HttpPost]
        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult GenerateFIRateReport(string finalizedDate)
        {
            var currDate = DateTime.Now;

            IWorkbook workbook;
            IWorksheet worksheet;

            string fileName = string.Empty;
            string fullPath = string.Empty;
            try
            {

                fileName = $"FI_{SimplifiedType}_RateUpdates_{currDate:yyyyMMdd}..xlsx".ToSafeFileName();
                fullPath = Path.Combine(Path.GetTempPath(), fileName);
                var dataModels = new List<FIRateUpdatesReportModel>();

                DateTime.TryParse(finalizedDate, out DateTime dateToCompare);
                DateTime dateToCompareAtNoon = new DateTime(dateToCompare.Year, dateToCompare.Month, dateToCompare.Day,
                    11, 59, 59, 999);

                using (var excelEngine = new ExcelEngine())
                {
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;
                    workbook = application.Workbooks.Create(1);

                    worksheet = workbook.Worksheets[0];

                    var providerType = SimplifiedType;
                    var previousDay = SubtractBusinessDays(dateToCompareAtNoon);
                    DateTime previousDayDate = new DateTime(previousDay.Year, previousDay.Month, previousDay.Day, 12,
                        00, 00, 001);
                    dataModels = RateBL.GetFIRateReportData(dateToCompareAtNoon, previousDayDate, providerType);

                    int rowCount = 1;
                    int column = 1;

                    worksheet.Range[rowCount, column].Text = "Provider ID";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 20);
                    column++;

                    worksheet.Range[rowCount, column].Text = "Effective Date";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 20);
                    column++;

                    worksheet.Range[rowCount, column].Text = "End Date";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 20);
                    column++;

                    worksheet.Range[rowCount, column].Text = "R&B Rate";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 20);
                    column++;

                    worksheet.Range[rowCount, column].Text = "H LOA Rate";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 20);
                    column++;

                    worksheet.Range[rowCount, column].Text = "L LOA Rate";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 20);

                    foreach (var model in dataModels)
                    {
                        rowCount++;
                        column = 1;

                        worksheet.Range[rowCount, column].Text = model.ProviderID; // A
                        column++;

                        worksheet.Range[rowCount, column].Text = model.EffectiveDate?.ToShortDateString(); // B
                        column++;

                        worksheet.Range[rowCount, column].Text = model.EndDate?.ToShortDateString(); // C
                        column++;

                        worksheet.Range[rowCount, column].Text = model.RBRate; // D
                        column++;

                        worksheet.Range[rowCount, column].Text = model.HLOARate; // E
                        column++;

                        worksheet.Range[rowCount, column].Text = model.LLOARate; // F
                    }

                    rowCount++;
                    worksheet.Range[rowCount, 1].Text = "Count = " + dataModels.Count.ToString(); // Count

                    worksheet.Columns[0].NumberFormat = "0000000";
                    worksheet.Columns[1].NumberFormat = @"mm\/dd\/yyyy";
                    worksheet.Columns[2].NumberFormat = @"mm\/dd\/yyyy";
                    worksheet.Columns[3].NumberFormat = "0.00";
                    worksheet.Columns[4].NumberFormat = "0.00";
                    worksheet.Columns[5].NumberFormat = "0.00";

                    if (worksheet.Rows.Length == 0)
                    {
                        throw new Exception(" No data met the criteria for the report.");
                    }

                    var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);

                    var bodyStyleName = CreateStyle(workbook, "BodyStyle", false, 10, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);

                    worksheet.UsedRange.CellStyleName = bodyStyleName; //bodyStyleName;
                    worksheet.Rows[0].CellStyleName = titleStyleName; //titleStyleName;

                    worksheet.UsedRange.AutofitRows();
                    worksheet.UsedRange.AutofitColumns();

                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;


                    fullPath = Path.Combine(Path.GetTempPath(), fileName);
                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    Filename = string.Empty,
                    Message = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }

            return Json(new
            {
                Success = true,
                FileName = fileName,
                Message = string.Empty
            },
                JsonRequestBehavior.AllowGet);
        }

        private DateTime SubtractBusinessDays(DateTime dateToCompareAtNoon)
        {
            DateTime endDate = dateToCompareAtNoon;
            DateTime startDate = new DateTime();

            if (endDate.DayOfWeek == DayOfWeek.Sunday)
                return startDate = endDate.AddDays(-2);

            if (endDate.DayOfWeek == DayOfWeek.Monday)
                return startDate = endDate.AddDays(-3);

            return startDate = endDate.AddDays(-1);
        }

