        #region Initial Rates for CHOP/New Provider Report

        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult InitialRatesForCHOPReport()
        {
            return PartialView("Report/_InitialRatesForCHOPReport", new IntialRateForCHOPViewModel());
        }

        [HttpPost]
        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult PrintInitialRateCHOPReport(DateTime startDate, DateTime endDate)
        {
            try
            {
                if (startDate > endDate)
                    throw new ArgumentException("Start date cannot be after end date.");

                var currDate = DateTime.Now;
                IWorkbook workbook;
                IWorksheet worksheet;

                string fileName = string.Empty;
                string fullPath = string.Empty;

                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    #region Gathering Data for Report

                    List<InitialRateForCHOPReportParametersModel> reportRows =
                        new List<InitialRateForCHOPReportParametersModel>(); //ExcelStyleHelper.GetReportModelsFromDataTable<InitialRateForCHOPReportParametersModel>(table);

                    List<Provider> providerList = GetAllProviderList(RetrieveSession.Classification.ARUMToken, false,
                        true, false, true, false, false, false, true, true,
                        "RateController.PrintChopReport").lstProviders;
                    if (providerList == null) throw new Exception(" No Providers Found in Database.");

                    #region CHOP Data

                    var chowAndProvider = providerList.SelectMany(p => p.ProviderChowChain,
                        (provider, chow) => new { provider, chowList = chow }).ToList();


                    var providerChowReviews = chowAndProvider
                        .Where(x => x.chowList.ApproveDate >= startDate && x.chowList.ApproveDate <= endDate)
                        .OrderByDescending(x => x.chowList.ApproveDate).ToList();

                    foreach (var chow in providerChowReviews)
                    {
                        if (reportRows.Any(x => x.ProviderId == chow.chowList.NewProviderID)) continue;
                        var newProvider = providerList.FirstOrDefault(x => x.ProviderID == chow.chowList.NewProviderID);
                        if (newProvider == null) continue;
                        var oldProvider = providerList.FirstOrDefault(x => x.ProviderID == chow.chowList.OldProviderID);
                        if (oldProvider == null) continue;

                        if (!IsProviderStatusActiveForChops(newProvider.ProviderStatuses)) continue;

                        var effectiveDateRecord = newProvider.EffectiveDates?
                            .OrderByDescending(x => x.EndDate)
                            .FirstOrDefault();
                        if (effectiveDateRecord == null)
                            continue;
                        if (((effectiveDateRecord.EndDate ?? null) == null)
                            || ((!effectiveDateRecord.IsActive)
                                || (effectiveDateRecord.EndDate <= DateTime.Now)))
                        {
                            continue;
                        }

                        var chowAttributeList = chow.chowList.ChowReviewAttributes;

                        var chowType = chow.chowList.Type;

                        if (chowType == null) continue;

                        InitialRateForCHOPReportParametersModel reportRow =
                            new InitialRateForCHOPReportParametersModel();
                        reportRow.ProviderId = newProvider.ProviderID;
                        reportRow.ProviderNumber = newProvider.MCAID;
                        reportRow.ProviderName = newProvider.Name;
                        reportRow.NPI = newProvider.Identifiers.FirstOrDefault(i => i.Type == "NPI")?.Value ??
                                        string.Empty;
                        reportRow.InitCertDate = newProvider.EffectiveDates.OrderByDescending(x => x.DateEffective)
                            .FirstOrDefault()?.DateEffective;
                        reportRow.ExitingProviderId = oldProvider.ProviderID;
                        reportRow.ExitingProviderNumber = oldProvider.MCAID;
                        reportRow.ExitingNPI = oldProvider.Identifiers.FirstOrDefault(x => x.Type == "NPI")?.Value ??
                                               string.Empty;

                        reportRows.Add(reportRow);
                    }

                    #endregion

                    #region New Facility Data

                    providerList = providerList.Where(x =>
                            SelectProviderEffectiveDate("WithinRange", x.EffectiveDates, startDate, endDate) != null)
                        .ToList();
                    var activeStatuses = new List<string> { "IEN" };

                    foreach (Provider provider in providerList)
                    {
                        if (provider.ProviderStatuses.Any())
                        {
                            var providerStatusRec = provider.ProviderStatuses
                                .Where(x => x.IsActive && x.Type.ToUpper() == "MEDICAID")
                                .OrderByDescending(x => x.ProviderStatusID)
                                .FirstOrDefault();
                            if (providerStatusRec == null ||
                                !activeStatuses.Contains(providerStatusRec.Status.ToUpper()))
                            {
                                // All statuses will be represented in these records, so this is not an error.
                                continue;
                            }
                        }
                        else continue;

                        InitialRateForCHOPReportParametersModel reportRow =
                            new InitialRateForCHOPReportParametersModel();
                        reportRow.ProviderId = provider.ProviderID;
                        reportRow.ProviderNumber = provider.MCAID;
                        reportRow.ProviderName = provider.Name;
                        reportRow.NPI = provider.Identifiers.FirstOrDefault(i => i.Type == "NPI")?.Value ??
                                        string.Empty;
                        reportRow.InitCertDate = provider.EffectiveDates.OrderByDescending(x => x.DateEffective)
                            .FirstOrDefault()?.DateEffective;

                        reportRows.Add(reportRow);
                    }

                    #endregion

                    #region Rate Setting Data

                    string joiningPropName = "ProviderId";
                    List<int> providerIds = reportRows.Select(x => x.ProviderId).ToList();
                    DataTable enteringTable =
                        RateBL.GetEnteringInitialRateDataForReport(string.Join(",", providerIds), startDate, endDate);
                    foreach (DataRow enteringRow in enteringTable.Rows)
                    {
                        int provId = (int)enteringRow[joiningPropName];
                        InitialRateForCHOPReportParametersModel reportRow =
                            reportRows.FirstOrDefault(x => x.ProviderId == provId);

                        if (reportRow != null)
                        {
                            PropertyInfo[] props = ExcelStyleHelper.GetUnpopulatedProperties(reportRow);
                            for (int i = 0; i < enteringRow.ItemArray.Length; i++)
                            {
                                PropertyInfo prop = props.FirstOrDefault(x =>
                                    x.Name == enteringRow.Table.Columns[i].ColumnName);
                                if (prop == null) continue;
                                ExcelStyleHelper.SetValueFromDataRow(prop, prop.PropertyType.Name, reportRow,
                                    enteringRow);
                            }
                        }
                    }

                    foreach (InitialRateForCHOPReportParametersModel reportRow in reportRows)
                    {
                        using (ProjectSpecificDbContext db = new ProjectSpecificDbContext(Functions.DatabaseConnection))
                        {
                            PopulateInitialRateDataforExitingProvider(startDate, endDate, reportRow, db);
                        }
                    }

                    reportRows = reportRows.OrderBy(x => x.ProviderNumber).ToList();

                    #endregion

                    #endregion

                    #region Writing Report to File

                    // ---------------------------------------------
                    // Set up the report
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;
                    workbook = application.Workbooks.Create(1);

                    worksheet = workbook.Worksheets[0];
                    // ---------------------------------------------

                    int row = 3;
                    int col = 1;

                    // ---------------------------------------------
                    // Create the headers
                    Dictionary<string, ExcelStylingAttribute> headers =
                        ExcelStyleHelper.GetReportHeaders<InitialRateForCHOPReportParametersModel>();

                    // Top row reserved for name of report and the date it was generated
                    IRange titleHeader = worksheet.Range[row, col, row, headers.Count];
                    titleHeader.Merge();
                    titleHeader.Text =
                        $"Initial Rates for CHOP/New providers for the period: {startDate.ToString("MM/dd/yyyy")} to {endDate.ToString("MM/dd/yyyy")} for NF Providers";

                    row++;

                    foreach (KeyValuePair<string, ExcelStylingAttribute> header in headers)
                    {
                        worksheet.Range[row, col].Text = header.Key;
                        col++;
                    }
                    // ---------------------------------------------

                    row++;

                    // ---------------------------------------------
                    // Populate Report Data
                    List<PropertyInfo> reportProps =
                        ExcelStyleHelper.GetReportProperties<InitialRateForCHOPReportParametersModel>();
                    foreach (InitialRateForCHOPReportParametersModel reportRow in reportRows)
                    {
                        col = 1;
                        foreach (PropertyInfo prop in reportProps)
                        {
                            AddValueToCell(reportRow, prop, worksheet, row, col);
                            col++;
                        }

                        row++;
                    }
                    // ---------------------------------------------

                    col = 0;

                    // ---------------------------------------------
                    // Format the document
                    var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, false, "Times New Roman",
                        ExcelVAlign.VAlignBottom, ExcelHAlign.HAlignCenter);
                    //var headerStyleName = CreateStyle(workbook, "HeaderStyle", false, 11, true, "Aptos Narrow",
                    //    ExcelVAlign.VAlignBottom, ExcelHAlign.HAlignCenter);
                    var bodyStyleName = CreateStyle(workbook, "BodyStyle", false, 10, false, "Times New Roman",
                        ExcelVAlign.VAlignBottom, ExcelHAlign.HAlignRight);

                    worksheet.UsedRange.CellStyleName = bodyStyleName;

                    if (worksheet.Rows.Length >= 3)
                    {
                        worksheet.Rows[0].CellStyleName = titleStyleName;
                        worksheet.Rows[1].CellStyleName = titleStyleName;
                    }

                    ApplyCellFormatting(headers, worksheet, col, true);

                    worksheet.Rows[1].CellStyle.WrapText = true;
                    worksheet.Range["A4"].RowHeight = 60;

                    worksheet.UsedRange.AutofitRows();
                    worksheet.PageSetup.FitToPagesTall = 1;
                    worksheet.PageSetup.FitToPagesWide = 1;
                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;
                    // ---------------------------------------------

                    #endregion

                    #region File Saving

                    // ---------------------------------------------
                    // Prepare to save the file
                    fileName = $"{SimplifiedType}_InitialRatesCHOPNewProviders_Run_{currDate:yyyyMMdd}.xlsx".ToSafeFileName();
                    fullPath = Path.Combine(Path.GetTempPath(), fileName);

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;

                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                    // ---------------------------------------------

                    #endregion
                }

                return Json(new
                {
                    Success = true,
                    FileName = fileName,
                    Message = string.Empty
                },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    FileName = string.Empty,
                    Message = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }
        }

        private void PopulateInitialRateDataforExitingProvider(DateTime startDate, DateTime endDate,
            InitialRateForCHOPReportParametersModel reportRow, ProjectSpecificDbContext db)
        {
            var rates = db.RatePackages.AsNoTracking()
                .Where(x => x.ProviderId == reportRow.ExitingProviderId).ToList();
            RatePackage rate = db.RatePackages.AsNoTracking()
                .Where(x => x.ProviderId == reportRow.ExitingProviderId
                            && x.RateEffectiveDate <= reportRow.InitCertDate)
                .OrderByDescending(y => y.LockedDate)
                .FirstOrDefault();

            if (rate != null)
            {
                var calculation = db.CalculationResults.AsNoTracking()
                    .Where(x => x.Key == "Totals_QualityIncentivePayment")
                    .FirstOrDefault(y => y.RemoteRecordId == rate.RatePackageId);

                if (calculation != null)
                    if (decimal.TryParse(calculation.Value, out decimal result))
                        reportRow.ExitingQualityPayment = result;

                reportRow.ExitingRED = rate.RateEffectiveDate;
                reportRow.ExitingTotalRate = rate.FinalRateAmount;
                reportRow.ExitingIssuanceDate = rate.LockedDate;
            }
        }

