        [HttpPost]
        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult GetAuditedRateFileCPAOReport(string startDate, string endDate)
        {
            var classification = RetrieveSession.Classification;
            int row = 1;

            IWorkbook workbook;
            IWorksheet worksheet;

            string fileName = string.Empty;
            string fullPath = string.Empty;
            string arumFileName = string.Empty;
            string pattern = @"Audited Rate File was sent to CPAO on (\d{2}/\d{2}/\d{4} \d{2}:\d{2}:\d{2})\.?";
            string rateFileHeading = string.Empty;

            try
            {
                var _applicationServiceProxy = ARUMApplication.GetARUMApplicationProxy(RetrieveSession.Classification);

                using (var excelEngine = new ExcelEngine())
                {

                    // ---------------------------------------------
                    // Set up the report
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;
                    workbook = application.Workbooks.Create(1);

                    worksheet = workbook.Worksheets[0];
                    // ---------------------------------------------
                    _ = DateTime.TryParse(startDate, out var startDt);
                    _ = DateTime.TryParse(endDate, out var endDt);

                    if (endDt != DateTime.MinValue)
                    {
                        endDt = endDt.Date.AddHours(23).AddMinutes(59).AddSeconds(59).AddMilliseconds(999);
                    }

                    List<AuditedRateFileCPAOReportViewModel> auditedRateFile_List = ReportBL.GetAuditedRateFileCPAOReport(startDt, endDt, classification);

                    var facilityStatus = string.Empty;
                    var facilityStatusEffDate = string.Empty;

                    //** 1. Populate required properties first
                    foreach (AuditedRateFileCPAOReportViewModel rateFileData in auditedRateFile_List)
                    {
                        MatchCollection matches = Regex.Matches(rateFileData.FinalizedMessages, pattern);

                        if (matches.Count > 0)
                        {
                            Match lastMatch = matches[matches.Count - 1];
                            string fileTime = lastMatch.Groups[1].Value?.TrimEnd('.');
                            rateFileData.DateSenttoCPAO = fileTime;

                            if (DateTime.TryParse(fileTime, out DateTime fileCreateTime))
                            {
                                arumFileName = ARUMConfigurationOHFI.CPAOFinalRatesFileName(RetrieveSession.Classification);
                                rateFileData.FileNameSenttoCPAO = arumFileName.Replace("^TYPE^", RetrieveSession.Classification.Type)
                                                       .Replace("^FILETIME^", fileCreateTime.ToString("yyyyMMdd_HHmm"));

                            }
                            MSLC.ProviderProxy.Interfaces.IArumDetailedProvider arum_provider = _providerServiceProxy.GetProviderInfoByARUMProviderID(RetrieveSession.Classification.ARUMToken, rateFileData.ProviderId, "Rate/GetAuditedRateFileCPAOReport");
                            rateFileData.NPI = arum_provider.Identifiers.FirstOrDefault(i => i.Type == "NPI")?.Value ?? string.Empty;

                        }
                    }

                    // 2. Sort the list
                    auditedRateFile_List = auditedRateFile_List
                                                .OrderByDescending(data => data.TimeSentToCPAO) // Primary sort: descending by TimeSentToCPAO
                                                .ThenByDescending(data => data.ProviderNumber)  // Secondary sort: descending by ProviderNumber
                                                .ToList();

                    // 3. Now print the sorted data in the foreach loop
                    foreach (AuditedRateFileCPAOReportViewModel rateFileData in auditedRateFile_List)
                    {
                        row = PrintAuditedRateFileCPAOReportDataRow(worksheet, rateFileData, row, startDt, endDt);
                    }

                    var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var headerStyleName = CreateStyle(workbook, "HeaderStyle", true, 11, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var bodyStyleName = CreateStyle(workbook, "BodyStyle", false, 10, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignLeft);

                    if (worksheet.Rows.Length == 0)
                    {
                        throw new Exception(" No data met the criteria for the report.");
                    }

                    worksheet.UsedRange.CellStyleName = bodyStyleName;

                    if (worksheet.Rows.Length > 3)
                    {
                        worksheet.Rows[0].CellStyleName = titleStyleName;
                        worksheet.Rows[1].CellStyleName = headerStyleName;
                        worksheet.Rows[1].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                        worksheet.Rows[2].CellStyleName = headerStyleName;
                        worksheet.Rows[2].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                        worksheet.Rows[4].CellStyleName = headerStyleName;
                    }

                    worksheet.Range["A1:M1"].Merge();
                    worksheet.Range["A2:B2"].Merge();
                    worksheet.Range["A3:B3"].Merge();
                    worksheet.Columns[11].NumberFormat = "0.00";
                    worksheet.Columns[11].HorizontalAlignment = ExcelHAlign.HAlignRight;
              
                    worksheet.UsedRange.AutofitRows();
                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.PageSetup.FitToPagesWide = 1;
                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    MemoryStream report = outputStream;

                    fileName = $"{RetrieveSession.Classification.Type}_AuditedRateFiletoCPAO_{DateTime.Now.ToString("yyyyMMdd")}.xlsx";
                    fullPath = Path.Combine(Path.GetTempPath(), fileName);

                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    FileName = string.Empty,
                    Message = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }

            return Json(new
            {
                Success = true,
                FileName = fileName,
                Message = string.Empty
            },
                JsonRequestBehavior.AllowGet);
        }


        public int PrintAuditedRateFileCPAOReportDataRow(IWorksheet worksheet, AuditedRateFileCPAOReportViewModel model, int row, DateTime startDate, DateTime endDate)
        {
            int column;
            if (row == 1)
            {
                column = 1;// LTC NF Audited Rates 1/1/2025 through 1/31/2025
                worksheet.Range[row, column].Text = $"LTC {RetrieveSession.Classification.Type} Audited Rates {startDate.ToShortDateString()} through {endDate.ToShortDateString()}";

                row++;
                IRange beginDate = worksheet.Range[row, 1, row, 2];
                beginDate.Merge();
                beginDate.Text = "Begin Date: " + startDate.ToShortDateString();

                row++;
                IRange endDateCell = worksheet.Range[row, 1, row, 2];
                endDateCell.Merge();
                endDateCell.Text = "End Date: " + endDate.ToShortDateString();

                row += 2;// Increment the row to skip the next line
                column = 1;

                worksheet.Range[row, column].Text = "Provider ID"; // A
                worksheet.SetColumnWidth(column, 12);
                column++;

                worksheet.Range[row, column].Text = "Provider Name"; // B
                worksheet.SetColumnWidth(column, 35);
                column++;

                worksheet.Range[row, column].Text = "NPI";  // C
                worksheet.SetColumnWidth(column, 12);
                column++;

                worksheet.Range[row, column].Text = "CR Type";  // D
                worksheet.SetColumnWidth(column, 20);
                column++;

                worksheet.Range[row, column].Text = "CR Begin Date"; // E
                worksheet.SetColumnWidth(column, 18);
                column++;

                worksheet.Range[row, column].Text = "CR End Date"; // F
                worksheet.SetColumnWidth(column, 18);
                column++;

                worksheet.Range[row, column].Text = "Document Number"; // G
                worksheet.SetColumnWidth(column, 20);
                column++;

                worksheet.Range[row, column].Text = "Rate Type";  // H
                worksheet.SetColumnWidth(column, 20);
                column++;

                worksheet.Range[row, column].Text = "SFY"; // I
                worksheet.SetColumnWidth(column, 10);
                column++;

                worksheet.Range[row, column].Text = "Rate Begin Date";  // J
                worksheet.SetColumnWidth(column, 15);
                column++;

                worksheet.Range[row, column].Text = "Rate End Date";  // K
                worksheet.SetColumnWidth(column, 15);
                column++;

                worksheet.Range[row, column].Text = "Rate";  // L
                worksheet.SetColumnWidth(column, 10);
                column++;

                worksheet.Range[row, column].Text = "Finalized Message";  // M
                worksheet.SetColumnWidth(column, 150);
                column++;

                worksheet.Range[row, column].Text = "Date & Time Sent to CPAO";  // N
                worksheet.SetColumnWidth(column, 25);
                column++;

                worksheet.Range[row, column].Text = "File Name Rate Sent to CPAO";  // O
                worksheet.SetColumnWidth(column, 35);
                column++;

            }

            row++;
            column = 1;

            worksheet.Range[row, column].Text = model.ProviderNumber; // A
            column++;
            worksheet.Range[row, column].Text = model.ProviderName; // B
            column++;
            worksheet.Range[row, column].Text = model.NPI;  // C
            column++;
            worksheet.Range[row, column].Text = model.CostReportTypeName;  // D
            column++;
            worksheet.Range[row, column].Text = model.PeriodBegin.HasValue ? model.PeriodBegin.Value.ToShortDateString() : string.Empty;  // E 
            column++;
            worksheet.Range[row, column].Text = model.PeriodEnd.HasValue ? model.PeriodEnd.Value.ToShortDateString() : string.Empty;  // F
            column++;
            worksheet.Range[row, column].Text = model.CostReportVersion;  // G
            column++;
            worksheet.Range[row, column].Text = model.RateTypeName;  // H
            column++;
            worksheet.Range[row, column].Number = model.FiscalYear;  // I

            column++;
            worksheet.Range[row, column].Text = model.RateBeginDate.HasValue ? model.RateBeginDate.Value.ToShortDateString() : string.Empty;  // J
            column++;
            worksheet.Range[row, column].Text = model.RateEndDate.HasValue? model.RateEndDate.Value.ToShortDateString() : string.Empty; // K
            column++;
            worksheet.Range[row, column].Number = ConvertToDouble(model.FinalRateAmount?.ToString()); // L 
            column++;
            worksheet.Range[row, column].Text = model.FinalizedMessages; // M
            column++;
            worksheet.Range[row, column].Text = model.DateSenttoCPAO; // N
            column++;
            worksheet.Range[row, column].Text = model.FileNameSenttoCPAO; // O

            return row;
        }
