        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult GenerateProviderRateComponentDataReport(int sfYear, string monthName)
        {
            //var redDate = redDateString;
            var classification = RetrieveSession.Classification;
            var facilityType = SimplifiedType;

            string fileName = string.Empty;
            DateTime userSelecteddate =
                DateTime.ParseExact($"{monthName} 1, {sfYear}", "MMMM d, yyyy", CultureInfo.InvariantCulture);
            int monthNumber = userSelecteddate.Month;
            int lastDayOfMonth = 0;
            DateTime comparisonDate;
            if (monthNumber <= 6)
            {
                lastDayOfMonth = CalculateLastDayOftheMonth(sfYear, monthNumber);
                comparisonDate = new DateTime(sfYear, monthNumber, lastDayOfMonth);
            }
            else
            {
                lastDayOfMonth = CalculateLastDayOftheMonth(sfYear - 1, monthNumber);
                comparisonDate = new DateTime(sfYear - 1, monthNumber, lastDayOfMonth);
            }

            try
            {
                if (OHFISession.IsICF)
                {
                    fileName = GenerateICFProviderRateComponentDataReport(comparisonDate, sfYear, monthName);
                }
                else
                {
                    fileName = GenerateNFProviderRateComponentDataReport(comparisonDate, sfYear, monthName);
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    FileName = string.Empty,
                    Message = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }

            return Json(new
            {
                Success = true,
                FileName = fileName,
                Message = string.Empty
            },
                JsonRequestBehavior.AllowGet);
        }

        public string GenerateNFProviderRateComponentDataReport(DateTime comparisonDate, int sfYear, string monthName)
        {
            var currDate = DateTime.Now;
            IWorkbook workbook;
            IWorksheet worksheet;

            string fileName = string.Empty;
            string fullPath = string.Empty;
            var _applicationServiceProxy = ARUMApplication.GetARUMApplicationProxy(RetrieveSession.Classification);
            var dataModels = new List<RateComponentDataReportParametersModelICF>();

            using (ExcelEngine excelEngine = new ExcelEngine())
            {
                #region Gathering Data for Report

                // ---------------------------------------------
                DataTable table = RateBL.GetNFRateComponentData(comparisonDate, sfYear);

                //Gets ARUM Provider data
                List<Provider> arum_Providers = GetAllProviderList(RetrieveSession.Classification.ARUMToken, false,
                    true, true,
                    true, false, false, false, true, false, "RateController.PrintRates").lstProviders;

                arum_Providers = arum_Providers.Where(x =>
                        RateProviderBL.SelectActiveProviderRateReport(true, x.EffectiveDates, comparisonDate))
                    .OrderBy(x => x.MCAID).ToList();

                //This is needed to convert ARUM's county codes to countys further down
                IAddressCodeFunctions addressCodeFunctions = CostReportBL.GetInstanceAddressCodeFunctions(RetrieveSession.Classification);
                //string[] medicaidStatuses = { "CHA", "IEN", "REN", "WDG" };

                List<RateComponentDataReportParametersModelNF> rowData = rowData =
                    ExcelStyleHelper.GetReportModelsFromDataTable<RateComponentDataReportParametersModelNF>(table);
                int cnt = 1;
                List<RateComponentDataReportParametersModelNF> list_providerDataFromDB =
                    new List<RateComponentDataReportParametersModelNF>();
                foreach (var arumProvider in arum_Providers)
                {
                    var providerDataDB = rowData
                                             .FirstOrDefault(x => x.ProviderId == arumProvider.ProviderID)
                                         ?? new RateComponentDataReportParametersModelNF();

                    // Common fields (apply to both existing and new)
                    providerDataDB.ProviderName = arumProvider.Name;

                    providerDataDB.NPI = arumProvider.Identifiers
                        .FirstOrDefault(x => x.Type == "NPI")?.Value ?? string.Empty;
                    providerDataDB.MedicareId = arumProvider.Identifiers
                        .FirstOrDefault(y => y.Type == "MEDICAREID")?.Value ?? string.Empty;

                    if (string.IsNullOrWhiteSpace(providerDataDB.ProviderNumber))
                    {
                        providerDataDB.ProviderNumber = arumProvider.Identifiers
                            .FirstOrDefault(y => y.Type == "MCAID")?.Value ?? string.Empty;
                    }

                    var initialCertDate = arumProvider.EffectiveDates
                        .OrderByDescending(x => x.DateEffective)
                        .FirstOrDefault();

                    providerDataDB.IntiialCertDate = initialCertDate?.DateEffective;

                    if (providerDataDB.ProviderId != 0) // means it came from DB (adjust if needed)
                    {
                        providerDataDB.MedicaidStatus = arumProvider.ProviderStatuses
                            .Where(x => x.Type == "Medicaid" && x.IsActive)
                            .OrderByDescending(y => y.EffectiveDate)
                            .FirstOrDefault()?.Status ?? string.Empty;

                        //if (!medicaidStatuses.Contains(providerDataDB.MedicaidStatus))
                        //    continue;

                        providerDataDB.LicensedBeds = RateBL.GetLastLicensedBeds(providerDataDB.ProviderId);

                        if (int.TryParse(initialCertDate?.County, out int result))
                        {
                            providerDataDB.County = addressCodeFunctions.GetCountyNameByCountyCode(result);
                        }
                    }
                    else
                    {
                        // Only defaults for new records
                        providerDataDB.County = string.Empty;
                        providerDataDB.RateType = string.Empty;
                        providerDataDB.AncillaryPeerGroup = string.Empty;
                        providerDataDB.DirectCarePeerGroup = string.Empty;
                        providerDataDB.CaseMixScore = null;
                        providerDataDB.DirectRate = null;
                        providerDataDB.AncillaryRate = null;
                        providerDataDB.CapitalRate = null;
                        providerDataDB.TaxRate = null;
                        providerDataDB.CriticalAccessAddOn = null;
                        providerDataDB.ORCAddOn = null;
                        providerDataDB.ORCDeduction = null;
                        providerDataDB.ORCPayment = null;
                        providerDataDB.OccupancyPercentage = null;
                        providerDataDB.OccupancyDeduction = null;
                        providerDataDB.TotalRate = null;
                        providerDataDB.LOAHigh = null;
                        providerDataDB.LOALow = null;
                        providerDataDB.IssuanceDate = null;
                    }

                    providerDataDB.Cnt = cnt++;
                    ;
                    list_providerDataFromDB.Add(providerDataDB);
                }

                // ---------------------------------------------

                #endregion

                #region Writing Report to File

                // ---------------------------------------------
                // Set up the report
                Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                application.DefaultVersion = ExcelVersion.Xlsx;
                workbook = application.Workbooks.Create(1);

                worksheet = workbook.Worksheets[0];
                // ---------------------------------------------

                int row = 1;
                int col = 1;

                // ---------------------------------------------
                // Create the headers
                Dictionary<string, ExcelStylingAttribute> headers =
                    ExcelStyleHelper.GetReportHeaders<RateComponentDataReportParametersModelNF>();

                // Top row reserved for name of report and the date it was generated
                IRange titleHeader = worksheet.Range[row, col, row, headers.Count];
                titleHeader.Merge();
                titleHeader.Text = $"Provider Rate Component Data Report NF: SFY {sfYear}, {monthName}";

                row++;
                col++;

                IRange runLabel = worksheet.Range[row, col];
                runLabel.Text = "Run Date:";

                col++;

                IRange runValue = worksheet.Range[row, col, row, col + 1];
                runValue.Merge();
                runValue.Text = currDate.ToString("MM/dd/yyyy");

                row++;
                col = 1;

                // Headers for the actual data appears two rows down from the top
                foreach (KeyValuePair<string, ExcelStylingAttribute> header in headers)
                {
                    worksheet.Range[row, col].Text = header.Key;
                    col++;
                }
                // ---------------------------------------------

                row++;

                // ---------------------------------------------
                // Populate Report Data
                List<PropertyInfo> reportProps =
                    ExcelStyleHelper.GetReportProperties<RateComponentDataReportParametersModelNF>();
                foreach (RateComponentDataReportParametersModelNF rowItem in list_providerDataFromDB)
                {
                    col = 1;
                    foreach (PropertyInfo prop in reportProps)
                    {
                        AddValueToCell(rowItem, prop, worksheet, row, col);
                        col++;
                    }

                    row++;
                }
                // ---------------------------------------------

                col = 0;

                // ---------------------------------------------
                // Format the document
                var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, false, "Times New Roman",
                    ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                var headerStyleName = CreateStyle(workbook, "HeaderStyle", true, 11, true, "Times New Roman",
                    ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                var bodyStyleName = CreateStyle(workbook, "BodyStyle", false, 8, false, "Times New Roman",
                    ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignRight);
                worksheet.UsedRange.CellStyleName = bodyStyleName;

                // Set number formatting for numeric columns / center cols 
                ApplyCellFormatting(headers, worksheet, col);

                // set up that cool header that stands still while user scrolls
                if (worksheet.Rows.Length > 3)
                {
                    worksheet.Rows[0].CellStyleName = titleStyleName;
                    worksheet.Rows[1].CellStyleName = headerStyleName;
                    worksheet.Rows[2].CellStyleName = headerStyleName;
                }

                worksheet.Range[4, 1].FreezePanes();
                worksheet.UsedRange.AutofitRows();

                worksheet.PageSetup.FitToPagesTall = 0;
                worksheet.PageSetup.FitToPagesWide = 1;
                worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;
                // ---------------------------------------------

                #endregion

                #region File Saving

                // ---------------------------------------------
                // Prepare to save the file
                fileName = $"{SimplifiedType}_ProviderRateComponentDataReport_SFY_{sfYear}_{monthName}_Run_{currDate:yyyyMMdd}.xlsx".ToSafeFileName();
                fullPath = Path.Combine(Path.GetTempPath(), fileName);

                //Save the workbook to stream
                MemoryStream outputStream = new MemoryStream();
                workbook.SaveAs(outputStream);
                outputStream.Position = 0;

                workbook.Close();

                //Dispose the ExcelEngine object
                MemoryStream report = outputStream;

                using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                {
                    report.WriteTo(fileStream);
                }

                // ---------------------------------------------

                #endregion
            }

            return fileName;
        }

        public string GenerateICFProviderRateComponentDataReport(DateTime comparisonDate, int sfYear, string monthName)
        {
            var currDate = DateTime.Now;
            IWorkbook workbook;
            IWorksheet worksheet;

            string fileName = string.Empty;
            string fullPath = string.Empty;
            var _applicationServiceProxy = ARUMApplication.GetARUMApplicationProxy(RetrieveSession.Classification);
            var dataModels = new List<RateComponentDataReportParametersModelICF>();

            int row = 1;

            using (var excelEngine = new ExcelEngine())
            {
                // ---------------------------------------------
                // Set up the report
                Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                application.DefaultVersion = ExcelVersion.Xlsx;
                workbook = application.Workbooks.Create(1);

                worksheet = workbook.Worksheets[0];
                // ---------------------------------------------
                var arum_Providers = GetAllProviderList(RetrieveSession.Classification.ARUMToken, false, true, false,
                    true, false, false, false, true, false, "RateController.PrintRates").lstProviders;
                // ************** GET Active Providers ************************
                arum_Providers = arum_Providers.Where(x =>
                        RateProviderBL.SelectActiveProviderRateReport(true, x.EffectiveDates, comparisonDate))
                    .OrderBy(x => x.MCAID).ToList();

                dataModels = GetRateComponentDataReportValues(comparisonDate, arum_Providers, sfYear);

                foreach (var model in dataModels)
                {
                    row = PrintProviderRateComponentDataRow(worksheet, model, row, comparisonDate, sfYear, monthName);
                }

                if (worksheet.Rows.Length == 0)
                {
                    throw new Exception(" No data met the criteria for the report.");
                }

                var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, false, "Times New Roman",
                    ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                var headerStyleName = CreateStyle(workbook, "HeaderStyle", true, 11, true, "Times New Roman",
                    ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                var bodyStyleName = CreateStyle(workbook, "BodyStyle", false, 8, false, "Times New Roman",
                    ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignRight);

                worksheet.UsedRange.CellStyleName = bodyStyleName;
                worksheet.Columns[2].NumberFormat = "0000000";
                worksheet.Columns[10].NumberFormat = "0.0000";
                worksheet.Columns[11].NumberFormat = "0.00";
                worksheet.Columns[12].NumberFormat = "0.00";
                worksheet.Columns[13].NumberFormat = "0.00";
                worksheet.Columns[14].NumberFormat = "0.00";
                worksheet.Columns[15].NumberFormat = "0.00";
                worksheet.Columns[16].NumberFormat = "0.00";
                worksheet.Columns[17].NumberFormat = "0.00";
                worksheet.Columns[18].NumberFormat = "0.00";
                worksheet.Columns[19].NumberFormat = "0.00";
                worksheet.Columns[20].NumberFormat = "0.00";
                worksheet.Columns[21].NumberFormat = "0.00";
                worksheet.Columns[23].NumberFormat = "0.00";
                worksheet.Columns[24].NumberFormat = "0.00";


                worksheet.Columns[1].HorizontalAlignment = ExcelHAlign.HAlignCenter;
                worksheet.Columns[2].HorizontalAlignment = ExcelHAlign.HAlignCenter;
                worksheet.Columns[3].HorizontalAlignment = ExcelHAlign.HAlignCenter;
                worksheet.Columns[4].HorizontalAlignment = ExcelHAlign.HAlignCenter;
                worksheet.Columns[5].HorizontalAlignment = ExcelHAlign.HAlignCenter;

                if (worksheet.Rows.Length > 3)
                {
                    worksheet.Rows[0].CellStyleName = titleStyleName;
                    worksheet.Rows[1].CellStyleName = headerStyleName;
                    worksheet.Rows[2].CellStyleName = headerStyleName;
                    worksheet.Rows[3].CellStyleName = headerStyleName;
                }

                worksheet.Rows[0].CellStyleName = titleStyleName;
                worksheet.Range["A1:U1"].Merge();
                worksheet.Range["B2:D2"].Merge();
                worksheet.Range["Q3:S3"].Merge();
                worksheet.Range["T3:X3"].Merge();
                worksheet.Range["Q3:S3"].BorderAround(ExcelLineStyle.Medium);
                worksheet.Range["T3:X3"].BorderAround(ExcelLineStyle.Medium);
                worksheet.Range["Q4:S4"].BorderAround(ExcelLineStyle.Medium);
                worksheet.Range["T4:X4"].BorderAround(ExcelLineStyle.Medium);

                worksheet.Range[4, 1].FreezePanes();
                worksheet.UsedRange.AutofitRows();

                worksheet.PageSetup.FitToPagesTall = 0;
                worksheet.PageSetup.FitToPagesWide = 1;
                worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;

                fileName = $"{SimplifiedType}_ProviderRateComponentDataReport_SFY_{sfYear}_{monthName}_Run_{currDate:yyyyMMdd}.xlsx".ToSafeFileName();
                fullPath = Path.Combine(Path.GetTempPath(), fileName);

                //Save the workbook to stream
                MemoryStream outputStream = new MemoryStream();
                workbook.SaveAs(outputStream);
                outputStream.Position = 0;

                workbook.Close();

                //Dispose the ExcelEngine object
                MemoryStream report = outputStream;

                using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                {
                    report.WriteTo(fileStream);
                }
            }

            return fileName;
        }

        private int CalculateLastDayOftheMonth(int year, int monthNumber)
        {
            return DateTime.DaysInMonth(year, monthNumber);
        }

