        public List<RateComponentDataReportParametersModelICF> GetRateComponentDataReportValues(DateTime comparisonDate,
            List<Provider> providers, int sfYear)
        {
            var dataList = new List<ProviderRateComponentDataForReport>();

            try
            {
                var csType = RedDateBL.GetCalculationSet(comparisonDate).Type;

                dataList = RateBL.GetProviderRateComponentDataForReport(comparisonDate, sfYear, csType)
                    .OrderBy(x => x.ProviderNumber).ToList();
                if (dataList == null)
                {
                    throw new Exception("No provider rate information was found for the report.");
                }

                var parametersModelList = new List<RateComponentDataReportParametersModelICF>();

                foreach (var arumProvider in providers)
                {
                    var parametersModel = new RateComponentDataReportParametersModelICF();
                    var itemList = dataList.Where(x => x.ProviderId == arumProvider.ProviderID)
                        .OrderBy(x => x.ProviderNumber).ToList();
                    if (itemList.Count != 0)
                    {
                        foreach (var dataItem in itemList)
                        {
                            switch (dataItem.Key.ToUpper())
                            {
                                case "PROVIDERNUMBER":
                                    parametersModel.ProviderNumber = dataItem.Value;
                                    break;
                                case "PROVIDERNAME":
                                    parametersModel.ProviderName = dataItem.ProviderName;
                                    break;
                                case "FACILITYCOUNTYNAME":
                                    parametersModel.FacilityCountyName = dataItem.Value;
                                    break;
                                case "PEERGROUP":
                                    parametersModel.PeerGroup = dataItem.Value;
                                    break;
                                case "COSTREPORTYEAREND":
                                    parametersModel.CostReportYearEnd = ConvertToDateTime(dataItem.Value);
                                    break;
                                case "TOTALS_OTHERPROTECTED": // L
                                    parametersModel.TotalsOtherProtected = ConvertToDouble(dataItem.Value);
                                    break;
                                case "EFFICIENCYINCENTIVE": // R
                                    parametersModel.EfficiencyIncentive = ConvertToDouble(dataItem.Value);
                                    break;
                                case "TOTALS_DIRECTCARE": // M
                                    parametersModel.TotalsDirectCare = ConvertToDouble(dataItem.Value);
                                    break;
                                case "TOTALS_DIRECTSUPPORTPERSONNEL": // N
                                    parametersModel.TotalsDirectSupportPersonnel = ConvertToDouble(dataItem.Value);
                                    break;
                                case "TOTALS_PROVQUALITYINCENTIVEPAYMENT": // P
                                    parametersModel.TotalsProvQualityIncentivePayment = ConvertToDouble(dataItem.Value);
                                    break;
                                case "TOTALS_PROFESSIONALWORKFORCEDEVELOPMENTPAYMENT": // O
                                    parametersModel.TotalsProfessionalWorkforceDevelopmentPayment =
                                        ConvertToDouble(dataItem.Value);
                                    break;
                                case "TOTALS_INDIRECTCARE": // S
                                    parametersModel.TotalsIndirectCare = ConvertToDouble(dataItem.Value);
                                    break;
                                case "PERDIEM": // T
                                    parametersModel.PerDiem = ConvertToDouble(dataItem.Value);
                                    break;
                                case "TOTALINDIRECTPERDIEM": // Q
                                    parametersModel.TotalIndirectPerDiem = ConvertToDouble(dataItem.Value);
                                    break;
                                case "TOTALSECONDARYBUILDINGFRVPERDIEM": // U
                                    parametersModel.TotalSecondaryBuildingFRVPerDiem = ConvertToDouble(dataItem.Value);
                                    break;
                                case "EQUIPMENTPERDIEM": // V
                                    parametersModel.EquipmentPerDiem = ConvertToDouble(dataItem.Value);
                                    break;
                                case "ALLOWABLENONEXTENSIVECOST": // W
                                    parametersModel.AllowableNonExtensiveCost = ConvertToDouble(dataItem.Value);
                                    break;
                                case "TOTALS_CAPITAL": // X
                                    parametersModel.TotalsCapital = ConvertToDouble(dataItem.Value);
                                    break;
                                case "TOTALS_TOTALPERDIEMRATE": // Y
                                    parametersModel.TotalsTotalPerDiemRate = ConvertToDouble(dataItem.Value);
                                    break;
                                case "INDIRECTCARECOSTORLIMIT": // Q
                                    parametersModel.IndirectCareCostOrLimit = ConvertToDouble(dataItem.Value);
                                    break;
                            }

                            parametersModel.RateType = dataItem.RateType;
                            parametersModel.CertifiedBedsTotal = dataItem.CertifiedBedsTotal;
                            parametersModel.IssuanceDate = dataItem.IssuanceDate;
                        }

                        // MedicareId
                        parametersModel.MedicareId =
                            arumProvider.Identifiers.FirstOrDefault(y => y.Type == "MEDICAREID")?.Value ?? string.Empty;
                        // InitialCertDate
                        var initialCertDate = arumProvider.EffectiveDates.OrderByDescending(x => x.DateEffective)
                            .FirstOrDefault();
                        parametersModel.InitialCertDate = initialCertDate?.DateEffective;

                        var lookupGroups = RateBL.GetDatabaseLookupGroupList(AnnualRateSettingEnum.AnnualCaseMixScores);
                        var dbLookupGroupData =
                            RateBL.GetDatabaseLookupGroupDataList(AnnualRateSettingEnum.AnnualCaseMixScores);

                        var costReportYear = parametersModel.CostReportYearEnd.Year;
                        var annualScores = RateBL.GetCMIScores(new DateTime(costReportYear, 01, 01),
                            parametersModel.ProviderNumber, lookupGroups, dbLookupGroupData,
                            AnnualRateSettingEnum.AnnualCaseMixScores);
                        parametersModel.AverageCaseMix = ConvertToDouble(annualScores); // K

                        var arumProvId = arumProvider.ProviderID;
                        var provider = providers.FirstOrDefault(x => x.ProviderID == arumProvId);
                        parametersModel.NPI = provider != null
                            ? provider.Identifiers.FirstOrDefault(x => x.Type == "NPI")?.Value
                            : string.Empty;

                        if (parametersModel.ProviderNumber != string.Empty)
                        {
                            parametersModelList.Add(parametersModel);
                        }
                    }
                    else
                    {
                        // Common fields (apply to both existing and new)
                        parametersModel.NPI = arumProvider.Identifiers
                            .FirstOrDefault(x => x.Type == "NPI")?.Value ?? string.Empty;

                        if (string.IsNullOrWhiteSpace(parametersModel.ProviderNumber))
                        {
                            parametersModel.ProviderNumber = arumProvider.Identifiers
                                .FirstOrDefault(y => y.Type == "MCAID")?.Value ?? string.Empty;
                        }

                        parametersModel.MedicareId = arumProvider.Identifiers
                            .FirstOrDefault(y => y.Type == "MEDICAREID")?.Value ?? string.Empty;

                        parametersModel.ProviderName = arumProvider.Name;

                        var initialCertDate = arumProvider.EffectiveDates
                            .OrderByDescending(x => x.DateEffective)
                            .FirstOrDefault();

                        parametersModel.InitialCertDate = initialCertDate?.DateEffective;
                        parametersModelList.Add(parametersModel);
                    }
                }

                dataList.Clear();

                return parametersModelList;
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                throw;
            }
        }

