        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult ChopReport()
        {
            try
            {
                var _arumApplicationClient =
                    ARUMApplication.GetARUMApplicationProxy(new ClassificationDTO { ARUMToken = Guid.Empty });

                var arumCodes = _arumApplicationClient.GetCodesByType(RetrieveSession.Classification.ARUMToken, "CHOW",
                    "Rate/ChopReport");

                var transactionTypes = new List<SelectListItem>();

                transactionTypes.Add(new SelectListItem
                { Value = "All", Text = "All" });

                foreach (var code in arumCodes.lstCodes)
                {
                    transactionTypes.Add(new SelectListItem
                    { Value = code.Value, Text = code.Name });
                }

                transactionTypes = transactionTypes.OrderBy(x => x.Text).ToList();

                var chopReportViewModel = new ChopReportViewModel();
                chopReportViewModel.TransactionTypes = transactionTypes;
                chopReportViewModel.SelectedTransactionType = string.Empty;

                return PartialView("Report/_ChopReport", chopReportViewModel);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message });
            }
        }


        private MSLC.ApplicationProxy.Interfaces.Models.Addresses GetBuyerAddress(
            List<MSLC.ApplicationProxy.Interfaces.Models.ChowReviewAttribute> attrs)
        {
            var address = new MSLC.ApplicationProxy.Interfaces.Models.Addresses();
            address.Address1 = attrs.FirstOrDefault(x => x.AttributeKey == "BUYER_ADDR_1")?.AttributeValue;
            address.Address2 = attrs.FirstOrDefault(x => x.AttributeKey == "BUYER_ADDR_2")?.AttributeValue;
            address.City = attrs.FirstOrDefault(x => x.AttributeKey == "BUYER_CITY")?.AttributeValue;
            address.State = attrs.FirstOrDefault(x => x.AttributeKey == "BUYER_STATE")?.AttributeValue;
            address.ZipCode = attrs.FirstOrDefault(x => x.AttributeKey == "BUYER_ZIP")?.AttributeValue;
            address.Phone = attrs.FirstOrDefault(x => x.AttributeKey == "BUYER_PHONE_NUM")?.AttributeValue;

            return address;
