        [HttpPost]
        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult PrintChopReport(string startDate, string endDate, string groupType)
        {
            var myUser = RetrieveSession.ARUMUser;
            var classification = RetrieveSession.Classification;
            IAddressCodeFunctions addressCodeFunctions = CostReportBL.GetInstanceAddressCodeFunctions(classification);

            IWorkbook workbook;
            IWorksheet worksheet;

            var fileName = string.Empty;
            var fullPath = string.Empty;
            var odhNumber = string.Empty;
            var transactionType = string.Empty;

            var headingLines = new List<int>();
            var reportRows = new System.Collections.Generic.List<ChowReportRow>();
            ChowReportRow chowReportRow;

            var _arumApplicationClient =
                ARUMApplication.GetARUMApplicationProxy(new ClassificationDTO { ARUMToken = Guid.Empty });
            List<Code> addressTypeCodes = _arumApplicationClient
                .GetCodesByType(RetrieveSession.Classification.ARUMToken, "Address", "Rate/ChopReport").lstCodes;
            List<Code> chowTypeCodes = _arumApplicationClient
                .GetCodesByType(RetrieveSession.Classification.ARUMToken, "CHOW", "Rate/ChopReport")
                .lstCodes
                .OrderBy(x => x.Name)
                .ToList();
            var arumAffiliates = GetAllAffiliatesList(RetrieveSession.Classification.ARUMToken, false, true, false,
                false, false, "RateController.LicensedBedCountReport");

            using (var excelEngine = new ExcelEngine())
            {
                try
                {
                    var startDt = ConvertToDateTime(startDate);
                    var endDt = ConvertToDateTime(endDate);

                    // ---------------------------------------------
                    // Set up the report workbook
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;
                    workbook = application.Workbooks.Create(1);

                    worksheet = workbook.Worksheets[0];
                    worksheet.Name = "(3)CHOP";

                    var providerList = GetAllProviderList(RetrieveSession.Classification.ARUMToken, false, true, false,
                        true, false, true, true, true, true,
                        "RateController.PrintChopReport").lstProviders;
                    if (providerList == null) throw new Exception(" No Providers Found in Database.");

                    var processedNewProvider = new List<int>();

                    var chowList = new List<ChowGroup>();
                    var chowAndProvider = providerList.SelectMany(p => p.ProviderChowChain,
                        (provider, chow) => new { provider, chowList = chow }).ToList();

                    var transactionCodeForSorting = string.Empty;

                    var providerChowReviews = chowAndProvider
                        .Where(x => x.chowList.ApproveDate >= startDt && x.chowList.ApproveDate <= endDt)
                        .OrderByDescending(x => x.chowList.ApproveDate).ToList();

                    foreach (var chow in providerChowReviews)
                    {
                        var newProvider = providerList.FirstOrDefault(x => x.ProviderID == chow.chowList.NewProviderID);
                        if (newProvider == null) continue;

                        if (!IsProviderStatusActiveForChops(newProvider.ProviderStatuses)) continue;

                        var effectiveDateRecord = newProvider.EffectiveDates?
                            .OrderByDescending(x => x.EndDate)
                            .FirstOrDefault();
                        if (effectiveDateRecord == null)
                            continue;
                        if (((effectiveDateRecord.EndDate ?? null) == null)
                            || ((!effectiveDateRecord.IsActive)
                                || (effectiveDateRecord.EndDate <= DateTime.Now)))
                        {
                            continue;
                        }

                        var chowAttributeList = chow.chowList.ChowReviewAttributes;

                        var chowType = chow.chowList.Type;
                        var chowName = chowTypeCodes.FirstOrDefault(x => x.Value == chowType).Name;

                        if (chowName == null) continue;
                        if (chowType == null) continue;

                        transactionType = chowName;
                        transactionCodeForSorting = chowType;

                        if (chowType != groupType && groupType != "All")
                        {
                            continue;
                        }

                        if (processedNewProvider.Contains((chow.chowList
                                .ChowReviewID))) // already processed this chow record
                        {
                            continue;
                        }
                        else
                        {
                            processedNewProvider.Add(chow.chowList.ChowReviewID);
                        }

                        chowReportRow = new ChowReportRow();

                        if (OHFISession.IsICF)
                            chowReportRow.CertifiedBeds =
                                RateBL.GetCertifiedBedCountByDate(chow.provider.ProviderID, startDt);
                        else if (OHFISession.IsNF)
                            chowReportRow.CertifiedBeds =
                                RateBL.GetLicensedBedCountByDate(chow.provider.ProviderID, startDt);

                        chowReportRow.TransactionCodeForSorting = transactionCodeForSorting;
                        chowReportRow.TransactionType = transactionType;
                        chowReportRow.StartDate = startDate;
                        chowReportRow.EndDate = endDate;
                        chowReportRow.GroupType = groupType == "All" ? groupType : chowName;
                        chowReportRow.BuyingProvider = newProvider;
                        chowReportRow.SellingProvider =
                            providerList.FirstOrDefault(x => x.ProviderID == chow.chowList.OldProviderID);

                        //--- Get the most recent cost report for selling provider and add final cost report dates to report
                        //--  This only happens if the final cost report is type 4.5

                        List<CostReportListItem> costReports = new List<CostReportListItem>();
                        costReports.AddRange(CostReportHistoryBL.GetList(chowReportRow.SellingProvider.ProviderID,
                            $"CY{startDt.ToString("yyyy")}", "4.5"));

                        if (startDt.Year != endDt.Year)
                            costReports.AddRange(CostReportHistoryBL.GetList(chowReportRow.SellingProvider.ProviderID,
                                $"CY{endDt.ToString("yyyy")}", "4.5"));

                        CostReportListItem cr = costReports.Where(x => x.Status == nameof(CostReportStatusEnum.Cleared))
                            .FirstOrDefault();

                        if (cr != null)
                        {
                            chowReportRow.FinalCostReportFrom = cr.CRBeginDate?.ToString("MM/dd/yyyy");
                            chowReportRow.FinalCostReportTo = cr.CREndDate?.ToString("MM/dd/yyyy");
                        }

                        var transValue = chowAttributeList
                            .FirstOrDefault(x => x.AttributeKey.ToUpper().Trim() == "TRANS_AMT"
                                                 && x.ChowReviewID == chow.chowList.ChowReviewID)?
                            .AttributeValue;
                        chowReportRow.CHOPTrnsAmt1 = ConvertToDouble(transValue);

                        transValue = chowAttributeList
                            .FirstOrDefault(x => x.AttributeKey.ToUpper().Trim() == "MASTER_LEASE_AMT"
                                                 && x.ChowReviewID == chow.chowList.ChowReviewID)?
                            .AttributeValue;
                        chowReportRow.CHOPTrnsAmt2 = ConvertToDouble(transValue);

                        transValue = chowAttributeList
                            .FirstOrDefault(x => x.AttributeKey.ToUpper().Trim() == "SUB_LEASE_AMT"
                                                 && x.ChowReviewID == chow.chowList.ChowReviewID)?
                            .AttributeValue;
                        chowReportRow.CHOPTrnsAmt3 = ConvertToDouble(transValue);

                        chowReportRow.SellingOrganizationName = chowAttributeList
                            .FirstOrDefault(x => x.AttributeKey == "SELLER_NAME")?.AttributeValue;
                        chowReportRow.BuyingOrganizationName = chowAttributeList
                            .FirstOrDefault(i => i.IsActive && i.AttributeKey == "BUYER_NAME")?.AttributeValue;

                        chowReportRow.TransactionDate = chow.chowList.ApproveDate ?? DateTime.Now;
                        int certifiedBeds = RateBL.GetLastCertifiedBedCount(chow.chowList.OldProviderID ?? 0);

                        if (newProvider.HasAffiliates)
                        {
                            chowReportRow.OdhNumber = GetARUMOdhNumber(chowReportRow.BuyingProvider, arumAffiliates);
                        }

                        chowReportRow.Address = GetBuyerAddress(chowAttributeList);

                        if (effectiveDateRecord?.County != null)
                        {
                            chowReportRow.County =
                                addressCodeFunctions.GetCountyNameByCountyCode(
                                    Convert.ToInt32(effectiveDateRecord.County ?? "0"));
                        }

                        var effectiveDateFrom = effectiveDateRecord.DateEffective;
                        var effectiveDateTo = effectiveDateRecord.EndDate ?? DateTime.Now;
                        effectiveDateFrom = effectiveDateFrom ?? DateTime.Now;
                        var diffs = GetDateDiff(effectiveDateTo,
                            effectiveDateFrom ?? DateTime.Now);

                        chowReportRow.MonthsInService = diffs.Months;
                        chowReportRow.YearsInService = diffs.Years;

                        chowReportRow.ChowIdentity = chow.chowList.ChowReviewID;


                        reportRows.Add(chowReportRow);
                    }

                    transactionCodeForSorting = string.Empty;


                    if (reportRows.Count < 1)
                    {
                        throw new Exception(" No records met the criteria for the report.");
                    }

                    var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var headerStyleName = CreateStyle(workbook, "HeaderStyle", true, 11, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var bodyStyleName = CreateStyle(workbook, "BodyStyle", false, 8, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);


                    PrintWorksheet(worksheet, reportRows, headingLines);


                    worksheet.UsedRange.CellStyleName = bodyStyleName;
                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.PageSetup.FitToPagesWide = 1;
                    worksheet.Rows[0].CellStyleName = titleStyleName;
                    worksheet.Rows[2].CellStyleName = titleStyleName;
                    worksheet.Rows[3].CellStyleName = titleStyleName;
                    worksheet.Rows[4].CellStyleName = headerStyleName;
                    worksheet.Rows[5].CellStyleName = headerStyleName;
                    worksheet.Rows[6].CellStyleName = headerStyleName;
                    worksheet.Rows[7].CellStyleName = headerStyleName;
                    worksheet.Range[3, 1].CellStyle.Font.Bold = true;
                    worksheet.Range[4, 1].CellStyle.Font.Bold = true;
                    worksheet.Range[5, 1].CellStyle.Font.Bold = true;
                    //worksheet.Range[1, 1].Cells.Font.Bold = true;

                    foreach (var line in headingLines)
                    {
                        worksheet.Range[line, 1].CellStyle.Font.Bold = true;
                        worksheet.Range[line, 2].CellStyle.Font.Bold = true;
                        worksheet.Range[line, 1].CellStyle.HorizontalAlignment = ExcelHAlign.HAlignLeft;
                        worksheet.Range[line, 2].CellStyle.HorizontalAlignment = ExcelHAlign.HAlignLeft;
                        worksheet.Range[line, 1].CellStyle.Font.Size = 11;
                        worksheet.Range[line, 2].CellStyle.Font.Size = 11;
                    }

                    worksheet.Range[3, 1].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;


                    // Heading Merges
                    worksheet.Range["A1:T2"].Merge();
                    worksheet.Range["A3:D3"].Merge();
                    worksheet.Range["A6:T6"].Merge();
                    worksheet.Range["A7:D7"].Merge();
                    worksheet.Range["E7:H7"].Merge();
                    worksheet.Range["M7:Q7"].Merge();
                    worksheet.Range["T7:U7"].Merge();
                    worksheet.Range["R7:S7"].Merge();
                    worksheet.Range["P7"].RowHeight = 45;
                    worksheet.Columns[1].NumberFormat = "0000000";
                    worksheet.Columns[3].NumberFormat = "0000000";

                    worksheet.Range["A4"].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                    worksheet.Range["A5"].HorizontalAlignment = ExcelHAlign.HAlignLeft;

                    worksheet.Range[9, 1].FreezePanes();

                    foreach (var headingRow in headingLines)
                    {
                        worksheet.Range[headingRow, 1].CellStyle.Font.Bold = true;
                        worksheet.Range[headingRow, 1].CellStyle.Font.Bold = true;
                        worksheet.Range[headingRow, 1].CellStyle.HorizontalAlignment = ExcelHAlign.HAlignLeft;
                        worksheet.Range[headingRow, 2].CellStyle.HorizontalAlignment = ExcelHAlign.HAlignLeft;
                        worksheet.Range[headingRow, 1].CellStyle.HorizontalAlignment = ExcelHAlign.HAlignLeft;
                        worksheet.Range[headingRow, 1].CellStyle.WrapText = false;
                    }

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;

                    fileName =
                        $"{SimplifiedType}_ChopReport_Run_{DateTime.Now.ToString("yyyyMMdd")}.xlsx"
                            .ToSafeFileName();
                    fullPath = Path.Combine(Path.GetTempPath(), fileName);


                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                }
                catch (Exception e)
                {
                    _logger.Error(e, e.Message);

                    return Json(new
                    {
                        Success = false,
                        FileName = string.Empty,
                        Message = e.Message
                    },
                        JsonRequestBehavior.AllowGet);
                }

                return Json(new
                {
                    Success = true,
                    FileName = fileName,
                    Message = string.Empty
                },
                    JsonRequestBehavior.AllowGet);
            }
        }

        private void PrintWorksheet(IWorksheet worksheet, List<ChowReportRow> reportRows, List<int> headingLines)
        {
            var printHeadings = true;
            //var row = 1;
            var saveKey = string.Empty;
            var group = string.Empty;

            var chopReportGroup = reportRows
                .OrderBy(x => x.TransactionCodeForSorting)
                .ThenBy(x => x.ChowIdentity)
                .ThenBy(x => x.ProviderGrouping)
                .ThenBy(x => x.TransactionDate)
                .GroupBy(x => x.TransactionCodeForSorting)
                .ToDictionary(x => x.Key, x => x.ToList());

            var printRow = 1;
            foreach (var key in chopReportGroup.Keys)
            {
                if (key == null)
                {
                    continue;
                }

                foreach (var line in chopReportGroup[key])
                {
                    if (printHeadings)
                    {
                        printRow = PrintHeadings(worksheet, line.GroupType, line);
                        printHeadings = false;
                    }

                    if (saveKey != key)
                    {
                        printRow++;

                        worksheet.Range[printRow, 1].Text = $"Transaction Type: {line.TransactionType}";

                        headingLines.Add(printRow);

                        saveKey = key;
                    }

                    printRow++;
                    printRow = PrintChopReportRow(worksheet, key, line, printRow);
                }

                printRow++;

                worksheet.HPageBreaks.Add(worksheet.Range["A" + printRow]);
            }
        }

        private int PrintChopReportRow(IWorksheet worksheet, string group, ChowReportRow printRow, int lineNumber)
        {
            var row = ++lineNumber;
            var column = 1;


            if (printRow.BlankLine)
            {
                return lineNumber;
            }

            worksheet.Range[row, column].Text = printRow.SellingProvider.MCAID;
            worksheet.Range[row, column].ColumnWidth = 11;
            column++;
            worksheet.Range[row, column].Text = printRow.SellingProvider.Identifiers
                .FirstOrDefault(x => x.Type == "NPI").Value ?? string.Empty;
            worksheet.Range[row, column].ColumnWidth = 11;
            column++;
            worksheet.Range[row, column].Text = printRow.SellingOrganizationName;
            worksheet.Range[row, column].ColumnWidth = 30;
            column++;
            worksheet.Range[row, column].Text = printRow.SellingProvider.Name;
            worksheet.Range[row, column].ColumnWidth = 30;
            column++;
            worksheet.Range[row, column].Text = printRow.BuyingProvider.MCAID;
            worksheet.Range[row, column].ColumnWidth = 10;
            column++;
            worksheet.Range[row, column].Text = printRow.BuyingProvider.Identifiers
                .FirstOrDefault(x => x.Type == "NPI").Value ?? string.Empty;
            worksheet.Range[row, column].ColumnWidth = 11;
            column++;
            worksheet.Range[row, column].Text = printRow.BuyingOrganizationName;
            worksheet.Range[row, column].ColumnWidth = 30;
            column++;
            worksheet.Range[row, column].Text = printRow.BuyingProvider.Name;
            worksheet.Range[row, column].ColumnWidth = 30;
            column++;
            worksheet.Range[row, column].Text = printRow.OdhNumber;
            worksheet.Range[row, column].ColumnWidth = 10;
            column++;
            worksheet.Range[row, column].Text = printRow.TransactionDate.ToString("MM/dd/yyyy");
            worksheet.Range[row, column].ColumnWidth = 12;
            column++;
            worksheet.Range[row, column].Text = $"{printRow.CHOPTrnsAmt1:F2}";
            worksheet.Range[row, column].ColumnWidth = 20;
            column++;
            worksheet.Range[row, column].Number = printRow.CertifiedBeds;
            column++;
            worksheet.Range[row, column].Text = printRow.Address?.Address1 ?? string.Empty;
            worksheet.Range[row, column].ColumnWidth = 20;
            column++;
            worksheet.Range[row, column].Text = printRow.Address?.City ?? string.Empty;
            worksheet.Range[row, column].ColumnWidth = 20;
            column++;
            worksheet.Range[row, column].Text = printRow.Address?.State ?? string.Empty;
            worksheet.Range[row, column].ColumnWidth = 8;
            column++;
            worksheet.Range[row, column].Text = printRow.Address?.ZipCode ?? string.Empty;
            worksheet.Range[row, column].ColumnWidth = 10;
            column++;
            worksheet.Range[row, column].Text = printRow.County;
            worksheet.Range[row, column].ColumnWidth = 12;
            column++;
            worksheet.Range[row, column].Number = printRow.YearsInService;
            worksheet.Range[row, column].ColumnWidth = 10;
            column++;
            worksheet.Range[row, column].Number = printRow.MonthsInService;
            worksheet.Range[row, column].ColumnWidth = 10;
            column++;
            worksheet.Range[row, column].Text = printRow.FinalCostReportFrom;
            worksheet.Range[row, column].ColumnWidth = 10;
            column++;
            worksheet.Range[row, column].Text = printRow.FinalCostReportTo;
            worksheet.Range[row, column].ColumnWidth = 10;

            row++;
            column = 11;
            worksheet.Range[row, column].Text = $"{printRow.CHOPTrnsAmt2:F2}";

            row++;
            column = 11;
            worksheet.Range[row, column].Text = $"{printRow.CHOPTrnsAmt3:F2}";

            return row;
        }

