        #region Pending Change Ownership And Closures Report

        private DateTime GetMaxImportDate(DateTime createDate, DateTime lastModified)
        {
            if (lastModified == null) lastModified = DateTime.MinValue;
            return createDate >= lastModified
                ? createDate
                : lastModified;
        }

        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult PendingChangeOfProviderOwnershipAndPendingClosuresReport()
        {
            var _arumApplicationClient =
                ARUMApplication.GetARUMApplicationProxy(new ClassificationDTO { ARUMToken = Guid.Empty });

            var facilityType = SimplifiedType;
            if (!(facilityType == "NF" || facilityType == "ICF"))
            {
                throw new Exception($" Invalid facility Type: {facilityType}");
            }

            var currDate = DateTime.Now;
            var fileName =
                $"{facilityType}_PendingChangeofOwnershipProvidersPendingClosureProvidersReport_{currDate:yyyyMMdd}.xlsx"
                    .ToSafeFileName();
            var fullPath = Path.Combine(Path.GetTempPath(), fileName);

            try
            {
                using (var excelEngine = new ExcelEngine())
                {
                    var reportLines = new List<PendingChopRow>();

                    IWorkbook workbook;
                    IWorksheet worksheet;

                    string pendingNotificationDateString = string.Empty;
                    DateTime reviewEndDate = DateTime.MinValue;
                    DateTime reviewEffDate = DateTime.MinValue;

                    // Set up the report
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;
                    workbook = application.Workbooks.Create(1);

                    worksheet = workbook.Worksheets[0];
                    string providerStatus = string.Empty;
                    DateTime providerStatusEffectiveDate = DateTime.MinValue;
                    var activeStatuses = new List<string>
                    {
                        "CHA",
                        "IEN",
                        "WDG",
                        "REN"
                    };

                    var validStatuses = new List<string>
                    {
                        "PENDING CLOSURE",
                        "PENDING CHOP"
                    };

                    var allProviders = GetAllProviderList(RetrieveSession.Classification.ARUMToken, false, true, false,
                        true, false,
                        false, true, true, false, "Rate/PendingChangeOfProviderOwnershipAndPendingClosuresReport");
                    if (!allProviders.Result.Successful)
                    {
                        throw new Exception($" Providers not found. {allProviders.Result.Message}.");
                    }

                    List<Code> chowTypeCodes = _arumApplicationClient
                        .GetCodesByType(RetrieveSession.Classification.ARUMToken, "CHOW", "Rate/ChopReport")
                        .lstCodes
                        .OrderBy(x => x.Name)
                        .ToList();
                    List<Code> statusTypeCodes = _arumApplicationClient
                        .GetCodesByType(RetrieveSession.Classification.ARUMToken, "ProviderStatus", "Rate/ChopReport")
                        .lstCodes
                        .OrderBy(x => x.Name)
                        .ToList();
                    var providersToProcess = allProviders.lstProviders
                        .Where(x => x.IsActive)
                        .OrderBy(x => x.MCAID)
                        .ToList();

                    foreach (var currentProvider in providersToProcess)
                    {
                        if (!currentProvider.HasAttributes)
                        {
                            continue;
                        }

                        bool isPChop = false;

                        var attributes = currentProvider.ProviderAttributes.ToList();
                        if (currentProvider.HasAttributes)
                        {
                            if (attributes.Any(x => x.IsActive &&
                                                    x.Category?.ToUpper() == "LTC_PROVINFO" &&
                                                    x.AttributeKey.ToUpper() == "REVIEW_TYPE_DESC" &&
                                                    (x.AttributeValue.ToUpper().Contains("PENDING CHOP") ||
                                                     x.AttributeValue.ToUpper().Contains("PENDING CLOSURE"))))
                            {
                                isPChop = attributes.Any();
                            }
                            else
                            {
                                continue;
                            }
                        }
                        else
                        {
                            continue;
                        }

                        var reviewEndDates = attributes.Where(x => x.Category?.ToUpper() == "LTC_PROVINFO" &&
                                                                   x.AttributeKey?.ToUpper() == "REVIEW_END_DATE");

                        if (reviewEndDates == null || reviewEndDates.Count() == 0)
                        {
                            _logger.Error("Could not find {Provider}'s attributess for review end dates",
                                currentProvider.Name);
                            throw new Exception(
                                "Unable to generate report, error has been logged, please contact OMESCR.RSwebportal@mslc.com for assistance.");
                        }

                        DateTime maxCreateDate = reviewEndDates.Max(x => x.CreateDate);
                        DateTime? maxLastModified = reviewEndDates.Max(x => x.LastModified);
                        DateTime useDate = GetMaxImportDate(maxCreateDate, (maxLastModified ?? DateTime.MinValue));

                        foreach (var rec in reviewEndDates)
                        {
                            if (maxCreateDate == useDate ||
                                maxLastModified == useDate)
                                reviewEndDate = ConvertToDateTime(rec.AttributeValue);
                            break;
                        }

                        if (DateTime.Now > reviewEndDate) continue;

                        maxLastModified = DateTime.MinValue;
                        maxCreateDate = DateTime.MinValue;
                        string reviewTypeDescString = String.Empty;
                        var reviewTypeDescRecs =
                            attributes.Where(x => x.IsActive &&
                                                  x.Category.ToUpper() == "LTC_PROVINFO" &&
                                                  x.AttributeKey.ToUpper() == "REVIEW_TYPE_DESC");

                        maxCreateDate = reviewTypeDescRecs.Max(x => x.CreateDate);
                        maxLastModified = reviewTypeDescRecs.Max(x => x.LastModified);
                        useDate = GetMaxImportDate(maxCreateDate, (maxLastModified ?? DateTime.MinValue));
                        foreach (var rec in reviewTypeDescRecs)
                        {
                            if (rec.CreateDate == useDate ||
                                rec.LastModified == useDate)
                            {
                                reviewTypeDescString = rec.AttributeValue;
                                break;
                            }
                        }

                        var reviewEffDateStrings =
                            attributes.Where(x => x.IsActive &&
                                                  x.Category.ToUpper() == "LTC_PROVINFO" &&
                                                  x.AttributeKey.ToUpper() == "REVIEW_EFF_DATE");
                        if (!reviewEffDateStrings.Any()) continue;

                        maxCreateDate = reviewEffDateStrings.Max(x => x.CreateDate);
                        maxLastModified = reviewEffDateStrings.Max(x => x.LastModified);

                        useDate = GetMaxImportDate(maxCreateDate, (maxLastModified ?? DateTime.MinValue));
                        foreach (var rec in reviewEffDateStrings)
                        {
                            if (rec.CreateDate == useDate ||
                                rec.LastModified == useDate)
                            {
                                reviewEffDate = ConvertToDateTime(rec.AttributeValue);
                                break;
                            }
                        }

                        if (pendingNotificationDateString == null) continue;

                        var statusRec = currentProvider.ProviderStatuses
                            .Where(x => x.IsActive && x.Type.ToUpper() == "MEDICAID")?
                            .OrderByDescending(x => x.EffectiveDate)?
                            .ThenByDescending(x => x.CreateDate)?
                            .FirstOrDefault();
                        if (statusRec == null || !activeStatuses.Contains(statusRec?.Status)) continue;

                        providerStatus = statusTypeCodes.FirstOrDefault(x => x.Value == statusRec.Status).Name;

                        var pendingChopRow = new PendingChopRow
                        {
                            SortField = providerStatus,
                            ProviderNumber = currentProvider.MCAID,
                            ProviderName = currentProvider.Name,
                            CurrentProviderStatus = providerStatus,
                            EffectiveDate = statusRec.EffectiveDate.ToShortDateString(),
                            PendingProviderStatus = reviewTypeDescString,
                            PendingNoticeDate = reviewEffDate.ToShortDateString(),
                            ReviewEndDate = reviewEndDate.ToShortDateString()
                        };

                        reportLines.Add(pendingChopRow);
                    }

                    if (reportLines.Count == 0)
                    {
                        throw new Exception(" No records met the criteria for this report.");
                    }

                    var headerLines = PrintReport(workbook, worksheet, reportLines);

                    var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var headerStyleName = CreateStyle(workbook, "HeaderStyle", true, 11, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var bodyStyleName = CreateStyle(workbook, "BodyStyle", false, 8, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);

                    worksheet.UsedRange.AutofitRows();

                    worksheet.UsedRange.CellStyleName = bodyStyleName;
                    worksheet.Columns[2].WrapText = true;
                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.PageSetup.FitToPagesWide = 1;
                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;

                    foreach (var line in headerLines)
                    {
                        if (line.row == 6)
                        {
                            worksheet.Rows[line.row - 6].CellStyleName = headerStyleName;
                            worksheet.Rows[line.row - 4].CellStyleName = titleStyleName;
                        }
                        else
                        {
                            worksheet.Rows[line.row - 5].CellStyleName = headerStyleName;
                            worksheet.Rows[line.row - 3].CellStyleName = titleStyleName;
                        }

                        var mergeStart = $"A{line.row - 4}";
                        var mergeEnd = $"G{line.row - 3}";
                        worksheet.Range[$"{mergeStart}:{mergeEnd}"].Merge();
                    }

                    worksheet.Columns[0].NumberFormat = "0000000";

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;

                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    FileName = string.Empty,
                    Message = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }

            return Json(new
            {
                Success = true,
                FileName = fileName,
                Message = string.Empty
            },
                JsonRequestBehavior.AllowGet);
        }


        public class PendingChopRow
        {
            public string SortField { get; set; } // should contain ChangeOfOwnership or PendingClosureProviders
            public string ProviderNumber { get; set; }
            public string ProviderName { get; set; }
            public string CurrentProviderStatus { get; set; }
            public string EffectiveDate { get; set; }
            public string PendingProviderStatus { get; set; }
            public string PendingNoticeDate { get; set; }
            public string ReviewEndDate { get; set; }
        }

        public List<(string title, int row)> PrintReport(IWorkbook workbook, IWorksheet worksheet,
            List<PendingChopRow> dataLines)
        {
            var sortedData = dataLines.OrderBy(x => x.PendingProviderStatus)
                .ThenBy(x => x.ProviderNumber);
            int row = 1;
            var facilityType = SimplifiedType;
            var title = string.Empty;
            var headerLines = new List<(string title, int row)>();
            var titleSortField = string.Empty;

            foreach (var dataLine in sortedData)
            {
                if (dataLine.PendingProviderStatus.ToUpper() == "PENDING CHOP")
                {
                    title = "Pending Change of Ownership Providers";
                }
                else
                {
                    if (dataLine.PendingProviderStatus.ToUpper() == "PENDING CLOSURE")
                    {
                        title = "Pending Closure Providers";
                    }
                    else
                    {
                        throw new Exception($" Invalid Pending Status: {dataLine.PendingProviderStatus}");
                    }
                }

                if (dataLine.PendingProviderStatus != titleSortField)
                {
                    row += 2;
                    row = PrintHeadings(workbook, worksheet, row, title);
                    headerLines.Add((title, row));
                }

                titleSortField = dataLine.PendingProviderStatus;

                row = PrintPendingChangeOfProviderOwnershipAndPendingClosuresReport(worksheet, row, dataLine);
            }

            return headerLines;
        }

        public int PrintHeadings(IWorkbook workbook, IWorksheet worksheet, int row, string title)
        {
            int column = 1;

            worksheet.Range[row, column].Text = title;
            row += 2;
            column = 1;

            worksheet.Range[row, column].Text = string.Empty;

            worksheet.Range[row, column].Text = "Provider Number";
            worksheet.Range[row, column].ColumnWidth = 10;
            column++;

            worksheet.Range[row, column].Text = "Provider Name";
            worksheet.Range[row, column].ColumnWidth = 50;
            column++;

            worksheet.Range[row, column].Text = "Current Provider Status";
            worksheet.Range[row, column].ColumnWidth = 15;
            column++;

            worksheet.Range[row, column].Text = "Provider Curr Status Eff Date";
            worksheet.Range[row, column].ColumnWidth = 10;
            column++;

            worksheet.Range[row, column].Text = "Pending Provider Status";
            worksheet.Range[row, column].ColumnWidth = 12;
            column++;

            worksheet.Range[row, column].Text = "Pending Notice Date";
            worksheet.Range[row, column].ColumnWidth = 12;
            column++;

            worksheet.Range[row, column].Text = "Review End Date";
            worksheet.Range[row, column].ColumnWidth = 12;
            column++;

            row++;
            return row;
        }

        public int PrintPendingChangeOfProviderOwnershipAndPendingClosuresReport(IWorksheet worksheet, int row,
            PendingChopRow data)
        {
            var column = 1;
            worksheet.Range[row, column].Text = data.ProviderNumber;
            column++;

            worksheet.Range[row, column].Text = data.ProviderName;
            column++;

            worksheet.Range[row, column].Text = data.CurrentProviderStatus;
            column++;

            worksheet.Range[row, column].Text = data.EffectiveDate;
            column++;

            worksheet.Range[row, column].Text = data.PendingProviderStatus;
            column++;

            worksheet.Range[row, column].Text = data.PendingNoticeDate;
            column++;

            worksheet.Range[row, column].Text = data.ReviewEndDate;
            column++;

            row++;
            return row;
        }

