        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult CMIAuditReport()
        {
            var items = new List<SelectListItem>();
            var cmiAuditReportViewModel = new CMIAuditReportViewModel();
            switch (SimplifiedType)
            {
                case "NF":
                    items.Add(new SelectListItem
                    {
                        Text = AnnualRateSettingEnum.AnnualCaseMixScores.GetDescription(),
                        Value = nameof(AnnualRateSettingEnum.AnnualCaseMixScores)
                    });
                    items.Add(new SelectListItem
                    {
                        Text = AnnualRateSettingEnum.SemiAnnualCaseMixScores.GetDescription(),
                        Value = nameof(AnnualRateSettingEnum.SemiAnnualCaseMixScores)
                    });
                    items.Add(new SelectListItem
                    {
                        Text = AnnualRateSettingEnum.QuarterlyCaseMixScores.GetDescription(),
                        Value = nameof(AnnualRateSettingEnum.QuarterlyCaseMixScores)
                    });
                    items.Add(new SelectListItem
                    {
                        Text = AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM.GetDescription(),
                        Value = nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM)
                    });

                    cmiAuditReportViewModel.ReportTypeList = items;
                    break;
                case "ICF":
                    items.Add(new SelectListItem
                    {
                        Text = AnnualRateSettingEnum.AnnualCaseMixScores.GetDescription(),
                        Value = nameof(AnnualRateSettingEnum.AnnualCaseMixScores)
                    });
                    items.Add(new SelectListItem
                    {
                        Text = AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY.GetDescription(),
                        Value = nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY)
                    });

                    cmiAuditReportViewModel.ReportTypeList = items;
                    break;
                default:
                    throw new Exception("Unsupported Project Type");
            }

            return PartialView("Report/_CMIAuditReport", cmiAuditReportViewModel);
        }

        public JsonResult GenerateCMIAuditReport(string fiscalYear, string annualRateSettingEnum)
        {
            try
            {
                DateTime currDate = DateTime.Now;
                DateTime dateTime = new DateTime();

                var reportType = string.Empty;
                var reportDataType = string.Empty;
                var reportPeriod = string.Empty;

                if (!string.IsNullOrEmpty(fiscalYear))
                {
                    switch (annualRateSettingEnum)
                    {
                        case nameof(AnnualRateSettingEnum.SemiAnnualCaseMixScores):
                        case nameof(AnnualRateSettingEnum.QuarterlyCaseMixScores):
                        case nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM):
                        case nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY):
                            if (SimplifiedType == "NF")
                            {
                                if (!DateTime.TryParse(fiscalYear, out dateTime))
                                {
                                    return Json(new
                                    {
                                        Success = false,
                                        Message = "Invalid input of fiscal year; please enter a valid quaterly date."
                                    }, JsonRequestBehavior.AllowGet);
                                }
                            }
                            else
                            {
                                dateTime = new DateTime(int.Parse(fiscalYear), 07, 01);
                            }

                            break;

                        case nameof(AnnualRateSettingEnum.AnnualCaseMixScores):
                            // Validate input
                            if (!int.TryParse(fiscalYear, out int year))
                            {
                                return Json(new
                                {
                                    Success = false,
                                    Message = "Invalid input of fiscal year; please simply enter the year number."
                                }, JsonRequestBehavior.AllowGet);
                            }

                            dateTime = new DateTime(int.Parse(fiscalYear), 01, 01);
                            break;

                        default:
                            throw new Exception("Invalid type for operation.");
                    }

                    switch (annualRateSettingEnum)
                    {
                        case nameof(AnnualRateSettingEnum.SemiAnnualCaseMixScores):
                            reportType = AnnualRateSettingEnum.SemiAnnualCaseMixScores.GetDescription();
                            reportPeriod = dateTime.ToString("MM/dd/yyyy");
                            reportDataType = nameof(AnnualRateSettingEnum.SemiAnnualCaseMixScores);
                            break;
                        case nameof(AnnualRateSettingEnum.QuarterlyCaseMixScores):
                            reportType = AnnualRateSettingEnum.QuarterlyCaseMixScores.GetDescription();
                            reportPeriod = dateTime.ToString("MM/dd/yyyy");
                            reportDataType = nameof(AnnualRateSettingEnum.QuarterlyCaseMixScores);
                            break;
                        case nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM):
                            reportType = AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM.GetDescription();
                            reportPeriod = dateTime.ToString("MM/dd/yyyy");
                            reportDataType = nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM);
                            break;
                        case nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY):
                            reportType = AnnualRateSettingEnum.QuarterlyCaseMixScores.GetDescription();
                            reportPeriod = dateTime.ToString("MM/dd/yyyy");
                            reportDataType = nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY);
                            break;
                        case nameof(AnnualRateSettingEnum.AnnualCaseMixScores):
                            reportType = AnnualRateSettingEnum.AnnualCaseMixScores.GetDescription();
                            if (SimplifiedType == "NF")
                            {
                                reportPeriod = dateTime.ToString("MM/dd/yyyy");
                            }
                            else
                            {
                                reportPeriod = fiscalYear;
                            }

                            reportDataType = nameof(AnnualRateSettingEnum.AnnualCaseMixScores);
                            break;
                        default:
                            throw new Exception("Invalid type for operation.");
                    }
                }

                var reportTypeNoSpaces = reportType.Replace(" ", string.Empty);
                string fullPath = "";
                var fileName =
                    $"{SimplifiedType}_CMIAuditReport_{reportTypeNoSpaces}_Run_{currDate:yyyyMMdd}.xlsx"
                        .ToSafeFileName();
                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    //Save the file to the path of the current user's temporary folder
                    fullPath = Path.Combine(Path.GetTempPath(), fileName);
                    //Instantiate the excel application object.
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;

                    //The workbook is created
                    IWorkbook workbook = application.Workbooks.Create(1);

                    //The first worksheet object in the worksheets collection is accessed
                    IWorksheet worksheet = workbook.Worksheets[0];

                    string classification = OHFISession.IsNF ? "NF" : "ICF";
                    var groupDataTable =
                        RateBL.GenerateDatabaseLookupHistoryReport(dateTime, annualRateSettingEnum, null);

                    if (groupDataTable.Rows.Count == 0)
                    {
                        throw new Exception("No records met the criteria for the report.");
                    }

                    int provNumberLookupGroupId = DatabaseLookupGroupBL.GetDatabaseLookupGroups(annualRateSettingEnum)
                        .FirstOrDefault(x => x.Name == "Provider Number")?.DatabaseLookupGroupId ?? 0;
                    int dbLookupGroupYearId = RateBL.GetDatabaseLookupYear(dateTime, annualRateSettingEnum)
                        ?.DatabaseLookupGroupYearId ?? 0;

                    AnnualRateSettingEnum valueType =
                        (AnnualRateSettingEnum)Enum.Parse(typeof(AnnualRateSettingEnum), annualRateSettingEnum);

                    var providerLookupGroupData = DatabaseLookupGroupBL
                        .GetDatabaseLookupGroupData(dateTime.Year, dateTime, valueType)
                        .FirstOrDefault(x => x.Key == provNumberLookupGroupId).AsEnumerable();

                    var auditFields = new List<CMIAuditReportFields>();

                    var row = 1;
                    int col = 0;
                    row = PrintCMIAuditReportHeadings(worksheet, row, fiscalYear, annualRateSettingEnum);

                    // The fields below with offset are due to the fact that NF does not have EffectiveDate, so without the offset
                    // the data would be skewed. If any more fields are added or removed this field will need to be modified above.
                    string currentProviderNumber = string.Empty;
                    string currentVariable = string.Empty;
                    foreach (DataRow item in groupDataTable.Rows)
                    {
                        int index = 0;
                        var auditField = new CMIAuditReportFields();
                        auditField.ChangeId = item[index].ToString();

                        index++;

                        //Check if we have moved on to new variable
                        auditField.Variable = item[index].ToString();
                        if (currentVariable != auditField.Variable)
                        {
                            currentVariable = auditField.Variable;
                            currentProviderNumber = string.Empty;
                        }

                        index++;

                        auditField.ProviderNumber = Convert.IsDBNull(item[index])
                            ? string.Empty
                            : item[index].ToString();

                        if (auditField.ProviderNumber != string.Empty && currentProviderNumber != string.Empty)
                        {
                            if (auditField.ProviderNumber != currentProviderNumber)
                                currentProviderNumber = auditField.ProviderNumber;
                        }
                        else if (currentProviderNumber != string.Empty)
                            auditField.ProviderNumber = currentProviderNumber;
                        else if (auditField.ProviderNumber != string.Empty)
                            currentProviderNumber = auditField.ProviderNumber;
                        else
                        {
                            var providerNumber = providerLookupGroupData
                                .Where(x => x.LastUpdatedOn == Convert.ToDateTime(item[12])
                                            && x.VariableName == currentVariable)
                                .OrderBy(y => y.LastUpdatedOn).FirstOrDefault();

                            if (providerNumber != null)
                            {
                                currentProviderNumber = providerNumber.Value;
                                auditField.ProviderNumber = providerNumber.Value;
                            }
                        }

                        index++;

                        auditField.PriorProviderNumber = Convert.IsDBNull(item[index])
                            ? string.Empty
                            : item[index].ToString();

                        index++;

                        auditField.ReportType = reportType;

                        if (annualRateSettingEnum == nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM))
                        {
                            auditField.TotalFacilityCaseMix = Convert.IsDBNull(item[index])
                                ? -1
                                : Convert.ToDouble(item[index]);
                            index++;

                            auditField.PriorTotalFacilityCaseMix = Convert.IsDBNull(item[index])
                                ? -1
                                : Convert.ToDouble(item[index]);
                            index++;
                        }

                        auditField.OverrideCMIScore = Convert.IsDBNull(item[index])
                            ? -1
                            : Convert.ToDouble(item[index]);

                        index++;

                        auditField.PriorCMIScore = Convert.IsDBNull(item[index])
                            ? -1
                            : Convert.ToDouble(item[index]);

                        index++;

                        auditField.OverrideMdsScoreType = Convert.IsDBNull(item[index]) ||
                                                          string.IsNullOrWhiteSpace(item[index].ToString())
                            ? -1
                            : Convert.ToDouble(item[index]);

                        index++;

                        auditField.PriorMdsScoreType = Convert.IsDBNull(item[index]) ||
                                                       string.IsNullOrWhiteSpace(item[index].ToString())
                            ? -1
                            : Convert.ToDouble(item[index]);

                        index++;

                        auditField.Comments = Convert.IsDBNull(item[index]) ||
                                              string.IsNullOrWhiteSpace(item[index].ToString())
                            ? string.Empty
                            : item[index].ToString();

                        index++;

                        auditField.PriorComments = Convert.IsDBNull(item[index]) ||
                                                   string.IsNullOrWhiteSpace(item[index].ToString())
                            ? string.Empty
                            : item[index].ToString();

                        index += 2;

                        // item[10] is 'Action'. Unneeded.
                        auditField.ModifiedBy = Convert.IsDBNull(item[index])
                            ? "System"
                            : item[index].ToString();

                        index++;

                        auditField.ChangeDate = Convert.ToDateTime(item[index]);

                        auditFields.Add(auditField);
                    }


                    auditFields = auditFields
                        .OrderBy(x => x.ProviderNumber)
                        .ThenBy(x => x.Variable)
                        .ThenBy(x => x.ChangeDate)
                        .ToList();

                    foreach (CMIAuditReportFields field in auditFields)
                    {
                        row++;
                        col = 1;

                        worksheet.Range[row, col].Text = field.ProviderNumber;
                        col++;
                        if (field.ProviderNumber != field.PriorProviderNumber)
                        {
                            worksheet.Range[row, col].Text = field.PriorProviderNumber;
                            col++;
                        }
                        else
                        {
                            col++;
                        }

                        worksheet.Range[row, col].Text = reportType;
                        col++;

                        if (annualRateSettingEnum == nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM))
                        {
                            if (field.TotalFacilityCaseMix != -1 &&
                                field.TotalFacilityCaseMix != field.PriorTotalFacilityCaseMix)
                                worksheet.Range[row, col].Text = field.TotalFacilityCaseMix.ToString("##0.0000");
                            else
                                worksheet.Range[row, col].Text = string.Empty;
                            col++;

                            if (field.PriorTotalFacilityCaseMix != -1 &&
                                field.TotalFacilityCaseMix != field.PriorTotalFacilityCaseMix)
                                worksheet.Range[row, col].Text = field.PriorTotalFacilityCaseMix.ToString("##0.0000");
                            else
                                worksheet.Range[row, col].Text = string.Empty;
                            col++;
                        }

                        if (field.OverrideCMIScore != -1 && (field.OverrideCMIScore != field.PriorCMIScore))
                        {
                            if (field.OverrideCMIScore != -1 || field.PriorCMIScore != -1
                                                             || field.OverrideCMIScore != field.PriorCMIScore)
                            {
                                worksheet.Range[row, col].Text = field.OverrideCMIScore.ToString("##0.0000");
                            }
                            else
                            {
                                worksheet.Range[row, col].Text = string.Empty;
                            }
                        }

                        col++;

                        if (field.PriorCMIScore != -1 && (field.PriorCMIScore != field.OverrideCMIScore))
                        {
                            worksheet.Range[row, col].Text = field.PriorCMIScore.ToString("##0.0000");
                        }
                        else
                        {
                            worksheet.Range[row, col].Text = string.Empty;
                        }

                        col++;


                        if (field.OverrideMdsScoreType != -1 && (field.OverrideMdsScoreType != field.PriorMdsScoreType))
                        {
                            worksheet.Range[row, col].Text =
                                field.OverrideMdsScoreType.ToString("0");
                        }
                        else
                        {
                            worksheet.Range[row, col].Text = string.Empty;
                        }

                        col++;

                        if (field.PriorMdsScoreType != -1 && (field.PriorMdsScoreType != field.OverrideMdsScoreType))
                        {
                            worksheet.Range[row, col].Text = field.PriorMdsScoreType.ToString("0");
                        }
                        else
                        {
                            worksheet.Range[row, col].Text = string.Empty;
                        }

                        col++;


                        if (field.Comments != field.PriorComments)
                        {
                            worksheet.Range[row, col].Text = field.Comments;
                            col++;
                            worksheet.Range[row, col].Text = field.PriorComments;
                            col++;
                        }
                        else
                        {
                            col += 2;
                        }

                        worksheet.Range[row, col].Text =
                            Convert.ToDateTime(field.ChangeDate).ToString("MM/dd/yyyy hh:mm:ss tt");
                        col++;
                        worksheet.Range[row, col].Text = field.ModifiedBy;
                    }

                    var bodyStyleName = CreateStyle(workbook, "BodyStyle", true, 8, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);


                    worksheet.UsedRange.AutofitRows();
                    worksheet.UsedRange.AutofitColumns();

                    worksheet.Columns[0].NumberFormat = "0000";
                    worksheet.Columns[1].NumberFormat = "0000000";
                    worksheet.Columns[3].NumberFormat = "###.0000";
                    worksheet.Columns[4].NumberFormat = "###.0000";

                    worksheet.SetColumnWidth(1, 10);
                    worksheet.SetColumnWidth(2, 12);
                    if (annualRateSettingEnum == nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM))
                    {
                        worksheet.SetColumnWidth(4, 17);
                        worksheet.SetColumnWidth(5, 17);
                        worksheet.SetColumnWidth(6, 12);
                        worksheet.SetColumnWidth(7, 12);
                        worksheet.SetColumnWidth(8, 10);
                        worksheet.SetColumnWidth(9, 10);
                        worksheet.SetColumnWidth(10, 30);
                        worksheet.SetColumnWidth(11, 30);
                    }
                    else
                    {
                        worksheet.SetColumnWidth(4, 10);
                        worksheet.SetColumnWidth(5, 10);
                        worksheet.SetColumnWidth(6, 10);
                        worksheet.SetColumnWidth(7, 10);

                        worksheet.SetColumnWidth(8, 30);
                        worksheet.SetColumnWidth(9, 30);
                    }

                    worksheet.Range["A1:K1"].Merge();


                    worksheet.UsedRange.CellStyleName = bodyStyleName;

                    var headerStyleName = CreateStyle(workbook, "HeaderStyle", true, 11, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);

                    worksheet.Range["A2"].HorizontalAlignment = ExcelHAlign.HAlignLeft;

                    worksheet.Range["A1:K1"].CellStyleName = titleStyleName;
                    worksheet.Range["A2:B2"].CellStyleName = headerStyleName;
                    worksheet.Range["A3:K3"].CellStyleName = headerStyleName;

                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;
                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.PageSetup.FitToPagesWide = 1;

                    worksheet.Range[4, 1].FreezePanes();

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;
                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create, FileAccess.ReadWrite))
                    {
                        report.WriteTo(fileStream);
                    }

                    return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) },
                        JsonRequestBehavior.AllowGet);
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message });
            }
        }

        public int PrintCMIAuditReportHeadings(IWorksheet worksheet, int row, string fiscalYear, string rateSetEnum)
        {
            int column = 1;
            if (row == 1)
            {
                worksheet.Range[row, column].Text =
                    "CMI Audit Report";

                row++;

                worksheet.Range[row, column].Text = "Report Period";
                column++;
                worksheet.Range[row, column].Text = fiscalYear;
                row++;
            }

            column = 1;

            worksheet.Range[row, column].Text = "Provider Number";
            column++;

            worksheet.Range[row, column].Text = "Previous Provider Number";
            column++;

            worksheet.Range[row, column].Text = "Report Type";
            column++;

            if (rateSetEnum == nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM))
            {
                worksheet.Range[row, column].Text = "Override Total Facility CMI Score";
                column++;

                worksheet.Range[row, column].Text = "Previous Total Facility CMI Score";
                column++;

                worksheet.Range[row, column].Text = "Override Medicaid Excluding PA1 PA2 CMI Score";
                column++;

                worksheet.Range[row, column].Text = "Previous Medicaid Excluding PA1 PA2 CMI Score";
                column++;
            }
            else
            {
                worksheet.Range[row, column].Text = "Override CMI Score";
                column++;

                worksheet.Range[row, column].Text = "Previous CMI Score";
                column++;
            }


            if (SimplifiedType == "NF")
            {
                worksheet.Range[row, column].Text = "Override MDS Score Type";
                column++;

                worksheet.Range[row, column].Text = "Previous MDS Score Type";
                column++;
            }
            else
            {
                worksheet.Range[row, column].Text = "Override Score Type";
                column++;

                worksheet.Range[row, column].Text = "Previous Score Type";
                column++;
            }

            worksheet.Range[row, column].Text = "Comments";
            column++;

            worksheet.Range[row, column].Text = "Previous Comments";
            column++;

            worksheet.Range[row, column].Text = "Modified Date";
            column++;

            worksheet.Range[row, column].Text = "Modified By";

            return row++;
        }

        public class CMIAuditReportFields
        {
            public string ChangeId { get; set; }
            public string Variable { get; set; }
            public string ProviderNumber { get; set; }
            public string PriorProviderNumber { get; set; }
            public string ReportType { get; set; }
            public double OverrideCMIScore { get; set; }
            public double PriorCMIScore { get; set; }
