        #region Current Active Provider Facility and Bed Counts

        public JsonResult GenerateCurrentActiveProviderFacilityAndBedCountsReport()
        {
            DateTime currDate = DateTime.Now;
            //DateTime dateTime = new DateTime();

            var facilityTypeHeading = string.Empty;
            var facilityType = string.Empty;
            var totalProviders = 0;
            var totalCertifiedBeds = 0;
            var totalBedCount = 0;
            var totalDualBedCount = 0;
            var FileName = string.Empty;
            var fullPath = string.Empty;

            try
            {
                var activeStatusList = new List<string>
                {
                    "CHA",
                    "IEN",
                    "WDG",
                    "REN"
                };

                switch (SimplifiedType)
                {
                    case "NF":
                        facilityTypeHeading = "Dual Nursing Facility";
                        facilityType = "NF";
                        FileName =
                            $"{facilityType}_CurrentActiveProviderFacilityandBedCounts_Run_{currDate:yyyyMMdd}.xlsx"
                                .ToSafeFileName();

                        break;
                    case "ICF":
                        facilityTypeHeading = "ICF-IID";
                        facilityType = "ICF";
                        FileName =
                            $"{facilityType}_CurrentActiveProviderFacilityandBedCounts_Run_{currDate:yyyyMMdd}.xlsx"
                                .ToSafeFileName();
                        break;
                    default:
                        throw new Exception($" Unknown Facility Type: {facilityType}");
                }

                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    //Save the file to the path of the current user's temporary folder

                    fullPath = Path.Combine(Path.GetTempPath(), FileName);
                    //Instantiate the excel application object.
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;

                    //The workbook is created
                    IWorkbook workbook = application.Workbooks.Create(1);

                    //The first worksheet object in the worksheets collection is accessed
                    IWorksheet worksheet = workbook.Worksheets[0];


                    var allArum_Providers = GetAllProviderList(RetrieveSession.Classification.ARUMToken, false, false,
                        false, true, false, false, false, true,
                        false,
                        "RateController.GenerateCurrentActiveProviderFacilityAndBedCounts");
                    if (!allArum_Providers.Result.Successful)
                    {
                        throw new Exception($" Providers not found. {allArum_Providers.Result.Message}.");
                    }

                    foreach (var currentProvider in allArum_Providers.lstProviders)
                    {
                        if (!IsProviderStatusActive(activeStatusList, currentProvider)) continue;
                        if (!RateProviderBL.SelectByProviderEffectiveDate(true, currentProvider.EffectiveDates))
                            continue;

                        totalProviders++;

                        CertifiedBeds bedRec = null;
                        List<string> validBedStatuses = new List<string> { "ACTUAL", "ACTIVE" };
                        var bedRecs = RateBL.GetCertifiedBeds(currentProvider.ProviderID)
                            .OrderByDescending(x => x.EffectiveDate)
                            .ToList();
                        foreach (var bed in bedRecs)
                        {
                            if (bed == null ||
                                bed.EffectiveDate > DateTime.Now ||
                                !validBedStatuses.Contains(bed.Status.ToUpper()))
                            {
                                continue;
                            }

                            bedRec = bed;
                            break;
                        }

                        if (bedRec == null) continue;

                        totalCertifiedBeds += bedRec?.Total ?? 0;

                        if (facilityType == "ICF")
                        {
                            totalBedCount += bedRec.Total;
                        }

                        if (facilityType == "NF")
                        {
                            totalBedCount += bedRec.Total + bedRec.DualSNFNF.Value;
                            totalDualBedCount += bedRec.DualSNFNF.Value;
                        }
                    }

                    if (totalBedCount == 0)
                    {
                        throw new Exception("No records met the criteria for the report.");
                    }

                    PrintMasterFacilityCounts(worksheet, totalProviders, totalCertifiedBeds, totalBedCount,
                        totalDualBedCount,
                        facilityTypeHeading, facilityType);


                    var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter, true, worksheet);
                    var headerStyleName = CreateStyle(workbook, "HeaderStyle", true, 11, true, "Times New Roman",
                        ExcelVAlign.VAlignBottom, ExcelHAlign.HAlignCenter);
                    var bodyStyleName = CreateStyle(workbook, "BodyStyle", false, 8, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignRight);

                    worksheet.UsedRange.CellStyleName = bodyStyleName;
                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.PageSetup.FitToPagesWide = 1;
                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;

                    worksheet.Rows[0].CellStyleName = titleStyleName;
                    worksheet.Rows[1].CellStyleName = titleStyleName;
                    worksheet.Rows[2].CellStyleName = titleStyleName;
                    worksheet.Rows[4].CellStyleName = headerStyleName;

                    if (facilityType == "ICF")
                    {
                        worksheet.Range["A1:G1"].Merge();
                        worksheet.Range["A2:G2"].Merge();
                        worksheet.Range["A3:G3"].Merge();
                        worksheet.Range["A4:G4"].Merge();
                        worksheet.Range["A5:G5"].Merge();
                    }
                    else
                    {
                        worksheet.Range["A1:J1"].Merge();
                        worksheet.Range["A2:J2"].Merge();
                        worksheet.Range["A3:J3"].Merge();
                        worksheet.Range["A4:J4"].Merge();
                        worksheet.Range["A5:J5"].Merge();
                    }

                    worksheet.Range["B6:B6"].Merge();

                    var range = worksheet.Range["A5:I5"];
                    range.CellStyle.Font.Underline = ExcelUnderline.Single;

                    range = worksheet.Range["B6"];
                    range.CellStyle.Font.Underline = ExcelUnderline.Single;
                    range = worksheet.Range["D6"];
                    range.CellStyle.Font.Underline = ExcelUnderline.Single;
                    range = worksheet.Range["F6"];
                    range.CellStyle.Font.Underline = ExcelUnderline.Single;
                    range = worksheet.Range["H6"];
                    range.CellStyle.Font.Underline = ExcelUnderline.Single;
                    if (facilityType == "NF")
                    {
                        range = worksheet.Range["J6"];
                        range.CellStyle.Font.Underline = ExcelUnderline.Single;
                    }

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;
                    fullPath = Path.Combine(Path.GetTempPath(), FileName);
                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create, FileAccess.ReadWrite))
                    {
                        report.WriteTo(fileStream);
                    }
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message });
            }


            return Json(new
            {
                Success = true,
                FileName = HttpUtility.UrlEncode(FileName),
                Message = string.Empty
            },
                JsonRequestBehavior.AllowGet);
        }


        public void PrintMasterFacilityCounts(IWorksheet worksheet, int providerCount, int certifiedBeds, int totalBeds,
            int dualBeds, string facilityTypeHeading, string facilityType)
        {
            DateTime currentDate = DateTime.Now;
            int row = 1;
            int column = 1;

            // Report Title
            column++;
            row++;
            worksheet.Range[row, column].Text = $"PROVIDER MASTER FACILITY COUNTS";

            row++;
            worksheet.Range[row, column].Text = "FOR ACTIVE FACILITIES ONLY";

            row++;
            worksheet.Range[row, column].Text =
                $"AS OF {currentDate.ToShortDateString()} AT {currentDate.ToShortTimeString()}";


            // Report Headings
            column = 1;
            row += 2;

            worksheet.Range[row, column].Text = "FACILITY";
            worksheet.SetColumnWidth(column, 12);

            column++;
            worksheet.SetColumnWidth(column, 5);

            column++;
            worksheet.SetColumnWidth(column, 10);
            worksheet.Range[row, column].Text = "COUNT";

            column++;
            worksheet.SetColumnWidth(column, 5);

            column++;
            worksheet.SetColumnWidth(column, 15);
            worksheet.Range[row, column].Text = "CERTIFIED";

            if (facilityType == "NF")
            {
                column++;
                worksheet.SetColumnWidth(column, 5);

                column++;
                worksheet.Range[row, column].Text = "DUAL";
                worksheet.SetColumnWidth(column, 10);
            }

            column++;
            worksheet.SetColumnWidth(column, 5);

            column++;
            worksheet.SetColumnWidth(column, 12);
            worksheet.Range[row, column].Text = "NUMBER OF BEDS";

            column = 1;
            row = 8;
            worksheet.Range[row, column].Text = facilityTypeHeading;

            column += 2;
            worksheet.Range[row, column].Text = $"{providerCount:n0}";

            column += 2;
            worksheet.Range[row, column].Text = $"{certifiedBeds:n0}";

            if (facilityType == "NF")
            {
                column += 2;
                worksheet.Range[row, column].Text = $"{dualBeds:n0}";
            }

            column += 2;
            worksheet.Range[row, column].Text = $"{totalBeds:n0}";
        }

