        /// <summary>
        /// This routine will accept an action to retrieve Effective Date records.
        /// </summary>
        /// <param name="action">WithinRange, ClosedWithinRange, ActiveThrough, AllActive, ActiveBeforeAsOf, Latest</param>
        /// <param name="dates">A list of Effective Date records</param>
        /// <param name="beginDate">The starting date.</param>
        /// <param name="endDate">The ending date, or the AsOf date if needed (may be null if not selected by the user)</param>
        /// <returns></returns>
        private EffectiveDate SelectProviderEffectiveDate(string action, List<EffectiveDate> dates,
            DateTime? beginDate = null, DateTime? endDate = null)
        {
            List<string> validActions = new List<string>
            {
                "WithinRange",
                "ActiveThrough",
                "AllActive",
                "ClosedWithinRange",
                "ActiveBeforeAsOf",
                "Latest"
            };

            EffectiveDate effDate = null;
            beginDate = beginDate?.Date;
            endDate = endDate?.Date;
            if (!beginDate.HasValue) beginDate = DateTime.MinValue;

            if (!endDate.HasValue) endDate = DateTime.Today;

            if (!validActions.Contains(action)) throw new Exception(" Unknown Status Type in Selection Criteria.");

            switch (action)
            {
                // If WithinRange was selected return the EffectiveDateRecord that falls within that range using the Effective date.
                case "WithinRange":
                    effDate = dates.Where(d => d.IsActive == true &&
                                               d.DateEffective >= beginDate &&
                                               d.DateEffective <= endDate)
                        .OrderByDescending(x => x.DateEffective)
                        .FirstOrDefault();
                    break;
                // If ClosedWithinRange was selected return the EffectiveDateRecord that falls within that range using the End Date.
                case "ClosedWithinRange":
                    effDate = dates.Where(d => d.IsActive == true &&
                                               d.EndDate >= beginDate &&
                                               d.EndDate <= endDate)
                        .OrderByDescending(x => x.DateEffective)
                        .FirstOrDefault();
                    break;
                // If "ActiveThrough" was selected, return all whose EndDate <= throughDate and DateEffective <= endDate.
                case "ActiveThrough":
                    effDate = dates.Where(d => d.IsActive == true &&
                                               d.DateEffective <= endDate &&
                                               (d.EndDate == null || d.EndDate >= beginDate))
                        .OrderByDescending(x => x.DateEffective)
                        .FirstOrDefault();
                    break;
                // If Allactive, then return those whose endDate >= today.
                case "AllActive":
                    bool isActive = RateProviderBL.SelectByProviderEffectiveDate(true, dates);
                    if (!isActive) return null;

                    effDate = dates.OrderByDescending(x => x.DateEffective)
                        .FirstOrDefault();
                    break;
                case "ActiveBeforeAsOf":
                    effDate = dates.Where(d => d.IsActive == true &&
                                               d.DateEffective != null &&
                                               d.DateEffective <= beginDate && d.EndDate >= DateTime.Now)
                        .OrderByDescending(x => x.DateEffective)
                        .FirstOrDefault();
                    break;
                case "Latest":
                    effDate = dates.Where(d => d.IsActive == true)
                        .OrderByDescending(x => x.DateEffective)
                        .FirstOrDefault();
                    break;
            }

            return effDate;
        }

        public string CreateExcelStyle(IWorkbook workbook, string styleName)
        {
            // Set up the fonts and stuff
            if (styleName == "TitleStyle")
            {
                IStyle headerStyle = workbook.Styles.Add(styleName);
                headerStyle.BeginUpdate();
                headerStyle.Font.FontName = "Times New Roman";
                headerStyle.Font.Size = 11;
                headerStyle.Font.Bold = true;
                headerStyle.VerticalAlignment = ExcelVAlign.VAlignTop;
                headerStyle.HorizontalAlignment = ExcelHAlign.HAlignCenter;
                headerStyle.WrapText = false;
                headerStyle.EndUpdate();
            }
            else if (styleName == "HeaderStyle")
            {
                IStyle headerStyle = workbook.Styles.Add(styleName);
                headerStyle.BeginUpdate();
                headerStyle.Font.FontName = "Times New Roman";
                headerStyle.Font.Size = 11;
                headerStyle.Font.Bold = true;
                headerStyle.VerticalAlignment = ExcelVAlign.VAlignTop;
                headerStyle.HorizontalAlignment = ExcelHAlign.HAlignCenter;
                headerStyle.WrapText = true;
                headerStyle.EndUpdate();
            }
            else if (styleName == "BodyStyle")
            {
                IStyle bodyStyle = workbook.Styles.Add(styleName);
                bodyStyle.BeginUpdate();
                bodyStyle.Font.FontName = "Times New Roman";
                bodyStyle.Font.Size = 8;
                bodyStyle.VerticalAlignment = ExcelVAlign.VAlignTop;
                bodyStyle.HorizontalAlignment = ExcelHAlign.HAlignCenter;
                bodyStyle.WrapText = false;
                bodyStyle.EndUpdate();
            }

            return styleName;
        }

        private string CreateStyle(IWorkbook workbook, string styleName, bool bold, int size, bool wrapText,
            string fontNane, ExcelVAlign vAlign, ExcelHAlign hAlign, bool underline = false,
            IWorksheet worksheet = null)
        {
            if (!workbook.Styles.Contains(styleName))
            {
                IStyle style = workbook.Styles.Add(styleName);
                style.BeginUpdate();
                style.Font.FontName = fontNane;
                style.Font.Size = size;
                style.Font.Bold = bold;
                style.VerticalAlignment = vAlign;
                style.HorizontalAlignment = hAlign;
                style.WrapText = wrapText;
                style.EndUpdate();
            }

            return styleName;
        }

        private string GetARUMOdhNumber(Provider provider, IArumDetailedAffiliateList affiliates)
        {
            string odhNumber = "";
            var affiliateId = provider.Affiliates.FirstOrDefault()?.AffiliateID;
            if (affiliateId.HasValue)
            {
                var affiliateList = affiliates.AffiliateList;
                var affiliate = affiliateList.FirstOrDefault(x => x.AffiliateObject.AffiliateID == affiliateId);
                odhNumber = CostReportBL.GetODHFromAffiliate(_providerServiceProxy, affiliate);
            }

            return odhNumber;
        }

        private (int Months, int Years) GetDateDiff(DateTime toDate, DateTime fromDate)
        {
            DateTime zeroTime = new DateTime(1, 1, 1);

            TimeSpan span = toDate - fromDate;

            // because we start at year 1 for the Gregorian 
            // calendar, we must subtract a year here.

            int years = (zeroTime + span).Year - 1;
            int months = (zeroTime + span).Month - 1;
            return (months, years);

            // https://stackoverflow.com/questions/38215171/calculate-year-month-and-day-between-two-dates-in-c-sharp
        }

        private bool IsProviderStatusActiveForChops(
            List<MSLC.ApplicationProxy.Interfaces.Models.ProviderStatus> statusRecords)
        {
            var activeStatusList = new List<string>
            {
                "CHA",
                "CHI"
            };
            var statusRec = statusRecords
                .Where(x => x.IsActive && x.Type.ToUpper() == "MEDICAID")
                .OrderByDescending(x => x.EffectiveDate)?
                .ThenByDescending(x => x.CreateDate)
                .FirstOrDefault();


            var hasMatch = activeStatusList.Contains(statusRec?.Status);
            if (statusRec == null || !hasMatch)
            {
                return false;
            }

            return true;
        }

        private bool IsProviderStatusActive(List<string> activeStatusList, Provider provider)
        {
            var statusRec = provider.ProviderStatuses
                .Where(x => x.IsActive && x.Type.ToUpper() == "MEDICAID")?
                .OrderByDescending(x => x.EffectiveDate)?
                .ThenByDescending(x => x.CreateDate)?
                .FirstOrDefault();

            return activeStatusList.Contains(statusRec?.Status);
        }

