        #region Cost Report Used/Not Used Ceiling Medians Common Methods

        private List<string> GenerateAllUsedOrNotUsedForCeilingsMediansReport(bool isUsedInCeilingsMedians, Period period, out string zipFileName)
        {
            List<ReportData> baseData = null;
            List<int> costReportsNotUsedIn = null;
            string dynamicWord = isUsedInCeilingsMedians ? string.Empty : "_Not_Used_for_Ceilings";
            string fileNamePrefix = $"ICF_CR_CY{period.BeginDate.ToString("yyyy")}{dynamicWord}";
            string csvDir = Path.Combine(AppContext.BaseDirectory, "Documents\\Reports\\ICF");
            zipFileName = $"{fileNamePrefix}.zip";

            IReadOnlyList<ColumnMapping> baseCols = ReportBuilder.GetColumnMap(Path.Combine(csvDir, "UsedNotUsedCeilingMedianBase.csv"));
            string[] baseRangeAddresses = baseCols.Select(x => x.RangeAddress).ToArray();

            #region Get Provider Info
            ARUMApplicationServiceProxy _arumApplicationClient = ARUMApplication.GetARUMApplicationProxy(RetrieveSession.Classification);
            IAllProviders applicationProviders = _arumApplicationClient.GetAllActiveProvidersWithOptions(RetrieveSession.Classification.ARUMToken,
                false, true, false, true, false, false, true, "UsedOrNotUsedForCeilingsMediansReport");
            #endregion

            if (isUsedInCeilingsMedians)
                baseData = RateBL.GetCostReportDataUsedInCeilingsMediansICF(period.BeginDate, period.EndDate, isUsedInCeilingsMedians, baseRangeAddresses);
            else
            {
                // Get Cost Report Data not used in Rate Calculation for the RedDate
                var redDate = new DateTime(period.FiscalYear - 1, 7, 1);
                costReportsNotUsedIn = RateBL.GetCostReportDataUsedNotUsedIn(redDate, isUsedInCeilingsMedians);
                baseData = RateBL.GetCostReportDataNotUsedInCeilingsMediansICF(costReportsNotUsedIn, baseRangeAddresses);
            }

            int[] crIds = baseData.Select(x => x.CostReportId).Distinct().ToArray();
            baseData.AddRange(RateBL.GetCostReportStatusCode(period.BeginDate, period.EndDate, crIds));

            CeilingMedianReport[] reports = new[]
            {
                new CeilingMedianReport()
                {
                    FileName = $"{fileNamePrefix}_ATT9_SECOND_BUILD.xlsx".ToSafeFileName(),
                    CSVFile = Path.Combine(csvDir, "ATT9SecondBuilding_ColumnMap.csv"),
                    IsSequenced = true,
                    SequencedRangeStartChars = new[] { "62" }
                },
                new CeilingMedianReport()
                {
                    FileName = $"{fileNamePrefix}_ATT9_RENOVATED.xlsx".ToSafeFileName(),
                    CSVFile = Path.Combine(csvDir, "ATT9Renovated_ColumnMap.csv"),
                    IsSequenced = true,
                    SequencedRangeStartChars = new[] { "62" }
                },
                new CeilingMedianReport()
                {
                    FileName = $"{fileNamePrefix}_ATT9_ADDITION_REMOVALS.xlsx".ToSafeFileName(),
                    CSVFile = Path.Combine(csvDir, "ATT9AddtionRemovals_ColumnMap.csv"),
                    IsSequenced = true,
                    SequencedRangeStartChars = new[] { "62" }
                },
                new CeilingMedianReport()
                {
                    FileName = $"{fileNamePrefix}_ATT9_SUMMARY.xlsx".ToSafeFileName(),
                    CSVFile = Path.Combine(csvDir, "ATT9Summary_ColumnMap.csv"),
                    IsSequenced = false
                },
                new CeilingMedianReport()
                {
                    FileName = $"{fileNamePrefix}_ATT8.xlsx".ToSafeFileName(),
                    CSVFile = Path.Combine(csvDir, "ATT8_ColumnMap.csv"),
                    IsSequenced = false
                },
                new CeilingMedianReport()
                {
                    FileName = $"{fileNamePrefix}_ATT6.xlsx".ToSafeFileName(),
                    CSVFile = Path.Combine(csvDir, "ATT6_ColumnMap.csv"),
                    IsSequenced = false
                },
                new CeilingMedianReport()
                {
                    FileName = $"{fileNamePrefix}_C_LN_68_OTHER_COST.xlsx".ToSafeFileName(),
                    CSVFile = Path.Combine(csvDir, "C_LN_68_ColumnMap.csv"),
                    IsSequenced = true,
                    SequencedRangeStartChars = new[] { "25" }
                },
                new CeilingMedianReport()
                {
                    FileName = $"{fileNamePrefix}_C_LN_47_OTHER_COST.xlsx".ToSafeFileName(),
                    CSVFile = Path.Combine(csvDir, "C_LN_47_ColumnMap.csv"),
                    IsSequenced = true,
                    SequencedRangeStartChars = new[] { "25" }
                },
                new CeilingMedianReport()
                {
                    FileName = $"{fileNamePrefix}_B2_OTHER_COST.xlsx".ToSafeFileName(),
                    CSVFile = Path.Combine(csvDir, "B2_Other_ColumnMap.csv"),
                    IsSequenced = true,
                    SequencedRangeStartChars = new[] { "2094", "2185", "2186" }
                }

            };

            List<string> fileNames = new List<string>()
            {
                GenerateSched_A_B1_B2_C_DReport(period.BeginDate, period.EndDate, fileNamePrefix, crIds, baseData, baseCols, 
                applicationProviders, isUsedInCeilingsMedians)
            };
            if (isUsedInCeilingsMedians) fileNames.Add(GenerateActive_ICF_Control_TypeReport(crIds, applicationProviders));

            fileNames.AddRange(reports.Select(x =>
                GenerateUsedAndNotUsedForCeilingsMediansReport(period.BeginDate, period.EndDate, x, crIds, baseData,
                    baseCols, applicationProviders, isUsedInCeilingsMedians)).ToList());
            return fileNames;
        }

        private string GenerateUsedAndNotUsedForCeilingsMediansReport(DateTime periodBegin, DateTime periodEnd, CeilingMedianReport context, int[] crIds, 
            List<ReportData> baseData, IReadOnlyList<ColumnMapping> baseCols, IAllProviders applicationProviders, bool isUsedInCeilingsMedians)
        {
            string fullPath = string.Empty;
            int provNumCol = 0;
            int crTypeCol = 4;

            IReadOnlyList<ColumnMapping> columnMap = baseCols.Concat(ReportBuilder.GetColumnMap(context.CSVFile)).ToList().AsReadOnly();
            string[] rangeAddresses = columnMap.Where(x => !baseData.Any(y => y.RangeAddress == x.RangeAddress)).Select(x => x.RangeAddress).ToArray();

            List<ReportData> reportData = null;
            if (isUsedInCeilingsMedians)
                reportData = RateBL.GetCostReportSpecificReportData(periodBegin, periodEnd, crIds, rangeAddresses);
            else
                reportData = RateBL.GetCostReportNotUsedInReportData(crIds, rangeAddresses);

            reportData.AddRange(baseData);

            List<object[]> reportRows;
            if (context.IsSequenced)
            {
                string[] sequencedRangeAddresses = rangeAddresses.Where(x => context.SequencedRangeStartChars.Any(prefix => x.StartsWith(prefix))).ToArray();
                ReportBuilder.HandleSequenceCorrelationForReport(reportData, sequencedRangeAddresses);
                reportRows = ReportBuilder.BuildSequencedReportWithArum(columnMap, reportData, applicationProviders);
            }
            else reportRows = ReportBuilder.BuildReportWithArum(columnMap, reportData, periodBegin, applicationProviders);

            using (ExcelEngine excelEngine = new ExcelEngine())
            {
                Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                application.DefaultVersion = ExcelVersion.Xlsx;

                IWorkbook workbook = application.Workbooks.Create(1);
                IWorksheet ws = workbook.Worksheets[0];

                // Headers
                for (int col = 0; col < columnMap.Count; col++)
                {
                    ws[1, col + 1].Text = columnMap[col].ColumnName;
                }

                // Rows
                for (int r = 0; r < reportRows.Count; r++)
                {
                    object[] cells = reportRows[r];
                    for (int col = 0; col < cells.Length; col++)
                    {
                        if (col == crTypeCol)
                        {
                            string fullType = cells[col]?.ToString();
                            if (!string.IsNullOrEmpty(fullType))
                            {
                                string type = fullType.Split('.').Last();
                                ws[r + 2, col + 1].Value2 = type;
                            }
                        }
                        else
                        {
                            ws[r + 2, col + 1].Value2 = cells[col];
                        }
                    }
                }

                ws.Columns[provNumCol].NumberFormat = "000000#";

                // Formatting
                ws.Rows[0].CellStyle.Font.Bold = true;
                ws.UsedRange.AutofitColumns();

                // Save the file
                fullPath = Path.Combine(Path.GetTempPath(), context.FileName);

                using (MemoryStream outputStream = new MemoryStream())
                {
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;
                    workbook.Close();

                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        outputStream.WriteTo(fileStream);
                    }
                }

            }
            return context.FileName;
        }

        #endregion

        #region  Sched_A_B1_B2_C_D Report

        private string GenerateSched_A_B1_B2_C_DReport(DateTime periodBegin, DateTime periodEnd, string fileNamePrefix, int[] crIds, List<ReportData> baseData, 
            IReadOnlyList<ColumnMapping> baseCols, IAllProviders applicationProviders, bool isUsedInCeilingsMedians)
        {
            string fileName;

            string csvDir = Path.Combine(AppContext.BaseDirectory, "Documents\\Reports\\ICF");
            IReadOnlyList<ColumnMapping> columnMap = baseCols.Concat(ReportBuilder.GetColumnMap(Path.Combine(csvDir, "Sched_A_B1_B2_C_D_ColumnMap.csv"))).ToList().AsReadOnly();
            string[] rangeAddresses = columnMap.Where(x => baseData.All(y => y.RangeAddress != x.RangeAddress)).Select(x => x.RangeAddress).ToArray();

            List<ReportData> reportData = null;
            if (isUsedInCeilingsMedians)
                reportData = RateBL.GetCostReportSpecificReportData(periodBegin, periodEnd, crIds, rangeAddresses);
            else
                reportData = RateBL.GetCostReportNotUsedInReportData(crIds, rangeAddresses);

            reportData.AddRange(baseData);
            //reportData.AddRange(RateBL.GetICFPeerGroupsReportData(crIds));
            reportData.AddRange(RateBL.GetDatabaseLookupGroupReportData(periodBegin, crIds, applicationProviders));
            reportData.AddRange(RateBL.GetAB1B2CDReportData(periodBegin, periodEnd, baseData));

            List<object[]> reportRows = ReportBuilder.BuildReportWithArum(columnMap, reportData, periodBegin, applicationProviders);
            
            using (ExcelEngine excelEngine = new ExcelEngine())
            {
                IApplication application = excelEngine.Excel;
                application.DefaultVersion = ExcelVersion.Xlsx;

                IWorkbook workbook = application.Workbooks.Create(1);
                IWorksheet ws = workbook.Worksheets[0];



                // Headers
                for (int col = 0; col < columnMap.Count; col++)
                {
                    ws[1, col + 1].Text = columnMap[col].ColumnName;
                }

                for (int r = 0; r < reportRows.Count; r++)
                {
                    object[] cells = reportRows[r];
                    for (int col = 0; col < cells.Length; col++)
                    {

                        ws[r + 2, col + 1].Value2 = cells[col];
                    }
                }

                ws.Columns[0].NumberFormat = "000000#";
                ws.Rows[0].CellStyle.Font.Bold = true;
                ws.UsedRange.AutofitColumns();
                ws.Range["A2"].FreezePanes();

                fileName = $"{fileNamePrefix}_Sched_A_B1_B2_C_D.xlsx".ToSafeFileName();
                var fullPath = Path.Combine(Path.GetTempPath(), fileName);

                MemoryStream outputStream = new MemoryStream();
                workbook.SaveAs(outputStream);
                outputStream.Position = 0;
                workbook.Close();

                MemoryStream report = outputStream;

                using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                {
                    report.WriteTo(fileStream);
                }
            }

            return fileName;
        }
