        public JsonResult GenerateDataDictionaryByCY(string cy)
        {
            try
            {
                if (!RateSettingPermissionBL.View())
                    throw new Exception("Permission denied.");

                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;

                    IWorkbook workbook = application.Workbooks.Create(1);
                    IWorksheet worksheet = workbook.Worksheets[0];

                    List<ChartOfAccount> chartOfAccts = ChartOfAccountSeed_OH.LoadChartOfAccounts();
                    DataTable rowData = RateBL.GetCYyyyyDDReportData(cy);

                    List<CYyyyyDDReportData> reportData = new List<CYyyyyDDReportData>();

                    var type = RetrieveSession.Classification.Type;
                    string csvFilePath;
                    if(type == "ICF")
					    csvFilePath = Path.Combine(AppContext.BaseDirectory, "Documents\\Reports\\ICF", "ICF_RangeAddress_ChartOfAcct.csv");
                    else
						csvFilePath = Path.Combine(AppContext.BaseDirectory, "Documents\\Reports\\NF", "NF_RangeAddress_ChartOfAcct.csv");


					var acctMap = ReportBuilder.GetChartOfAcctMap(csvFilePath);
                    foreach(DataRow rd in rowData.Rows)
                    {
                        var den = rd.Field<string>("DATA_ELEM_NUM");

                        var reportDatum = new CYyyyyDDReportData()
                        {
                            DEN = den,
                            ScheduleName = rd.Field<string>("CR_SCHED"),
                            Line = rd.Field<string>("CR_LINE"),
                            Column = rd.Field<string>("CR_COL"),
                            Length = rd.Field<int>("LENGTH"),
                            Precision = rd.Field<int>("PRECISION"),
                            Type = rd.Field<string>("TYPE"),
                            Conditional = GetConditional(rd.Field<int>("REQUIREMENT_TYPE")),
                            LowSuffix = rd.Field<string>("LOW_SUFFIX"),
                            HighSuffix = rd.Field<string>("HIGH_SUFFIX"),
                            SequenceDictionary = rd.Field<int>("SequenceDictionary"),
                            DescriptionLong = rd.Field<string>("DESC_LONG"),
                            ChartOfAccountNumber = acctMap.Where(a => a.RangeAddress == den).Select(a => a.ChartOfAcctNumber).FirstOrDefault()
                        };

                      
                            reportData.Add(reportDatum);
                    }

                    var row = 1;
                    var col = 1;

                    Dictionary<string, ExcelStylingAttribute> headers = ExcelStyleHelper.GetReportHeaders<CYyyyyDDReportData>();
                    
                    foreach (KeyValuePair<string, ExcelStylingAttribute> header in headers)
                    {
                        worksheet.Range[row, col].Text = header.Key;
                        col++;
                    }

                    row++;

                    List<PropertyInfo> reportProps = ExcelStyleHelper.GetReportProperties<CYyyyyDDReportData>();

                    foreach (CYyyyyDDReportData rowItem in reportData)
                    {
                        col = 1;
                        foreach (PropertyInfo prop in reportProps)
                        {
                            AddValueToCell(rowItem, prop, worksheet, row, col);
                            col++;
                        }
                        row++;
                    }

                    worksheet.Rows[0].CellStyle.Font.Bold = true;
                    worksheet.UsedRange.AutofitColumns();
                    worksheet.Range["A2"].FreezePanes();

                    var fileName = RetrieveSession.Classification.GetDDReportFileName(cy);
                    var fullPath = Path.Combine(Path.GetTempPath(), fileName);

                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    MemoryStream report = outputStream;

                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }

                    return Json(new
                    {
                        Success = true,
                        FileName = fileName,
                        Message = string.Empty
                    },
                        JsonRequestBehavior.AllowGet);
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
        }
