        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult GenerateCRyyRevICFReport(string cy)
        {
            try
            {
                var period = ReportBL.GetPeriodByPeriodCode(cy);

                List<CRyyRevIcfReportData>
                    reportData = RateBL.GetCRyyRevIcfReportData(period.BeginDate, period.EndDate);

                if (!reportData.Any())
                    return Json("No Data Found");


                var columnMap = CRyyRevICFReportBuilder.GetColumnMap();
                var reportRows = CRyyRevICFReportBuilder.BuildReport(reportData, columnMap, cy.Substring(2));

                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;

                    IWorkbook workbook = application.Workbooks.Create(1);
                    IWorksheet ws = workbook.Worksheets[0];

                    // Headers
                    for (int col = 0; col < columnMap.Count; col++)
                    {
                        ws[1, col + 1].Text = columnMap[col].ColumnName;
                    }

                    // Rows
                    for (int r = 0; r < reportRows.Count; r++)
                    {
                        object[] cells = reportRows[r];


                        for (int col = 0; col < cells.Length; col++)
                        {

                            ws[r + 2, col + 1].Value2 = cells[col];
                        }
                    }

                    // Formatting
                    ws.Rows[0].CellStyle.Font.Bold = true;
                    ws.UsedRange.AutofitRows();
                    ws.UsedRange.AutofitColumns();
                    ws.Range["A2"].FreezePanes();

                    int firstRow = ws.UsedRange.Row;
                    int lastRow = ws.UsedRange.LastRow;
                    int lastCol = ws.UsedRange.LastColumn;

                    int atargetCol = -1;
                    int stargetCol = -1;
                    int ctargetCol = -1;
                    int ptargetCol = -1;
                    for (int col = 1; col <= lastCol; col++)
                    {
                        if (atargetCol > -1 && stargetCol > -1 && ctargetCol > -1 && ptargetCol > -1)
                        {
                            break;
                        }

                        string header = (ws[firstRow, col].Text ?? string.Empty).Trim();

                        switch (header)
                        {
                            case "ANNCM":
                                atargetCol = col;
                                break;
                            case "QTRCM":
                                stargetCol = col;
                                break;
                            case "CONTROL":
                                ctargetCol = col;
                                break;
                            case "PROV_NUM":
                                ptargetCol = col;
                                break;
                        }
                    }

                    if (atargetCol > 0 && lastRow > firstRow)
                    {
                        ws.Range[firstRow + 1, atargetCol, lastRow, atargetCol].NumberFormat = "0.0000";
                    }

                    if (stargetCol > 0 && lastRow > firstRow)
                    {
                        ws.Range[firstRow + 1, stargetCol, lastRow, stargetCol].NumberFormat = "0.0000";
                    }

                    if (ptargetCol > 0 && lastRow > firstRow)
                    {
                        ws.Range[firstRow + 1, ptargetCol, lastRow, ptargetCol].NumberFormat = "0000000";
                    }

                    if (ctargetCol > 0 && lastRow > firstRow)
                    {
                        ws.Range[firstRow + 1, ctargetCol, lastRow, ctargetCol].HorizontalAlignment =
                            ExcelHAlign.HAlignRight;
                    }


                    ws.Columns[12].NumberFormat = @"mm\/dd\/yyyy";
                    ws.Columns[13].NumberFormat = @"mm\/dd\/yyyy";

                    ws.PageSetup.FitToPagesTall = 0;
                    ws.PageSetup.FitToPagesWide = 1;
                    var fileName = $"CR{cy.Substring(cy.Length - 2)}RevICF.xlsx".ToSafeFileName();
                    var fullPath = Path.Combine(Path.GetTempPath(), fileName);

                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    MemoryStream report = outputStream;

                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }

                    return Json(new
                    {
                        Success = true,
                        FileName = fileName,
                        Message = string.Empty
                    },
                        JsonRequestBehavior.AllowGet);
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
        }

