        public JsonResult GenerateCRyyRevNFReport(string cy)
        {
            try
            {
                if (!RateSettingPermissionBL.View())
                    throw new Exception("Permission denied.");

                string fileName;

                string csvFilePath = Path.Combine(AppContext.BaseDirectory, "Documents\\Reports\\NF",
                    "CRyyRevNF_ColumnMap.csv");
                var columnMap = ReportBuilder.GetColumnMap(csvFilePath);
                List<string> rangeAddresses = columnMap.Select(x => x.RangeAddress).ToList();
                rangeAddresses.AddRange(new[]
                    { "10880", "10890", "11010", "10910", "10920", "10930", "10940", "10950", "10960" });
                // Gather report data
                List<ReportData> reportData =
                    RateBL.GetNFReportData( rangeAddresses.ToArray());

                int[] costReportIds = reportData.Select(x => x.CostReportId).Distinct().ToArray();
                ReportBuilder.HandleVersionCorrelationForReport(reportData, "DOCNUM");
                ReportBuilder.HandleNFPeerGroupsCorrelationForReport(reportData, RetrieveSession.Classification);

                reportData.AddRange(RateBL.GetCMReportData(cy, costReportIds));

                RateBL.HandlePracticeTypeForReportData(reportData);

                reportData = reportData.OrderBy(x => x.CostReportId).ToList();

                var period = ReportBL.GetPeriodByPeriodCode(cy);

                List<object[]> reportRows = ReportBuilder.BuildReport2(columnMap, reportData, period);

                reportRows = reportRows.OrderBy(array => Convert.ToInt32(array[0]))
                    .ToList();

                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;

                    IWorkbook workbook = application.Workbooks.Create(1);
                    IWorksheet ws = workbook.Worksheets[0];

                    // Headers
                    for (int col = 0; col < columnMap.Count; col++)
                    {
                        ws[1, col + 1].Text = columnMap[col].ColumnName;
                    }

                    // Rows
                    for (int r = 0; r < reportRows.Count; r++)
                    {
                        object[] cells = reportRows[r];
                        for (int col = 0; col < cells.Length; col++)
                        {

                            ws[r + 2, col + 1].Value2 = cells[col];
                        }
                    }

                    // Formatting
                    ws.Rows[0].CellStyle.Font.Bold = true;
                    ws.UsedRange.AutofitColumns();
                    ws.Range["A2"].FreezePanes();

                    int firstRow = ws.UsedRange.Row;
                    int lastRow = ws.UsedRange.LastRow;
                    int lastCol = ws.UsedRange.LastColumn;

                    int atargetCol = -1;
                    int stargetCol = -1;
                    int ctargetCol = -1;
                    int ptargetCol = -1;
                    for (int col = 1; col <= lastCol; col++)
                    {
                        if (atargetCol > -1 && stargetCol > -1 && ctargetCol > -1 && ptargetCol > -1)
                        {
                            break;
                        }

                        string header = (ws[firstRow, col].Text ?? string.Empty).Trim();

                        switch (header)
                        {
                            case "ANNUALCM":
                                atargetCol = col;
                                break;
                            case "SEMICM":
                                stargetCol = col;
                                break;
                            case "CONTROL":
                                ctargetCol = col;
                                break;
                            case "10020":
                                ptargetCol = col;
                                break;
                        }
                    }

                    if (atargetCol > 0 && lastRow > firstRow)
                    {
                        ws.Range[firstRow + 1, atargetCol, lastRow, atargetCol].NumberFormat = "0.0000";
                    }

                    if (stargetCol > 0 && lastRow > firstRow)
                    {
                        ws.Range[firstRow + 1, stargetCol, lastRow, stargetCol].NumberFormat = "0.0000";
                    }

                    if (ptargetCol > 0 && lastRow > firstRow)
                    {
                        ws.Range[firstRow + 1, ptargetCol, lastRow, ptargetCol].NumberFormat = "0000000";
                    }

                    if (ctargetCol > 0 && lastRow > firstRow)
                    {
                        ws.Range[firstRow + 1, ctargetCol, lastRow, ctargetCol].HorizontalAlignment =
                            ExcelHAlign.HAlignRight;
                    }

                    // Save the file
                    fileName = $"CR{period.BeginDate:yy}RevNF.xlsx".ToSafeFileName();
                    var fullPath = Path.Combine(Path.GetTempPath(), fileName);

                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;
                    workbook.Close();

                    MemoryStream report = outputStream;
                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                }

                return Json(new
                {
                    Success = true,
                    FileName = fileName,
                    Message = string.Empty
                },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception ex)
            {
                return Json(new
                {
                    Success = false,
                    FileName = string.Empty,
                    Message = ex.Message
                });
            }
        }

        #endregion CRyyRevICF Report

