        public JsonResult GenerateWGHRCYyyNFReport(string cy)
        {
            string fileName = string.Empty;
            string fullPath = string.Empty;
            string csvFilePath = Path.Combine(AppContext.BaseDirectory, "Documents\\Reports\\NF", "WGHRCYyyNF_ColumnMap.csv");

            IReadOnlyList<ColumnMapping> columnMap = ReportBuilder.GetColumnMap(csvFilePath);
            string[] rangeAddresses = columnMap.Select(x => x.RangeAddress).ToArray();

            // Gather report data
            List<ReportData> reportData = RateBL.GetNFReportData( rangeAddresses);

            var period = ReportBL.GetPeriodByPeriodCode(cy);

            List<object[]> reportRows = ReportBuilder.BuildReport2(columnMap, reportData, period);
            reportRows = reportRows.OrderBy(array => Convert.ToInt32(array[0]))
                .ToList();

            // Generate the Excel File
            using (ExcelEngine excelEngine = new ExcelEngine())
            {
                IApplication application = excelEngine.Excel;
                application.DefaultVersion = ExcelVersion.Xlsx;

                IWorkbook workbook = application.Workbooks.Create(1);
                IWorksheet ws = workbook.Worksheets[0];

                // Headers
                for (int col = 0; col < columnMap.Count; col++)
                {
                    ws[1, col + 1].Text = columnMap[col].ColumnName;
                }

                // Rows
                for (int r = 0; r < reportRows.Count; r++)
                {
                    object[] cells = reportRows[r];
                    for (int col = 0; col < cells.Length; col++)
                    {
                        if (col == 6)
                        {
                            string fullType = cells[col]?.ToString();
                            if (!string.IsNullOrEmpty(fullType))
                            {
                                string type = fullType.Split('.').Last();
                                ws[r + 2, col + 1].Value2 = type;
                            }
                        }
                        else
                        {
                            ws[r + 2, col + 1].Value2 = cells[col];
                        }
                    }
                }

                ws.Rows[0].CellStyle.Font.Bold = true;
                ws.Range["A2"].FreezePanes();
                ws.UsedRange.AutofitRows();
                ws.UsedRange.AutofitColumns();

                ws.PageSetup.FitToPagesTall = 0;
                ws.PageSetup.FitToPagesWide = 1;

                ws.UsedRange.HorizontalAlignment = ExcelHAlign.HAlignLeft;

                int firstRow = ws.UsedRange.Row;
                int lastRow = ws.UsedRange.LastRow;
                int lastCol = ws.UsedRange.LastColumn;

                int p1targetCol = -1;
                int p2targetCol = -1;
                int prtargetCol = -1;

                for (int col = 1; col <= lastCol; col++)
                {
                    if (p1targetCol > -1 && p2targetCol > -1 && prtargetCol > -1)
                    {
                        break;
                    }

                    string header = (ws[firstRow, col].Text ?? string.Empty).Trim();

                    switch (header)
                    {
                        case "10020":
                            prtargetCol = col;
                            break;
                        case "10370":
                            p1targetCol = col;
                            break;
                        case "10380":
                            p2targetCol = col;
                            break;
                    }
                }

                if (prtargetCol > 0 && lastRow > firstRow)
                {
                    ws.Range[firstRow + 1, prtargetCol, lastRow, prtargetCol].NumberFormat = "0000000";
                }

                if (p1targetCol > 0 && lastRow > firstRow)
                {
                    ws.Range[firstRow + 1, p1targetCol, lastRow, p1targetCol].NumberFormat = @"mm\/dd\/yyyy";
                }

                if (p2targetCol > 0 && lastRow > firstRow)
                {
                    ws.Range[firstRow + 1, p2targetCol, lastRow, p2targetCol].NumberFormat = @"mm\/dd\/yyyy";
                }
                // Save the file
                fileName = $"WGHRCY{period.BeginDate:yyyy}NF.xlsx".ToSafeFileName();
                fullPath = Path.Combine(Path.GetTempPath(), fileName);

                MemoryStream outputStream = new MemoryStream();
                workbook.SaveAs(outputStream);
                outputStream.Position = 0;
                workbook.Close();

                MemoryStream report = outputStream;
                using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                {
                    report.WriteTo(fileStream);
                }
            }

            return Json(new
            {
                Success = true,
                FileName = fileName,
                Message = string.Empty
            },
                JsonRequestBehavior.AllowGet);
        }
