            string[] rangeAddresses = columnMap.Select(x => x.RangeAddress).ToArray();

            // Sequences for this report start with 46
            string[] sequenceRangeAddresses = rangeAddresses.Where(x => x.Substring(0, 2) == "46").ToArray();

            // Gather report data
            var period = ReportBL.GetPeriodByPeriodCode(cy);
            List<ReportData> reportData = RateBL.GetReportData(period.BeginDate, period.EndDate, rangeAddresses);
            int[] costReportIds = reportData.Select(x => x.CostReportId).Distinct().ToArray();
            ReportBuilder.HandleVersionCorrelationForReport(reportData, "DOC_NUM");
            ReportBuilder.HandleSequenceCorrelationForReport(reportData, sequenceRangeAddresses);
            reportData.AddRange(RateBL.GetCostReportStatusCode(period.BeginDate, period.EndDate, costReportIds));

            List<object[]> reportRows = ReportBuilder.BuildSequencedReport(columnMap, reportData);

            // Generate the Excel File
            using (ExcelEngine excelEngine = new ExcelEngine())
            {
                Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                application.DefaultVersion = ExcelVersion.Xlsx;

                IWorkbook workbook = application.Workbooks.Create(1);
                IWorksheet ws = workbook.Worksheets[0];

                // Headers
                for (int col = 0; col < columnMap.Count; col++)
                {
                    ws[1, col + 1].Text = columnMap[col].ColumnName;
                }

                // Rows
                for (int r = 0; r < reportRows.Count; r++)
                {
                    object[] cells = reportRows[r];
                    for (int col = 0; col < cells.Length; col++)
                    {
                        if (col == crTypeCol)
                        {
                            string fullType = cells[col]?.ToString();
                            if (!string.IsNullOrEmpty(fullType))
                            {
                                string type = fullType.Split('.').Last();
                                ws[r + 2, col + 1].Value2 = type;
                            }
                        }
                        else if (col == amountCol)
                        {
                            if (int.TryParse(cells[col].ToString(), out int amount))
                                ws[r + 2, col + 1].Value2 = amount * -1;
                            else ws[r + 2, col + 1].Value2 = cells[col];
                        }
                        else
                        {
                            ws[r + 2, col + 1].Value2 = cells[col];
                        }
                    }
                }

                // Formatting
                ws.Rows[0].CellStyle.Font.Bold = true;
                ws.UsedRange.AutofitColumns();
                ws.Range["A2"].FreezePanes();
                ws.Columns[0].NumberFormat = "0000000";

                // Save the file
                fileName = $"ICF_CY{period.BeginDate.ToString("yyyy")}_ATT1_Other_Revenue.xlsx".ToSafeFileName();
                fullPath = Path.Combine(Path.GetTempPath(), fileName);

                MemoryStream outputStream = new MemoryStream();
                workbook.SaveAs(outputStream);
                outputStream.Position = 0;
                workbook.Close();

                MemoryStream report = outputStream;
                using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                {
                    report.WriteTo(fileStream);
                }
            }

            return Json(new
            {
                Success = true,
                FileName = fileName,
                Message = string.Empty
            },
                JsonRequestBehavior.AllowGet);
        }

        #endregion ICF_CYyyyy_ATT1_Other Revenue Report

