        [ARUMFeatureActionFilter("RateSetting:View")]
        private string GenerateActive_ICF_Control_TypeReport(int[] crIds, IAllProviders applicationProviders)
        {
            string fileName;
            List<Active_ICF_Control_TypeReportData> reportData = RateBL.GetProviderAttributes(crIds, applicationProviders);

            using (ExcelEngine excelEngine = new ExcelEngine())
            {
                IApplication application = excelEngine.Excel;
                application.DefaultVersion = ExcelVersion.Xlsx;

                IWorkbook workbook = application.Workbooks.Create(1);
                IWorksheet ws = workbook.Worksheets[0];

                int row = 1;
                int col = 1;

                Dictionary<string, ExcelStylingAttribute> headers = ExcelStyleHelper.GetReportHeaders<Active_ICF_Control_TypeReportData>();

                foreach (KeyValuePair<string, ExcelStylingAttribute> header in headers)
                {
                    ws.Range[row, col].Text = header.Key;
                    col++;
                }

                row++;

                List<PropertyInfo> reportProps = ExcelStyleHelper.GetReportProperties<Active_ICF_Control_TypeReportData>();

                foreach (var rowItem in reportData)
                {
                    col = 1;
                    foreach (PropertyInfo prop in reportProps)
                    {
                        AddValueToCell(rowItem, prop, ws, row, col);
                        col++;
                    }
                    row++;
                }

                ws.Rows[0].CellStyle.Font.Bold = true;
                ws.UsedRange.AutofitColumns();
                ws.Range["A2"].FreezePanes();

                fileName = "Active_ICF_Control_Type.xlsx".ToSafeFileName();
                var fullPath = Path.Combine(Path.GetTempPath(), fileName);

                MemoryStream outputStream = new MemoryStream();
                workbook.SaveAs(outputStream);
                outputStream.Position = 0;
                workbook.Close();

                MemoryStream report = outputStream;

                using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                {
                    report.WriteTo(fileStream);
                }
            }

            return fileName;
        }

