        #region DatabaseLookupGroup - Common methods

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public JsonResult GetDatabaseLookupGroup(string lookUpGroupDate, AnnualRateSettingEnum annualRateSettingEnum)
        {
            try
            {
                if (string.IsNullOrEmpty(lookUpGroupDate))
                    throw new Exception($"Missing group date");

                DateTime dateTime = new DateTime();
                int i;
                switch (annualRateSettingEnum)
                {
                    case AnnualRateSettingEnum.SemiAnnualCaseMixScores:
                    case AnnualRateSettingEnum.QuarterlyCaseMixScores:
                    case AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM:
                    case AnnualRateSettingEnum.QualityPoints:
                        if (!DateTime.TryParse(lookUpGroupDate, out dateTime))
                            throw new Exception("Invalid input of fiscal year; please enter a valid quaterly date.");
                        break;

                    case AnnualRateSettingEnum.QualityPointsRateSch6:
                    case AnnualRateSettingEnum.DirectCareRateFreeze:
                    case AnnualRateSettingEnum.RateParametersByPeerGroupRED:
                        if (!DateTime.TryParse(lookUpGroupDate, out dateTime))
                            throw new Exception(
                                "Invalid input of effective date; please enter a valid effective date.");
                        break;

                    case AnnualRateSettingEnum.CHOWQualityPaymentOverride:
                    case AnnualRateSettingEnum.ProvidersWithTaxOverride:
                    case AnnualRateSettingEnum.ProvidersWithLowOccupancyOverride:
                    case AnnualRateSettingEnum.OccupancyPercentageLOARate:
                        if (!int.TryParse(lookUpGroupDate, out i))
                            throw new Exception(
                                "Invalid input of state fiscal year; please simply enter the year number.");
                        dateTime = new DateTime(i - 1, 7, 1);
                        break;
                    case AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY:
                        if (!int.TryParse(lookUpGroupDate, out i))
                            throw new Exception(
                                "Invalid input of state fiscal year; please simply enter the year number.");
                        dateTime = new DateTime(i, 7, 1);
                        break;
                    default:
                        // Validate input
                        if (!int.TryParse(lookUpGroupDate, out i))
                            throw new Exception("Invalid input of fiscal year; please simply enter the year number.");
                        dateTime = new DateTime(i, 1, 1);
                        break;
                }

                DatabaseLookupGroupViewModel lookupGroupViewModel =
                    GetDatabaseLookupGroupViewModel(dateTime, annualRateSettingEnum);
                return Json(new
                {
                    Success = true,
                    LookupGroupViewModel = lookupGroupViewModel
                }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    Message = e.Message
                }, JsonRequestBehavior.AllowGet);
            }
        }

        private DatabaseLookupGroupViewModel GetDatabaseLookupGroupViewModel(DateTime dateTime,
            AnnualRateSettingEnum annualRateSettingEnum, int year = -1)
        {
            try
            {
                DatabaseLookupGroupViewModel lookupGroupViewModel = new DatabaseLookupGroupViewModel();

                string valueType = annualRateSettingEnum.ToString();
                List<DatabaseLookupGroup> lookupGroups = DatabaseLookupGroupBL.GetDatabaseLookupGroups(valueType);
                List<Column> cols = new List<Column>();
                List<ColumnValidations> validations = new List<ColumnValidations>();

                #region Build Grid Dynamic Column

                var dataTable = DatabaseLookupGroupBL.GetDatabaseLookupGroup(dateTime, valueType, year);

                foreach (DataColumn col in dataTable.Columns)
                {
                    col.ColumnName = col.ColumnName.Replace(" ", "");
                }

                int pKeyId = 1; // Syncfusion Grid needs a PrimaryKey
                dataTable.Columns.Add("PrimaryKeyID", typeof(System.Int32));
                foreach (DataRow row in dataTable.Rows)
                {
                    row["PrimaryKeyID"] = pKeyId;
                    pKeyId++;
                }

                switch (valueType)
                {
                    case nameof(AnnualRateSettingEnum.QualityPointsRateSch6):
                    case nameof(AnnualRateSettingEnum.QualityPointsRateSch5):
                    case nameof(AnnualRateSettingEnum.CorpOfficeSalaryCeilingTables):
                    case nameof(AnnualRateSettingEnum.QualityPoints):
                    case nameof(AnnualRateSettingEnum.AnnualCaseMixScores):
                    case nameof(AnnualRateSettingEnum.SemiAnnualCaseMixScores):
                    case nameof(AnnualRateSettingEnum.QuarterlyCaseMixScores):
                    case nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM):
                    case nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY):
                    case nameof(AnnualRateSettingEnum.ProvidersWithTaxOverride):
                    case nameof(AnnualRateSettingEnum.DirectCareRateFreeze):
                    case nameof(AnnualRateSettingEnum.ProvidersWithLowOccupancyOverride):
                    case nameof(AnnualRateSettingEnum.Wh0Ceiling):
                    case nameof(AnnualRateSettingEnum.CHOWQualityPaymentOverride):
                    case nameof(AnnualRateSettingEnum.OccupancyPercentageLOARate):
                        cols.Add(new Column()
                        { Field = "VariableName", HeaderText = "Variable Name", Visible = false, Type = "string" });
                        cols.Add(new Column()
                        { Field = "Description", HeaderText = "Description", Visible = false, Type = "string" });
                        break;
                    case nameof(AnnualRateSettingEnum.PeerGroup):
                    case nameof(AnnualRateSettingEnum.RateParametersByPeerGroupRED):
                        bool canEdit = RetrieveSession.IsAdministrator;
                        cols.Add(new Column()
                        {
                            Field = "VariableName",
                            HeaderText = "Variable Name",
                            Visible = true,
                            Type = "string",
                            AllowEditing = canEdit
                        });
                        cols.Add(new Column()
                        {
                            Field = "Description",
                            HeaderText = "Description",
                            Visible = true,
                            Type = "string",
                            AllowEditing = canEdit
                        });
                        break;
                    default:
                        cols.Add(new Column()
                        { Field = "VariableName", HeaderText = "Variable Name", Visible = true, Type = "string" });
                        cols.Add(new Column()
                        { Field = "Description", HeaderText = "Description", Visible = true, Type = "string" });
                        break;
                }

                foreach (DatabaseLookupGroup lookupGroup in lookupGroups)
                {
                    var column = new Column();
                    // If this group is not "active" for the time specified, it will be a hidden column.
                    if ((lookupGroup.StartDate == null || lookupGroup.StartDate <= dateTime) &&
                        (lookupGroup.EndDate == null || lookupGroup.EndDate >= dateTime))
                    {
                        column.Field = lookupGroup.Name.Replace(" ", "");
                        column.HeaderText = lookupGroup.Name;
                        column.Visible = true;
                        column.Type = "string";
                        column.Width = 75;
                    }
                    else
                    {
                        column.Field = lookupGroup.Name.Replace(" ", "");
                        column.HeaderText = lookupGroup.Name;
                        column.Visible = false;
                        column.Type = "string";
                        column.Width = 75;
                    }

                    Dictionary<string, object> temp = new Dictionary<string, object>();

                    // https://ej2.syncfusion.com/documentation/grid/editing/validation
                    // https://help.syncfusion.com/cr/blazor/Syncfusion.Blazor.Grids.ValidationRules.html
                    switch (lookupGroup.Name)
                    {
                        case "Wages":
                        case "Hours":
                            column.Type =
                                "number"; // https://ej2.syncfusion.com/angular/documentation/grid/columns/columns
                            column.Format = "N";
                            break;

                        case "Per Hour":
                        case "Ceiling":
                        case "Tax Rate":
                            column.Type =
                                "number"; // https://ej2.syncfusion.com/angular/documentation/grid/columns/columns
                            column.Format = "N2";
                            break;

                        case "Case Mix Value":
                            column.Type =
                                "number"; // https://ej2.syncfusion.com/angular/documentation/grid/columns/columns
                            column.Format = "N4";
                            break;

                        case "MDS Score Type":
                            column.Type =
                                "number"; // https://ej2.syncfusion.com/angular/documentation/grid/columns/columns
                            column.Format = "N";
                            break;

                        case "Effective Date":
                            column.Type = "date";
                            column.EditType = Syncfusion.JavaScript.EditingType.Datepicker;
                            column.Format = "{0:MM/dd/yyyy}";
                            break;

                        case "General Classification":
                            column.Visible = false;
                            break;

                        case "Classification Number":
                            column.Visible = false;
                            break;

                        case "Step 1":
                        case "Step 2":
                        case "Step 3":
                        case "Step 4":
                        case "Step 5":
                        case "Step 6":
                        case "Step 7":
                        case "Step 8":
                        case "Step 9":
                            column.Type =
                                "number"; // https://ej2.syncfusion.com/angular/documentation/grid/columns/columns
                            column.Format = "N";
                            break;
                    }

                    cols.Add(column);
                }

                #endregion

                #region Load Look up Group DD Fiscal years from DB

                List<SelectListItem> lookupGroupFiscalYears = new List<SelectListItem>();
                List<DatabaseLookupGroupYear> lookupGroupYear =
                    DatabaseLookupGroupBL.GetAllDatabaseLookupGroupYears(annualRateSettingEnum.ToString());

                foreach (DatabaseLookupGroupYear lookupGroup in lookupGroupYear)
                {
                    string startDate;
                    switch (annualRateSettingEnum)
                    {
                        // These use actual dates
                        case AnnualRateSettingEnum.SemiAnnualCaseMixScores:
                        case AnnualRateSettingEnum.QuarterlyCaseMixScores:
                        case AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM:
                        case AnnualRateSettingEnum.QualityPointsRateSch6:
                        case AnnualRateSettingEnum.QualityPoints:
                        case AnnualRateSettingEnum.DirectCareRateFreeze:
                        case AnnualRateSettingEnum.RateParametersByPeerGroupRED:
                            startDate = lookupGroup.LookUpDate.ToString("MM/dd/yyyy");
                            break;

                        // SFY date is actually the year after the start date.
                        case AnnualRateSettingEnum.CHOWQualityPaymentOverride:
                        case AnnualRateSettingEnum.ProvidersWithTaxOverride:
                        case AnnualRateSettingEnum.ProvidersWithLowOccupancyOverride:
                        case AnnualRateSettingEnum.OccupancyPercentageLOARate:
                            startDate = (lookupGroup.LookUpDate.Year + 1).ToString();
                            break;

                        // Default is the year of the lookup date.
                        default:
                            startDate = lookupGroup.LookUpDate.Year.ToString();
                            break;
                    }

                    lookupGroupFiscalYears.Add(new SelectListItem
                    {
                        Text = startDate,
                        Value = ClientMapping.MapInternalIdToClientId(lookupGroup.DatabaseLookupGroupYearId.ToString(),
                            "dblookupgroupyear"),
                    });
                }

                #endregion

                string JSONString = JsonConvert.SerializeObject(dataTable);

                lookupGroupViewModel.DataModel = JSONString;
                lookupGroupViewModel.GridColumns = cols;
                lookupGroupViewModel.GridColumnValidations = validations;
                lookupGroupViewModel.LookupGroupFiscalYears = lookupGroupFiscalYears;
                return lookupGroupViewModel;
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                throw;
            }
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
