        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult SaveDatabaseLookupGroup(string value, string lookupGroupYearId, string lookupGroupDate,
            AnnualRateSettingEnum annualRateSettingEnum)
        {
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;

            try
            {
                string valueType = annualRateSettingEnum.ToString();

                var serializer = new JavaScriptSerializer();
                var dataDictionary = serializer.Deserialize<Dictionary<string, string>>(value);
                int groupYearId = -1;

                if (!int.TryParse(ClientMapping.GetInternalIdFromClientId(lookupGroupYearId, "dblookupgroupyear"),
                        out groupYearId))
                    return Json(new { Success = false, Message = "Invalid lookup group year specified." },
                        JsonRequestBehavior.AllowGet);
                DatabaseLookupGroupYear lookupYear = DatabaseLookupGroupBL.GetDatabaseLookupGroupYearById(groupYearId);

                List<DatabaseLookupGroup> lookupGroups =
                    DatabaseLookupGroupBL.GetDatabaseLookupGroups(annualRateSettingEnum.ToString(), false);

                // Get the saved database lookup group data records from the session to make saving easier.
                List<DatabaseLookupGroupData> listLookupGroupDataId =
                    (List<DatabaseLookupGroupData>)Session[SESSION_KEYS_RS.LOOKUP_GROUP_DATA_ID];

                if (listLookupGroupDataId != null && listLookupGroupDataId.Count > 0
                                                  && dataDictionary["VariableName"] != null) // Edit
                {
                    foreach (DatabaseLookupGroup lookupGroup in lookupGroups)
                    {
                        string fieldName = string.Join("", lookupGroup.Name.Split(' '));
                        string textValue = dataDictionary[fieldName];
                        decimal d;
                        switch (fieldName)
                        {
                            case "TaxRate":
                                if (decimal.TryParse(textValue, out d))
                                {
                                    textValue = d.ToString("0.00");
                                }
                                else
                                {
                                    textValue = "0.00";
                                }

                                break;

                            case "CaseMixValue":
                            case "MedicaidExcludingPACaseMixValue":
                            case "TotalFacilityCaseMixValue":
                                if (decimal.TryParse(textValue, out d))
                                {
                                    textValue = d.ToString("0.0000");
                                }
                                else
                                {
                                    textValue = "0.0000";
                                }

                                break;
                            case "EffectiveDate":
                                if (DateTime.TryParse(textValue, out DateTime dt))
                                {
                                    textValue = dt.ToShortDateString();
                                }
                                else
                                {
                                    textValue = "";
                                }

                                break;
                        }

                        DatabaseLookupGroupData data = listLookupGroupDataId
                            .FirstOrDefault(x => x.DatabaseLookupGroupId == lookupGroup.DatabaseLookupGroupId);

                        // Are we missing a saved data placeholder?
                        if (data == null)
                        {
                            // If this has value, save it.
                            if (!string.IsNullOrWhiteSpace(textValue))
                            {
                                DatabaseLookupGroupData pgDataModel = new DatabaseLookupGroupData
                                {
                                    DatabaseLookupGroupDataId = 0, // Set the LookupGroupDataId from the Session
                                    DatabaseLookupGroupId = lookupGroup.DatabaseLookupGroupId, // Set the LookupGroupId
                                    DatabaseLookupGroupYearId = groupYearId,
                                    ValueType = dataDictionary["ValueType"],
                                    VariableName = dataDictionary["VariableName"],
                                    Description = dataDictionary["Description"],
                                    Value = textValue,
                                    LastUpdatedOn = DateTime.Now,
                                    LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}"
                                };

                                DatabaseLookupGroupBL.SaveDatabaseLookupGroup(pgDataModel);
                            }
                        }
                        else
                        {
                            if ((!string.IsNullOrWhiteSpace(textValue) || data.DatabaseLookupGroupDataId != 0) &&
                                (annualRateSettingEnum == AnnualRateSettingEnum.PeerGroup || annualRateSettingEnum ==
                                    AnnualRateSettingEnum.RateParametersByPeerGroupRED))
                            {
                                DatabaseLookupGroupData pgDataModel = new DatabaseLookupGroupData
                                {
                                    DatabaseLookupGroupDataId =
                                        data.DatabaseLookupGroupDataId, // Set the LookupGroupDataId from the Session
                                    DatabaseLookupGroupId = lookupGroup.DatabaseLookupGroupId, // Set the LookupGroupId
                                    DatabaseLookupGroupYearId = groupYearId,
                                    ValueType = dataDictionary["ValueType"],
                                    VariableName = dataDictionary["VariableName"],
                                    Description = dataDictionary["Description"],
                                    Value = textValue,
                                    LastUpdatedOn = DateTime.Now,
                                    LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}"
                                };

                                DatabaseLookupGroupBL.SaveDatabaseLookupGroup(pgDataModel);
                            }
                            else if ((!string.IsNullOrWhiteSpace(textValue) || data.DatabaseLookupGroupDataId != 0) &&
                                     textValue != data.Value)
                            {
                                // Only save this value if it has already been saved or if there is an actual value to save
                                DatabaseLookupGroupData pgDataModel = new DatabaseLookupGroupData
                                {
                                    DatabaseLookupGroupDataId =
                                        data.DatabaseLookupGroupDataId, // Set the LookupGroupDataId from the Session
                                    DatabaseLookupGroupId = lookupGroup.DatabaseLookupGroupId, // Set the LookupGroupId
                                    DatabaseLookupGroupYearId = groupYearId,
                                    ValueType = dataDictionary["ValueType"],
                                    VariableName = dataDictionary["VariableName"],
                                    Description = dataDictionary["Description"],
                                    Value = textValue,
                                    LastUpdatedOn = DateTime.Now,
                                    LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}"
                                };

                                DatabaseLookupGroupBL.SaveDatabaseLookupGroup(pgDataModel);
                            }
                        }
                    }

                    Session[SESSION_KEYS_RS.LOOKUP_GROUP_DATA_ID] = null;
                }
                else // Add
                {
                    int lookupIndex = 0;

                    List<int> listLookupGroupId = DatabaseLookupGroupBL.GetDatabaseLookupGroup(valueType);
                    switch (valueType)
                    {
                        // This data needs to generate a variable name
                        case nameof(AnnualRateSettingEnum.QualityPointsRateSch6):
                        case nameof(AnnualRateSettingEnum.QualityPointsRateSch5):
                        case nameof(AnnualRateSettingEnum.CorpOfficeSalaryCeilingTables):
                        case nameof(AnnualRateSettingEnum.QualityPoints):
                        case nameof(AnnualRateSettingEnum.AnnualCaseMixScores):
                        case nameof(AnnualRateSettingEnum.SemiAnnualCaseMixScores):
                        case nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY):
                        case nameof(AnnualRateSettingEnum.QuarterlyCaseMixScores):
                        case nameof(AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM):
                        case nameof(AnnualRateSettingEnum.ProvidersWithTaxOverride):
                        case nameof(AnnualRateSettingEnum.DirectCareRateFreeze):
                        case nameof(AnnualRateSettingEnum.ProvidersWithLowOccupancyOverride):
                        case nameof(AnnualRateSettingEnum.CHOWQualityPaymentOverride):
                        case nameof(AnnualRateSettingEnum.OccupancyPercentageLOARate):
                            List<string> listVariableNames =
                                DatabaseLookupGroupBL.GetDatabaseLookupGroupVariableName(groupYearId, valueType);
                            int variableName = 0;
                            if (listVariableNames.Count > 0)
                            {
                                variableName = listVariableNames.Select(x => int.Parse(x)).Max();
                            }

                            int newVariableName = variableName + 1; // Required for PIVOT to make a set unique.

                            foreach (DatabaseLookupGroup dbColumn in lookupGroups)
                            {
                                string fieldName = string.Join("", dbColumn.Name.Split(' '));
                                switch (fieldName)
                                {
                                    case "EffectiveDate":
                                        if (DateTime.TryParse(dataDictionary[fieldName], out DateTime dt))
                                        {
                                            dataDictionary[fieldName] = dt.ToShortDateString();
                                        }
                                        else
                                        {
                                            dataDictionary[fieldName] = "";
                                        }

                                        break;
                                }

                                if (!string.IsNullOrWhiteSpace(dataDictionary[fieldName]))
                                {
                                    DatabaseLookupGroupData pgDataModel = new DatabaseLookupGroupData
                                    {
                                        DatabaseLookupGroupId = listLookupGroupId[lookupIndex],
                                        DatabaseLookupGroupYearId = groupYearId,
                                        VariableName = newVariableName.ToString(),
                                        ValueType = valueType,
                                        Value = dataDictionary[fieldName],
                                        CreatedOn = DateTime.Now,
                                        CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                                        LastUpdatedOn = DateTime.Now,
                                        LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}"
                                    };
                                    DatabaseLookupGroupBL.SaveDatabaseLookupGroup(pgDataModel);
                                }

                                lookupIndex++;
                            }

                            break;

                        // This data should specify a variable name
                        default:
                            foreach (DatabaseLookupGroup lookupGroup in lookupGroups)
                            {
                                string fieldName = string.Join("", lookupGroup.Name.Split(' '));
                                if (!string.IsNullOrWhiteSpace(dataDictionary[fieldName]))
                                {
                                    DatabaseLookupGroupData pgDataModel = new DatabaseLookupGroupData
                                    {
                                        DatabaseLookupGroupId = listLookupGroupId[lookupIndex],
                                        DatabaseLookupGroupYearId = groupYearId,
                                        VariableName = dataDictionary["VariableName"],
                                        Description = dataDictionary["Description"],
                                        ValueType = valueType,
                                        Value = dataDictionary[fieldName],
                                        CreatedOn = DateTime.Now,
                                        CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                                        LastUpdatedOn = DateTime.Now,
                                        LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}"
                                    };
                                    DatabaseLookupGroupBL.SaveDatabaseLookupGroup(pgDataModel);
                                }

                                lookupIndex++;
                            }

                            break;
                    }
                }

                DatabaseLookupGroupViewModel lookupGroupViewModel =
                    GetDatabaseLookupGroupViewModel(lookupYear.LookUpDate, annualRateSettingEnum);
                return Json(new
                {
                    Success = true,
                    LookupGroupViewModel = lookupGroupViewModel
                },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    ResponseText = e.Message
                },
                    JsonRequestBehavior.AllowGet);
            }
        }

