        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult AddQualityPointDate(string qualityPointDate, AnnualRateSettingEnum annualRateSettingEnum)
        {
            try
            {
                MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
                List<SelectListItem> lookupGroupFiscalYears = new List<SelectListItem>();
                DateTime lookUpGroupDate = new DateTime();
                if (string.IsNullOrEmpty(qualityPointDate))
                    throw new Exception("Invalid or missing lookup group year or date. Please check submission.");
                if (!DateTime.TryParse(qualityPointDate, out lookUpGroupDate))
                    throw new Exception("Invalid input of date; please enter a valid quality point date.");

                var pgYears = DatabaseLookupGroupBL.GetLookupGroupYears(lookUpGroupDate, annualRateSettingEnum);
                if (pgYears.Count > 0) throw new Exception("Record already exists.");

                DatabaseLookupGroupYear lookupYearData = new DatabaseLookupGroupYear
                {
                    ValueType = annualRateSettingEnum.ToString(),
                    CreatedOn = DateTime.Now,
                    CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                    LastUpdatedOn = DateTime.Now,
                    LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}",
                    LookUpDate = lookUpGroupDate
                };

                DatabaseLookupGroupBL.AddQualityPointDate(lookupYearData);

                var qualityPointYears =
                    DatabaseLookupGroupBL.GetAllDatabaseLookupGroupYears(annualRateSettingEnum.ToString());

                foreach (DatabaseLookupGroupYear lookupGroup in qualityPointYears)
                {
                    lookupGroupFiscalYears.Add(new SelectListItem
                    {
                        Text = lookupGroup.LookUpDate.ToString("MM/dd/yyyy"),
                        Value = ClientMapping.MapInternalIdToClientId(lookupGroup.DatabaseLookupGroupYearId.ToString(),
                            "dblookupgroupyear"),
                    });
                }

                return Json(new
                {
                    Success = true,
                    LookupGroupFiscalYears = lookupGroupFiscalYears
                },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult SaveLookupGroupDate(string fiscalYear, AnnualRateSettingEnum annualRateSettingEnum)
        {
            try
            {
                MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;

                DateTime lookUpGroupDate = new DateTime();
                int i;
                if (string.IsNullOrEmpty(fiscalYear))
                    throw new Exception("Invalid or missing lookup group year or date. Please check submission.");

                switch (annualRateSettingEnum)
                {
                    case AnnualRateSettingEnum.SemiAnnualCaseMixScores:
                        if (!DateTime.TryParse(fiscalYear, out lookUpGroupDate))
                            throw new Exception("Invalid input of date; please enter a valid semi-annual date.");
                        break;

                    case AnnualRateSettingEnum.QuarterlyCaseMixScores:
                    case AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM:
                        if (!DateTime.TryParse(fiscalYear, out lookUpGroupDate))
                            throw new Exception("Invalid input of date; please enter a valid quaterly date.");
                        break;
                    case AnnualRateSettingEnum.QualityPoints:
                        if (!DateTime.TryParse(fiscalYear, out lookUpGroupDate))
                            throw new Exception("Invalid input of date; please enter a valid quality points date.");
                        break;

                    case AnnualRateSettingEnum.QualityPointsRateSch6:
                    case AnnualRateSettingEnum.DirectCareRateFreeze:
                    case AnnualRateSettingEnum.RateParametersByPeerGroupRED:
                        if (!DateTime.TryParse(fiscalYear, out lookUpGroupDate))
                            throw new Exception("Invalid input of date; please enter a valid effective date.");
                        break;

                    case AnnualRateSettingEnum.CHOWQualityPaymentOverride:
                    case AnnualRateSettingEnum.ProvidersWithTaxOverride:
                    case AnnualRateSettingEnum.ProvidersWithLowOccupancyOverride:
                    case AnnualRateSettingEnum.OccupancyPercentageLOARate:
                        if (!int.TryParse(fiscalYear, out i))
                            throw new Exception(
                                "Invalid input of state fiscal year; please simply enter the year number.");
                        lookUpGroupDate =
                            new DateTime(i - 1, 7, 1); // SFY is END year: SFY 2020 = 7/1/2019 to 6/30/2020
                        break;
                    case AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY:
                        if (!int.TryParse(fiscalYear, out i))
                            throw new Exception(
                                "Invalid input of state fiscal year; please simply enter the year number.");
                        lookUpGroupDate = new DateTime(i, 7, 1);
                        break;

                    default:
                        // Validate input
                        if (!int.TryParse(fiscalYear, out i))
                            throw new Exception(
                                "Invalid input of fiscal year end; please simply enter the year number.");
                        lookUpGroupDate = new DateTime(i, 1, 1);
                        break;
                }

                var pgYears = DatabaseLookupGroupBL.GetLookupGroupYears(lookUpGroupDate, annualRateSettingEnum);
                if (pgYears.Count > 0) throw new Exception("Record already exists.");

                if (annualRateSettingEnum == AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY ||
                    annualRateSettingEnum == AnnualRateSettingEnum.OccupancyPercentageLOARate)
                {
                    DatabaseLookupGroupBL.AddLookupGroupYear(lookUpGroupDate, annualRateSettingEnum.ToString(),
                        myUser.FirstName + " " + myUser.LastName);
                }
                else
                {
                    DatabaseLookupGroupBL.AddLookupGroupFYE(lookUpGroupDate, annualRateSettingEnum,
                        $"{myUser.FirstName} {myUser.LastName}");
                }

                DatabaseLookupGroupViewModel lookupViewModel =
                    GetDatabaseLookupGroupViewModel(lookUpGroupDate, annualRateSettingEnum);

                return Json(new
                {
                    Success = true,
                    DatabaseLookupGroupViewModel = lookupViewModel
                },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public JsonResult DeleteLookupGroupFYEData(string lookupGroupYearId,
            AnnualRateSettingEnum annualRateSettingEnum)
        {
            try
            {
                int dbLookupId = 0;
                if (int.TryParse(ClientMapping.GetInternalIdFromClientId(lookupGroupYearId, "dblookupgroupyear"),
                        out int i))
                {
                    dbLookupId = i;
                }

                List<DatabaseLookupGroupYear> years =
                    DatabaseLookupGroupBL.DeleteDatabaseLookupGroupDataFYE(dbLookupId,
                        annualRateSettingEnum.ToString());

                List<SelectListItem> itemList = new List<SelectListItem>();
                foreach (var rate in years)
                {
                    string startDate;
                    switch (annualRateSettingEnum)
                    {
                        // These values use dates.
                        case AnnualRateSettingEnum.SemiAnnualCaseMixScores:
                        case AnnualRateSettingEnum.QuarterlyCaseMixScores:
                        case AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM:
                        case AnnualRateSettingEnum.QualityPointsRateSch6:
                        case AnnualRateSettingEnum.AncillaryPerDiemRanking:
                        case AnnualRateSettingEnum.DirectCareRateFreeze:
                        case AnnualRateSettingEnum.QualityPoints:
                            startDate = rate.LookUpDate.ToString("MM/dd/yyyy");
                            break;

                        // These values use SFY; SFY 2020 = 7/1/2019 to 6/30/2020
                        case AnnualRateSettingEnum.CHOWQualityPaymentOverride:
                        case AnnualRateSettingEnum.ProvidersWithTaxOverride:
                        case AnnualRateSettingEnum.ProvidersWithLowOccupancyOverride:
                        case AnnualRateSettingEnum.OccupancyPercentageLOARate:
                            startDate = (rate.LookUpDate.Year + 1).ToString();
                            break;

                        // These values use the year number (FYE, etc.)/
                        default:
                            startDate = rate.LookUpDate.Year.ToString();
                            break;
                    }

                    itemList.Add(new SelectListItem
                    {
                        Text = startDate,
                        Value = ClientMapping.MapInternalIdToClientId(rate.DatabaseLookupGroupYearId.ToString(),
                            "dblookupgroupyear"),
                    });
                }

                DatabaseLookupGroupViewModel dbLookupGroupViewModel = new DatabaseLookupGroupViewModel
                {
                    LookupGroupFiscalYears = itemList,
                    DateText = RateSettingLookupDateType.GetLookupDateTypeString(annualRateSettingEnum)
                };
                return Json(new { Success = true, DatabaseLookupGroupViewModel = dbLookupGroupViewModel },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public JsonResult GenerateQualityPointsReport(string selectedRED, AnnualRateSettingEnum annualRateSettingEnum)
        {
            try
            {
                DateTime dateTime = new DateTime();

                if (!DateTime.TryParse(selectedRED, out dateTime))
                {
                    return Json(new
                    {
                        Success = false,
                        Message = "Invalid input of RED; please enter a valid date."
                    }, JsonRequestBehavior.AllowGet);
                }

                string fullPath = "";
                var fileName = $"{dateTime.ToString("yyyy-MM-dd")} Quality Point Report.xlsx";
                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    //Save the file to the path of the current user's temporary folder
                    fullPath = Path.Combine(Path.GetTempPath(), fileName);
                    //Instantiate the excel application object.
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;

                    //The workbook is created
                    IWorkbook workbook = application.Workbooks.Create(1);

                    //The first worksheet object in the worksheets collection is accessed
                    IWorksheet worksheet = workbook.Worksheets[0];

                    // Import Data
                    DataTable dataTable = DatabaseLookupGroupBL.GetQualityPointReportData(dateTime, annualRateSettingEnum.ToString());

                    //Add NPI number
                    dataTable.Columns.Add("NPI_NUM", typeof(string)).SetOrdinal(0);

                    var providerNumbers = dataTable.AsEnumerable()
                        .Select(row => row.Field<string>("PROV_NUM"))
                        .ToList();

                    var npis = GetNpiNumbers(providerNumbers);

                    foreach (DataRow row in dataTable.Rows)
                    {
                        row["NPI_NUM"] = npis.TryGetValue(row["PROV_NUM"].ToString(), out var npi) ? npi : string.Empty;
                    }

                    worksheet.ImportDataTable(dataTable, true, 1, 1, -1, -1, true);


                    // Header bold Style 
                    var headerStyleName = CreateStyle(workbook, "HeaderStyle", true, 11, false, "Calibri",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignLeft);
                    worksheet.Rows[0].CellStyleName = headerStyleName;

                    // Number Format
                    worksheet.Columns[0].NumberFormat = "0000000000";
                    worksheet.Columns[1].NumberFormat = "0000000";
                    worksheet.Columns[2].NumberFormat = "0";
                    worksheet.Columns[3].NumberFormat = "0";
                    worksheet.Columns[4].NumberFormat = "0";
                    worksheet.Columns[5].NumberFormat = "0";
                    worksheet.Columns[6].NumberFormat = "0.00;0.00";
                    worksheet.Columns[7].NumberFormat = "0.00;0.00";
                    worksheet.Columns[8].NumberFormat = "0.00;0.00";
                    worksheet.Columns[9].NumberFormat = "0.00;0.00";
                    worksheet.Columns[10].NumberFormat = "0.00;0.00";

                    //Saving the workbook as stream
                    FileStream file = new FileStream(fullPath, FileMode.Create, FileAccess.ReadWrite);
                    worksheet.UsedRange.AutofitColumns();
                    workbook.SaveAs(file);
                    file.Dispose();
                }

                return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
        }


