        public DataTable GenerateDataGroupExportForReport(string fiscalYear,
            AnnualRateSettingEnum annualRateSettingEnum)
        {
            try
            {
                DateTime dateTime = new DateTime();

                // Default column name for group data is CYE (basically calendar year end)
                string dateColumnName = "CYE";
                string dateValue = "";
                int year;
                switch (annualRateSettingEnum)
                {
                    case AnnualRateSettingEnum.SemiAnnualCaseMixScores:
                    case AnnualRateSettingEnum.QuarterlyCaseMixScores:
                    case AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM:
                    case AnnualRateSettingEnum.QualityPointsRateSch6:
                    case AnnualRateSettingEnum.DirectCareRateFreeze:
                        if (!DateTime.TryParse(fiscalYear, out dateTime))
                        {
                            throw new Exception("Invalid input of selection date or year; please enter a valid value.");
                        }

                        dateColumnName = "Effective Date";
                        dateValue = dateTime.ToShortDateString();
                        break;

                    case AnnualRateSettingEnum.CHOWQualityPaymentOverride:
                    case AnnualRateSettingEnum.ProvidersWithTaxOverride:
                    case AnnualRateSettingEnum.ProvidersWithLowOccupancyOverride:
                    case AnnualRateSettingEnum.OccupancyPercentageLOARate:
                        // Validate input
                        if (!int.TryParse(fiscalYear, out year))
                        {
                            throw new Exception("Invalid input of selection date or year; please enter a valid value.");
                        }

                        dateTime = new DateTime(year - 1, 07, 01);
                        dateColumnName = "SFY";
                        dateValue = (dateTime.Year + 1).ToString();
                        break;

                    case AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY:
                        // Validate input
                        if (!int.TryParse(fiscalYear, out year))
                        {
                            throw new Exception("Invalid input of selection date or year; please enter a valid value.");
                        }

                        dateTime = new DateTime(year, 07, 01);
                        dateColumnName = "SFY";
                        dateValue = (dateTime.Year).ToString();
                        break;

                    default:
                        // Validate input
                        if (!int.TryParse(fiscalYear, out year))
                        {
                            throw new Exception("Invalid input of selection date or year; please enter a valid value.");
                        }

                        dateTime = new DateTime(year, 01, 01);
                        dateValue = dateTime.Year.ToString();
                        break;
                }

                // Import Data
                return DatabaseLookupGroupBL.GetDatabaseLookupGroupExport(dateTime, annualRateSettingEnum.ToString(),
                    dateColumnName, dateValue);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                throw;
            }
        }

        public JsonResult GenerateDataExport(string fiscalYear, AnnualRateSettingEnum annualRateSettingEnum,
            string type = "XLSX")
        {
            try
            {
                DateTime dateTime = RateSettingLookupDateType.GetLookupDateByType(annualRateSettingEnum, fiscalYear);

                // Default column name for group data is FYE (basically calendar year end)
                string dateColumnName = RateSettingLookupDateType.GetLookupDateTypeString(annualRateSettingEnum);
                string dateValue = annualRateSettingEnum.GetLookupDateValue(dateTime);

                string fullPath = "";
                var suffix = type.ToUpper() == "CSV" ? "csv" : "xlsx";

                var fileName =
                    $"{dateTime.ToString("yyyy-MM-dd")} {annualRateSettingEnum.GetDescription()} Report.{suffix}";
                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    //Save the file to the path of the current user's temporary folder
                    fullPath = Path.Combine(Path.GetTempPath(), fileName);
                    //Instantiate the excel application object.
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;

                    //The workbook is created
                    IWorkbook workbook = application.Workbooks.Create(1);

                    //The first worksheet object in the worksheets collection is accessed
                    IWorksheet worksheet = workbook.Worksheets[0];

                    // Import Data
                    DataTable dataTable = DatabaseLookupGroupBL.GetDatabaseLookupExport(dateTime,
                        annualRateSettingEnum.ToString(), dateColumnName, dateValue);

                    worksheet.ImportDataTable(dataTable, true, 1, 1, true);

                    //Saving the workbook as stream
                    FileStream file = new FileStream(fullPath, FileMode.Create, FileAccess.ReadWrite);
                    worksheet.UsedRange.AutofitColumns();

                    if (type.ToUpper() == "CSV")
                    {
                        workbook.SaveAs(file, ",");
                    }
                    else
                    {
                        workbook.SaveAs(file);
                    }

                    file.Dispose();
                }

                return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
        }

