            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public JsonResult GenerateCaseMixReport(string fiscalYear, AnnualRateSettingEnum annualRateSettingEnum)
        {
            try
            {
                DateTime dateTime = new DateTime();
                var fileName = string.Empty;
                //Determines whether or not the first header is just year or dd/MM/YYYY format
                bool firstHeaderIsYearOnly = true;
                if (!string.IsNullOrEmpty(fiscalYear))
                {
                    //string dateType = RateSettingLookupDateType.GetLookupDateTypeString(annualRateSettingEnum);
                    switch (annualRateSettingEnum)
                    {
                        case AnnualRateSettingEnum.SemiAnnualCaseMixScores:
                        case AnnualRateSettingEnum.QuarterlyCaseMixScores:
                        case AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM:
                            fileName = $"{fiscalYear}_{annualRateSettingEnum.ToString()}.xlsx".ToSafeFileName();
                            firstHeaderIsYearOnly = false;
                            if (!DateTime.TryParse(fiscalYear, out dateTime))
                            {
                                return Json(new
                                {
                                    Success = false,
                                    Message = "Invalid input of fiscal year; please enter a valid quaterly date."
                                }, JsonRequestBehavior.AllowGet);
                            }

                            break;
                        case AnnualRateSettingEnum.AnnualCaseMixScores:
                            //fileName = $"{dateType}{fiscalYear}_{annualRateSettingEnum.ToString()}.xlsx".ToSafeFileName();
                            // Validate input
                            if (!int.TryParse(fiscalYear, out int year))
                            {
                                return Json(new
                                {
                                    Success = false,
                                    Message = "Invalid input of fiscal year; please simply enter the year number."
                                }, JsonRequestBehavior.AllowGet);
                            }

                            dateTime = new DateTime(int.Parse(fiscalYear), 01, 01);
                            fileName = GenerateExcelFileName(annualRateSettingEnum, dateTime);
                            break;
                        case AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY:
                            //fileName = $"{dateType}{fiscalYear}_{annualRateSettingEnum.ToString()}.xlsx".ToSafeFileName();
                            // Validate input
                            if (!int.TryParse(fiscalYear, out int qYear))
                            {
                                return Json(new
                                {
                                    Success = false,
                                    Message = "Invalid input of fiscal year; please simply enter the year number."
                                }, JsonRequestBehavior.AllowGet);
                            }

                            dateTime = new DateTime(int.Parse(fiscalYear), 07, 01);
                            fileName = GenerateExcelFileName(annualRateSettingEnum, dateTime);
                            break;

                        default:
                            throw new Exception("Invalid type for operation.");
                    }
                }

                string fullPath = "";

                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    //Save the file to the path of the current user's temporary folder
                    fullPath = Path.Combine(Path.GetTempPath(), fileName);
                    //Instantiate the excel application object.
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;

                    //The workbook is created
                    IWorkbook workbook = application.Workbooks.Create(1);

                    //The first worksheet object in the worksheets collection is accessed
                    IWorksheet worksheet = workbook.Worksheets[0];

                    //Two specific reports need "Quarter End Date" as first header which is not a current Mnemonic we have
                    AnnualRateSettingEnum[] quarterEndDateEnums =
                    {
                        AnnualRateSettingEnum.QuarterlyCaseMixScores, AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM
                    };

                    //Populate data table, then give it header names
                    DataTable dataTable = new DataTable();
                    var groupDataTable =
                        DatabaseLookupGroupBL.GetDatabaseLookupGroup(dateTime, annualRateSettingEnum.ToString());
                    if (groupDataTable.Columns.Count > 4)
                    {
                        int i = 0;
                        string dateHeader = quarterEndDateEnums.Contains(annualRateSettingEnum)
                            ? "Quarter End Date"
                            : annualRateSettingEnum.GetDateType().GetDateMnemonic();

                        dataTable.Columns.Add(dateHeader);

                        foreach (DataColumn tableColumn in groupDataTable.Columns)
                        {
                            if (i >= 4) // Skip the first 4 columns of 8. 
                            {
                                dataTable.Columns.Add(tableColumn.ColumnName, typeof(string));
                            }

                            i++;
                        }

                        int j = 0;
                        if (dataTable.Columns.Count > 0)
                        {
                            DataRow dataRow = null;

                            foreach (DataRow rowData in groupDataTable.Rows)
                            {
                                dataRow = dataTable.NewRow();
                                dataRow[dataTable.Columns[0].ColumnName] = fiscalYear;
                                for (int c = 1; c < dataTable.Columns.Count; c++)
                                {
                                    dataRow[dataTable.Columns[c].ColumnName] =
                                        groupDataTable.Rows[j][dataTable.Columns[c].ColumnName];
                                }

                                dataTable.Rows.Add(dataRow);
                                j++;
                            }
                        }
                    }

                    //Row starts at 2 as we are skipping headers here
                    var dataColumns = dataTable.Columns;
                    var row = 2;
                    var column = 1;
                    var dataCol = 0;
                    bool thirdRowIsEffectiveDate = dataTable.Columns[2].Caption == "Effective Date";

                    //Populate the body of the report
                    foreach (DataRow rowData in dataTable.Rows)
                    {
                        dataCol = 0;
                        column = 1;

                        if (firstHeaderIsYearOnly) // Effective Date
                            worksheet.Range[row, column++].Number =
                                ConvertToDouble(rowData[dataColumns[dataCol++]].ToString());
                        else
                            worksheet.Range[row, column++].Text = rowData[dataColumns[dataCol++]].ToString();

                        worksheet.Range[row, column++].Text =
                            rowData[dataColumns[dataCol++]].ToString(); // Provider Number

                        if (thirdRowIsEffectiveDate)
                            worksheet.Range[row, column++].Text = rowData[dataColumns[dataCol++]].ToString();
                        else
                            worksheet.Range[row, column++].Number =
                                ConvertToDouble(rowData[dataColumns[dataCol++]].ToString());
                        worksheet.Range[row, column++].Number =
                            ConvertToDouble(rowData[dataColumns[dataCol++]].ToString());
                        worksheet.Range[row, column++].Text = rowData[dataColumns[dataCol++]].ToString();

                        row++;
                    }

                    //Reset columns index to populate headers and styling
                    column = 1;
                    dataCol = 0;
                    row = 1;
                    //Iterate through first row setting header names and styles for entire column
                    foreach (DataColumn col in dataColumns)
                    {
                        string header = col.Caption;
                        worksheet.Range[row, column++].Text = header;
                        switch (header)
                        {
                            case "SFY":
                            case "CYE":
                                worksheet.Columns[dataCol].NumberFormat = "0000";
                                break;
                            case "Provider Number":
                                worksheet.Columns[dataCol].NumberFormat = "0000000";
                                worksheet.Columns[dataCol].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                                break;
                            case "Case Mix Value":
                            case "Total Facility Case Mix Score":
                            case "Medicaid Excluding PA Case Mix Value":
                                worksheet.Columns[dataCol].NumberFormat = "0.0000";
                                break;
                            case "Comments":
                                worksheet.Columns[dataCol].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                                break;
                        }

                        dataCol++;
                    }

                    worksheet.UsedRange.AutofitColumns();
                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.PageSetup.FitToPagesWide = 1;
                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;


                    //Saving the workbook as stream
                    FileStream file = new FileStream(fullPath, FileMode.Create, FileAccess.ReadWrite);
                    workbook.SaveAs(file);
                    file.Dispose();
                }

                return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
        }

