        #region DatabaseLookupGroup - Import methods

        [HttpPost]
        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult CheckGroupYear(AnnualRateSettingEnum annualRateSettingEnum, string lookupGroupDate)
        {
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;

            try
            {
                var alertMsg = "";
                DateTime checkDate;
                if (!DateTime.TryParse(lookupGroupDate, out checkDate))
                    throw new Exception($"Invalid date value {lookupGroupDate}");

                var addRED = DatabaseLookupGroupBL.GetAllDatabaseLookupGroupYears(annualRateSettingEnum.ToString())
                    .Where(x => x.LookUpDate == checkDate).FirstOrDefault();

                if (addRED != null)
                {
                    switch (annualRateSettingEnum)
                    {
                        case AnnualRateSettingEnum.AnnualCaseMixScores:
                        case AnnualRateSettingEnum.QualityPoints:
                        case AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY:
                            alertMsg =
                                $"Record for {addRED.LookUpDate.Year} already exists, should current data be overwritten?";
                            break;
                        case AnnualRateSettingEnum.CHOWQualityPaymentOverride:
                        case AnnualRateSettingEnum.ProvidersWithTaxOverride:
                        case AnnualRateSettingEnum.ProvidersWithLowOccupancyOverride:
                            alertMsg =
                                $"Record for {addRED.LookUpDate.Year + 1} already exists, should current data be overwritten?";
                            break;
                        default:
                            alertMsg =
                                $"Record for {lookupGroupDate} already exists, should current data be overwritten?";
                            break;
                    }

                    return Json(new { Success = true, fyeValue = lookupGroupDate, AlertMessage = alertMsg });
                }

                switch (annualRateSettingEnum)
                {
                    case AnnualRateSettingEnum.AnnualCaseMixScores:
                    case AnnualRateSettingEnum.QualityPoints:
                        alertMsg =
                            $"Record for {lookupGroupDate.Last(4)} doesn't exist! A new FYE year will be created";
                        break;
                    case AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY:
                        alertMsg =
                            $"Record for {lookupGroupDate.Last(4)} doesn't exist! A new SFY year will be created";
                        break;
                    case AnnualRateSettingEnum.CHOWQualityPaymentOverride:
                    case AnnualRateSettingEnum.ProvidersWithTaxOverride:
                    case AnnualRateSettingEnum.ProvidersWithLowOccupancyOverride:
                    case AnnualRateSettingEnum.OccupancyPercentageLOARate:
                        alertMsg =
                            $"Record for {int.Parse(lookupGroupDate.Last(4)) + 1} doesn't exist! A new SFY year will be created";
                        break;
                    default:
                        alertMsg = $"Record for {lookupGroupDate} doesn't exist! A new Date Group will be created";
                        break;
                }

                return Json(new { Success = false, fyeValue = lookupGroupDate, AlertMessage = alertMsg });
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    Message =
                        $"Error occurred importing the file. Unable to correctly parse one or more date/year values {lookupGroupDate}"
                });
            }
        }

