                    case AnnualRateSettingEnum.QualityPoints:
                        JSONString = JsonConvert.SerializeObject(spreadQualityPointsResult);
                        break;

                    case AnnualRateSettingEnum.DirectCareRateFreeze:
                        JSONString = JsonConvert.SerializeObject(spreadSheetResultDirectCareRateFreeze);
                        break;

                    case AnnualRateSettingEnum.AnnualCaseMixScores:
                        JSONString = JsonConvert.SerializeObject(spreadSheetAnnualCaseMixScoresResult);
                        break;
                    case AnnualRateSettingEnum.QuarterlyCaseMixScores:
                    case AnnualRateSettingEnum.SemiAnnualCaseMixScores:
                        JSONString = JsonConvert.SerializeObject(spreadSheetCaseMixScoresResult);
                        break;
                    case AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM:
                        JSONString = JsonConvert.SerializeObject(pdpmCaseMixResult);
                        break;
                    case AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY:
                        JSONString = JsonConvert.SerializeObject(spreadCaseMixScoresSFYResultViewModel);
                        break;
                    case AnnualRateSettingEnum.CHOWQualityPaymentOverride:
                        JSONString = JsonConvert.SerializeObject(spreadSheetResultQualityPaymentOverride);
                        break;
                }

                result.GridColumns = cols;
                result.GroupDataTable = JSONString;

                if (!inValid)
                {
                    int databaseLookupGroupYearId = DatabaseLookupGroupBL.AddLookupGroupYear(checkDate, valueType,
                        myUser.FirstName + " " + myUser.LastName);
                    List<int> groupId = DatabaseLookupGroupBL.GetDatabaseLookupGroup(valueType);
                    int groupIndex = 0;

                    foreach (var importData in importGroupData)
                    {
                        if (groupIndex == groupId.Count)
                        {
                            // Reset the index of GroupId's
                            groupIndex = 0;
                        }

                        DatabaseLookupGroupData groupData = new DatabaseLookupGroupData
                        {
                            Value = importData.Value,
                            DatabaseLookupGroupYearId = databaseLookupGroupYearId,
                            DatabaseLookupGroupId = groupId[groupIndex],
                            ValueType = valueType,
                            VariableName = importData.VariableName,
                            CreatedOn = DateTime.Now,
                            CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                            LastUpdatedOn = DateTime.Now,
                            LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}"
                        };
                        list.Add(groupData);
                        groupIndex++;
                    }

                    DatabaseLookupGroupBL.SaveDatabaseLookupGroup(list);
                }

                return Json(new { Success = true, Message = @"Import completed successfully.", Data = result });
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(new
                {
                    Success = false,
                    Message =
                        $"Error occurred importing the file. Invalid data or format for date/year {lookupGroupDate}"
                });
            }
            finally
            {
                if (clearSession)
                {
                    Session[SESSION_KEYS_RS.LOOKUP_GROUP_VIEWMODEL] = null;
                    Session[SESSION_KEYS_RS.LOOKUP_GROUP_RESULT] = null;
                }
            }
        }

        private DataTable ToDataTable<T>(List<T> items, List<Column> lstColumns)
        {
            DataTable dataTable = new DataTable(typeof(T).Name);
            //Get all the properties
            PropertyInfo[] Props = typeof(T).GetProperties(BindingFlags.Public | BindingFlags.Instance);
            foreach (Column columns in lstColumns)
            {
                //Setting column names
                dataTable.Columns.Add(columns.HeaderText);
            }

            foreach (T item in items)
            {
                var values = new object[Props.Length];
                for (int i = 0; i < Props.Length; i++)
                {
                    //inserting property values to datatable rows
                    values[i] = Props[i].GetValue(item, null);
                }

                dataTable.Rows.Add(values);
            }

            return dataTable;
        }

