        public ActionResult CalculateRates(List<RatePackageViewModel> providerData)
        {
            List<IGrouping<string, RatePackageViewModel>> redDateGroup = null;
            try
            {
                if (!RateSettingPermissionBL.AnnualRateSettingEdit())
                {
                    if (providerData.Any(x => !RateSettingProviderRatesPermissionBL.Calculate(x.RateType)))
                        throw new Exception("Invalid Request");
                }

                if (providerData == null)
                    return Json(new { Success = false }, JsonRequestBehavior.AllowGet);

                //Get distinct RED dates
                redDateGroup = providerData
                    .GroupBy(x => x.RateEffectiveDate)
                    .ToList();

                foreach (IGrouping<string, RatePackageViewModel> group in redDateGroup)
                {
                    if (!DateTime.TryParse(group.Key, out DateTime redDate))
                    {
                        throw new Exception($"Invalid Rate Effective Date [{group.Key}]");
                    }

                    List<ProviderRateResponseViewModel> responses = CalculateRates(redDate, group.ToList());
                }

                ARUMHandler.ClearCache();
                return Json(new { Success = true }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                ARUMHandler.ClearCache();
                return Json(new
                {
                    Success = false,
                    Message = e.Message
                }, JsonRequestBehavior.AllowGet);
            }
            finally
            {
                if (redDateGroup != null) redDateGroup.Clear();
            }
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult CalculateAll(string red)
        {
            try
            {
                //Now run the rates
                if (!DateTime.TryParse(red, out DateTime redDate))
                {
                    throw new Exception($"Invalid Rate Effective Date [{red}]");
                }

                List<ProviderRateResponseViewModel> responses = CalculateRates(redDate);

                return Json(new
                {
                    Success = true,
                    data = responses
                }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                ARUMHandler.ClearCache();
                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
        }

        private List<ProviderRateResponseViewModel> CalculateRates(DateTime redDate,
            List<RatePackageViewModel> providerRates = null)
        {
            ARUMHandler.ClearCache();
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;

            List<RateSettingPackage> ratePackages = null;
            List<RateSettingPackage> ratePackageSource = null;
            List<ProviderQualityCalculation> providerQualityCalculations = null;
            List<RateSettingPackage.ProviderPackage> providers = null;

            try
            {
                ProjectSpecificDbContext db = RateBL.GetContextInstance();

                DateTime cutoffDate = DatabaseLookupGroupBL.GetDatabaseLookupCostReportCutoff(db, redDate);

                //TODO: Refactor this method to take these providers as an argument since CalculateRates() is invoked inside a loop
                //  this could significantly decrease load times
                providers = GetActiveProviders();

                List<ProviderList> providerLists = GetAllTypeActiveProviders(providers, null);

                // We need to get all the possible rate packages for this RED to do any possible
                // pre-processing operations (like disallowances, etc.).
                // Note that this will allow getting partial cost report years as long as they are latest cleared 4.1 or 4.6
                ratePackageSource = RateBL.GetBaseYearData(db, RateBL.GetCostReportYearFromRED(redDate), BaseYearTypeEnum.Tax);

                // Get a list to accumulate the selected rate packages
                if (providerRates != null && providerRates.Any())
                {
                    // Get the rate package ids from the source that were selected.
                    foreach (RatePackageViewModel rp in providerRates)
                    {
                        if (!int.TryParse(ClientMapping.GetInternalIdFromClientId(rp.RatePackageId, "ratepackage"),
                                out int i))
                        {
                            throw new RatePackageNotFoundException("Unable to find specified rate ratePackage.");
                        }

                        // set the rate package Id to the internal rate package Id instead of client Id
                        rp.RatePackageId = i.ToString();
                    }
                }

                if (providerRates != null && providerRates.Any())
                {
                    // Get the rate packages for the rates being run.
                    ratePackages = RateBL.GetRateSettingData(db, redDate, providerRates.Select(x => int.Parse(x.RatePackageId)).ToList());

                }
                else
                {
                    // If no rate packacges were specified, then we are calculating ALL rate packages.
                    ratePackages = RateBL.GetRateSettingData(db, redDate, RetrieveSession.Classification.GetSimplifiedType());
                }

                // For each of the rate packages being calculated, replace the disallowance rate package with the one 
                // being calculated
                foreach (RateSettingPackage package in ratePackages)
                {
                    // Get the current rate package from the disallowance list
                    RateSettingPackage rp = ratePackageSource.FirstOrDefault(x => x.Provider.ProviderId == package.Provider.ProviderId);
                    // Remove the provider rate package, if it exists, and replace with the one being calculated.
                    if (rp != null) ratePackageSource.Remove(rp);
                    ratePackageSource.Add(package);
                }

                // Populate the effective dates for all disallowance rate packages pulled.
                foreach (RateSettingPackage package in ratePackageSource)
                {
                    // Copy the effective dates from the provider objects to the rate package objects.
                    // If none were found, throw an error.
                    package.Provider.EffectiveDates = providers
                        .FirstOrDefault(x => x.ProviderId == package.Provider.ProviderId)
                        ?.EffectiveDates ?? throw new GlobalApplicationSettingsException(
                            $"Missing ARUM Effective Date information for {package.Provider.ProviderNumber}, {package.Provider.ProviderName}");
                }

                // Get the quality calcualtion information for these rates.
                providerQualityCalculations = DatabaseLookupGroupBL.GetProviderQualityCalculations(db, redDate);
                // If there were no quality calculations found, reset the list to prevent errors.
                if (providerQualityCalculations == null)
                    providerQualityCalculations = new List<ProviderQualityCalculation>();

                //Now run the rates
                List<ProviderRateResponseViewModel> list = RateSettingSubmission(cutoffDate.Year - 1, redDate, providers, providerLists, ratePackageSource,
                    providerQualityCalculations, $"{myUser.FirstName} {myUser.LastName}", providerRates);

                #region When the 4.9X cost report is created
                foreach (RateSettingPackage package in ratePackages)
                {
                    if (package.RateTypeId == (int)RateTypeEnumExtended.AUDIT_INITIAL
                              || package.RateTypeId == (int)RateTypeEnumExtended.AUDIT_REVISED
                              || package.RateTypeId == (int)RateTypeEnumExtended.AUDIT_FINAL)
                    {
                        string eventName = string.Empty;
                        switch (package.RateTypeId)
                        {
                            case (int)RateTypeEnumExtended.AUDIT_INITIAL:
                                eventName = "Initial Audit Rate Run";
                                break;
                            case (int)RateTypeEnumExtended.AUDIT_REVISED:
                                eventName = "Revised Audit Rate Run";
                                break;
                            case (int)RateTypeEnumExtended.AUDIT_FINAL:
                                eventName = "Final Audit Rate Run";
                                break;
                        }

                        if (!string.IsNullOrEmpty(eventName))
                        {
                            RateBL.SaveCostReportStatlog(new ProviderCostReportStatlog
                            {
                                CRID = package.ProviderCostReport.ProviderCostReportId,
                                EventDate = DateTime.Now,
                                Stamp = DateTime.Now,
                                EventName = eventName,
                                UserId = myUser.Email,
                                CreatedOn = DateTime.UtcNow,
                                CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                                LastUpdatedOn = DateTime.UtcNow,
                                LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}",
                            });
                        }
                    }
                }

                #endregion

                return list;
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                throw;
            }
            finally
            {
                if (ratePackages != null)
                {
                    // This should not be necessary, as these are just copies of what is in ratePackageSource
                    ratePackages.ForEach(x => x.Dispose());
                    ratePackages.Clear();
                }

                providerQualityCalculations?.Clear();
            }
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult FinalizeAll(List<RatePackageViewModel> providerData)
        {
            try
            {
                // Set all Locked Date
                foreach (RatePackageViewModel provider in providerData)
                {
                    if (provider.Rate != null && provider.Issuance == null)
                    {
                        if (int.TryParse(ClientMapping.GetInternalIdFromClientId(provider.RatePackageId, "ratepackage"),
                                out int ratePackId))
                        {
                            RedDateBL.Finalize(ratePackId);
                        }
                    }
                }

                providerData.Clear();
                return Json(new { Success = true });
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message });
            }
            finally
            {
                if (providerData != null)
                {
                    providerData.ForEach(x => x.Dispose());
                    providerData.Clear();
                }
            }
        }

        // Through Grid Selection
        public ActionResult Finalize(string ratePackageId, string providerCostReportId, string rateType)
        {
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
            try
            {
                if (!string.IsNullOrWhiteSpace(ratePackageId))
                {
                    if (!int.TryParse(ClientMapping.GetInternalIdFromClientId(ratePackageId, "ratepackage"),
                            out int ratePackId))
                        throw new Exception("Unable to find specified rate package.");

                    int rateTypeId = 0;
                    if (!int.TryParse(ClientMapping.GetInternalIdFromClientId(rateType, "ratetype"),
                        out rateTypeId))
                        throw new Exception("Unable to find specified rate type.");

                    int crid = 0;
                    if (!int.TryParse(ClientMapping.GetInternalIdFromClientId(providerCostReportId, "costreport"),
                        out crid))
                        throw new Exception("Unable to find provider cost report.");

                    if (!RateSettingProviderRatesPermissionBL.Select(ratePackId))
                        throw new Exception("Invalid Request");

                    if (rateTypeId == (int)RateTypeEnumExtended.AUDIT_INITIAL
                        || rateTypeId == (int)RateTypeEnumExtended.AUDIT_REVISED
                        || rateTypeId == (int)RateTypeEnumExtended.AUDIT_FINAL)
                    {
                        RedDateBL.Finalize(ratePackId, $"{myUser.FirstName} {myUser.LastName}");

                        string eventName = string.Empty;
                        switch (rateTypeId)
                        {
                            case (int)RateTypeEnumExtended.AUDIT_INITIAL:
                                eventName = "Initial Audit Rate Finalized";
                                break;
                            case (int)RateTypeEnumExtended.AUDIT_REVISED:
                                eventName = "Revised Audit Rate Finalized";
                                break;
                            case (int)RateTypeEnumExtended.AUDIT_FINAL:
                                eventName = "Final Audit Rate Finalized";
                                break;
                        }

                        if (!string.IsNullOrEmpty(eventName))
                        {
                            RateBL.SaveCostReportStatlog(new ProviderCostReportStatlog
                            {
                                CRID = crid,
                                EventDate = DateTime.Now,
                                Stamp = DateTime.Now,
                                EventName = eventName,
                                UserId = myUser.Email,
                                CreatedOn = DateTime.UtcNow,
                                CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                                LastUpdatedOn = DateTime.UtcNow,
                                LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}",
                            });
                        }
                    }
                    else
                    {
                        RedDateBL.Finalize(ratePackId);
                    }
                }

                return Json(new { Success = true });
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message });
            }
        }

        // Through Grid Selection
        public ActionResult UnFinalize(string ratePackageId, string providerCostReportId, string rateType)
        {
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
            try
            {
                if (!string.IsNullOrWhiteSpace(ratePackageId))
                {
                    if (int.TryParse(ClientMapping.GetInternalIdFromClientId(ratePackageId, "ratepackage"),
                            out int ratePackId))
                    {
                        if (!RateSettingPermissionBL.AnnualRateSettingEdit())
                        {
                            if (!RateSettingProviderRatesPermissionBL.Select(ratePackId))
                                throw new Exception("Invalid Request");
                        }

                        int rateTypeId = 0;
                        if (!int.TryParse(ClientMapping.GetInternalIdFromClientId(rateType, "ratetype"),
                            out rateTypeId))
                            throw new Exception("Unable to find specified rate type.");

                        int crid = 0;
                        if (!int.TryParse(ClientMapping.GetInternalIdFromClientId(providerCostReportId, "costreport"),
                            out crid))
                            throw new Exception("Unable to find provider cost report.");

                        RedDateBL.UnFinalize(ratePackId);

                        #region When the 4.9X Audit Rate UnFinalized

                        if (rateTypeId == (int)RateTypeEnumExtended.AUDIT_INITIAL
                                      || rateTypeId == (int)RateTypeEnumExtended.AUDIT_REVISED
                                      || rateTypeId == (int)RateTypeEnumExtended.AUDIT_FINAL)
                        {
                            string eventName = string.Empty;
                            switch (rateTypeId)
                            {
                                case (int)RateTypeEnumExtended.AUDIT_INITIAL:
                                    eventName = "Initial Audit Rate UnFinalized.";
                                    break;
                                case (int)RateTypeEnumExtended.AUDIT_REVISED:
                                    eventName = " Revised Audit Rate UnFinalized.";
                                    break;
                                case (int)RateTypeEnumExtended.AUDIT_FINAL:
                                    eventName = "Final Audit Rate UnFinalized.";
                                    break;
                            }

                            if (!string.IsNullOrEmpty(eventName))
                            {
                                RateBL.SaveCostReportStatlog(new ProviderCostReportStatlog
                                {
                                    CRID = crid,
                                    EventDate = DateTime.Now,
                                    Stamp = DateTime.Now,
                                    EventName = eventName,
                                    UserId = myUser.Email,
                                    CreatedOn = DateTime.UtcNow,
                                    CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                                    LastUpdatedOn = DateTime.UtcNow,
                                    LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}",
                                });
                            }
                        }
                        #endregion
                    }
                }

                return Json(new { Success = true });
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message });
            }
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult UnFinalizeAll(List<RatePackageViewModel> providerData)
        {
            try
            {
                // Update all Locked Date to Null
                foreach (RatePackageViewModel provider in providerData)
                {
                    if (provider.Rate != null && provider.Issuance != null)
                    {
                        if (int.TryParse(ClientMapping.GetInternalIdFromClientId(provider.RatePackageId, "ratepackage"),
                                out int ratePackId))
                        {
                            RedDateBL.UnFinalize(ratePackId);
                        }
                    }
                }

                providerData.Clear();
                return Json(new { Success = true });
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message });
            }
            finally
            {
                if (providerData != null)
                {
                    providerData.ForEach(x => x.Dispose());
                    providerData.Clear();
                }
            }
        }

