                    default:
                        throw new Exception("Unknown provider type for exporting data.");
                }

                //Save the file to the path of the current user's temporary folder
                fullPath = Path.Combine(Path.GetTempPath(), fileName);

                //Instantiate the spreadsheet creation engine
                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    //Instantiate the excel application object.
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;

                    //The workbook is created
                    IWorkbook workbook = application.Workbooks.Create(1);

                    //The first worksheet object in the worksheets collection is accessed
                    IWorksheet worksheet = workbook.Worksheets[0];

                    //Import data from the data table with column header, at first row and first column, 
                    //and by its column type.
                    DataTable dataTable = RateBL.PrintRatesExcel(redDate, SimplifiedType);

                    #region Adding NPI to Records

                    if (OHFISession.IsICF)
                    {
                        var arum_Providers = GetAllProviderList(RetrieveSession.Classification.ARUMToken, false, true,
                            false,
                            true, false, false, false, true, false, "RateController.PrintRates").lstProviders;

                        int npiColIndex = dataTable.Columns.IndexOf("NPI Number");
                        int provIdColIndex = dataTable.Columns.IndexOf("ProviderId");
                        dataTable.Columns[npiColIndex].ReadOnly =
                            false; //Required in order to add NPI to the new column
                        dataTable.Columns[npiColIndex].MaxLength = 10;

                        foreach (DataRow row in dataTable.Rows)
                        {
                            Provider provider =
                                arum_Providers.FirstOrDefault(x => x.ProviderID == row.Field<int>(provIdColIndex));
                            row[npiColIndex] = provider != null
                                ? provider.Identifiers.FirstOrDefault(x => x.Type == "NPI")?.Value
                                : "";
                        }

                        dataTable.Columns
                            .Remove(
                                "ProviderId"); //ProviderId column only necessary for getting NPI, it can be removed before being copied to Excel
                    }

                    #endregion

                    //if (dataTable == null || dataTable.Rows.Count == 0)
                    //{
                    //    return Json(new { Success = false, Message = "At least one provider rate is not calculated. Cannot print rates that are not calculated." });
                    //}                    
                    //dataTable.DefaultView.ToTable(false, fieldsToPrint.Keys.ToArray());
                    //foreach (var column in fieldsToPrint)
                    //{
                    //    if (dataTable.Columns.Contains(column.Key))
                    //    {
                    //        dataTable.Columns[column.Key].ColumnName = column.Value;
                    //    }
                    //}

                    worksheet.ImportDataTable(dataTable, true, 1, 1, true);

                    //Saving the workbook as stream
                    FileStream file = new FileStream(fullPath, FileMode.Create, FileAccess.ReadWrite);
                    //If new columns are added before the Cost Report Begin Date column, the two columns below will need adjusted
                    worksheet.Columns[5].NumberFormat = @"mm\/dd\/yyyy";
                    worksheet.Columns[6].NumberFormat = @"mm\/dd\/yyyy";
                    worksheet.UsedRange.AutofitColumns();
                    workbook.SaveAs(file);
                    file.Dispose();
                }

                fileList.Add(fileName);

                string zipPrintRatesFileName = $"{redDate.ToString("yyyy-MM-dd")} Provider List.zip"; //Zip file name
                var zipFileName = ZipFiles(fileList, zipPrintRatesFileName);
                DeleteFiles(fileList);

                ARUMHandler.ClearCache();
                return Json(new { Success = true, fileName = HttpUtility.UrlEncode(zipFileName) });
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                ARUMHandler.ClearCache();
                return Json(new { Success = false, Message = $"{e.Message}\n{fullPath}" });
            }
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
