        private List<DatabaseLookupValueViewModel> LoadRateParameters(DateTime redDate)
        {
            List<DatabaseLookupValueViewModel> model = new List<DatabaseLookupValueViewModel>();
            List<DatabaseLookupValue> rateParams = RedDateBL.GetRateParamtersByRED(redDate);

            foreach (var dbvalue in rateParams)
            {
                model.Add(new DatabaseLookupValueViewModel
                {
                    DatabaseLookupVariableId =
                        ClientMapping.MapInternalIdToClientId(dbvalue.DatabaseLookupVariableId.ToString(), "dblookup"),
                    VersionVGS = dbvalue.VersionVGS,
                    Key = dbvalue.Key,
                    Value = dbvalue.Value,
                    DisplayName = dbvalue.DisplayName,
                    ValueType = dbvalue.ValueType,
                    StartDate = dbvalue.StartDate,
                    EndDate = dbvalue.EndDate,
                    RangeMaximum = dbvalue.RangeMaximum,
                    RangeMinimum = dbvalue.RangeMinimum,
                    Sequence = dbvalue.Sequence
                });
            }

            return model;
        }

        private List<DatabaseLookupValueViewModel> LoadRateParameters(ProjectSpecificDbContext db, DateTime redDate)
        {
            List<DatabaseLookupValueViewModel> model = new List<DatabaseLookupValueViewModel>();
            List<DatabaseLookupValue> rateParams = RedDateBL.GetRateParamtersByRED(db, redDate);

            foreach (var dbvalue in rateParams)
            {
                model.Add(new DatabaseLookupValueViewModel
                {
                    DatabaseLookupVariableId =
                        ClientMapping.MapInternalIdToClientId(dbvalue.DatabaseLookupVariableId.ToString(), "dblookup"),
                    VersionVGS = dbvalue.VersionVGS,
                    Key = dbvalue.Key,
                    Value = dbvalue.Value,
                    DisplayName = dbvalue.DisplayName,
                    ValueType = dbvalue.ValueType,
                    StartDate = dbvalue.StartDate,
                    EndDate = dbvalue.EndDate,
                    RangeMaximum = dbvalue.RangeMaximum,
                    RangeMinimum = dbvalue.RangeMinimum,
                    Sequence = dbvalue.Sequence
                });
            }

            return model;
        }

        [HttpPost]
        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult UpdateRateParameters(DatabaseLookupValueViewModel value, string redDate)
        {
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;

            if (value == null)
            {
                return Json(new { Success = false, Message = "None or invalid value selected.", rpt = "" },
                    JsonRequestBehavior.AllowGet);
            }

            DateTime startDate = DateTime.Parse(redDate);
            List<DatabaseLookupValue> rateParams = null;

            try
            {
                using (var db = new ProjectSpecificDbContext(Functions.DatabaseConnection))
                {
                    int recordId = 0;
                    if (int.TryParse(
                            ClientMapping.GetInternalIdFromClientId(value.DatabaseLookupVariableId, "dblookup"),
                            out int i))
                    {
                        recordId = i;
                    }

                    DatabaseLookupValue rateParameter = new DatabaseLookupValue
                    {
                        StartDate = startDate,
                        ValueType = nameof(AnnualRateSettingEnum.AnnualRateSettingDetails),
                        DisplayName = value.DisplayName,
                        Key = value.Key,
                        Value = value.Value
                    };
                    if (recordId > 0)
                    {
                        rateParameter.DatabaseLookupVariableId = recordId;
                    }

                    RedDateBL.UpdateRateParameter(db, rateParameter, $"{myUser.FirstName} {myUser.LastName}");

                    // Convert to view model
                    List<DatabaseLookupValueViewModel> model = LoadRateParameters(db, startDate);

                    return Json(new
                    {
                        Success = true,
                        Message = "Rate Parameters Added.",
                        ViewModel = model
                    },
                        JsonRequestBehavior.AllowGet);
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message },
                    JsonRequestBehavior.AllowGet);
            }
            finally
            {
                if (rateParams != null) rateParams.Clear();
            }
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult RemoveRateParameters(DatabaseLookupValueViewModel value, string date)
        {
            List<DatabaseLookupValue> parameters = null;

            try
            {
                int dbLookupId = 0;
                if (int.TryParse(ClientMapping.GetInternalIdFromClientId(value.DatabaseLookupVariableId, "dblookup"),
                        out int i))
                {
                    dbLookupId = i;
                }

                if (dbLookupId == 0)
                {
                    // remove all with the specified starting date.
                    RedDateBL.RemoveRateParameters(DateTime.Parse(date));
                }
                else
                {
                    // remove the specified single item.
                    RedDateBL.RemoveRateParameter(dbLookupId);
                }

                parameters = RedDateBL.GetRateParamtersByRED(DateTime.Parse(date));
                List<DatabaseLookupValueViewModel> rateParams = new List<DatabaseLookupValueViewModel>();
                foreach (DatabaseLookupValue item in parameters)
                {
                    rateParams.Add(new DatabaseLookupValueViewModel
                    {
                        DatabaseLookupVariableId =
                            ClientMapping.MapInternalIdToClientId(item.DatabaseLookupVariableId.ToString(), "dblookup"),
                        VersionVGS = item.VersionVGS,
                        ValueType = item.ValueType,
                        Key = item.Key,
                        Value = item.Value,
                        DisplayName = item.DisplayName,
                        StartDate = item.StartDate,
                        EndDate = item.EndDate,
                        RangeMinimum = item.RangeMinimum,
                        RangeMaximum = item.RangeMaximum,
                        Sequence = item.Sequence
                    });
                }

                return Json(new { Success = true, ViewModel = rateParams },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message },
                    JsonRequestBehavior.AllowGet);
            }
            finally
            {
                if (parameters != null) parameters.Clear();
            }
        }

