        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public JsonResult AdminCeilingExportExcel(string cyeYear, string rateStartDate,
            AnnualRateSettingEnum annualRateSettingEnum)
        {
            switch (SimplifiedType)
            {
                case "ICF":
                    break;
                default:
                    throw new Exception($" Invalid Project: {SimplifiedType}");
            }

            DateTime currDate = DateTime.Now;
            //List<DatabaseLookupGroupData> dbLookupGroupData = null;
            List<Provider> providersViewModel = null;
            int cyeYr = ConvertToInteger(cyeYear);
            int redYear = cyeYr + 1;
            int sfyYear = cyeYr + 2;
            DateTime redDate = new DateTime(redYear, 7, 1);
            DateTime rateStartDt = ConvertToDateTime(rateStartDate);
            DateTime baseDt = new DateTime(cyeYr, 06, 01);

            try
            {
                string fullPath = "";
                var fileName =
                    $"{SimplifiedType}_Administrator_Ceiling_Calculation_Report_Run_{currDate:yyyyMMdd}.xlsx"
                        .ToSafeFileName();

                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    //Save the file to the path of the current user's temporary folder
                    fullPath = Path.Combine(Path.GetTempPath(), fileName);
                    //Instantiate the excel application object.
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;

                    //The workbooks are created
                    IWorkbook workbook = application.Workbooks.Create(4);
                    workbook.Worksheets[0].Name = "Bed Range 0-49";
                    workbook.Worksheets[1].Name = "Bed Range 50-99";
                    workbook.Worksheets[2].Name = "Bed Range 100-149";
                    workbook.Worksheets[3].Name = "Bed Range 150-Plus";

                    var worksheet = workbook.Worksheets;

                    var rateEffectiveDate = new DateTime(redYear, 7, 1);

                    CalculationSet calculationSet = RedDateBL.GetBaseYearCalculationSet(rateStartDt);

                    //Get CalculationResult table records
                    var calculatedData = RateBL.GetBaseYearCalculationResultData(cyeYr, rateEffectiveDate,
                        nameof(BaseYearTypeEnum.AdminCeiling), (int)calculationSet.Type);

                    var calculatedAdminCompLimits =
                        calculatedData.Where(x => x.Key.Contains("AdminCompLimits")).ToList();

                    int[] compLimit = new int[4];
                    DatabaseLookupViewModel dbLookupViewModel = GetLookUpData(annualRateSettingEnum, cyeYear);
                    foreach (var item in dbLookupViewModel.DatabaseLookupGridViewModelList)
                    {
                        switch (item.RangeMinimum)
                        {
                            case 0:
                                compLimit[0] = ConvertToInteger(item.Value);
                                break;
                            case 50:
                                compLimit[1] = ConvertToInteger(item.Value);
                                break;
                            case 100:
                                compLimit[2] = ConvertToInteger(item.Value);
                                break;
                            case 150:
                                compLimit[3] = ConvertToInteger(item.Value);
                                break;
                        }
                    }

                    var providerNumbers = calculatedAdminCompLimits.Select(x => x.ProviderNumber).Distinct()
                        .OrderBy(x => x).ToList();

                    Dictionary<string, string> npiProviderNumbers = GetNpiNumbers(providerNumbers);

                    if (!providerNumbers.Any())
                    {
                        throw new Exception(" No Providers were found for the report.");
                    }

                    var reportDataListAdminCompLimits = new List<ReportLineForAdminCeiling>();
                    ReportLineForAdminCeiling reportData;
                    foreach (var providerNumber in providerNumbers)
                    {
                        reportData = new ReportLineForAdminCeiling();
                        reportData.ProviderNumber = providerNumber;
                        reportData.NPINumber = npiProviderNumbers.TryGetValue(providerNumber, out var npi) ? npi : string.Empty;

                        var calculatedProvData = calculatedAdminCompLimits
                            .Where(x => x.ProviderNumber == providerNumber.ToString()).ToList();
                        foreach (var calcData in calculatedProvData)
                        {
                            var item = calcData.KeyName.Split('_');
                            switch (item[1])
                            {
                                case "DocumentNumber":
                                    reportData.DocumentNumber = ConvertToDouble(calcData.Value);
                                    break;
                                case "Beds":
                                    reportData.Beds = ConvertToInteger(calcData.Value);
                                    break;
                                case "TotalAllowableCompensation":
                                    reportData.TotalComp = ConvertToInteger(calcData.Value);
                                    break;
                                case "DaysInTimeSlice":
                                    reportData.TotalDays = ConvertToDouble(calcData.Value);
                                    break;
                                case "WeeklyHours":
                                    reportData.WeeklyHours = ConvertToDouble(calcData.Value);
                                    break;
                                case "AdjustedTotalHours":
                                    reportData.AdjustedWeeklyHours = ConvertToDouble(calcData.Value);
                                    break;
                                case "RawCalculatedAdministratorCompensation":
                                    reportData.Calc1 = ConvertToDouble(calcData.Value);
                                    break;
                                case "AnnualizedAdministratorCompensation":
                                    reportData.Calc2 = ConvertToDouble(calcData.Value);
                                    break;
                            }

                            if (reportData.Beds >= 0 && reportData.Beds <= 49)
                                reportData.Ceiling = compLimit[0];
                            else if (reportData.Beds >= 50 && reportData.Beds <= 99)
                                reportData.Ceiling = compLimit[1];
                            else if (reportData.Beds >= 100 && reportData.Beds <= 149)
                                reportData.Ceiling = compLimit[2];
                            else if (reportData.Beds >= 150)
                                reportData.Ceiling = compLimit[3];
                        }

                        reportDataListAdminCompLimits.Add(reportData);
                    }

                    var lineArray = reportDataListAdminCompLimits.ToArray();

                    PrintAdminCeilingWorksheetTitles(workbook, sfyYear);
                    PrintAdminCeilingWorksheet(workbook, lineArray);

                    var titleStyleName = CreateStyle(workbook, "TitleStyle", true, 11, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var headerStyleName = CreateStyle(workbook, "HeaderStyle", true, 11, true, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);
                    var bodyStyleName = CreateStyle(workbook, "BodyStyle", false, 8, false, "Times New Roman",
                        ExcelVAlign.VAlignCenter, ExcelHAlign.HAlignCenter);

                    for (var x = 0; x < 4; x++)
                    {
                        worksheet[x].UsedRange.AutofitRows();
                        worksheet[x].UsedRange.CellStyleName = bodyStyleName;

                        worksheet[x].Columns[1].NumberFormat = "0000000";
                        worksheet[x].Columns[5].NumberFormat = "##0";
                        worksheet[x].Columns[6].NumberFormat = "##0.00";
                        worksheet[x].Columns[8].NumberFormat = "###,##0.0000";
                        worksheet[x].Columns[9].NumberFormat = "###,###,##0.0000";
                        worksheet[x].Columns[10].NumberFormat = "###,###,##0.0000";
                        worksheet[x].Columns[11].NumberFormat = "###,###,##0";

                        worksheet[x].Columns[4].HorizontalAlignment = ExcelHAlign.HAlignCenter;
                        worksheet[x].Columns[5].HorizontalAlignment = ExcelHAlign.HAlignCenter;
                        worksheet[x].Columns[6].HorizontalAlignment = ExcelHAlign.HAlignCenter;
                        worksheet[x].Columns[8].HorizontalAlignment = ExcelHAlign.HAlignCenter;
                        worksheet[x].Columns[9].HorizontalAlignment = ExcelHAlign.HAlignCenter;
                        worksheet[x].Columns[10].HorizontalAlignment = ExcelHAlign.HAlignCenter;
                        worksheet[x].Columns[11].HorizontalAlignment = ExcelHAlign.HAlignCenter;

                        worksheet[x].PageSetup.Orientation = ExcelPageOrientation.Landscape;
                        worksheet[x].PageSetup.FitToPagesTall = 0;
                        worksheet[x].PageSetup.FitToPagesWide = 1;

                        worksheet[x].UsedRange.CellStyleName = bodyStyleName;
                        worksheet[x].Rows[0].CellStyleName = titleStyleName;
                        worksheet[x].Rows[1].CellStyleName = titleStyleName;
                        worksheet[x].Rows[2].CellStyleName = headerStyleName;

                        worksheet[x].UsedRange.AutofitRows();
                        worksheet[x].Rows[2].RowHeight = 59;

                        worksheet[x].Columns[1].NumberFormat = "0000000";
                        worksheet[x].Columns[4].NumberFormat = "###,##0";
                        worksheet[x].Columns[5].NumberFormat = "##0";
                        worksheet[x].Columns[6].NumberFormat = "##0.00";
                        worksheet[x].Columns[7].NumberFormat = "###,##0.00";
                        worksheet[x].Columns[8].NumberFormat = "###,##0.0000";
                        worksheet[x].Columns[9].NumberFormat = "###,##0.0000";
                        worksheet[x].Columns[10].NumberFormat = "###,###,##0.0000";
                        worksheet[x].Columns[11].NumberFormat = "###,##0";


                        worksheet[x].Columns[4].HorizontalAlignment = ExcelHAlign.HAlignRight;
                        worksheet[x].Columns[6].HorizontalAlignment = ExcelHAlign.HAlignRight;
                        worksheet[x].Columns[8].HorizontalAlignment = ExcelHAlign.HAlignRight;
                        worksheet[x].Columns[9].HorizontalAlignment = ExcelHAlign.HAlignRight;

                        worksheet[x].Rows[2].HorizontalAlignment = ExcelHAlign.HAlignCenter;


                        //Merge the Cells
                        worksheet[x].Range["A1:L1"].Merge();
                        worksheet[x].Range["A2:L2"].Merge();

                        if (worksheet[x].UsedRange.End.Row > 4)
                            worksheet[x].Range[4, 1].FreezePanes();

                        // This puts the borders around all cells in the spreadsheet
                        worksheet[x].UsedRange.Borders[ExcelBordersIndex.EdgeBottom].LineStyle = ExcelLineStyle.Thin;
                        worksheet[x].UsedRange.Borders[ExcelBordersIndex.EdgeLeft].LineStyle = ExcelLineStyle.Thin;
                        worksheet[x].UsedRange.Borders[ExcelBordersIndex.EdgeRight].LineStyle = ExcelLineStyle.Thin;
                        worksheet[x].UsedRange.Borders[ExcelBordersIndex.EdgeTop].LineStyle = ExcelLineStyle.Thin;

                        // Then remove the ones you don't want
                        //RemoveBorderForColumn(worksheet[x], 5, "right");
                        //RemoveBorderForColumn(worksheet[x], 6, "left");
                    }

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;
                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create, FileAccess.ReadWrite))
                    {
                        report.WriteTo(fileStream);
                    }
                }

                return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message });
            }
        }

        public void PrintAdminCeilingWorksheet(IWorkbook workbook, ReportLineForAdminCeiling[] dataValues)
        {
            double[] runningTotal = new double[4];

            int[] row = new int[] { 4, 4, 4, 4 };
            for (var x = 0; x < dataValues.Length; x++)
            {
                var item = dataValues[x];

                if (item.Beds > 0 && item.Beds <= 49)
                {
                    row[0] = PrintAdminCeilingLine(workbook.Worksheets[0], item, row[0]);
                    runningTotal[0] += item.Calc2;
                }
                else if (item.Beds > 50 && item.Beds <= 99)
                {
                    row[1] = PrintAdminCeilingLine(workbook.Worksheets[1], item, row[1]);
                    runningTotal[1] += item.Calc2;
                }
                else if (item.Beds >= 100 && item.Beds <= 149)
                {
                    row[2] = PrintAdminCeilingLine(workbook.Worksheets[2], item, row[2]);
                    runningTotal[2] += item.Calc2;
                }
                else if (item.Beds >= 150)
                {
                    row[3] = PrintAdminCeilingLine(workbook.Worksheets[3], item, row[3]);
                    runningTotal[3] += item.Calc2;
                }
            }

            if (runningTotal[0] > 0)
                workbook.Worksheets[0].Range[4, 11].Number = runningTotal[0]; // K
            if (runningTotal[1] > 0)
                workbook.Worksheets[1].Range[4, 11].Number = runningTotal[1];
            if (runningTotal[2] > 0)
                workbook.Worksheets[2].Range[4, 11].Number = runningTotal[2];
            if (runningTotal[3] > 0)
                workbook.Worksheets[3].Range[4, 11].Number = runningTotal[3];
        }

        public void PrintAdminCeilingWorksheetTitles(IWorkbook workbook, int sfyYear)
        {
            for (var x = 0; x < 4; x++)
            {
                workbook.Worksheets[x].Range[1, 1].Text = "Administrator Ceiling Calculation Report";
                switch (x)
                {
                    case 0:
                        workbook.Worksheets[x].Range[2, 1].Text =
                            $"SFY {sfyYear} Report Ceiling G (Ceiling Information for 0 - 49 beds)";
                        break;
                    case 1:
                        workbook.Worksheets[x].Range[2, 1].Text =
                            $"SFY {sfyYear} Report Ceiling G (Ceiling Information for 50 - 99 beds)";
                        break;
                    case 2:
                        workbook.Worksheets[x].Range[2, 1].Text =
                            $"SFY {sfyYear} Report Ceiling G (Ceiling Information for 100 - 149 beds)";
                        break;
                    case 3:
                        workbook.Worksheets[x].Range[2, 1].Text =
                            $"SFY {sfyYear} Report Ceiling G (Ceiling Information for 150-Plus beds)";
                        break;
                }

                PrintAdminCeilingHeaders(workbook.Worksheets[x], sfyYear);
            }
        }

        public void PrintAdminCeilingHeaders(IWorksheet worksheet, int sfyYear)
        {
            var row = 3;
            var column = 1;

            worksheet.Range[row, column].Text = "CT"; //a
            worksheet.SetColumnWidth(column, 5);

            column++;
            worksheet.Range[row, column].Text = "NPI Number"; //a1
            worksheet.SetColumnWidth(column, 12);

            column++;
            worksheet.Range[row, column].Text = "Provider"; //b
            worksheet.SetColumnWidth(column, 12);

            column++;
            worksheet.Range[row, column].Text = "Document"; //c
            worksheet.SetColumnWidth(column, 14);

            column++;
            worksheet.Range[row, column].Text = "Beds"; //d
            worksheet.SetColumnWidth(column, 7);

            column++;
            worksheet.Range[row, column].Text = "Total Comp      (a)"; // e
            worksheet.SetColumnWidth(column, 12);

            column++;
            worksheet.Range[row, column].Text = "Total Days    (b)"; // f
            worksheet.SetColumnWidth(column, 7);

            column++;
            worksheet.Range[row, column].Text = "Weekly Hours    (c)"; // g
            worksheet.SetColumnWidth(column, 8);

            column++;
            worksheet.Range[row, column].Text = "Adjusted Weekly Hours      (d)"; // h
            worksheet.SetColumnWidth(column, 10);

            column++;
            worksheet.Range[row, column].Text = "Calc1                   (a) x (d) / (c)       (e)"; // i
            worksheet.SetColumnWidth(column, 12);

            var endOfYear = new DateTime(sfyYear, 12, 31);
            var beginningOfYear = new DateTime(sfyYear, 1, 1);
            var daysInYear = (endOfYear - beginningOfYear).Days + 1;

            column++;
            worksheet.Range[row, column].Text = $"Calc2                    (e) x ({daysInYear}) / b"; // k
            worksheet.SetColumnWidth(column, 14);

            column++;
            worksheet.Range[row, column].Text = $"Total"; // l
            worksheet.SetColumnWidth(column, 15);

            column++;
            worksheet.Range[row, column].Text = $"Ceiling (Average)"; // m
            worksheet.SetColumnWidth(column, 11);
        }

        public int PrintAdminCeilingLine(IWorksheet worksheet, ReportLineForAdminCeiling item, int row)
        {
            var column = 1;

            worksheet.Range[row, column].Number = row - 3;

            column++;
            worksheet.Range[row, column].Text = item.NPINumber; // a1

            column++;
            worksheet.Range[row, column].Text = item.ProviderNumber; // a

            column++;
            worksheet.Range[row, column].Number = item.DocumentNumber; // b

            column++;
            worksheet.Range[row, column].Number = item.Beds; // c

            column++;
            worksheet.Range[row, column].Number = item.TotalComp; // d

            column++;
            worksheet.Range[row, column].Number = item.TotalDays; // e

            column++;
            worksheet.Range[row, column].Number = item.WeeklyHours; // h

            column++;
            worksheet.Range[row, column].Number = item.AdjustedWeeklyHours; // g

            column++;
            worksheet.Range[row, column].Number = item.Calc1; // h

            column++;
            worksheet.Range[row, column].Number = item.Calc2; // i

            if (row == 4)
            {
                column = 12;
                worksheet.Range[row, column].Number = item.Ceiling; // L
            }

            row++;
            return row;
        }

        public class ReportLineForAdminCeiling
        {
            public string ProviderNumber { get; set; }
            public string NPINumber { get; set; }
            public double DocumentNumber { get; set; }
            public int Beds { get; set; }
            public int TotalComp { get; set; }
            public double TotalDays { get; set; }
            public double WeeklyHours { get; set; }
            public double AdjustedWeeklyHours { get; set; }
            public double Calc1 { get; set; }
            public double Calc2 { get; set; }
            public int Ceiling { get; set; }
        }

