        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public JsonResult ExportCorpOfficeSalaryCeilingTables(string fiscalYear,
            AnnualRateSettingEnum annualRateSettingEnum)
        {
            try
            {
                DateTime dateTime = RateSettingLookupDateType.GetLookupDateByType(annualRateSettingEnum, fiscalYear);

                // Default column name for group data is FYE (basically calendar year end)
                string dateColumnName = RateSettingLookupDateType.GetLookupDateTypeString(annualRateSettingEnum);
                string dateValue = annualRateSettingEnum.GetLookupDateValue(dateTime);

                string fullPath = "";
                string dateType = RateSettingLookupDateType.GetLookupDateTypeString(annualRateSettingEnum);
                string fileName = $"{dateType}{dateTime.Year}_{annualRateSettingEnum.ToString()}Report.xlsx";
                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    //Save the file to the path of the current user's temporary folder
                    fullPath = Path.Combine(Path.GetTempPath(), fileName);
                    //Instantiate the excel application object.
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;

                    //The workbook is created
                    IWorkbook workbook = application.Workbooks.Create(1);

                    //The first worksheet object in the worksheets collection is accessed
                    IWorksheet worksheet = workbook.Worksheets[0];

                    // Import Data
                    DataTable dataTable = DatabaseLookupGroupBL.GetDatabaseLookupGroupExport(dateTime,
                        annualRateSettingEnum.ToString(), dateColumnName, dateValue);

                    var row = 1;
                    var column = 1;
                    var dataCol = 0;
                    var dataColumns = dataTable.Columns;
                    foreach (DataRow rowData in dataTable.Rows)
                    {
                        if (row == 1)
                        {
                            foreach (var heading in dataColumns)
                            {
                                // headings. do not include column 0 (Variable)
                                if (dataCol == 0)
                                {
                                    dataCol++;
                                    continue;
                                }

                                worksheet.Range[row, column++].Text = dataColumns[dataCol++].Caption; // Date
                            }

                            row++;
                        }
                        for (column = 1; column < dataColumns.Count; column++)
                        {
                            worksheet.Range[row, column].Number =
                                ConvertToDouble(rowData[dataColumns[column++]].ToString()); // Date

                            // Backwards compatibility for years that may not have General Classification and Classification Number column entries.
                            if (dataColumns.Count == 16)
                            {
                                worksheet.Range[row, column].Text =
                                rowData[dataColumns[column++]].ToString(); // General Classification
                            }

                            worksheet.Range[row, column].Text =
                                rowData[dataColumns[column++]].ToString(); // Classification Title

                            if (dataColumns.Count == 16)
                            {
                                worksheet.Range[row, column].Text =
                                rowData[dataColumns[column++]].ToString(); // Classification Number
                            }

                            worksheet.Range[row, column].Number =
                                ConvertToDouble(rowData[dataColumns[column++]].ToString()); // Bed Size Min
                            worksheet.Range[row, column].Text =
                                rowData[dataColumns[column++]].ToString(); // Position Num
                            worksheet.Range[row, column].Number =
                                ConvertToDouble(rowData[dataColumns[column++]].ToString()); // Step 1
                            worksheet.Range[row, column].Number =
                                ConvertToDouble(rowData[dataColumns[column++]].ToString()); // Step 2
                            worksheet.Range[row, column].Number =
                                ConvertToDouble(rowData[dataColumns[column++]].ToString()); // Step 3
                            worksheet.Range[row, column].Number =
                                ConvertToDouble(rowData[dataColumns[column++]].ToString()); // Step 4
                            worksheet.Range[row, column].Number =
                                ConvertToDouble(rowData[dataColumns[column++]].ToString()); // Step 5
                            worksheet.Range[row, column].Number =
                                ConvertToDouble(rowData[dataColumns[column++]].ToString()); // Step 6
                            worksheet.Range[row, column].Number =
                                ConvertToDouble(rowData[dataColumns[column++]].ToString()); // Step 7
                            worksheet.Range[row, column].Number =
                                ConvertToDouble(rowData[dataColumns[column++]].ToString()); // Step 8
                            worksheet.Range[row, column].Number =
                                ConvertToDouble(rowData[dataColumns[column++]].ToString()); // Step 9

                            row++;
                        }
                    }

                    worksheet.UsedRange.AutofitColumns();

                    if (dataColumns.Count == 15)
                    {
                        worksheet.Columns[0].NumberFormat = "0000";                         // Date
                        worksheet.Columns[1].HorizontalAlignment = ExcelHAlign.HAlignLeft;  // General Classification
                        worksheet.Columns[2].HorizontalAlignment = ExcelHAlign.HAlignLeft;  // Classification Title
                        worksheet.Columns[3].HorizontalAlignment = ExcelHAlign.HAlignLeft;  // Classification Number
                        worksheet.Columns[5].NumberFormat = "0";                            // Position Num
                        worksheet.Columns[6].NumberFormat = "0";                            // Step 1
                        worksheet.Columns[7].NumberFormat = "0";                            // Step 2
                        worksheet.Columns[8].NumberFormat = "0";                            // Step 3
                        worksheet.Columns[9].NumberFormat = "0";                            // Step 4
                        worksheet.Columns[10].NumberFormat = "0";                           // Step 5
                        worksheet.Columns[11].NumberFormat = "0";                           // Step 6
                        worksheet.Columns[12].NumberFormat = "0";                           // Step 7
                        worksheet.Columns[13].NumberFormat = "0";                           // Step 8
                        worksheet.Columns[14].NumberFormat = "0";                           // Step 9
                    }
                    else
                    {
                        worksheet.Columns[0].NumberFormat = "0000";                         // Date
                        worksheet.Columns[1].HorizontalAlignment = ExcelHAlign.HAlignLeft;  // Classification Title
                        worksheet.Columns[3].HorizontalAlignment = ExcelHAlign.HAlignLeft;  // Position Num
                        worksheet.Columns[4].NumberFormat = "0";                            // Step 1
                        worksheet.Columns[5].NumberFormat = "0";                            // Step 2
                        worksheet.Columns[6].NumberFormat = "0";                            // Step 3
                        worksheet.Columns[7].NumberFormat = "0";                            // Step 4
                        worksheet.Columns[8].NumberFormat = "0";                            // Step 5
                        worksheet.Columns[9].NumberFormat = "0";                            // Step 6
                        worksheet.Columns[10].NumberFormat = "0";                           // Step 7
                        worksheet.Columns[11].NumberFormat = "0";                           // Step 8
                        worksheet.Columns[12].NumberFormat = "0";                           // Step 9
                    }

                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.PageSetup.FitToPagesWide = 1;
                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;

                    //Saving the workbook as stream
                    FileStream file = new FileStream(fullPath, FileMode.Create, FileAccess.ReadWrite);

                    workbook.SaveAs(file);
                    file.Dispose();
                }

                return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
        }

