        // Add FYE
        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult
            AddFYE(AnnualRateSettingEnum annualRateSettingEnum, string fiscalYear) // Some cases Datetime
        {
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;

            try
            {
                DateTime dateTime = new DateTime();
                if (!string.IsNullOrEmpty(fiscalYear))
                {
                    if ((annualRateSettingEnum == AnnualRateSettingEnum.SemiAnnualCaseMixScores)
                        || (annualRateSettingEnum == AnnualRateSettingEnum.QuarterlyCaseMixScores)
                        || (annualRateSettingEnum == AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM))
                    {
                        if (!DateTime.TryParse(fiscalYear, out dateTime))
                        {
                            return Json(new
                            {
                                Success = false,
                                Message = "Invalid input of fiscal year; please enter a valid quaterly date."
                            }, JsonRequestBehavior.AllowGet);
                        }
                    }
                    else
                    {
                        // Validate input
                        if (!int.TryParse(fiscalYear, out int year))
                        {
                            return Json(new
                            {
                                Success = false,
                                Message = "Invalid input of fiscal year; please simply enter the year number."
                            }, JsonRequestBehavior.AllowGet);
                        }

                        dateTime = new DateTime(int.Parse(fiscalYear), 01, 01);
                    }
                }

                List<DatabaseLookupGridViewModel> listDatabaselookUp = new List<DatabaseLookupGridViewModel>();
                DatabaseLookupViewModel dbLookupViewModel = new DatabaseLookupViewModel();

                List<DatabaseLookupValue> annualREDList = DatabaseLookupVariableBL.GetAnnualRED(annualRateSettingEnum)
                    .Where(x => x.StartDate == dateTime).ToList();

                if (annualREDList.Count > 0)
                {
                    return Json(new { Success = false, Message = "Record already exists.", rpt = annualREDList },
                        JsonRequestBehavior.AllowGet);
                }
                else
                {
                    DatabaseLookupVariableBL.AddDatabaseLookupVariableYearByCopy(annualRateSettingEnum.ToString(),
                        dateTime, $"{myUser.FirstName} {myUser.LastName}");
                    List<DatabaseLookupValue> lookUpData =
                        DatabaseLookupVariableBL.GetDatabaseLookUpVariableInfo(annualRateSettingEnum, dateTime);
                    foreach (var data in lookUpData)
                    {
                        listDatabaselookUp.Add(new DatabaseLookupGridViewModel
                        {
                            Value = data.Value,
                            DatabaseLookupVariableId =
                                ClientMapping.MapInternalIdToClientId(data.DatabaseLookupVariableId.ToString(),
                                    "dblookup"),
                        });
                    }

                    lookUpData.Clear();

                    Dictionary<int, DateTime> dates =
                        DatabaseLookupVariableBL.GetLookupSelectListDictionary(annualRateSettingEnum);
                    // we are adding a date; if there isn't one then inject it here so the grid will show.
                    if (dates.Count == 0) dates.Add(0, dateTime);
                    List<SelectListItem> ItemList = new List<SelectListItem>();
                    foreach (int key in dates.Keys)
                    {
                        if (dates.TryGetValue(key, out DateTime date))
                        {
                            string startDate = date.Year.ToString();
                            if ((annualRateSettingEnum == AnnualRateSettingEnum.SemiAnnualCaseMixScores)
                                || (annualRateSettingEnum == AnnualRateSettingEnum.QuarterlyCaseMixScores)
                                || (annualRateSettingEnum == AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM))
                            {
                                startDate = date.ToString("MM/dd/yyyy");
                            }

                            ItemList.Add(new SelectListItem
                            {
                                Text = startDate,
                                Value = ClientMapping.MapInternalIdToClientId(key.ToString(), "dblookup"),
                            });
                        }
                    }

                    dbLookupViewModel.RedDateList = ItemList;

                    dbLookupViewModel.DatabaseLookupGridViewModelList = listDatabaselookUp;

                    return Json(new { Success = true, DatabaseLookupViewModel = dbLookupViewModel },
                        JsonRequestBehavior.AllowGet);
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
        }

        // Grid events 
        // Add or Update from Grid
        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult SaveLookUpVariables(AnnualRateSettingEnum annualRateSettingEnum,
            DatabaseLookupGridViewModel value, string fiscalYear)
        {
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;

            try
            {
                DateTime dateTime = new DateTime();
                if (!string.IsNullOrEmpty(fiscalYear))
                {
                    if ((annualRateSettingEnum == AnnualRateSettingEnum.SemiAnnualCaseMixScores)
                        || (annualRateSettingEnum == AnnualRateSettingEnum.QuarterlyCaseMixScores)
                        || (annualRateSettingEnum == AnnualRateSettingEnum.AnnualMedianCaseMixCalculation)
                        || (annualRateSettingEnum == AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM))
                    {
                        if (!DateTime.TryParse(fiscalYear, out dateTime))
                        {
                            return Json(new
                            {
                                Success = false,
                                Message = "Invalid input of fiscal year; please enter a valid date."
                            }, JsonRequestBehavior.AllowGet);
                        }
                    }
                    else
                    {
                        if (!int.TryParse(fiscalYear, out int fy))
                        {
                            return Json(new
                            {
                                Success = false,
                                Message = "Invalid input of fiscal year; please simply enter a year number."
                            }, JsonRequestBehavior.AllowGet);
                        }

                        dateTime = new DateTime(fy, 01, 01);
                    }
                }

                int dbLookupId = 0;
                if (int.TryParse(ClientMapping.GetInternalIdFromClientId(value.DatabaseLookupVariableId, "dblookup"),
                        out int i) || string.IsNullOrWhiteSpace(value.DatabaseLookupVariableId))
                {
                    // If there was no Id, then it is a new value (and default value of 0 is good to go!).
                    if (!string.IsNullOrWhiteSpace(value.DatabaseLookupVariableId)) dbLookupId = i;

                    // If there is no VGS version, get one based on the enumeration type and date.
                    if (!value.VersionVGS.HasValue)
                    {
                        value.VersionVGS = DatabaseLookupVariableBL.GetVersionVGS(dateTime, annualRateSettingEnum);
                    }

                    DatabaseLookupValue databaseLookupValue = new DatabaseLookupValue
                    {
                        DatabaseLookupVariableId = dbLookupId,
                        VersionVGS = value.VersionVGS,
                        Key = value.Key,
                        Value = value.Value,
                        StartDate = dateTime,
                        EndDate = value.EndDate,
                        ValueType = annualRateSettingEnum.ToString(),
                        DisplayName = value.DisplayName,
                        RangeMinimum = value.RangeMinimum.ToString(),
                        RangeMaximum = value.RangeMaximum.ToString(),
                        CreatedOn = DateTime.Now,
                        LastUpdatedOn = DateTime.Now,
                        LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}"
                    };
                    DatabaseLookupVariableBL.SaveLookUpVariables(databaseLookupValue);
                }

                //Get Updated Grid Data
                DatabaseLookupViewModel dbLookupViewModel = GetLookUpData(annualRateSettingEnum, fiscalYear);

                return Json(new
                {
                    Success = true,
                    DatabaseLookupViewModel = dbLookupViewModel
                },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
        }

        private DatabaseLookupViewModel GetLookUpData(AnnualRateSettingEnum annualRateSettingEnum, string fiscalYear)
        {
            DatabaseLookupViewModel dbLookupViewModel = new DatabaseLookupViewModel();
            List<DatabaseLookupGridViewModel> listDatabaselookUp = new List<DatabaseLookupGridViewModel>();
            List<DatabaseLookupValue> lookUpData = null;

            try
            {
                DateTime dateTime = new DateTime();
                if (!string.IsNullOrEmpty(fiscalYear))
                {
                    if ((annualRateSettingEnum == AnnualRateSettingEnum.SemiAnnualCaseMixScores)
                        || (annualRateSettingEnum == AnnualRateSettingEnum.QuarterlyCaseMixScores)
                        || (annualRateSettingEnum == AnnualRateSettingEnum.AnnualMedianCaseMixCalculation)
                        || (annualRateSettingEnum == AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM))
                    {
                        dateTime = Convert.ToDateTime(fiscalYear);
                    }
                    else
                    {
                        dateTime = new DateTime(int.Parse(fiscalYear), 01, 01);
                    }
                }

                if (dateTime != null)
                {
                    lookUpData =
                        DatabaseLookupVariableBL.GetDatabaseLookUpVariableInfo(annualRateSettingEnum, dateTime);
                    foreach (var data in lookUpData)
                    {
                        if (!Int32.TryParse(data.RangeMinimum, out var rangeMinimum))
                        {
                            rangeMinimum = 0;
                        }

                        if (!Int32.TryParse(data.RangeMaximum, out var rangeMaximum))
                        {
                            rangeMaximum = 0;
                        }

                        listDatabaselookUp.Add(new DatabaseLookupGridViewModel
                        {
                            DatabaseLookupVariableId =
                                ClientMapping.MapInternalIdToClientId(data.DatabaseLookupVariableId.ToString(),
                                    "dblookup"),
                            VersionVGS = data.VersionVGS,
                            Key = data.Key,
                            Value = data.Value,
                            StartDate = data.StartDate,
                            EndDate = data.EndDate,
                            ValueType = data.ValueType,
                            DisplayName = data.DisplayName,
                            RangeMinimum = rangeMinimum,
                            RangeMaximum = rangeMaximum
                        });
                    }
                }

                dbLookupViewModel.DatabaseLookupGridViewModelList = listDatabaselookUp;
                return dbLookupViewModel;
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                throw;
            }
            finally
            {
                if (lookUpData != null) lookUpData.Clear();
            }
        }

