        #region Import

        #region Annual Case Mix Scores Import

        [HttpPost]
        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult AnnualCaseMixScores_Import()
        {
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
            HttpPostedFileBase file = null;

            try
            {
                //Get all files from Request object  
                file = Request.Files[0];

                CsvConfiguration config = new CsvConfiguration(CultureInfo.InvariantCulture)
                {
                    HasHeaderRecord = true,
                };

                int j = 1; // Set Variable Name

                List<DatabaseLookupItemViewModel> listDataBaseLookupGroupViewModel =
                    new List<DatabaseLookupItemViewModel>();
                List<AnnualCaseMixScoresResultViewModel> resultViewModels =
                    new List<AnnualCaseMixScoresResultViewModel>();
                //IEnumerable<Models.Import.QualityPointsModel> csvFileRecords = null;
                using (StreamReader reader = new StreamReader(file.InputStream))
                {
                    using (CsvReader csv = new CsvReader(reader, config))
                    {
                        // Create the collection as a type using the interface object
                        IEnumerable<Models.Import.IAnnualCaseMixScore> csvFileRecordsAnnualCaseMixScore =
                            new List<Models.Import.IAnnualCaseMixScore>();
                        // Load the collection using the specific concrete class that implements the interface
                        switch (SimplifiedType)
                        {
                            case "NF":
                                csvFileRecordsAnnualCaseMixScore =
                                    csv.GetRecords<WebPortal_OH_FI.Models.Import.AnnualCaseMixScoreNF>();
                                break;

                            case "ICF":
                                csvFileRecordsAnnualCaseMixScore =
                                    csv.GetRecords<WebPortal_OH_FI.Models.Import.AnnualCaseMixScoreICF>();
                                break;

                                // Any other type here, or else not imported.
                        }

                        foreach (Models.Import.IAnnualCaseMixScore csvFileRecord in csvFileRecordsAnnualCaseMixScore)
                        {
                            string fiscalYear = csvFileRecord.CYE;
                            //Provider Number be 7 digits. Adding the missing zeros are at the beginning
                            string providerNumber = !string.IsNullOrWhiteSpace(csvFileRecord.ProviderNumber)
                                ? csvFileRecord.ProviderNumber.PadLeft(7, '0')
                                : "";
                            //Values need to be 4 decimals after the period
                            string value = !string.IsNullOrWhiteSpace(csvFileRecord.CaseMixValue)
                                ? PopulateDecimalValue(csvFileRecord.CaseMixValue)
                                : "0.0000";

                            string reasonText = "";
                            bool isValid = true;
                            DateTime startDate;
                            var chkStartDate = DateTime.TryParse(string.Format("01/01/{0}", csvFileRecord.CYE),
                                out startDate);
                            if (string.IsNullOrWhiteSpace(fiscalYear) || !chkStartDate)
                            {
                                reasonText = "Fisical Year not found or not in correct format";
                                isValid = false;
                            }
                            else if (string.IsNullOrWhiteSpace(providerNumber) ||
                                     !BL.Helpers.ValueFormatHelper.validProviderNumberPattern.IsMatch(providerNumber))
                            {
                                reasonText = "Provider Number not found or 7 digits only";
                                isValid = false;
                            }
                            else if (csvFileRecord.Comments.Length > 100)
                            {
                                reasonText = "Comments cannot exceed 100 characters";
                                isValid = false;
                            }

                            if (!isValid)
                            {
                                resultViewModels.Add(new AnnualCaseMixScoresResultViewModel
                                {
                                    CYE = csvFileRecord.CYE,
                                    ProviderNumber = csvFileRecord.ProviderNumber,
                                    CaseMixValue = csvFileRecord.CaseMixValue,
                                    MDSScoreType = csvFileRecord.Score,
                                    Comments = csvFileRecord.Comments,
                                    Reason = reasonText
                                });
                                continue;
                            }

                            List<string> lstColumn = new List<string>();
                            lstColumn.Add(providerNumber);
                            lstColumn.Add(value);
                            lstColumn.Add(csvFileRecord.Score);
                            lstColumn.Add(csvFileRecord.Comments);

                            for (int i = 0; i < lstColumn.Count; i++)
                            {
                                // Transformation
                                listDataBaseLookupGroupViewModel.Add(new DatabaseLookupItemViewModel
                                {
                                    Value = lstColumn[i].Replace("$", "").Replace(",", ""),
                                    LookUpDate = startDate,
                                    ValueType = nameof(AnnualRateSettingEnum.AnnualCaseMixScores),
                                    VariableName = j.ToString() // To Partition a group for PIVOT 
                                });
                            }

                            lstColumn.Clear();
                            j++;
                        }
                    }
                }

                List<string> fisicalYear = listDataBaseLookupGroupViewModel
                    .Select(x => x.LookUpDate.ToShortDateString()).Distinct().ToList();
                Session[SESSION_KEYS_RS.LOOKUP_GROUP_VIEWMODEL] = listDataBaseLookupGroupViewModel;
