        #region Quality points 5 & 6 Import

        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult QualityPointsRateSch6_Import()
        {
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
            HttpPostedFileBase file = null;

            try
            {
                //Get all files from Request object  
                file = Request.Files[0];

                CsvConfiguration config = new CsvConfiguration(CultureInfo.InvariantCulture)
                {
                    HasHeaderRecord = true,
                };

                int j = 1; // Set Variable Name

                List<DatabaseLookupItemViewModel> listDataBaseLookupGroupViewModel =
                    new List<DatabaseLookupItemViewModel>();
                List<QualityPointsRateSch6ResultViewModel> resultViewModels =
                    new List<QualityPointsRateSch6ResultViewModel>();
                IEnumerable<Models.Import.QualityPointsRateSch6Model> csvFileRecords = null;
                using (StreamReader reader = new StreamReader(file.InputStream))
                {
                    using (CsvReader csv = new CsvReader(reader, config))
                    {
                        csvFileRecords = csv.GetRecords<WebPortal_OH_FI.Models.Import.QualityPointsRateSch6Model>();
                        foreach (Models.Import.QualityPointsRateSch6Model csvFileRecord in csvFileRecords)
                        {
                            //Provider Number be 7 digits. Adding the missing zeros are at the beginning
                            string providerNumber = !string.IsNullOrWhiteSpace(csvFileRecord.ProviderNumber)
                                ? csvFileRecord.ProviderNumber.PadLeft(7, '0')
                                : "";
                            //Occupancy value need to be 2 decimals after the period
                            string occupancy = !string.IsNullOrWhiteSpace(csvFileRecord.Occupancy)
                                ? PopulateCurrencyValue(csvFileRecord.Occupancy)
                                : "0.00";
                            //LSDI value need to be 2 decimals after the period
                            string lsdi = !string.IsNullOrWhiteSpace(csvFileRecord.LSDI)
                                ? PopulateCurrencyValue(csvFileRecord.LSDI)
                                : "0.00";
                            //LSFI value need to be 2 decimals after the period
                            string lsfi = !string.IsNullOrWhiteSpace(csvFileRecord.LSFI)
                                ? PopulateCurrencyValue(csvFileRecord.LSFI)
                                : "0.00";
                            //LSAM value need to be 2 decimals after the period
                            string lsam = !string.IsNullOrWhiteSpace(csvFileRecord.LSAM)
                                ? PopulateCurrencyValue(csvFileRecord.LSAM)
                                : "0.00";
                            //AdjustedStaffing value need to be 2 decimals after the period
                            string adjustedStaffing = !string.IsNullOrWhiteSpace(csvFileRecord.AdjustedStaffing)
                                ? PopulateCurrencyValue(csvFileRecord.AdjustedStaffing)
                                : "0.00";


                            string effectiveDate = csvFileRecord.EffectiveDate;
                            string reasonText = "";
                            bool isValid = true;

                            DateTime starDateTime;
                            string[] format = { "MM/dd/yyyy", "M/d/yyyy", "MM/d/yyyy", "M/dd/yyyy" };
                            var chkEffectiveDate = DateTime.TryParseExact(effectiveDate, format,
                                new CultureInfo("en-US"), DateTimeStyles.None, out starDateTime);
                            if (string.IsNullOrWhiteSpace(effectiveDate) || !chkEffectiveDate)
                            {
                                reasonText = "Effective Date not found or not in correct format 'MM/DD/YYYY'";
                                isValid = false;
                            }
                            else if (string.IsNullOrWhiteSpace(providerNumber) ||
                                     !BL.Helpers.ValueFormatHelper.validProviderNumberPattern.IsMatch(providerNumber))
                            {
                                reasonText = "Provider Number not found or 7 digits only";
                                isValid = false;
                            }

                            if (!isValid)
                            {
                                resultViewModels.Add(new QualityPointsRateSch6ResultViewModel
                                {
                                    EffectiveDate = csvFileRecord.EffectiveDate,
                                    ProviderNumber = csvFileRecord.ProviderNumber,
                                    PressureUlcers = csvFileRecord.PressureUlcers,
                                    UrinaryTractInfection = csvFileRecord.UrinaryTractInfection,
                                    IndependentMovement = csvFileRecord.IndependentMovement,
                                    Catheter = csvFileRecord.Catheter,
                                    Occupancy = csvFileRecord.Occupancy,
                                    LSDI = csvFileRecord.LSDI,
                                    LSFI = csvFileRecord.LSFI,
                                    LSAM = csvFileRecord.LSAM,
                                    AdjustedStaffing = csvFileRecord.AdjustedStaffing,
                                    Reason = reasonText
                                });
                                continue;
                            }

                            // Normalize the data; there may be blanks, dashes, etc. :/
                            if (csvFileRecord.PressureUlcers.Trim() == "-" ||
                                string.IsNullOrWhiteSpace(csvFileRecord.PressureUlcers))
                                csvFileRecord.PressureUlcers = "0";
                            if (csvFileRecord.UrinaryTractInfection.Trim() == "-" ||
                                string.IsNullOrWhiteSpace(csvFileRecord.UrinaryTractInfection))
                                csvFileRecord.UrinaryTractInfection = "0";
                            if (csvFileRecord.IndependentMovement.Trim() == "-" ||
                                string.IsNullOrWhiteSpace(csvFileRecord.IndependentMovement))
                                csvFileRecord.IndependentMovement = "0";
                            if (csvFileRecord.Catheter.Trim() == "-" ||
                                string.IsNullOrWhiteSpace(csvFileRecord.Catheter)) csvFileRecord.Catheter = "0";

                            List<string> lstString = new List<string>
                            {
                                "0".Repeat(7 - providerNumber.Length) + providerNumber,
                                csvFileRecord.PressureUlcers,
                                csvFileRecord.UrinaryTractInfection,
                                csvFileRecord.IndependentMovement,
                                csvFileRecord.Catheter,
                                occupancy,
                                lsdi,
                                lsfi,
                                lsam,
                                adjustedStaffing
                            };

                            for (int i = 0; i < lstString.Count; i++)
                            {
                                listDataBaseLookupGroupViewModel.Add(new DatabaseLookupItemViewModel
                                {
                                    Value = lstString[i],
                                    LookUpDate = starDateTime,
                                    ValueType = nameof(AnnualRateSettingEnum.QualityPointsRateSch6),
                                    VariableName = j.ToString() // To Partition a group for PIVOT 
                                });
                            }

                            lstString.Clear();
                            j++;
                        }
                    }
                }

                List<string> listDates = listDataBaseLookupGroupViewModel.Select(x => x.LookUpDate.ToShortDateString())
                    .Distinct().ToList();
                Session[SESSION_KEYS_RS.LOOKUP_GROUP_VIEWMODEL] = listDataBaseLookupGroupViewModel;
                Session[SESSION_KEYS_RS.LOOKUP_GROUP_RESULT] = resultViewModels;

                return Json(new { Success = true, Data = listDates }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                Session[SESSION_KEYS_RS.LOOKUP_GROUP_VIEWMODEL] = null;
                Session[SESSION_KEYS_RS.LOOKUP_GROUP_RESULT] = null;
                return Json(
                    new
                    {
                        Success = false,
                        Message =
                            "Error occurred importing the file. Please check that headers are correct and this is the correct file type."
                    }, JsonRequestBehavior.AllowGet);
            }
            finally
            {
                if (file != null) file = null;
            }
        }

