                            var step_8 = string.IsNullOrWhiteSpace(csvFileRecord.Step_8)
                                ? 0
                                : Math.Ceiling(decimal.Parse(csvFileRecord.Step_8));
                            var step_9 = string.IsNullOrWhiteSpace(csvFileRecord.Step_9)
                                ? 0
                                : Math.Ceiling(decimal.Parse(csvFileRecord.Step_9));

                            List<string> lstColumn = new List<string>();
                            lstColumn.Add(csvFileRecord.General_Classification);
                            lstColumn.Add(csvFileRecord.Classification_Title);
                            lstColumn.Add(csvFileRecord.Classification_Number);
