        #region Special Focus Facilities Import

        [HttpPost]
        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult SpecialFocusFacilities_Import()
        {
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
            HttpPostedFileBase file = null;

            try
            {
                //Get all files from Request object  
                file = Request.Files[0];

                CsvConfiguration config = new CsvConfiguration(CultureInfo.InvariantCulture)
                {
                    HasHeaderRecord = true //false
                };

                List<DatabaseLookupVariableResult> res = new List<DatabaseLookupVariableResult>();
                List<DatabaseLookupValue> listDatabaselookUp = new List<DatabaseLookupValue>();

                using (StreamReader reader = new StreamReader(file.InputStream))
                {
                    using (CsvReader csv = new CsvReader(reader, config))
                    {
                        IEnumerable<Models.Import.ProviderByFYE> csvFileRecords =
                            csv.GetRecords<WebPortal_OH_FI.Models.Import.ProviderByFYE>();
                        foreach (Models.Import.ProviderByFYE csvFileRecord in csvFileRecords)
                        {
                            //Provider Number be 7 digits. Adding the missing zeros are at the beginning
                            string providerNumber = !string.IsNullOrWhiteSpace(csvFileRecord.ProviderNumber)
                                ? csvFileRecord.ProviderNumber.PadLeft(7, '0')
                                : "";

                            string reasonText = "";
                            bool isValid = true;
                            DateTime startDate;
                            var chkStartDate = DateTime.TryParse(string.Format("01/01/{0}", csvFileRecord.CYE),
                                out startDate);
                            if (string.IsNullOrWhiteSpace(csvFileRecord.CYE) || !chkStartDate)
                            {
                                reasonText = "Fisical Year not found or not in correct format";
                                isValid = false;
                            }
                            else if (string.IsNullOrWhiteSpace(providerNumber) ||
                                     !BL.Helpers.ValueFormatHelper.validProviderNumberPattern.IsMatch(providerNumber))
                            {
                                reasonText = "Provider Number not found or 7 digits only";
                                isValid = false;
                            }

                            if (!isValid)
                            {
                                res.Add(new DatabaseLookupVariableResult
                                {
                                    FiscalYear = csvFileRecord.CYE,
                                    Value = csvFileRecord.ProviderNumber,
                                    Reason = reasonText
                                });
                                continue;
                            }

                            listDatabaselookUp.Add(new DatabaseLookupValue
                            {
                                //Key = csvFileRecord.ProviderNumber,
                                Value = providerNumber,
                                StartDate = startDate,
                                ValueType = nameof(AnnualRateSettingEnum.SpecialFocusFacilities),
                                CreatedOn = DateTime.Now,
                                CreatedBy = $"{myUser.FirstName} {myUser.LastName}",
                                LastUpdatedOn = DateTime.Now,
                                LastUpdateBy = $"{myUser.FirstName} {myUser.LastName}"
                            });
                        }
                    }
                }

                var fisicalYear = FisicalYearDateList(listDatabaselookUp);

                Session[SESSION_KEYS_RS.LOOKUP_VALUE] = listDatabaselookUp;

                return Json(new { Success = true, Data = fisicalYear, RejectList = res }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                Session[SESSION_KEYS_RS.LOOKUP_VALUE] = null;
                return Json(
                    new
                    {
                        Success = false,
                        Message =
                            "Error occurred importing the file. Please check that headers are correct and this is the correct file type."
                    }, JsonRequestBehavior.AllowGet);
            }
            finally
            {
                if (file != null) file = null;
            }
        }

