                Session[SESSION_KEYS_RS.LOOKUP_GROUP_VIEWMODEL] = listDataBaseLookupGroupViewModel;
                Session[SESSION_KEYS_RS.LOOKUP_GROUP_RESULT] = resultViewModels;

                return Json(new { Success = true, Data = fisicalYear }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                Session[SESSION_KEYS_RS.LOOKUP_GROUP_VIEWMODEL] = null;
                Session[SESSION_KEYS_RS.LOOKUP_GROUP_RESULT] = null;
                return Json(
                    new
                    {
                        Success = false,
                        Message =
                            "Error occurred importing the file. Please check that headers are correct and this is the correct file type."
                    }, JsonRequestBehavior.AllowGet);
            }
            finally
            {
                if (file != null) file = null;
            }
        }

