        public List<string> FisicalYearDateList(List<DatabaseLookupValue> listDatabaselookUp)
        {
            return listDatabaselookUp
                .Select(x => x.StartDate)
                .Distinct()
                .OrderBy(x => x)
                .Select(x => x.Date.ToString())
                .ToList();
        }

        [HttpPost]
        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult CheckFYE(AnnualRateSettingEnum annualRateSettingEnum, DateTime date)
        {
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;

            try
            {
                var alertMsg = "";
                int year = date.Year;
                List<DatabaseLookupValue> listDatabaselookUp =
                    (List<DatabaseLookupValue>)Session[SESSION_KEYS_RS.LOOKUP_VALUE];
                DatabaseLookupValue addRED = DatabaseLookupVariableBL.GetAnnualRED(annualRateSettingEnum)
                    .Where(x => x.StartDate == date).FirstOrDefault();

                if (addRED != null)
                {
                    year = addRED.StartDate.Year;
                    alertMsg = $"Record for {year} already exists, should current data be overwritten.?";
                    return Json(new { Success = true, fyeValue = year, AlertMessage = alertMsg });
                }

                switch (annualRateSettingEnum)
                {
                    case AnnualRateSettingEnum.FRVCountyModifiers:
                    case AnnualRateSettingEnum.AnnualCaseMixScores:
                    case AnnualRateSettingEnum.SemiAnnualCaseMixScores:
                    case AnnualRateSettingEnum.QuarterlyCaseMixScores:
                    case AnnualRateSettingEnum.QuarterlyCaseMixScoresPDPM:
                    case AnnualRateSettingEnum.PeerGroupFiveA:
                    case AnnualRateSettingEnum.ProviderDownsized:
                    case AnnualRateSettingEnum.CriticalAccessProviders:
                    case AnnualRateSettingEnum.SpecialFocusFacilities:
                        alertMsg = $"Record for {year} doesn't exist! a new CYE year will be created.";
                        break;
                    default:
                        alertMsg = $"Record for {year} doesn't exist! a new FYE year will be created.";
                        break;
                }

                return Json(new { Success = false, fyeValue = year, AlertMessage = alertMsg },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(
                    new
                    {
                        Success = false,
                        Message =
                            "Error occurred importing the file. Please check that headers are correct and this is the correct file type."
                    }, JsonRequestBehavior.AllowGet);
            }
        }

        [HttpPost]
        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult Import(AnnualRateSettingEnum annualRateSettingEnum, bool flag, bool inValid,
            string effectiveFYE, bool clearSession)
        {
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
            List<DatabaseLookupValue> importFYE = null;

            try
            {
                List<DatabaseLookupValue> listDatabaselookUp =
                    (List<DatabaseLookupValue>)Session[SESSION_KEYS_RS.LOOKUP_VALUE];
                List<DatabaseLookupVariableResult> res = new List<DatabaseLookupVariableResult>();

                DateTime starDateTime;
                string[] format = { "MM/dd/yyyy", "yyyy" };
                DateTime.TryParseExact(effectiveFYE, format, new CultureInfo("en-US"), DateTimeStyles.None,
                    out starDateTime);

                if (flag)
                {
                    DatabaseLookupVariableBL.RemoveFYE(annualRateSettingEnum, starDateTime);
                }

                importFYE = listDatabaselookUp.Where(dt => dt.StartDate.Date == starDateTime.Date).ToList();

                if (!inValid)
                {
                    DatabaseLookupVariableBL.SaveLookUpVariables(importFYE);
                }

                return Json(new { Success = true, Message = @"Import completed successfully.", Data = res },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                return Json(
                    new
                    {
                        Success = false,
                        Message =
                            "Error occurred importing the file. Please check that headers are correct and this is the correct file type."
                    }, JsonRequestBehavior.AllowGet);
            }
            finally
            {
                if (clearSession) Session[SESSION_KEYS_RS.LOOKUP_VALUE] = null;
                if (importFYE != null) importFYE.Clear();
            }
        }

