        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult GetProviderAddressByType(AddressTypeEnum addressType)
        {
            var myUser = RetrieveSession.ARUMUser;

            AddressFullViewModel addressViewModel = new AddressFullViewModel();
            if (Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT] != null)
            {
                int providerId = (int)Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT];
                IAllProviders arum_AllProviders = _applicationServiceProxy.GetAllActiveProvidersFromListWithOptions(
                    RetrieveSession.Classification.ARUMToken,
                    new List<int> { providerId }, true, true, true, true, false, false, false, "ratesetting.providers");

                var current_provider = arum_AllProviders.lstProviders.Where(p => p.ProviderID == providerId)
                    .FirstOrDefault();


                addressViewModel.AddressName = current_provider.Name;
                if (current_provider.Addresses != null && current_provider.Addresses.Count > 0)
                {
                    MSLC.ApplicationProxy.Interfaces.Models.Addresses address = null;
                    MSLC.ApplicationProxy.Interfaces.Models.Contact contact = null;
                    switch (addressType)
                    {
                        case AddressTypeEnum.Mailing:
                            address = current_provider.Addresses.Where(x => x.Type == "MA").FirstOrDefault();
                            addressViewModel.AddressType = AddressTypeEnum.Mailing.GetDescription();
                            break;
                        case AddressTypeEnum.Facility:
                            address = current_provider.Addresses.Where(x => x.Type == "FA").FirstOrDefault();
                            addressViewModel.AddressType = AddressTypeEnum.Facility.GetDescription();
                            break;
                        case AddressTypeEnum.Corporation:
                            address = current_provider.Addresses.Where(x => x.Type == "CO").FirstOrDefault();
                            addressViewModel.AddressType = AddressTypeEnum.Corporation.GetDescription();
                            break;
                        case AddressTypeEnum.HomeOffice:
                            address = current_provider.Addresses.Where(x => x.Type == "HO").FirstOrDefault();
                            addressViewModel.AddressType = AddressTypeEnum.HomeOffice.GetDescription();
                            break;
                        case AddressTypeEnum.PayTo:
                            address = current_provider.Addresses.Where(x => x.Type == "PT").FirstOrDefault();
                            addressViewModel.AddressType = AddressTypeEnum.PayTo.GetDescription();
                            break;
                        default:
                            break;
                    }

                    if (address != null)
                    {
                        contact = current_provider.Contacts.Where(c => c.AddressID == address.AddressID)
                            .FirstOrDefault();
                        if (contact != null)
                        {
                            if (!string.IsNullOrEmpty(contact.FirstName) || !string.IsNullOrEmpty(contact.LastName))
                            {
                                addressViewModel.AddressContactPerson = contact.FirstName + " " + contact.LastName;
                            }

                            addressViewModel.AddressEmail = contact.Email != null ? contact.Email : string.Empty;
                        }
                        else
                        {
                            addressViewModel.AddressContactPerson = string.Empty;
                            addressViewModel.AddressEmail = string.Empty;
                        }

                        addressViewModel.AddressLineOne = address.Address1 != null ? address.Address1 : string.Empty;
                        addressViewModel.AddressLineTwo = address.Address2 != null ? address.Address2 : string.Empty;
                        addressViewModel.AddressCity = address.City != null ? address.City : string.Empty;
                        addressViewModel.AddressState = address.State != null ? address.State : string.Empty;
                        addressViewModel.AddressZipCode = address.ZipCode != null ? address.ZipCode : string.Empty;
                        addressViewModel.AddressCounty = GetNfArumProviderCounty(providerId);
                        addressViewModel.AddressPhone = address.Phone != null ? address.Phone : string.Empty;
                        addressViewModel.AddressFax = address.Fax != null ? address.Fax : string.Empty;
                    }
                }
            }

            return Json(new
            {
                Success = true,
                AddressFullViewModel = addressViewModel
            },
                JsonRequestBehavior.AllowGet);
        }

