        private List<CertifiedBedTransfersViewModel> GetAllCertifiedBedTransfersCollection(int providerId)
        {
            List<CertifiedBedTransfers> certifiedBedTransfersData = RateBL.GetAllCertifiedBedTransfers(providerId);
            List<CertifiedBedTransfersViewModel> lstCertifiedBedTransfersViewModel =
                new List<CertifiedBedTransfersViewModel>();
            foreach (var transferData in certifiedBedTransfersData)
            {
                lstCertifiedBedTransfersViewModel.Add(new CertifiedBedTransfersViewModel
                {
                    CertifiedBedTransfersId =
                        ClientMapping.MapInternalIdToClientId(transferData.CertifiedBedTransfersId.ToString(),
                            "certifiedtransfer"),
                    ProviderId = ClientMapping.MapInternalIdToClientId(transferData.ProviderId.ToString(), "provider"),
                    ProviderFromNumber = transferData.ProviderFromNumber.ToString(),
                    // This string data must be formatted here in a manner that allows accurate sorting, so year, month, day.
                    EffectiveDate = transferData.EffectiveDate.ToString("yyyy-MM-dd"),
                    CertifiedBedsTransferred = transferData.CertifiedBedsTransferred,
                    ProviderFromName = transferData.ProviderFromName,
                    Comments = transferData.Comments,
                    BedsOnHold = transferData.BedsOnHold == true ? "Yes" : "No"
                });
            }

            return lstCertifiedBedTransfersViewModel;
        }

        private List<CertifiedBedTransfersProvidersViewModel> GetAllARUMProvidersCollection()
        {
            ClassificationDTO classification = RetrieveSession.Classification;
            ARUMApplicationServiceProxy _arumApplicationClient =
                ARUMApplication.GetARUMApplicationProxy(classification);

            IAllProviders lstProviders = _arumApplicationClient.GetAllActiveProvidersWithOptions(
                classification.ARUMToken,
                false, false, false, false, false, false, false, "Rate/GetAllARUMProvidersCollection");

            if (!lstProviders.Result.Successful)
                throw new Exception("Unable to retrieve list of providers.");

            List<CertifiedBedTransfersProvidersViewModel> AllARUMProviders = lstProviders.lstProviders.Select(p =>
                new CertifiedBedTransfersProvidersViewModel()
                {
                    ProviderId = ClientMapping.MapInternalIdToClientId(p.ProviderID.ToString(), "provider"),
                    Name = p.Name,
                    Number = p.MCAID
                }).ToList();
            return AllARUMProviders;
        }

        // Add/ Update
        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult SaveCertifiedBedTransfers(CertifiedBedTransfersViewModel value)
        {
            var sanitizer = new HtmlSanitizer();
            if (!int.TryParse(Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT]?.ToString(), out int sessionProviderID))
                return Json(new { Success = false, Message = "Provider Id not found." }, JsonRequestBehavior.AllowGet);

            var mappedTransferID =
                ClientMapping.GetInternalIdFromClientId(value.CertifiedBedTransfersId, "certifiedtransfer");

            // Could be an existing ID or a new one
            int.TryParse(mappedTransferID, out int dbCertifiedBedTransfersId);

            // force 00:00:00
            DateTime midnight = DateTime.Parse(value.EffectiveDate).Date;
            midnight = DateTime.SpecifyKind(midnight, DateTimeKind.Unspecified);

            CertifiedBedTransfers dataModel = new CertifiedBedTransfers
            {
                ProviderId = sessionProviderID,
                CertifiedBedTransfersId = dbCertifiedBedTransfersId,
                ProviderFromNumber = value.ProviderFromNumber,
                EffectiveDate = midnight,
                BedsOnHold = value.BedsOnHold == "Yes" ? true : false,
                CertifiedBedsTransferred = value.CertifiedBedsTransferred,
                ProviderFromName = value.ProviderFromName,
                Comments = sanitizer.Sanitize(value.Comments),
            };

            RateBL.SaveCertifiedBedTransfers(dataModel);

            return Json(new
            {
                Success = true,
                CertifiedBedTransfersListViewModel = GetAllCertifiedBedTransfersCollection(sessionProviderID)
            }, JsonRequestBehavior.AllowGet);
        }

