        /// <returns></returns>
        private List<CertifiedBedsViewModel> GetCertifiedBeds(int providerId)
        {
            List<CertifiedBedsViewModel> listViewModel = new List<CertifiedBedsViewModel>();
            var listBeds = RateBL.GetCertifiedBeds(providerId);

            if (listBeds.Count > 0)
            {
                foreach (var certifiedBed in listBeds)
                {
                    listViewModel.Add(MapCertifiedBedsToViewModel(certifiedBed));
                }
            }

            return listViewModel;
        }

        private CertifiedBedsViewModel MapCertifiedBedsToViewModel(CertifiedBeds certifiedBed)
        {
            if (certifiedBed == null)
            {
                return new CertifiedBedsViewModel();
            }

            return new CertifiedBedsViewModel
            {
                CertifiedBedsId =
                    ClientMapping.MapInternalIdToClientId(certifiedBed.CertifiedBedsId.ToString() ?? "0",
                        "certifiedbeds"),
                ProviderId =
                    ClientMapping.MapInternalIdToClientId(certifiedBed.ProviderId.ToString() ?? "0", "certifiedbeds"),
                // This string data must be formatted here in a manner that allows accurate sorting, so year, month, day.
                EffectiveDate = certifiedBed.EffectiveDate,
                Status = certifiedBed.Status,
                MedicaidNF = certifiedBed.MedicaidNF ?? 0,
                DualSNFNF = certifiedBed.DualSNFNF ?? 0,
                Total = certifiedBed.Total,
                Comments = certifiedBed.Comments,
            };
        }

