        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult SaveCertifiedBeds(CertifiedBedsViewModel certifiedBedsInput)
        {
            List<CertifiedBedsViewModel> certifiedBedsViewModel = new List<CertifiedBedsViewModel>();
            if (Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT] != null)
            {
                int providerId = (int)Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT];
                int dbCertifiedBedsId = 0;
                if (int.TryParse(
                        ClientMapping.GetInternalIdFromClientId(certifiedBedsInput.CertifiedBedsId, "certifiedbeds"),
                        out int i))
                {
                    dbCertifiedBedsId = i;
                }

                CertifiedBeds certifiedBeds = new CertifiedBeds();
                if (certifiedBedsInput != null)
                {
                    int total = OHFISession.IsNF
                        ? (certifiedBedsInput.MedicaidNF + certifiedBedsInput.DualSNFNF)
                        : certifiedBedsInput.Total;
                    // force 00:00:00
                    DateTime midnight = certifiedBedsInput.EffectiveDate.Date;
                    midnight = DateTime.SpecifyKind(midnight, DateTimeKind.Unspecified);

                    certifiedBeds = new CertifiedBeds
                    {
                        CertifiedBedsId = dbCertifiedBedsId,
                        ProviderId = providerId,
                        EffectiveDate = midnight,
                        Status = certifiedBedsInput.Status,
                        MedicaidNF = OHFISession.IsICF ? null : (int?)certifiedBedsInput.MedicaidNF,
                        DualSNFNF = OHFISession.IsICF ? null : (int?)certifiedBedsInput.DualSNFNF,
                        Total = total,
                        Comments = certifiedBedsInput.Comments,
                    };
                }

                RateBL.SaveCertifiedBeds(certifiedBeds);

                return Json(new
                {
                    Success = true,
                    CertifiedBedsViewModel = GetCertifiedBeds(providerId)
                },
                    JsonRequestBehavior.AllowGet);
