        private LicensedBedsViewModel MapLicensedBedsToViewModel(LicensedBeds licensedBeds)
        {
            if (licensedBeds == null) return new LicensedBedsViewModel();

            var effDate = licensedBeds.EffectiveDate;

            return new LicensedBedsViewModel()
            {
                LicensedBedsId =
                    ClientMapping.MapInternalIdToClientId(licensedBeds.LicensedBedsId.ToString(), "licensedbeds"),
                ProviderId = ClientMapping.MapInternalIdToClientId(licensedBeds.ProviderId.ToString(), "provider"),
                // This string data must be formatted here in a manner that allows accurate sorting, so year, month, day.
                EffectiveDate = licensedBeds.EffectiveDate,
                Status = licensedBeds.Status,
                BedCountNF = licensedBeds.BedCountNF,
                BedCountRegisteredHospital = licensedBeds.BedCountRegisteredHospital,
                BedCountOther = licensedBeds.BedCountOther,
                BedCountICF = licensedBeds.BedCountICF,
                TotalLicBeds = licensedBeds.TotalLicBeds,
                TotalProjBeds = licensedBeds.TotalProjBeds,
                ResidentialCare = licensedBeds.ResidentialCare,
                OutOfService = licensedBeds.OutOfService,
                OnHold = licensedBeds.OnHold,

                Comments = licensedBeds.Comments
            };
        }

