                    LicensedBedsViewModel = new List<LicensedBedsViewModel>()
                },
                    JsonRequestBehavior.AllowGet);
            }
        }

        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult SaveLicensedBeds(LicensedBedsViewModel licensedBedsInput)
        {
            var sanitizer = new HtmlSanitizer();
            if (Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT] != null)
            {
                int providerId = (int)Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT];
                try
                {
                    if (licensedBedsInput != null)
                    {
                        int dbLicensedBedsId = 0;
                        if (int.TryParse(
                                ClientMapping.GetInternalIdFromClientId(licensedBedsInput.LicensedBedsId,
                                    "licensedbeds"), out int i))
                        {
                            dbLicensedBedsId = i;
                        }

                        string[]
                            statusOptions = new[]
                            {
                                "Active"
                            }; // This is the same list as in the load, we might want to move this list somewhere else later. 
                        if (!statusOptions.Any(o => o.Equals(licensedBedsInput.Status)))
                        {
                            throw new Exception("Invalid status selected for operation.");
                        }

                        #region Calculate Totals

                        licensedBedsInput.TotalLicBeds = licensedBedsInput.BedCountNF +
                                                         licensedBedsInput.BedCountOther +
                                                         licensedBedsInput.BedCountICF +
                                                         licensedBedsInput.BedCountRegisteredHospital;

                        switch (SimplifiedType)
                        {
                            case "NF":
                                licensedBedsInput.TotalProjBeds = licensedBedsInput.BedCountNF +
                                                                  licensedBedsInput.BedCountRegisteredHospital;
                                break;
                            case "ICF":
                                licensedBedsInput.TotalProjBeds = licensedBedsInput.BedCountICF;
                                break;
                            default:
                                throw new Exception("Invalid project type for operation.");
                        }

                        #endregion

                        // force 00:00:00
                        DateTime midnight = licensedBedsInput.EffectiveDate.Date;
                        midnight = DateTime.SpecifyKind(midnight, DateTimeKind.Unspecified);

                        RateBL.SaveLicensedBeds(new LicensedBeds
                        {
                            LicensedBedsId = dbLicensedBedsId,
                            ProviderId = providerId,
                            EffectiveDate = midnight,
                            Status = licensedBedsInput.Status,
                            BedCountNF = licensedBedsInput.BedCountNF,
                            BedCountRegisteredHospital = licensedBedsInput.BedCountRegisteredHospital,
                            BedCountOther = licensedBedsInput.BedCountOther,
                            BedCountICF = licensedBedsInput.BedCountICF,
                            TotalLicBeds = licensedBedsInput.TotalLicBeds,
                            TotalProjBeds = licensedBedsInput.TotalProjBeds,
                            ResidentialCare = licensedBedsInput.ResidentialCare,
                            OutOfService = licensedBedsInput.OutOfService,
                            OnHold = licensedBedsInput.OnHold,

                            Comments = sanitizer.Sanitize(licensedBedsInput.Comments)
                        });
                    }

                    return Json(new
                    {
                        Success = true,
                        LicensedBedsViewModel = GetLicensedBeds(providerId).OrderByDescending(x => x.EffectiveDate)
                    },
                        JsonRequestBehavior.AllowGet);
                }
                catch (Exception e)
                {
                    _logger.Error(e, e.Message);

                    return Json(new
                    {
                        Success = false,
                        Message = e.Message
                    }, JsonRequestBehavior.AllowGet);
                }
            }
            else
            {
                return Json(new
                {
                    Success = false,
                    LicensedBedsViewModel = new List<LicensedBedsViewModel>()
                },
                    JsonRequestBehavior.AllowGet);
            }
        }

        [ARUMFeatureActionFilter("RateSetting:View")]
        public JsonResult DeleteLicensedBeds(LicensedBedsViewModel licensedBedsInput)
        {
            if (Session[SESSION_KEYS_RS.PROVIDER_ID_CURRENT] != null)
