        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult ProcessBaseYear(int year, DateTime? rateStartDate, BaseYearTypeEnum baseYearTypeEnum)
        {
            try
            {
                ARUMHandler.ClearCache();
                MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;

                // Accommodate time zone issues with rate start date
                if (rateStartDate.HasValue)
                {
                    rateStartDate = new DateTime(rateStartDate.Value.Year, rateStartDate.Value.Month,
                        rateStartDate.Value.Day);
                }

                // Update the database setting for the base year record.
                BaseYear by = RateBL.UpdateIsBaseYear(year, rateStartDate, baseYearTypeEnum, true,
                    $"{myUser.FirstName} {myUser.LastName}");

                // Response string not used.
                ProcessBaseYear(by, baseYearTypeEnum);
                ARUMHandler.ClearCache();

                return Json(new
                {
                    Success = true
                }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                ARUMHandler.ClearCache();
                return Json(new
                {
                    Success = false,
                    Message = e.Message
                }, JsonRequestBehavior.AllowGet);
            }
        }

        private List<RateSettingPackage.ProviderPackage> GetActiveProviders()
        {
            return GetActiveProviders(null);
        }

        private List<RateSettingPackage.ProviderPackage> GetActiveProviders(DateTime? effectiveDate)
        {
            // This needs to be done in the controller - "cannot" be done in business layer?
            List<Provider> lstProviders = GetAllProviderList(RetrieveSession.Classification.ARUMToken, false, true,
                false, true, true, false, false, false, true, "RateController.GetActiveProviders").lstProviders;

            List<RateSettingPackage.ProviderPackage> list = new List<RateSettingPackage.ProviderPackage>();
            List<string> output = new List<string>();

            foreach (var provider in lstProviders)
            {
                if (effectiveDate == null ||
                    RateProviderBL.SelectByProviderEffectiveDate(true, provider.EffectiveDates, effectiveDate.Value))
                {
                    RateSettingPackage.ProviderPackage package = RateProviderBL.GetProviderPackage(provider);
                    list.Add(package);
                    if (provider.HasChowReviews)
                    {
                        package.Chows = provider.ProviderChowChain
                            .Where(x => x.NewProviderID == provider.ProviderID)
                            .Select(x => new RateSettingPackage.ProviderPackage.ProviderChowInfo
                            {
                                NewProviderId = x.NewProviderID.Value,
                                OldProviderId = x.OldProviderID.Value,
                                ApproveDate = x.ApproveDate.Value
                            }).ToList();
                    }
#if DEBUG
                    output.Add($"{provider.ProviderID},{provider.Name},{provider.MCAID}");
#endif
                }
            }

            lstProviders.Clear();

#if DEBUG
            if (!effectiveDate.HasValue) effectiveDate = DateTime.Now;
            System.IO.File.WriteAllText(
                Path.Combine(Path.GetTempPath(), $"activeproviders_{effectiveDate.Value.ToString("yyyy-MM-dd")}.csv"),
                string.Join("\n", output.ToArray()));
#endif

            return list;
        }

