        public static List<ClassificationModel> FilterClassifications(List<ClassificationModel> classifications, string type)
        {
            string sessionType = type;

            // Filter logic based on session type
            return classifications.Where(c =>
                !(sessionType == "ICF" && (c.Type == "NF_ProdRestore" || c.Type == "ICF_ProdRestore")) &&
                !(sessionType == "ICF_ProdRestore" && (c.Type == "NF" || c.Type == "ICF")) &&
                !(sessionType == "NF" && (c.Type == "NF_ProdRestore" || c.Type == "ICF_ProdRestore")) &&
                !(sessionType == "NF_ProdRestore" && (c.Type == "NF" || c.Type == "ICF"))
            ).ToList();
        }

        private List<ProviderList> GetAllTypeActiveProviders(List<RateSettingPackage.ProviderPackage> providers, DateTime? effectiveDate)
        {
            List<ProviderList> providerLists = new List<ProviderList>();
            providerLists.Add(new ProviderList
            {
                Type = SimplifiedType,
                Providers = providers
            });

            // Disallowance will need information from other providers type (only NF for now).
            // Ensure that the engine has access to what they are for getting data.
            List<ClassificationModel> classifications = ProjectsViewModel.CloneClassifications(new ProjectsViewModel.Projects().Classifications);

            classifications = FilterClassifications(classifications, RetrieveSession.Classification.Type);

            foreach (var classification in classifications)
            {
                if (classification.Type == RetrieveSession.Classification.Type) continue;

                // This needs to be done in the controller - "cannot" be done in business layer?
                List<Provider> lstProviders = GetAllProviderList(classification.ARUMToken, false, true, false, true,
                    true, false, false, false, true, "RateController.GetActiveProviders").lstProviders;

                List<RateSettingPackage.ProviderPackage> list = new List<RateSettingPackage.ProviderPackage>();

                foreach (var provider in lstProviders)
                {
                    if (effectiveDate == null ||
                        RateProviderBL.SelectByProviderEffectiveDate(true, provider.EffectiveDates,
                            effectiveDate.Value))
                    {
                        RateSettingPackage.ProviderPackage package = RateProviderBL.GetProviderPackage(provider);
                        list.Add(package);
                        if (provider.HasChowReviews)
                        {
                            package.Chows = provider.ProviderChowChain
                                .Where(x => x.NewProviderID == provider.ProviderID)
                                .Select(x => new RateSettingPackage.ProviderPackage.ProviderChowInfo
                                {
                                    NewProviderId = x.NewProviderID.Value,
                                    OldProviderId = x.OldProviderID.Value,
                                    ApproveDate = x.ApproveDate.Value
                                }).ToList();
                        }
                    }
                }
                var dto = Common.Extensions.ClassificationDTOExtensions.CloneDTOClassification(classification);
                string type = Common.Extensions.ClassificationDTOExtensions.GetSimplifiedType(dto);

                providerLists.Add(new ProviderList
                {
                    Type = type,
                    Providers = list
                });

                lstProviders.Clear();
            }

            return providerLists;
        }

        /// <summary>
        /// Perform the base year process for specified base year object.
        /// </summary>
        /// <param name="redDate"></param>
        /// <param name="isBaseYear"></param>
        /// <returns></returns>
        private string ProcessBaseYear(BaseYear baseYear, BaseYearTypeEnum baseYearTypeEnum)
        {
            string ret = string.Empty;

            List<RateSettingPackage.ProviderPackage> providers = null;
            List<RateSettingPackage> rateSettingPackages = null;

            try
            {
                MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
                string username = $"{myUser.FirstName} {myUser.LastName}";

                // Get active providers as of the rate for the base year
                providers = GetActiveProviders(new DateTime(baseYear.Year, 12, 31));

                List<ProviderList> providerLists =
                    GetAllTypeActiveProviders(providers, new DateTime(baseYear.Year, 12, 31));

                // Get all the information from the database.
                rateSettingPackages = RateBL.GetBaseYearData(baseYear.Year, baseYearTypeEnum);
                if (rateSettingPackages.Count == 0)
                    throw new Exception("There are no Cost Reports for this date.");

                // Ensure that we only have active providers as of the RED.
                rateSettingPackages = rateSettingPackages
                    .Where(x => providers.Any(p => p.ProviderId == x.Provider.ProviderId)).ToList();

                // Get only those packages which are for providers active during the RED.
                foreach (var package in rateSettingPackages)
                {
                    package.Provider.EffectiveDates = providers
                        .FirstOrDefault(x => x.ProviderNumber == package.Provider.ProviderNumber)
                        ?.EffectiveDates ?? package.Provider.CreateListEffectiveDates();
                }

                //reset providers list to get all providers, even terminated ones
                providers = GetActiveProviders();

                ret = ProcessBaseYear(baseYear, rateSettingPackages, providers, providerLists, baseYearTypeEnum);
                return ret;
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                throw;
            }
            finally
            {
                // Release memory
                ARUMHandler.ClearCache();

                if (providers != null)
                {
                    providers.ForEach(x => x.Dispose());
                    providers.Clear();
                }

                if (rateSettingPackages != null)
                {
                    rateSettingPackages.ForEach(x => x.Dispose());
                    rateSettingPackages.Clear();
                }
            }
        }

        /// <summary>
        /// Perform the base year process for specified base year object using specified rate package list.
        /// </summary>
        /// <param name="redDate"></param>
        /// <param name="lstProviderData"></param>
        /// <returns></returns>
        /// <exception cref="Exception"></exception>
        private string ProcessBaseYear(BaseYear baseYear, List<RateSettingPackage> ratePackages,
            List<RateSettingPackage.ProviderPackage> providers, List<ProviderList> providerLists,
            BaseYearTypeEnum baseYearTypeEnum)
        {
            ARUMHandler.ClearCache();
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
            string username = $"{myUser.FirstName} {myUser.LastName}";

            string sJsonSubmission,
                sResponse,
                logDate = $"{baseYear.Year}1231";
            BL.JsonObjects.NF.IJsonInRuleBaseYearResponseNF jsonRootNF = null;
            BL.JsonObjects.ICF.IJsonInRuleBaseYearResponseICF jsonRootICF = null;

            try
            {
                List<RexVersionDateRange> ranges =
                    RexRequestHelper.ParseInRuleAppVersionRanges(OHFISession.BaseYearInRuleAppVersions);
                DateTime redDate = new DateTime(baseYear.Year, 7, 1);
                RexVersionDateRange selectedVersion =
                    ranges.FirstOrDefault(x => x.DateFrom <= redDate && x.DateTo >= redDate);
                if (selectedVersion == null) selectedVersion = ranges.OrderBy(x => x.DateTo).LastOrDefault();
                if (selectedVersion == null)
                    throw new Exception(
                        "Unable to select InRule Base Year rule set version. Please check ARUM settings.");
                ranges.Clear();

                List<ProviderRateResponse> responses = new List<ProviderRateResponse>();

                // We need to handle the numbers for the rate packages. Since we may have real and fake ones in
                // the array, but we use the Ids for reference, we need to ensure that the Ids are unique.
                // To ensure we differentiate between real and fake ones, fake ones will be a negative number.
                ratePackages = RateBL.VerifyRateCostReportsForRatePackages(ratePackages, username, baseYear.BaseYearId);

                switch (SimplifiedType)
                {
                    case "NF":
                        sJsonSubmission = BaseYearSubmissionNF(baseYear, providers, ratePackages, providerLists);

                        if (string.IsNullOrWhiteSpace(sJsonSubmission))
                            return "No cost report data found for Base Year operation.";

#if DEBUG
                        System.IO.File.WriteAllText(
                            Path.Combine(Path.GetTempPath(),
                                $"test.NF_BaseYear_Calculation.v{selectedVersion.Version}.listing.{logDate}.json"),
                            sJsonSubmission);
#endif

                        sResponse = SubmitInRuleData(OHFISession.BaseYearInRuleApp, selectedVersion.Version,
                            "NF_BaseYear_Calculation", sJsonSubmission, logDate);
                        sJsonSubmission = String.Empty;

#if DEBUG
                        System.IO.File.WriteAllText(
                            Path.Combine(Path.GetTempPath(),
                                $"test.NF_BaseYear_Calculation.v{selectedVersion.Version}.response.{logDate}.json"),
                            sResponse);
#endif

                        // Save results back down to database records.
                        jsonRootNF =
                            JsonVersioningBL.DeserializeNfBaseYearResponse(sResponse, baseYear.RateStartDate.Value);
                        sResponse = String.Empty;

                        // Clear out prior base year data.
                        RateBL.ClearBaseYear(baseYear);

                        RateBL.SaveNfBaseYear(baseYear, jsonRootNF, username, baseYearTypeEnum);
                        break;

                    case "ICF":
                        // Get the version ranges for Disallowance submission
                        ranges = RexRequestHelper.ParseInRuleAppVersionRanges(OHFISession
                            .DisallowanceInRuleAppVersions);
                        redDate = new DateTime(baseYear.Year, 7, 1);
                        RexVersionDateRange disallowanceVersion =
                            ranges.FirstOrDefault(x => x.DateFrom <= redDate && x.DateTo >= redDate);
                        if (disallowanceVersion == null)
                            disallowanceVersion = ranges.OrderBy(x => x.DateTo).LastOrDefault();
                        if (disallowanceVersion == null)
                            throw new Exception(
                                "Unable to select InRule Disallowance rule set version. Please check ARUM settings.");

                        ProjectSpecificDbContext db = RateBL.GetContextInstance();
                        OperationEngineIcfBaseYear engine = new OperationEngineIcfBaseYear(db, baseYearTypeEnum);

                        // Disallowance will need information from other providers type (only NF for now).
                        // Ensure that the engine has access to what they are for getting data.
                        engine.Classifications = ProjectsViewModel.CloneClassifications(new ProjectsViewModel.Projects().Classifications);
                        engine.Classifications = FilterClassifications(engine.Classifications, RetrieveSession.Classification.Type);
                       
                        engine.providerLists.AddRange(providerLists);
                        
                        ISubmissionData submitData = engine.GetData(baseYear.Year, baseYear.RateStartDate.Value,
                            ratePackages, engine.Classifications); // BaseYearSubmissionICF(baseYear, ratePackages);
                        IJsonInRuleDisallowanceSubmitICF submitDisallowance =
                            (IJsonInRuleDisallowanceSubmitICF)submitData;

                        if (submitDisallowance == null) return "No cost report data found for Base Year operation.";
                        submitDisallowance.PeerGroupMedians = null;
                        sJsonSubmission = submitDisallowance.Serialize();

#if DEBUG
                        System.IO.File.WriteAllText(
                            Path.Combine(Path.GetTempPath(),
                                $"test.ICF_BaseYear_Disallowance.v{disallowanceVersion.Version}.listing.{logDate}.json"),
                            sJsonSubmission);
#endif

                        // Call InRule specifying the rule set to use
                        sResponse = SubmitInRuleDataRuleset(OHFISession.DisallowanceInRuleApp,
                            disallowanceVersion.Version,
                            "Disallowances", sJsonSubmission, logDate, "BaseYearCall");
                        sJsonSubmission = String.Empty;

#if DEBUG
                        System.IO.File.WriteAllText(
                            Path.Combine(Path.GetTempPath(),
                                $"test.ICF_BaseYear_Disallowance.v{disallowanceVersion.Version}.response.{logDate}.json"),
                            sResponse);
#endif

                        // Save results back down to database records.
                        IJsonInRuleDisallowanceResponseICF jsonRootICFDis =
                            JsonVersioningBL.DeserializeIcfDisallowanceResponse(sResponse,
                                baseYear.RateStartDate.Value);
                        engine.ResponseData = jsonRootICFDis;
                        sResponse = String.Empty;

                        switch (baseYearTypeEnum)
                        {
                            case BaseYearTypeEnum.AdminCeiling:
                                // handle clearing and saving lookup and base year data.
                                engine.SaveDataAdminCeiling(baseYear, username);
                                break;

                            case BaseYearTypeEnum.Wh0Ceiling:
                                // handle clearing and saving lookup and base year data.
                                engine.SaveDataWh0Ceiling(baseYear, username);
                                break;

                            default:
                                // Create a base year submission object and assign the response values from disallowance needed.
                                IJsonInRuleBaseYearSubmitICF submitBaseYear =
                                    JsonVersioningBL.CreateBaseYearSubmitIcfByDate(baseYear.RateStartDate.Value);
                                submitBaseYear.RateYear = submitDisallowance.RateYear;
                                submitBaseYear.RuleParameters = submitDisallowance.RuleParameters;
                                submitBaseYear.RuleParametersByPeerGroup = submitDisallowance.RuleParametersByPeerGroup;

                                // Each provider needs to have the disallowance values updated in the provider objects.
                                foreach (IProviderICF provider in jsonRootICFDis.Providers)
                                {
                                    // Find the provider in the submission
                                    IProviderICF submitProvider =
                                        submitDisallowance.Providers.FirstOrDefault(x =>
                                            x.RatePackageId == provider.RatePackageId);
                                    if (submitProvider != null)
                                    {
                                        // Update the disallowance values from the disallowance response.
                                        submitProvider.DirectCostDisallowance = provider.DirectCostDisallowance;
                                        submitProvider.IndirectDisallowances = provider.IndirectDisallowances;
                                        submitProvider.TotalProratedOwnerandRelativeofOwnerCompensationAmount =
                                            provider.TotalProratedOwnerandRelativeofOwnerCompensationAmount;
                                        submitProvider.TotalIndividualOwnerDisallowance =
                                            provider.TotalIndividualOwnerDisallowance;
                                        submitProvider.IndirectOwnerAndRelativeOfOwnerCompensationDisallowanceAmount =
                                            provider.IndirectOwnerAndRelativeOfOwnerCompensationDisallowanceAmount;
                                        submitProvider.TotalCertifiedBedsAdminCeiling =
                                            provider.TotalCertifiedBedsAdminCeiling;
                                        submitProvider.BaseCompLimitAdminCeiling = provider.BaseCompLimitAdminCeiling;
                                        submitProvider.AllowPercentageAdminCeiling =
                                            provider.AllowPercentageAdminCeiling;
                                        submitProvider.OverallAdjustedBaseCompLimit =
                                            provider.OverallAdjustedBaseCompLimit;
                                        submitProvider.TotalFinalAdjustedProratedAdministerCompensationAmount =
                                            provider.TotalFinalAdjustedProratedAdministerCompensationAmount;
                                        submitProvider.TotalProratedAdministratorCompensationAmount =
                                            provider.TotalProratedAdministratorCompensationAmount;
                                        submitProvider.OverallAdministratorAggregateCompDisallowance =
                                            provider.OverallAdministratorAggregateCompDisallowance;
                                        submitProvider.IndirectAdministrativeCeiling =
                                            provider.IndirectAdministrativeCeiling;
                                        submitProvider.FinalOverallAdministratorCompDisallowance =
                                            provider.FinalOverallAdministratorCompDisallowance;
                                        submitProvider.TotalCalculatedDisallowanceAdjustments =
                                            provider.TotalCalculatedDisallowanceAdjustments;
                                        submitProvider.TotalDaysInTimeSlice = provider.TotalDaysInTimeSlice;
                                        submitProvider.TotalIndividualAdministratorCompDisallowance =
                                            provider.TotalIndividualAdministratorCompDisallowance;
                                    }
                                }

                                // Set the data to the base year submission object.
                                submitBaseYear.Providers = submitDisallowance.Providers;
                                submitBaseYear.C1Data = jsonRootICFDis.C1Data;
                                submitBaseYear.C2Data = jsonRootICFDis.C2Data;
                                submitBaseYear.C3Data = submitDisallowance.C3Data;
                                submitBaseYear.P2CeilingData = submitDisallowance.P2CeilingData;
                                submitBaseYear.OwnerCeilingData = submitDisallowance.OwnerCeilingData;
                                submitBaseYear.NonOwnerCeilingData = submitDisallowance.NonOwnerCeilingData;

                                // Set the WH0 Ceiling values returned (processed?) from disallowance response.
                                submitBaseYear.OwnerCompLimits = jsonRootICFDis.OwnerCompLimits;

                                // Set the Admin Ceiling values returned (processed?) from disallowance response.
                                submitBaseYear.CompLimit_0_49 = jsonRootICFDis.CompLimit_0_49;
                                submitBaseYear.CompLimit_50_99 = jsonRootICFDis.CompLimit_50_99;
                                submitBaseYear.CompLimit_100_149 = jsonRootICFDis.CompLimit_100_149;
                                submitBaseYear.CompLimit_150_Plus = jsonRootICFDis.CompLimit_150_Plus;

                                sJsonSubmission = submitBaseYear.Serialize();

#if DEBUG
                                System.IO.File.WriteAllText(
                                    Path.Combine(Path.GetTempPath(),
                                        $"test.ICF_BaseYear_Calculation.v{selectedVersion.Version}.listing.{logDate}.json"),
                                    sJsonSubmission);
#endif

                                // Call InRule just specifying the entity to use
                                sResponse = SubmitInRuleData(OHFISession.BaseYearInRuleApp, selectedVersion.Version,
                                    "BaseYear", sJsonSubmission, logDate);
                                sJsonSubmission = String.Empty;

#if DEBUG
                                System.IO.File.WriteAllText(
                                    Path.Combine(Path.GetTempPath(),
                                        $"test.ICF_BaseYear_Calculation.v{selectedVersion.Version}.response.{logDate}.json"),
                                    sResponse);
#endif

                                // Save results back down to database records.
                                jsonRootICF =
                                    JsonVersioningBL.DeserializeIcfBaseYearResponse(sResponse,
                                        baseYear.RateStartDate.Value);
                                sResponse = String.Empty;

                                // Clear out prior base year data.
                                RateBL.ClearBaseYear(db, baseYear);

                                RateBL.SaveIcfBaseYear(db, baseYear, jsonRootICF, username, baseYearTypeEnum);
                                break;
                        }

                        break;

                    default:
                        return "Provider type does not support Base Year operation.";
                }

                return $"Base Year information for {redDate.ToString("MM/dd/yyyy")} is set.";
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                throw;
            }
            finally
            {
                sJsonSubmission = String.Empty;
                sResponse = String.Empty;
            }
        }

        private string BaseYearSubmissionNF(BaseYear baseYear, List<RateSettingPackage.ProviderPackage> providers,
            List<RateSettingPackage> ratePackages, List<ProviderList> providerLists)
        {
            // This is possible because the submission ratePackage for Base Year is identical to Rate Setting
            // NOTE: We **DO** WANT TO SUPPRESS quality calculations here, we don't need them for base year medians.
            // The RED for base year is 7/1 of the base year + 1 - This will then use the values from the base year itself.
            // NOTE: providers list should not be necessary for base year processing.
            var nfProviders = providerLists.FirstOrDefault(x => x.Type == "NF").Providers;
            return RateBL.RateSettingSubmissionNF(baseYear.Year, baseYear.RateStartDate.Value,
                providers, ratePackages, new List<ProviderQualityCalculation>(),
                null, RateSettingOperations.BASEYEAR, nfProviders);
        }

        #endregion

        #region Rate Setting Submission
        /// <summary>
        /// Wrapper method to submit and receive rate information from service.
        /// </summary>
        /// <param name="year">Cost Report year for data.</param>
        /// <param name="redDate">RED date</param>
        /// <param name="providers">List of active provdiers from ARUM</param>
        /// <param name="ratePackages">All rate packages for the RED</param>
        /// <param name="providerQualityCalculations">Provider Quality calculation objects for the RED</param>
        /// <param name="userName">User name of the operator</param>
        /// <param name="providerRates">List of rates selected to be processed</param>
        /// <returns></returns>
        private List<ProviderRateResponseViewModel> RateSettingSubmission(int year, DateTime redDate,
            List<RateSettingPackage.ProviderPackage> providers, List<ProviderList> providerLists,
            List<RateSettingPackage> ratePackages,
            List<ProviderQualityCalculation> providerQualityCalculations, string userName,
            List<RatePackageViewModel> providerRates = null)
        {
            using (ProjectSpecificDbContext db = new ProjectSpecificDbContext(Functions.DatabaseConnection))
            {
                return RateSettingSubmission(db, year, redDate, providers, providerLists,
                    ratePackages, providerQualityCalculations, userName, providerRates);
            }
        }

        /// <summary>
        /// Wrapper method to submit and receive rate information from service.
        /// </summary>
        /// <param name="db">Database context specified to use.</param>
        /// <param name="year">Cost Report year for data.</param>
        /// <param name="redDate">RED date</param>
        /// <param name="providers">List of active provdiers from ARUM</param>
        /// <param name="providerLists">List of providers</param>
        /// <param name="ratePackages">All rate packages for the RED</param>
        /// <param name="providerQualityCalculations">Provider Quality calculation objects for the RED</param>
        /// <param name="userName">User name of the operator</param>
        /// <param name="providerRates">List of rates selected to be processed</param>
        /// <returns></returns>
        private List<ProviderRateResponseViewModel> RateSettingSubmission(ProjectSpecificDbContext db, int year, DateTime redDate,
            List<RateSettingPackage.ProviderPackage> providers, List<ProviderList> providerLists,
            List<RateSettingPackage> ratePackages,
            List<ProviderQualityCalculation> providerQualityCalculations, string userName,
            List<RatePackageViewModel> providerRates = null)
        {
            string logDate = $"{redDate.Year}{redDate.Month.ToString().PadLeft(2, '0')}{redDate.Day.ToString().PadLeft(2, '0')}";
            List<RexVersionDateRange> ranges = null;
            RexVersionDateRange selectedVersion = null;
            List<MSLC.ProviderProxy.Interfaces.Models.ChowReview> chows = null;

            try
            {
                ranges = RexRequestHelper.ParseInRuleAppVersionRanges(OHFISession.StandardRateSettingInRuleAppVersions);
                selectedVersion = ranges.FirstOrDefault(x => x.DateFrom <= redDate && x.DateTo >= redDate);
                if (selectedVersion == null) selectedVersion = ranges.OrderBy(x => x.DateTo).LastOrDefault();
                if (selectedVersion == null)
                    throw new Exception("Unable to select InRule rule set version. Please check ARUM settings.");
                ranges.Clear();

                List<ProviderRateResponseViewModel> responses = new List<ProviderRateResponseViewModel>();

                // We need to handle the numbers for the rate packages. Since we may have real and fake ones in
                // the array, but we use the Ids for reference, we need to ensure that the Ids are unique.
                // To ensure we differentiate between real and fake ones, fake ones will be a negative number.
                // NOTE: This will also ensure that rate packages with 4.2 or 4.8 cost report type are marked as CHOP rates.
                ratePackages = RateBL.VerifyRateCostReportsForRatePackages(ratePackages, userName);

                chows = new List<MSLC.ProviderProxy.Interfaces.Models.ChowReview>();

                // Set up responses...
                for (int i = ratePackages.Count - 1; i >= 0; i--)
                {
                    RateSettingPackage ratePackage = ratePackages[i];

                    // Flag to indicate if this rate is actually being saved/calculated, or if this
                    // rate package is required for pre-processing actions (disalloance, etc.).
                    bool skipRate = providerRates != null &&
                                    !providerRates.Any(x =>
                                        x.RatePackageId == ratePackage.RatePackageId.ToString());

                    ProviderRateResponseViewModel rateResponse = new ProviderRateResponseViewModel
                    {
                        RatePackageId = ratePackage.RatePackageId.ToString()
                    };

                    if (!skipRate && ratePackage.LockedDate.HasValue)
                    {
                        // Is there a rate value?
                        if (ratePackage.Rate.HasValue)
                        {
                            // If the ratePackage is already finalized, set the rate; we can't recalculate it.
                            rateResponse.RateAmount = ratePackage.Rate.Value;
                        }
                        else
                        {
                            // If there is no rate value, then there isn't much we can do with this. :(
                            AppendRateResponseMessage(rateResponse,
                                "Unable to set rate; rate is already finalized");
                        }
                    }

                    if (ratePackage.RateTypeId == (int)RateTypeEnumExtended.CHOP)
                    {
                        MSLC.ProviderProxy.Interfaces.IArumChowReviewChain arum_CHOP =
                            _providerServiceProxy.GetChowReviewChainByNewProviderID(
                                RetrieveSession.Classification.ARUMToken, ratePackage.Provider.ProviderId,
                                "Rate/Provider");
                        // Ensure, if there is CHOP data, that this is after the cost report end date - which would make this the "first" time the provider is rated, even if it is chopped later in the year.
                        MSLC.ProviderProxy.Interfaces.Models.ChowReview anyChopsBeforePeriodEnd = arum_CHOP
                            .ChowReviews
                            .FirstOrDefault(x => x.NewProviderID == ratePackage.Provider.ProviderId);

                        if (anyChopsBeforePeriodEnd != null)
                        {
                            chows.Add(anyChopsBeforePeriodEnd);
                        }
                        else
                        {
                            // If we are skipping this rate, this package doesn't need a response.
                            if (!skipRate)
                            {
                                // The CHOP information was not found; invalid CHOP information (date, provider, etc.).
                                ratePackages.Remove(ratePackage);
                                AppendRateResponseMessage(rateResponse, RateBL.sChopRateLockedMessage);
                                RateBL.UpdateRatePackageMessage(ratePackage.RatePackageId, rateResponse.Message);
                            }
                        }
                    }

                    // NOTE: Otherwise, we expect this rate to be calculated as normal.
                    // Even if rate package was removed, return the response.
                    if (!skipRate) responses.Add(rateResponse);
                }

                switch (SimplifiedType)
                {
                    case "NF":
                        // as there is no pre-processing, just rate the items.
                        if (providerRates != null)
                        {
                            ratePackages = ratePackages.Where(x =>
                                providerRates.Any(y => y.RatePackageId == x.RatePackageId.ToString())).ToList();
                        }

                        // NOTE: We WANT TO SUPPRESS quality calculations - we need to pass in what is provided from
                        //       the last quality calculation ("providerQualityCalculations", etc.).
                        if (ratePackages.Count > 0)
                        {
                            var nfProviders = providerLists.FirstOrDefault(x => x.Type == "NF").Providers;
                            string sJsonSubmission = RateBL.RateSettingSubmissionNF(db, year, redDate, providers, ratePackages,
                                providerQualityCalculations, chows, RateSettingOperations.RATESETTING, nfProviders);

                            if (string.IsNullOrWhiteSpace(sJsonSubmission)) return responses;

#if DEBUG
                            System.IO.File.WriteAllText(
                                Path.Combine(Path.GetTempPath(),
                                    $"test.NF_RateSetting_Calculation.v{selectedVersion.Version}.listing.{logDate}.json"),
                                sJsonSubmission);
#endif

                            string sResponse = SubmitInRuleData(OHFISession.StandardRateSettingInRuleApp,
                                selectedVersion.Version,
                                "NF_RateSetting_Calculation", sJsonSubmission, logDate);

#if DEBUG
                            System.IO.File.WriteAllText(
                                Path.Combine(Path.GetTempPath(),
                                    $"test.NF_RateSetting_Calculation.v{selectedVersion.Version}.response.{logDate}.json"),
                                sResponse);
#endif

                            IJsonInRuleRateSettingResponseNF jsonRoot =
                                JsonVersioningBL.DeserializeNfRateSettingResponse(sResponse, redDate);

                            RateBL.SaveNfRateSetting(db, redDate, jsonRoot, userName, responses);
                        }

                        break;

                    case "ICF":
                        if (ratePackages.Count > 0)
                        {
                            // Get the version ranges for Disallowance submission
                            ranges = RexRequestHelper.ParseInRuleAppVersionRanges(OHFISession
                                .DisallowanceInRuleAppVersions);
                            RexVersionDateRange disallowanceVersion =
                                ranges.FirstOrDefault(x => x.DateFrom <= redDate && x.DateTo >= redDate);
                            if (disallowanceVersion == null)
                                disallowanceVersion = ranges.OrderBy(x => x.DateTo).LastOrDefault();
                            if (disallowanceVersion == null)
                                throw new Exception(
                                    "Unable to select InRule Disallowance rule set version. Please check ARUM settings.");

                            OperationEngineIcfRateSetting engine = new OperationEngineIcfRateSetting(db);
                            // Disallowance will need information from other providers type (only NF for now).
                            // Ensure that the engine has access to what they are for getting data.

                            engine.Classifications = ProjectsViewModel.CloneClassifications(new ProjectsViewModel.Projects().Classifications);
                            //if (RetrieveSession.Classification.Type.Contains("_ProdRestore"))
                            engine.Classifications = FilterClassifications(engine.Classifications, RetrieveSession.Classification.Type);

                            engine.providerLists.AddRange(providerLists);

                            ISubmissionData submitData =
                                engine.GetData(year, redDate, ratePackages,
                                    engine.Classifications); // BaseYearSubmissionICF(baseYear, ratePackages);
                            //ISubmissionData submitData = engine.GetData(baseYear.Year, baseYear.RateStartDate.Value, ratePackages, engine.Classifications);
                            //ISubmissionData submitData = engine.GetData(baseYear.Year, baseYear.RateStartDate.Value, new List<RateSettingPackage.ProviderPackage>(), 
                            //    ratePackages, new List<MSLC.ProviderProxy.Interfaces.Models.ChowReview>(), engine.Classifications);
                            IJsonInRuleDisallowanceSubmitICF submitDisallowance = (IJsonInRuleDisallowanceSubmitICF)submitData;

                            if (submitDisallowance == null) return responses;
                            List<IProviderICF> nonCostReportProviders = submitDisallowance.Providers.ToList()
                                .Where(x => x.RateCostReportId == "0").ToList();
                            // Set those rates without cost reports to the side for now.
                            submitDisallowance.Providers = submitDisallowance.Providers.Except(nonCostReportProviders).ToArray();

                            IJsonInRuleDisallowanceResponseICF jsonRootICFDis;
                            if (submitDisallowance.Providers.Count() > 0)
                            {
                                string sJsonSubmission = submitDisallowance.Serialize();

#if DEBUG
                                System.IO.File.WriteAllText(
                                    Path.Combine(Path.GetTempPath(),
                                        $"test.ICF_RateSetting_Disallowance.v{disallowanceVersion.Version}.listing.{logDate}.json"),
                                    sJsonSubmission);
#endif

                                // Call InRule specifying the rule set to use
                                string sResponse = SubmitInRuleDataRuleset(OHFISession.DisallowanceInRuleApp,
                                    disallowanceVersion.Version,
                                    "Disallowances", sJsonSubmission, logDate, "RateSettingCall");

#if DEBUG
                                System.IO.File.WriteAllText(
                                    Path.Combine(Path.GetTempPath(),
                                        $"test.ICF_RateSetting_Disallowance.v{disallowanceVersion.Version}.response.{logDate}.json"),
                                    sResponse);
#endif

                                // Save results back down to database records.
                                jsonRootICFDis =
                                    JsonVersioningBL.DeserializeIcfDisallowanceResponse(sResponse, redDate);
                                engine.ResponseData = jsonRootICFDis;
                            }
                            else
                            {
                                jsonRootICFDis = (IJsonInRuleDisallowanceResponseICF)submitDisallowance;
                            }

                            // Create a base year submission object and assign the response values from disallowance needed.
                            IJsonInRuleRateSettingSubmitICF submitRateSetting = JsonVersioningBL.CreateRateSettingSubmitIcfByDate(redDate);
                            submitRateSetting.RateYear = submitDisallowance.RateYear;
                            submitRateSetting.RuleParameters = submitDisallowance.RuleParameters;
                            submitRateSetting.RuleParametersByPeerGroup = submitDisallowance.RuleParametersByPeerGroup;

                            // Collect back together all that we need to work on.
                            if (nonCostReportProviders.Any())
                            {
                                submitDisallowance.Providers = submitDisallowance.Providers
                                    .Concat(nonCostReportProviders)
                                    .ToArray();
                            }

                            // Filter out only what we need to deal with for rate setting.
                            if (providerRates != null && providerRates.Count > 0)
                            {
                                submitDisallowance.Providers = submitDisallowance.Providers
                                    .Where(x => providerRates.Any(r => r.RatePackageId == x.RatePackageId.ToString()))
                                    .ToArray();
                            }

                            // Pull the disallowance values for just the rates we are setting.
                            foreach (IProviderICF submitProvider in submitDisallowance.Providers)
                            {
                                RateSettingPackage ratePackage =
                                    ratePackages.FirstOrDefault(x => x.RatePackageId == submitProvider.RatePackageId);
                                if (ratePackage != null)
                                {
                                    // If the rate is already locked, we don't need to rate set - it will not be added!
                                    if (ratePackage.LockedDate.HasValue) continue;
                                    // This provider will have a rate set - update provider specific information from disallowance results
                                    IProviderICF item = jsonRootICFDis.Providers.FirstOrDefault(x =>
                                        x.RatePackageId == submitProvider.RatePackageId);
                                    if (item != null)
                                    {
                                        submitProvider.DirectCostDisallowance = item.DirectCostDisallowance;
                                        submitProvider.IndirectDisallowances = item.IndirectDisallowances;
                                        submitProvider.TotalProratedOwnerandRelativeofOwnerCompensationAmount =
                                            item.TotalProratedOwnerandRelativeofOwnerCompensationAmount;
                                        submitProvider.TotalIndividualOwnerDisallowance =
                                            item.TotalIndividualOwnerDisallowance;
                                        submitProvider.IndirectOwnerAndRelativeOfOwnerCompensationDisallowanceAmount =
                                            item.IndirectOwnerAndRelativeOfOwnerCompensationDisallowanceAmount;
                                        submitProvider.TotalCertifiedBedsAdminCeiling =
                                            item.TotalCertifiedBedsAdminCeiling;
                                        submitProvider.BaseCompLimitAdminCeiling = item.BaseCompLimitAdminCeiling;
                                        submitProvider.AllowPercentageAdminCeiling = item.AllowPercentageAdminCeiling;
                                        submitProvider.OverallAdjustedBaseCompLimit = item.OverallAdjustedBaseCompLimit;
                                        submitProvider.TotalFinalAdjustedProratedAdministerCompensationAmount =
                                            item.TotalFinalAdjustedProratedAdministerCompensationAmount;
                                        submitProvider.TotalProratedAdministratorCompensationAmount =
                                            item.TotalProratedAdministratorCompensationAmount;
                                        submitProvider.OverallAdministratorAggregateCompDisallowance =
                                            item.OverallAdministratorAggregateCompDisallowance;
                                        submitProvider.IndirectAdministrativeCeiling =
                                            item.IndirectAdministrativeCeiling;
                                        submitProvider.FinalOverallAdministratorCompDisallowance =
                                            item.FinalOverallAdministratorCompDisallowance;
                                        submitProvider.TotalCalculatedDisallowanceAdjustments =
                                            item.TotalCalculatedDisallowanceAdjustments;
                                        submitProvider.TotalDaysInTimeSlice = item.TotalDaysInTimeSlice;
                                        submitProvider.TotalIndividualAdministratorCompDisallowance =
                                            item.TotalIndividualAdministratorCompDisallowance;
                                    }

                                    submitRateSetting.AddProvider(submitProvider);
                                }
                            }

                            // Add the quality information for this period to the rate setting submission object.
                            engine.GetQualityData(submitRateSetting);
                            submitRateSetting.PeerGroupMedians = submitDisallowance.PeerGroupMedians;

                            // Copy over data from disallowance submission/response
                            submitRateSetting.C1Data = jsonRootICFDis.C1Data;
                            submitRateSetting.C2Data = jsonRootICFDis.C2Data;
                            submitRateSetting.C3Data = submitDisallowance.C3Data;
                            submitRateSetting.P2CeilingData = submitDisallowance.P2CeilingData;
                            submitRateSetting.OwnerCeilingData = submitDisallowance.OwnerCeilingData;
                            submitRateSetting.NonOwnerCeilingData = submitDisallowance.NonOwnerCeilingData;

                            // Add in the WH0 Ceiling values
                            submitRateSetting.OwnerCompLimits = jsonRootICFDis.OwnerCompLimits;

                            // Add in the Admin Ceiling values.
                            submitRateSetting.CompLimit_0_49 = jsonRootICFDis.CompLimit_0_49;
                            submitRateSetting.CompLimit_50_99 = jsonRootICFDis.CompLimit_50_99;
                            submitRateSetting.CompLimit_100_149 = jsonRootICFDis.CompLimit_100_149;
                            submitRateSetting.CompLimit_150_Plus = jsonRootICFDis.CompLimit_150_Plus;

                            if (submitRateSetting.Providers.Any())
                            {
                                // Serialize for submission to InRule
                                string sJsonSubmission = submitRateSetting.Serialize();

#if DEBUG
                                System.IO.File.WriteAllText(
                                    Path.Combine(Path.GetTempPath(),
                                        $"test.ICF_RateSetting_Calculation.v{selectedVersion.Version}.listing.{logDate}.json"),
                                    sJsonSubmission);
#endif

                                // Call InRule just specifying the entity to use
                                string sResponse = SubmitInRuleData(OHFISession.StandardRateSettingInRuleApp,
                                    selectedVersion.Version,
                                    "RateSetting", sJsonSubmission, logDate);

#if DEBUG
                                System.IO.File.WriteAllText(
                                    Path.Combine(Path.GetTempPath(),
                                        $"test.ICF_RateSetting_Calculation.v{selectedVersion.Version}.response.{logDate}.json"),
                                    sResponse);
#endif

                                IJsonInRuleRateSettingResponseICF jsonRootIcf =
                                    JsonVersioningBL.DeserializeIcfRateSettingResponse(sResponse, redDate);

                                RateBL.SaveIcfRateSetting(db, redDate, jsonRootIcf, userName, responses);
                            }
                        }

                        break;

                    default:
                        return responses;
                }

                return responses;
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                throw;
            }
        }

        /// <summary>
        /// Submit the specified submission ratePackage to the REX/InRule service. Request
        /// execution of the specified entity ruleSet and version.
        /// </summary>
        /// <param name="appName"></param>
        /// <param name="version"></param>
        /// <param name="entityName"></param>
        /// <param name="submission"></param>
        /// <returns></returns>
        /// <exception cref="HttpException"></exception>
        private string SubmitInRuleDataRuleset(string appName, int version, string entityName, string submission,
            string logDate = null, string ruleSetName = "RuleSet1")
        {
            return SubmitInRuleCall(OHFISession.RexInRuleServerUrl, OHFISession.RexInRuleServerApiPathRuleSet, appName,
                version, entityName, submission, logDate, ruleSetName);
        }

        /// <summary>
        /// Submit the specified submission ratePackage to the REX/InRule service. Request
        /// execution of the specified entity ruleSet and version.
        /// </summary>
        /// <param name="appName"></param>
        /// <param name="version"></param>
        /// <param name="entityName"></param>
        /// <param name="submission"></param>
        /// <returns></returns>
        /// <exception cref="HttpException"></exception>
        private string SubmitInRuleData(string appName, int version, string entityName, string submission,
            string logDate = null)
        {
            return SubmitInRuleCall(OHFISession.RexInRuleServerUrl, OHFISession.RexInRuleServerApiPath, appName,
                version, entityName, submission, logDate);
        }

        private string SubmitInRuleCall(string serverUrl, string serverApiPath, string appName, int version,
            string entityName, string submission, string logDate = null, string ruleSetName = "RuleSet1")
        {
            string sEncoded;
            try
            {
                JavaScriptSerializer serializer = new JavaScriptSerializer
                {
                    MaxJsonLength = Int32.MaxValue
                };

                sEncoded = serializer.Serialize(submission);
                sEncoded = sEncoded.Substring(1);
                sEncoded = sEncoded.Substring(0, sEncoded.Length - 1);

                // Add the REX request JSON wrapper
                var httpContent = new StringContent(
                    RexRequestHelper.RexRequestJsonWrapper(appName, version, sEncoded, entityName, ruleSetName),
                    Encoding.UTF8, "application/json");

#if DEBUG
                if (logDate != null)
                {
                    System.IO.File.WriteAllText(
                        Path.Combine(Path.GetTempPath(),
                            $"test.{appName}.{entityName}.v{version}.submission.{logDate}.json"),
                        RexRequestHelper.RexRequestJsonWrapper(appName, version, sEncoded, entityName, ruleSetName));
                }
#endif

                // Submit to InRule/REX here
                HttpClientAsyncWrapper rexClient = new HttpClientAsyncWrapper();
                HttpResponseMessage resResponse = rexClient.PostRequest(serverUrl + serverApiPath, httpContent);

                // Handle responses here.
                if (!resResponse.IsSuccessStatusCode)
                {
                    // we did not get a successful request.
                    string s = rexClient.GetResponseString(resResponse);
                    throw new HttpException((int)resResponse.StatusCode, "Error retrieving InRule responses: " + s);
                }

                string sResponse = rexClient.GetResponseString(resResponse);

                // Clean up the responses string - remove execution fluff.
                if (sResponse.IndexOf(",\"Execution\":{") > -1)
                    sResponse = sResponse.Substring(0, sResponse.IndexOf(",\"Execution\":{")) + "}";

                return sResponse;
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                throw;
            }
            finally
            {
                sEncoded = null;
            }
        }

        private string GetNfArumProviderCounty(int providerId)
        {
            MSLC.ProviderProxy.Interfaces.IArumDetailedProvider arum_provider =
                _providerServiceProxy.GetProviderInfoByARUMProviderID(RetrieveSession.Classification.ARUMToken,
                    providerId, "Rate/Provider");

            if (arum_provider != null)
            {
                string countyCode = string.Empty;
                if (arum_provider.EffectiveDates != null && arum_provider.EffectiveDates.Count > 0)
                {
                    DateTime? effectiveDate = arum_provider.EffectiveDates.OrderByDescending(ED => ED.EffectiveDate)
                        .Select(x => x.EffectiveDate).FirstOrDefault();
                    countyCode = arum_provider.EffectiveDates.Select(x => x.County).FirstOrDefault();
                }

                string countyName =
                    arum_provider.ProviderAttributes.FirstOrDefault(i => i.AttributeKey == "Phys_County_Desc") != null
                        ? arum_provider.ProviderAttributes.FirstOrDefault(i => i.AttributeKey == "Phys_County_Desc")
                            .AttributeValue
                        : string.Empty;

                return countyName ?? countyCode;
            }

            return string.Empty;
        }

        private decimal GetNFInitialRate(ProjectSpecificDbContext db, DateTime redDate, int providerId,
            List<MedianData> ancillaryMedians, List<MedianData> capitalMedians, List<MedianData> directCareMedians)
        {
            decimal returnAmount = 0;

            try
            {
                // Get county and bed count so we can get the peer group
                string county = GetNfArumProviderCounty(providerId);
                if (string.IsNullOrWhiteSpace(county)) return returnAmount;
                int certifiedBeds = RateBL.GetCertifiedBeds(providerId).FirstOrDefault()?.Total ?? 0;

                // Get the peer groups
                string ancillaryPG = RateBL.GetNfPeerGroupAncillaryByCounty("OH", county, certifiedBeds);
                string directCarePG = RateBL.GetNfPeerGroupDirectCareByCounty("OH", county, certifiedBeds);

                // Get the median values for each component for the appropriate peer group
                string peerGroupA = $"Ancillary_{ancillaryPG}";
                string peerGroupC = $"Capital_{ancillaryPG}";
                string peerGroupDC = $"DirectCare_{directCarePG}";

                string ancillaryAmountString =
                    ancillaryMedians
                        .FirstOrDefault(x => x.PeerGroup.StartsWith(peerGroupA) && x.MedianName == "FinalGroupPrice")
                        ?.MedianValue ?? "0";
                if (string.IsNullOrWhiteSpace(ancillaryAmountString)) ancillaryAmountString = "0";
                string capitalAmountString =
                    capitalMedians
                        .FirstOrDefault(x => x.PeerGroup.StartsWith(peerGroupC) && x.MedianName == "FinalGroupPrice")
                        ?.MedianValue ?? "0";
                if (string.IsNullOrWhiteSpace(capitalAmountString)) capitalAmountString = "0";
                string directCareAmountString =
                    directCareMedians
                        .FirstOrDefault(x => x.PeerGroup.StartsWith(peerGroupDC) && x.MedianName == "FinalGroupPrice")
                        ?.MedianValue ?? "0";
                if (string.IsNullOrWhiteSpace(directCareAmountString)) directCareAmountString = "0";
                string capitalTaxString =
                    capitalMedians
                        .FirstOrDefault(x => x.PeerGroup.StartsWith(peerGroupC) && x.MedianValue == "MedianTaxRate")
                        ?.MedianValue ?? "0";
                if (string.IsNullOrEmpty(capitalTaxString)) capitalTaxString = "0";

                // Convert values to amounts and add them together
                if (decimal.TryParse(ancillaryAmountString, out decimal ancillaryAmount))
                    returnAmount += ancillaryAmount;
                if (decimal.TryParse(capitalAmountString, out decimal capitalAmount)) returnAmount += capitalAmount;
                if (decimal.TryParse(directCareAmountString, out decimal directCareAmount))
                    returnAmount += directCareAmount;
                if (decimal.TryParse(capitalTaxString, out decimal capitalTaxAmout)) returnAmount += capitalTaxAmout;
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                returnAmount = 0;
            }

            return returnAmount;
        }

        private decimal GetICFInitialRate(ProjectSpecificDbContext db, DateTime redDate, int providerId,
            List<MedianData> ancillaryMedians, List<MedianData> capitalMedians, List<MedianData> directCareMedians)
        {
            decimal returnAmount = 0;

            try
            {
                // Get county and bed count so we can get the peer group
                string county = GetNfArumProviderCounty(providerId);
                if (string.IsNullOrWhiteSpace(county)) return returnAmount;
                int certifiedBeds = RateBL.GetCertifiedBeds(providerId).FirstOrDefault()?.Total ?? 0;

                string providerNumber =
                    db.RateProviders.FirstOrDefault(x => x.ProviderId == providerId)?.ProviderNumber;
                List<DatabaseLookupValue> dbLookups = db.DatabaseLookupValues.AsNoTracking()
                    .Where(x => x.StartDate <= redDate && (x.EndDate == null || redDate <= x.EndDate))
                    .ToList();

                string peerGroup = RateBL.GetIcfPeerGroup(certifiedBeds, dbLookups, providerNumber);

                // Get the median values for each component for the appropriate peer group
                string peerGroupA = $"Ancillary_{peerGroup}";
                string peerGroupC = $"Capital_{peerGroup}";
                string peerGroupDC = $"DirectCare_{peerGroup}";

                // Get the median values for each component for the appropriate peer group
                string ancillaryAmountString = ancillaryMedians
                    .FirstOrDefault(x => x.PeerGroup.StartsWith(peerGroupA) && x.MedianName == "FinalGroupPrice")
                    ?.MedianValue;
                if (string.IsNullOrWhiteSpace(ancillaryAmountString)) ancillaryAmountString = "0";
                string capitalAmountString = capitalMedians
                    .FirstOrDefault(x => x.PeerGroup.StartsWith(peerGroupC) && x.MedianName == "FinalGroupPrice")
                    ?.MedianValue;
                if (string.IsNullOrWhiteSpace(capitalAmountString)) capitalAmountString = "0";
                string directCareAmountString = directCareMedians
                    .FirstOrDefault(x => x.PeerGroup.StartsWith(peerGroupDC) && x.MedianName == "FinalGroupPrice")
                    ?.MedianValue;
                if (string.IsNullOrWhiteSpace(directCareAmountString)) directCareAmountString = "0";

                // Convert values to amounts and add them together
                if (decimal.TryParse(ancillaryAmountString, out decimal ancillaryAmount))
                    returnAmount += ancillaryAmount;
                if (decimal.TryParse(capitalAmountString, out decimal capitalAmount)) returnAmount += capitalAmount;
                if (decimal.TryParse(directCareAmountString, out decimal directCareAmount))
                    returnAmount += directCareAmount;
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                returnAmount = 0;
            }

            return returnAmount;
        }

