        private BaseYearViewModel GetBaseYearModel(BaseYearTypeEnum baseYearTypeEnum)
        {
            BaseYearViewModel baseYearViewModel = new BaseYearViewModel();
            var dates = RateBL.GetBaseYearList(baseYearTypeEnum);
            var yearList = new List<SelectListItem>();
            foreach (var date in dates)
            {
                string rateStartDate = date.RateStartDate.HasValue
                    ? date.RateStartDate.Value.ToString("MM/dd/yyyy")
                    : string.Empty;

                yearList.Add(new SelectListItem
                {
                    Text = date.Year.ToString() + " - " + rateStartDate,
                    Value = ClientMapping.MapInternalIdToClientId(date.BaseYearId.ToString(), "baseyear"),
                });
            }

            baseYearViewModel.FiscalYearList = yearList;
            baseYearViewModel.BaseYearTypeEnum = baseYearTypeEnum.ToString();
            baseYearViewModel.HeaderText = baseYearTypeEnum.GetDescription();
            baseYearViewModel.DateType = BaseYearTypeEnumExtended.GetDateType(baseYearTypeEnum).GetDateMnemonic();
            baseYearViewModel.AllowExcelExport = true;

            return baseYearViewModel;
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult GetBaseYearInfo(string fiscalYearId)
        {
            // Grid Data
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;

            if (!int.TryParse(ClientMapping.GetInternalIdFromClientId(fiscalYearId, "baseyear"), out int baseYearId))
                return Json(new { Success = false }, JsonRequestBehavior.AllowGet);

            BaseYear by = RateBL.GetBaseYearById(baseYearId);
            BaseYearTypeEnum byType = BaseYearTypeEnumExtended.GetEnumeration(by.BaseYearType);
            switch (byType)
            {
                case BaseYearTypeEnum.Wh0Ceiling:
                    BaseYearDGViewModel model = GetBaseYearDGModel(byType);
                    DatabaseLookupGroupViewModel dataModel = GetDatabaseLookupGroupViewModel(by.RateStartDate.Value,
                        AnnualRateSettingEnum.Wh0Ceiling, by.Year);
                    model.DataModel = dataModel.DataModel;
                    model.GridColumns = dataModel.GridColumns;
                    model.GridColumnValidations = dataModel.GridColumnValidations;

                    return Json(new { Success = true, BaseYearDGViewModel = model }, JsonRequestBehavior.AllowGet);

                default:
                    return Json(new { Success = true, BaseYearGridViewModel = GetBaseYearCollection(baseYearId) },
                        JsonRequestBehavior.AllowGet);
            }
        }

        public List<BaseYearGridViewModel> GetBaseYearCollection(int baseYearId)
        {
            var medianDataList = RateBL.GetBaseYearInfo(baseYearId).OrderBy(b => b.MedianName + b.PeerGroup);
            List<BaseYearGridViewModel> listBaseYearViewModel = new List<BaseYearGridViewModel>();
            foreach (var data in medianDataList)
            {
                listBaseYearViewModel.Add(new BaseYearGridViewModel
                {
                    MedianDataId = ClientMapping.MapInternalIdToClientId(data.MedianDataId.ToString(), "mediandata"),
                    PeerGroup = data.PeerGroup,
                    MedianName = data.MedianName,
                    MedianValue = data.MedianValue,
                });
            }

            return listBaseYearViewModel;
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult AddBaseYear(string baseYear, DateTime rateStartDate, BaseYearTypeEnum baseYearTypeEnum)
        {
            try
            {
                MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;

                // Accommodate issues with time zones
                rateStartDate = new DateTime(rateStartDate.Year, rateStartDate.Month, rateStartDate.Day);

                if (!int.TryParse(baseYear, out int b)) throw new Exception("Invalid year, please try again.");

                // Get or create the base year record for this year value.
                BaseYear by = RateBL.AddBaseYear(b, rateStartDate, baseYearTypeEnum,
                    $"{myUser.FirstName} {myUser.LastName}");

                if (by == null)
                {
                    return Json(new
                    { Success = false, Message = "Invalid data; unable to create base year - please try again." });
                }

                switch (baseYearTypeEnum)
                {
                    case BaseYearTypeEnum.Wh0Ceiling:
                        return Json(new { Success = true, BaseYearDGViewModel = GetBaseYearDGModel(baseYearTypeEnum) },
                            JsonRequestBehavior.AllowGet);
                    case BaseYearTypeEnum.AdminCeiling:
                        return Json(
                            new { Success = true, BaseYearLookupViewModel = GetBaseYearLookupModel(baseYearTypeEnum) },
                            JsonRequestBehavior.AllowGet);
                    default:
                        return Json(new { Success = true, BaseYearViewModel = GetBaseYearModel(baseYearTypeEnum) },
                            JsonRequestBehavior.AllowGet);
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
        }

