                    return BaseYearsAncillaryNfExportExcel(baseYear, rateEffectiveDate);
                case nameof(BaseYearTypeEnum.DirectCare):
                    return BaseYearsDirectCareNfExportExcel(baseYear, rateEffectiveDate);
                case nameof(BaseYearTypeEnum.Capital):
                    return BaseYearsCapitalNfExportExcel(baseYear, rateEffectiveDate);
                case nameof(BaseYearTypeEnum.Tax): return BaseYearsTaxNfExportExcel(baseYear, rateEffectiveDate);
                case nameof(BaseYearTypeEnum.DirectCareCost):
                    return BaseYearsDirectCareCostICFExportExcel(baseYear, rateEffectiveDate);
                case nameof(BaseYearTypeEnum.IndirectCareCost):
                    return BaseYearsInDirectCareCostICFExportExcel(baseYear, rateEffectiveDate);
                case nameof(BaseYearTypeEnum.ProtectedCost):
                    return BaseYearsProtectedRateICFExportExcel(baseYear, rateEffectiveDate);
                case nameof(BaseYearTypeEnum.Wh0Ceiling):
                    return BaseYearsWh0CeilingICFExportExcel(baseYear, rateEffectiveDate);
                case nameof(BaseYearTypeEnum.CapitalCost):
                    return BaseYearsCapitalIcfExportExcel(baseYear, rateEffectiveDate);
                default:
                    return Json(new { Success = false, Message = "Report is not available for this base year." });
            }
        }

        //[ARUMFeatureActionFilter("RateSetting:View")]
        private ActionResult BaseYearsAncillaryNfExportExcel(int baseYear, string rateEffectiveDate)
        {
            try
            {
                Dictionary<string, string> fieldsToPrint_Ancillary = new Dictionary<string, string>
                {
                    // Tab 1
                    { "PeerGroup", "Peer Group" },
                    { "AncillaryCost__C14515", "Ancillary Cost" },
                    { "AncillaryCalculatedPerDiem", "Calculated Per Diem" },
                    { "AncillaryPeerGroup_StandardDeviation", "Standard Deviation" },
                    { "AncillaryPeerGroup_Mean", "Mean" },
                    {
                        "AncillaryCalculatedPerDiemForRateSetting",
                        "Allowable Calculated Per Diem for use in Rate Setting"
                    },
                    {
                        "AncillaryPeerGroup_Calced25thPercentile",
                        "25th Percentile of the Ancillary Per Day Population (No Outliers)"
                    },
                    { "AncillaryPeerGroup_FinalGroupPrice", "Final Price" },
                    { "BedDaysForAncillary_CapitalUse__C10115", "Days" },
                    { "ProviderNumber", "Provider Number" },
                    { "ProviderName", "Provider Name" },
                    { "CostReportYearBegin", "CostReportBeginDate" },
                    { "CostReportYearEnd", "CostReportEndDate" },
                    { "AncillaryPerDiemRanking", "AncillaryPerDiemRanking" },
                };

                //Retrieving base year calculation set
                CalculationSet calculationSet = RedDateBL.GetBaseYearCalculationSet(new DateTime(baseYear, 12, 31));
                var baseYearId = RateBL.GetBaseYearId(baseYear, BaseYearTypeEnum.Ancillary);

                //Get CalculationResult table records
                var rateEffectiveDt = ConvertToDateTime(rateEffectiveDate);
                var calculatedData = RateBL.GetBaseYearCalculationResultData(baseYear, rateEffectiveDt,
                    nameof(BaseYearTypeEnum.Ancillary), (int)calculationSet.Type);
                //Getting the ProviderList from the calculatedData
                var providerNumbers = calculatedData.Select(x => x.ProviderNumber).Distinct().OrderBy(x => x).ToList();

                //Getting median data based on base year
                var medianDataList = RateBL.GetBaseYearInfo(baseYearId);
                //Output file name
                string fileName = string.Format(@"Ancillary Prices Report.xlsx");
                MedianReportData reportData;

                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;
                    IWorkbook workbook = application.Workbooks.Create(1);

                    var worksheet = workbook.Worksheets[0];

                    int rowCount = 1;
                    int column = 1;

                    worksheet.Range[rowCount, column].Text = "Provider Number";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

