                        "25th Percentile of the Ancillary Per Day Population (No Outliers)";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;


                    worksheet.Range[rowCount, column].Text = "Final Price";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

                    worksheet.Range[rowCount, column].Text = "Used in Base Year";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);

                    foreach (var providerNumber in providerNumbers)
                    {
                        column = 1;

                        //Retrieving the data for specific provider
                        var calculatedProvData = calculatedData.Where(x => x.ProviderNumber == providerNumber).ToList();

                        reportData = new MedianReportData();
                        foreach (var calcData in calculatedProvData)
                        {
                            var calcKey = calcData.KeyName;

                            if (fieldsToPrint_Ancillary.ContainsKey(calcKey))
                            {
                                if (calcKey == "PeerGroup")
                                {
                                    //Ancillary
                                    reportData.AncillaryPeerGroup_StandardDeviation = medianDataList.Where(x =>
                                            x.PeerGroup.StartsWith("Ancillary_" + calcData.Value)
                                            && x.MedianName == "StandardDeviation")
                                        .Select(x => x.MedianValue).FirstOrDefault();
                                    reportData.AncillaryPeerGroup_Mean = medianDataList.Where(x =>
                                            x.PeerGroup.StartsWith("Ancillary_" + calcData.Value)
                                            && x.MedianName == "Mean")
                                        .Select(x => x.MedianValue).FirstOrDefault();
                                    reportData.AncillaryPeerGroup_Calced25thPercentile = medianDataList.Where(x =>
                                            x.PeerGroup.StartsWith("Ancillary_" + calcData.Value)
                                            && x.MedianName == "Calced25thPercentile")
                                        .Select(x => x.MedianValue).FirstOrDefault();
                                    reportData.AncillaryPeerGroup_FinalGroupPrice = medianDataList.Where(x =>
                                            x.PeerGroup.StartsWith("Ancillary_" + calcData.Value)
                                            && x.MedianName == "FinalGroupPrice")
                                        .Select(x => x.MedianValue).FirstOrDefault();
                                }

                                switch (calcKey)
                                {
                                    case "ProviderNumber":
                                        reportData.ProviderNumber = calcData.Value;
                                        break;
                                    case "ProviderName":
                                        reportData.ProviderName = calcData.Value;
                                        break;
                                    case "CostReportYearBegin":
                                        reportData.CostReportBeginDate = Convert.ToDateTime(calcData.Value);
                                        break;
                                    case "CostReportYearEnd":
                                        reportData.CostReportEndDate = Convert.ToDateTime(calcData.Value);
                                        break;
                                    case "PeerGroup":
                                        reportData.PeerGroup = calcData.Value;
                                        break;
                                    case "AncillaryCost__C14515":
                                        reportData.AncillaryCost__C14515 = calcData.Value;
                                        break;
                                    case "CapitalCost__C14195":
                                        reportData.CapitalCost__C14195 = calcData.Value;
                                        break;
                                    case "DirectCareCost__C14055":
                                        reportData.DirectCareCost__C14055 = calcData.Value;
                                        break;
                                    case "BedDaysForAncillary_CapitalUse__C10115":
                                        reportData.BedDaysForAncillary_CapitalUse__C10115 = calcData.Value;
                                        break;
                                    case "AncillaryCalculatedPerDiem":
                                        reportData.AncillaryCalculatedPerDiem = calcData.Value;
                                        break;
                                    case "AncillaryCalculatedPerDiemForRateSetting":
                                        reportData.AncillaryCalculatedPerDiemForRateSetting = calcData.Value;
                                        break;
                                    case "AncillaryPeerGroup_Calced25thPercentile":
                                        reportData.AncillaryPeerGroup_Calced25thPercentile = calcData.Value;
                                        break;
                                    case "AncillaryPeerGroup_FinalGroupPrice":
                                        reportData.AncillaryPeerGroup_FinalGroupPrice = calcData.Value;
                                        break;
                                    case "AncillaryPerDiemRanking":
                                        reportData.AncillaryPerDiemRanking = calcData.Value;
                                        break;
                                }
                            }
                        }

                        rowCount++;

                        worksheet.Range[rowCount, column].Text = reportData.ProviderNumber;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.ProviderName;
                        column++;
                        // Tab 1
                        worksheet.Range[rowCount, column].Text = reportData.CostReportBeginDate?.ToShortDateString();
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.CostReportEndDate?.ToShortDateString();
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.PeerGroup;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.AncillaryCost__C14515;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.BedDaysForAncillary_CapitalUse__C10115;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.AncillaryCalculatedPerDiem;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.AncillaryPeerGroup_StandardDeviation;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.AncillaryPeerGroup_Mean;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.AncillaryCalculatedPerDiemForRateSetting;
                        column++;
                        worksheet.Range[rowCount, column].Text =
                            reportData
                                .AncillaryPerDiemRanking; // Ranking of Allowable Calculated per diem by Peer Group
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.AncillaryPeerGroup_Calced25thPercentile;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.AncillaryPeerGroup_FinalGroupPrice;
                        //column++;
                        //worksheet.Range[rowCount, column].Text = provider.IsBaseYear ? "Y" : "N";
                    }

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;
                    string fullPath;

                    fullPath = Path.Combine(Path.GetTempPath(), fileName);
                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                }

                return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message });
            }
        }

