                        worksheet.Range[rowCount, column].Text = reportData.DirectCareCost__C14055;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.DirectCareBedDays__10460;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.DirectCareCalculatedPerDiem;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.DirectCareAnnualCMI; // Annual CMI
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.DirectCareNormalizedCost;
                        column++;
                        worksheet.Range[rowCount, column].Text =
                            reportData.DirectPeerGroup_StandardDeviation; // Standard Deviation
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.DirectPeerGroup_Mean; // Mean
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.DirectCarePerDiemForMedians;
                        column++;
                        worksheet.Range[rowCount, column].Text =
                            reportData
                                .DirectCarePerDiemRanking; //Ranking of Allowable Calculated per Diem by Peer Group
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.DirectCareRankingForPercentile;
                        //column++;
                        //worksheet.Range[rowCount, column].Text = provider.IsBaseYear ? "Y" : "N";
                    }

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;
                    string fullPath;

                    fullPath = Path.Combine(Path.GetTempPath(), fileName);
                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                }

                return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message });
            }
        }

        //[ARUMFeatureActionFilter("RateSetting:View")]
        private ActionResult BaseYearsTaxNfExportExcel(int baseYear, string rateEffectiveDate)
        {
            try
            {
                Dictionary<string, string> fieldsToPrint_Tax = new Dictionary<string, string>
                {
                    { "PeerGroup", "Peer Group" },
                    { "ProviderNumber", "Provider Number" },
                    { "ProviderName", "Provider Name" },
                    { "CostReportYearBegin", "CostReportBeginDate" },
                    { "CostReportYearEnd", "CostReportEndDate" },
                    // Tab 4
                    { "TotalBedDaysAvailable__10440", "TotalBedDaysAvailable__10440" },
                    { "TaxCostSum", "TaxCostSum" },
                    { "Totals_TaxPrice", "Totals_TaxPrice" },
                    { "CapitalPeerGroup_MedianTaxRate", "CapitalPeerGroup_MedianTaxRate" },
                };

                //Retrieving base year calculation set
                CalculationSet calculationSet = RedDateBL.GetBaseYearCalculationSet(new DateTime(baseYear, 12, 31));
                var baseYearId = RateBL.GetBaseYearId(baseYear, BaseYearTypeEnum.Tax);

                Dictionary<string, string> providerData = new Dictionary<string, string>();

                //Get CalculationResult table records based on BaseYear and CalculationSetId
                var rateEffectiveDt = ConvertToDateTime(rateEffectiveDate);
                var calculatedData = RateBL.GetBaseYearCalculationResultData(baseYear, rateEffectiveDt,
                    nameof(BaseYearTypeEnum.Tax), (int)calculationSet.Type);

                //Getting the ProviderList from the calculatedData
                var providerNumbers = calculatedData.Select(x => x.ProviderNumber).Distinct().OrderBy(x => x).ToList();

                //Getting median data based on base year
                var medianDataList = RateBL.GetBaseYearInfo(baseYearId);
                //Output file name
                string fileName = string.Format(@"Median Tax Rate Report.xlsx");
                MedianReportData reportData;

                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;
                    IWorkbook workbook = application.Workbooks.Create(1);

                    var worksheet = workbook.Worksheets[0];

                    int rowCount = 1;
                    int column = 1;

                    worksheet.Range[rowCount, column].Text = "Provider Number";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

                    worksheet.Range[rowCount, column].Text = "Provider Name";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 60);
                    column++;

                    worksheet.Range[rowCount, column].Text = "CostReportBeginDate";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

                    worksheet.Range[rowCount, column].Text = "CostReportEndDate";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

                    worksheet.Range[rowCount, column].Text = "Peer Group";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

                    worksheet.Range[rowCount, column].Text = "Bed Days";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

                    worksheet.Range[rowCount, column].Text = "Tax Cost";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;


                    worksheet.Range[rowCount, column].Text = "Tax Per Diem";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

                    worksheet.Range[rowCount, column].Text = "Median";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);

                    foreach (var providerNumber in providerNumbers)
                    {
                        column = 1;
                        //Retrieving the data for specific provider
                        var calculatedProvData = calculatedData.Where(x => x.ProviderNumber == providerNumber).ToList();

                        reportData = new MedianReportData();
                        foreach (var calcData in calculatedProvData)
                        {
                            string keyName = calcData.KeyName;

                            if (fieldsToPrint_Tax.ContainsKey(keyName))
                            {
                                if (keyName == "PeerGroup")
                                {
                                    //Tax 
                                    reportData.CapitalPeerGroup_MedianTaxRate = medianDataList.Where(x =>
                                            x.PeerGroup.StartsWith("Tax_" + calcData.Value)
                                            && x.MedianName == "MedianTaxRate")
                                        .Select(x => x.MedianValue).FirstOrDefault();
                                }

                                switch (keyName)
                                {
                                    case "ProviderNumber":
                                        reportData.ProviderNumber = calcData.Value;
                                        break;
                                    case "ProviderName":
                                        reportData.ProviderName = calcData.Value;
                                        break;
                                    case "CostReportYearBegin":
                                        reportData.CostReportBeginDate = Convert.ToDateTime(calcData.Value);
                                        break;
                                    case "CostReportYearEnd":
                                        reportData.CostReportEndDate = Convert.ToDateTime(calcData.Value);
                                        break;
                                    case "PeerGroup":
                                        reportData.PeerGroup = calcData.Value;
                                        break;
                                    // Tab 4
                                    case "TotalBedDaysAvailable__10440":
                                        reportData.TotalBedDaysAvailable__10440 = calcData.Value;
                                        break;
                                    case "TaxCostSum":
                                        reportData.TaxCostSum = calcData.Value;
                                        break;
                                    case "Totals_TaxPrice":
                                        reportData.Totals_TaxPrice = calcData.Value;
                                        break;
                                }
                            }
                        }

                        rowCount++;
                        worksheet.Range[rowCount, column].Text = reportData.ProviderNumber;
                        column++;

                        worksheet.Range[rowCount, column].Text = reportData.ProviderName;
                        column++;

                        // Tab 4
                        worksheet.Range[rowCount, column].Text = reportData.CostReportBeginDate?.ToShortDateString();
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.CostReportEndDate?.ToShortDateString();
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.PeerGroup;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.TotalBedDaysAvailable__10440; // Bed days
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.TaxCostSum;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.Totals_TaxPrice; // Tax Per Diem
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.CapitalPeerGroup_MedianTaxRate; // Median
                    }

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;
                    string fullPath;

                    fullPath = Path.Combine(Path.GetTempPath(), fileName);
                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                }

                return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message });
            }
        }

