                    worksheet1.Columns[3].NumberFormat = "0.00";
                    worksheet1.Columns[4].NumberFormat = "0.00";

                    worksheet2.Columns[0].NumberFormat = "0000000000";
                    worksheet2.Columns[1].NumberFormat = "0000000";
                    worksheet2.Columns[2].NumberFormat = "00000000000";
                    worksheet2.Columns[3].NumberFormat = "0.00";
                    worksheet2.Columns[4].NumberFormat = "0.00";

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;

                    var fullPath = Path.Combine(Path.GetTempPath(), fileName);

                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                }

                return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message });
            }
        }



