                worksheetTwo.UsedRange.CellStyleName = bodyStyleName;

                worksheetOne.Range["A1:L1"].CellStyleName = headerStyleName;
                worksheetTwo.Range["A1:L1"].CellStyleName = headerStyleName;

                worksheetOne.PageSetup.Orientation = ExcelPageOrientation.Landscape;
                worksheetOne.PageSetup.FitToPagesTall = 0;
                worksheetOne.PageSetup.FitToPagesWide = 1;
                worksheetTwo.PageSetup.Orientation = ExcelPageOrientation.Landscape;
                worksheetTwo.PageSetup.FitToPagesTall = 0;
                worksheetTwo.PageSetup.FitToPagesWide = 1;

                worksheetOne.Range[2, 1].FreezePanes();
                worksheetTwo.Range[2, 1].FreezePanes();

                worksheetOne.Columns[2].HorizontalAlignment = ExcelHAlign.HAlignLeft;
                worksheetTwo.Columns[2].HorizontalAlignment = ExcelHAlign.HAlignLeft;

                worksheetOne.Columns[8].HorizontalAlignment = ExcelHAlign.HAlignRight;
                worksheetOne.Columns[9].HorizontalAlignment = ExcelHAlign.HAlignRight;
                worksheetTwo.Columns[8].HorizontalAlignment = ExcelHAlign.HAlignRight;
                worksheetTwo.Columns[9].HorizontalAlignment = ExcelHAlign.HAlignRight;

                worksheetOne.Columns[1].NumberFormat = "0000000";
                worksheetOne.Columns[8].NumberFormat = "0.00";
                worksheetOne.Columns[9].NumberFormat = "0.00";

                worksheetTwo.Columns[1].NumberFormat = "0000000";
                worksheetTwo.Columns[8].NumberFormat = "0.00";
                worksheetTwo.Columns[9].NumberFormat = "0.00";

                //Save the workbook to stream
                //string contentType = "Application/msexcel";
                MemoryStream outputStream = new MemoryStream();
                workbook.SaveAs(outputStream);
                outputStream.Position = 0;

                workbook.Close();

                //Dispose the ExcelEngine object
                MemoryStream report = outputStream;
                string fullPath;

                fullPath = Path.Combine(Path.GetTempPath(), fileName);
                using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                {
                    report.WriteTo(fileStream);
                }
            }

            return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) },
                JsonRequestBehavior.AllowGet);
        }


        public ActionResult BaseYearsWh0CeilingICFExportExcel(int baseYear, string rateEffectiveDate)
        {
            string fileName = string.Empty;
            if (!DateTime.TryParse(rateEffectiveDate, out DateTime redDate))
            {
                return Json(new
                {
                    Success = false,
                    Message = "Invalid date specified."
                }, JsonRequestBehavior.AllowGet);
            }

            // Get the data for the period specified.
            DataTable data = DatabaseLookupGroupBL.GetDatabaseLookupGroupExport(redDate,
                nameof(AnnualRateSettingEnum.Wh0Ceiling), "Effective Date", redDate.ToString("yyyy-MM-dd"));

            // Add description column
            data.Columns.Add("WH0 Description", typeof(string)).SetOrdinal(4);

            // Get Account Numbers and Descriptions.
            var accounts = ChartOfAccountSeed_OH.LoadChartOfAccounts().Select(a => new { a.AccountNumber, a.Description }).ToList();

            // Populate "WH0 Description" for each row.
            for (int i = 0; i < data.Rows.Count; i++)
            {
                var description = accounts.Where(a => a.AccountNumber == (string)data.Rows[i]["Account Number"]).Select(a => a.Description).FirstOrDefault();
                if (!String.IsNullOrEmpty(description))
                    data.Rows[i]["WH0 Description"] = description.ToUpper();
            }

            fileName = $"CYE {baseYear} WH0 Ceiling Median Report.xlsx";

            using (ExcelEngine excelEngine = new ExcelEngine())
            {
                Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                application.DefaultVersion = ExcelVersion.Xlsx;
                IWorkbook workbook = application.Workbooks.Create(1);

                IWorksheet worksheet = workbook.Worksheets[0];

                worksheet.ImportDataTable(data, true, 1, 1, false);
                worksheet.UsedRange.AutofitColumns();

                //Save the workbook to stream
                MemoryStream outputStream = new MemoryStream();
                workbook.SaveAs(outputStream);
                outputStream.Position = 0;

                workbook.Close();

                //Dispose the ExcelEngine object
                MemoryStream report = outputStream;
                string fullPath;

                fullPath = Path.Combine(Path.GetTempPath(), fileName);
                using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                {
                    report.WriteTo(fileStream);
                }
            }

            return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) },
                JsonRequestBehavior.AllowGet);
        }

        //[ARUMFeatureActionFilter("RateSetting:View")]
        private ActionResult BaseYearsCapitalIcfExportExcel(int baseYear, string rateEffectiveDate)
        {
            try
            {
                Dictionary<string, string> fieldsToPrint_Capital = new Dictionary<string, string>
                {
                    { "ProviderNumber", "Provider Number" },
                    { "NPI", "NPI Number" },
                    { "ProviderName", "Provider Name" },
                    { "PeerGroup", "Peer Group" },
                    { "DocumentNumber", "Document Number" },
                    { "CostReportTypeCode", "CR Type" },
                    { "CostReportYearBegin", "CR From Date" },
                    { "CostReportYearEnd", "CR To Date" },
                    { "TotalRateCapitalPerDiem", "Capital Rate" },
                    { "NewFacilityMedianCapitalRates", "Median Capital Rate" },
                };

                //Retrieving base year calculation set
                CalculationSet calculationSet = RedDateBL.GetBaseYearCalculationSet(new DateTime(baseYear, 12, 31));
                var baseYearId = RateBL.GetBaseYearId(baseYear, BaseYearTypeEnum.CapitalCost);

                var rateEffectiveDt = ConvertToDateTime(rateEffectiveDate);

                //Get CalculationResult table records
                var calculatedData = RateBL.GetBaseYearCalculationResultData(baseYear, rateEffectiveDt,
                    nameof(BaseYearTypeEnum.CapitalCost), (int)calculationSet.Type);
                //Getting the ProviderList from the calculatedData
                var providerNumbers = calculatedData.Select(x => x.ProviderNumber).Distinct().OrderBy(x => x).ToList();

                //Getting median data based on base year
                var medianDataList = RateBL.GetBaseYearInfo(baseYearId);
                //Output file name
                string fileName =
                    string.Format($"Median Capital Rate Report {rateEffectiveDt.ToString("yyyy-MM-dd")}.xlsx");
                MedianReportData reportData;

                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;
                    IWorkbook workbook = application.Workbooks.Create(1);

                    var worksheet = workbook.Worksheets[0];

                    int rowCount = 1;
                    int column = 1;

                    worksheet.Range[rowCount, column].Text = "RED";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

                    worksheet.Range[rowCount, column].Text = "NPI Number";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

                    worksheet.Range[rowCount, column].Text = "Provider Number";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

                    worksheet.Range[rowCount, column].Text = "Provider Name";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 60);
                    column++;

                    worksheet.Range[rowCount, column].Text = "Peer Group";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

                    worksheet.Range[rowCount, column].Text = "Document Number";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

                    worksheet.Range[rowCount, column].Text = "CR Type";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

                    worksheet.Range[rowCount, column].Text = "CR From Date";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

                    worksheet.Range[rowCount, column].Text = "CR To Date";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

                    worksheet.Range[rowCount, column].Text = "CaptialRate";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;

                    worksheet.Range[rowCount, column].Text = "MedianCapitalRate";
                    worksheet.Range[rowCount, column].WrapText = true;
                    worksheet.SetColumnWidth(column, 30);
                    column++;


                    var npis = GetNpiNumbers(providerNumbers);

                    foreach (var providerNumber in providerNumbers)
                    {
                        column = 1;

                        //Retrieving the data for specific provider
                        var calculatedProvData = calculatedData.Where(x => x.ProviderNumber == providerNumber).ToList();

                        reportData = new MedianReportData();
                        foreach (var calcData in calculatedProvData)
                        {
                            string calcKey = calcData.KeyName;
                            var item = calcData.KeyName.Split('_');

                            if (fieldsToPrint_Capital.ContainsKey(calcKey))
                            {
                                if (calcKey == "PeerGroup")
                                {
                                    // Median Capital Rate
                                    reportData.NewFacilityMedianCapitalRates = double.Parse(medianDataList
                                        .FirstOrDefault(x =>
                                            x.PeerGroup == calcData.Value &&
                                            x.MedianName == "NewFacilityMedianCapitalRates").MedianValue);
                                }

                                switch (calcKey)
                                {
                                    case "ProviderNumber":
                                        reportData.ProviderNumber = calcData.Value;
                                        break;
                                    case "ProviderName":
                                        reportData.ProviderName = calcData.Value;
                                        break;
                                    case "PeerGroup":
                                        reportData.PeerGroup = calcData.Value;
                                        break;
                                    case "DocumentNumber":
                                        reportData.DocumentNumber = calcData.Value;
                                        break;
                                    case "CostReportTypeCode":
                                        reportData.CostReportTypeCode = calcData.Value;
                                        break;
                                    case "CostReportYearBegin":
                                        reportData.CostReportBeginDate = Convert.ToDateTime(calcData.Value);
                                        break;
                                    case "CostReportYearEnd":
                                        reportData.CostReportEndDate = Convert.ToDateTime(calcData.Value);
                                        break;
                                    case "TotalRateCapitalPerDiem":
                                        reportData.TotalRateCapitalPerDiem = double.Parse(calcData.Value);
                                        break;
                                    case "NewFacilityMedianCaptialRates":
                                        reportData.NewFacilityMedianCapitalRates = double.Parse(calcData.Value);
                                        break;
                                }
                            }
                        }

                        rowCount++;

                        worksheet.Range[rowCount, column].Text = rateEffectiveDate;
                        column++;
                        worksheet.Range[rowCount, column].Text = npis.TryGetValue(providerNumber, out var npi) ? npi : string.Empty;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.ProviderNumber;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.ProviderName;
                        column++;
                        // Tab 2
                        worksheet.Range[rowCount, column].Text = reportData.PeerGroup;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.DocumentNumber;
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.CostReportTypeCode;
                        column++;
                        worksheet.Range[rowCount, column].Text =
                            reportData.CostReportBeginDate.Value.ToShortDateString();
                        column++;
                        worksheet.Range[rowCount, column].Text = reportData.CostReportEndDate.Value.ToShortDateString();
                        column++;
                        worksheet.Range[rowCount, column].Number = reportData.TotalRateCapitalPerDiem;
                        worksheet.Range[rowCount, column].NumberFormat = "0.00";
                        column++;
                        worksheet.Range[rowCount, column].Number = reportData.NewFacilityMedianCapitalRates;
                        worksheet.Range[rowCount, column].NumberFormat = "0.00";
                        column++;
                    }

                    //Save the workbook to stream
                    MemoryStream outputStream = new MemoryStream();
                    workbook.SaveAs(outputStream);
                    outputStream.Position = 0;

                    workbook.Close();

                    //Dispose the ExcelEngine object
                    MemoryStream report = outputStream;
                    string fullPath;

                    fullPath = Path.Combine(Path.GetTempPath(), fileName);
                    using (FileStream fileStream = new FileStream(fullPath, FileMode.Create))
                    {
                        report.WriteTo(fileStream);
                    }
                }

                return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message });
            }
        }

        private Dictionary<string, string> GetNpiNumbers(List<string> providerNumbers)
        {
            Dictionary<string, string> providers = new Dictionary<string, string>();
            var allProviders = GetAllProviderList(RetrieveSession.Classification.ARUMToken, false, true, false,
                true, false,
                false, true, true, false, "Rate/GetNpiNumbers");

            using (ProjectSpecificDbContext db = new ProjectSpecificDbContext(Functions.DatabaseConnection))
            {
                List<RateProvider> rateProviders =
                    db.RateProviders.Where(p => providerNumbers.Contains(p.ProviderNumber)).ToList();

                foreach (var rateProvider in rateProviders)
                {
                    try
                    {
                        Provider arumProvider =
                            allProviders.lstProviders.FirstOrDefault(x => x.ProviderID == rateProvider.ProviderId);
                        if (arumProvider != null)
                            providers[rateProvider.ProviderNumber] =
                                arumProvider.Identifiers.FirstOrDefault(x => x.Type == "NPI")?.Value ?? string.Empty;
                    }
                    catch (Exception e)
                    {
                        Console.WriteLine(e);
                        throw;
                    }
                }

                return providers;
            }
        }




