        public UsersListViewModel GetCRStaffTable()
        {
            UsersListViewModel usersListViewModel = new UsersListViewModel();
            List<UsersViewModel> listCRStaff = new List<UsersViewModel>();

            var result = RateBL.GetCRStaffTable();

            if (result.Count > 0)
            {
                foreach (var item in result)
                {
                    listCRStaff.Add(new UsersViewModel
                    {
                        UserId = ClientMapping.MapInternalIdToClientId(item.UserId.ToString(), "users"),
                        Mnemonic = item.Mnemonic,
                        FirstName = item.FirstName,
                        LastName = item.LastName,
                        Email = item.Email,
                        PhoneNumber = item.PhoneNumber,
                        ActiveFlag = item.ActiveFlag == true ? "Yes" : "No",
                        LegacyStaffId = item.LegacyStaffId,
                        CreatedBy = item.CreatedBy,
                        CreatedOn = item.CreatedOn.ToString("MM/dd/yyyy")
                    });
                }

                usersListViewModel.Users = listCRStaff;
            }

            usersListViewModel.UserTypes = RateBL.GetUserTypes()
                .Select(x => new SelectItemList { value = x.UserType, text = x.UserType }).ToList();
            return usersListViewModel;
        }

