        #region Rate Setting Quality Points Calculation

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult ProcessQualityPointsCalculation(string qualityPointsId)
        {
            List<RateSettingPackage.ProviderPackage> providers = null;
            List<RateSettingPackage> ratePackages = null;
            List<ProviderQualityCalculation> providerQualityCalculations = null;

            try
            {
                ARUMHandler.ClearCache();

                if (!int.TryParse(ClientMapping.GetInternalIdFromClientId(qualityPointsId, "dblookupgroupyear"),
                        out int id))
                    return Json(new { Success = false, Message = "Unable to find specified quality records." },
                        JsonRequestBehavior.AllowGet);

                DatabaseLookupGroupYear lookupYear = DatabaseLookupGroupBL.GetDatabaseLookupGroupYearById(id);

                using (ProjectSpecificDbContext db = new ProjectSpecificDbContext(Functions.DatabaseConnection))
                {
                    // Date this quality points calculation is usable by rates
                    DateTime redDate = lookupYear.LookUpDate;

                    // Get cost report data for the proper period year.
                    int costReportPeriodYear = lookupYear.LookUpDate.Month >= 7
                        ? lookupYear.LookUpDate.Year -
                          1 // If the effective date month is 7 or higher, it will be previous year.
                        : lookupYear.LookUpDate.Year -
                          2; // If the effective date month is less than 7, it will be two years back.

                    // Cost reports submitted after this date cannot be used
                    // for this base year processing.
                    DateTime cutoffDate = new DateTime(costReportPeriodYear, 10, 1);

                    providers = GetActiveProviders(cutoffDate);

                    // Get all the information from the database.
                    ratePackages = RateBL.GetQualityPointData(costReportPeriodYear); //cleared and 4.1
                    if (ratePackages.Count == 0)
                        throw new Exception("There are no Rate Packages for this RED.");

                    // Get the effective dates for each rate pacakge
                    for (int i = ratePackages.Count - 1; i >= 0; i--)
                    {
                        RateSettingPackage package = ratePackages[i];
                        RateSettingPackage.ProviderPackage provider =
                            providers.FirstOrDefault(x => x.ProviderId == package.Provider.ProviderId);
                        if (provider == null)
                        {
                            // Ensure that we only have active providers as of the RED.
                            ratePackages.Remove(package);
                            continue;
                        }

                        package.Provider.EffectiveDates = provider.EffectiveDates;
                    }

                    string ret =
                        ProcessQualityPointsCalculation(costReportPeriodYear, lookupYear, providers, ratePackages);

                    db.Dispose();
                }

                return Json(new
                {
                    Success = true
                }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message });
            }
            finally
            {
                if (providers != null)
                {
                    providers.ForEach(x => x.Dispose());
                    providers.Clear();
                }

                if (ratePackages != null)
                {
                    ratePackages.ForEach(x => x.Dispose());
                    ratePackages.Clear();
                }

                if (providerQualityCalculations != null) providerQualityCalculations.Clear();
            }
        }

        /// <summary>
        /// This will set the Base Year to TRUE for the specified RED.
        /// </summary>
        /// <param name = "year" ></ param >
        /// < param name="lookupYear"></param>
        /// <param name = "ratePackages" ></ param >
        /// <returns></returns>
        /// <exception cref = "Exception" ></ exception >
        private string ProcessQualityPointsCalculation(int year, DatabaseLookupGroupYear lookupYear,
            List<RateSettingPackage.ProviderPackage> providers, List<RateSettingPackage> ratePackages)
        {
            ARUMHandler.ClearCache();
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
            string username = $"{myUser.FirstName} {myUser.LastName}";

            List<RexVersionDateRange> ranges =
                RexRequestHelper.ParseInRuleAppVersionRanges(OHFISession.StandardRateSettingInRuleAppVersions);
            DateTime redDate = lookupYear.LookUpDate;
            RexVersionDateRange selectedVersion =
                ranges.FirstOrDefault(x => x.DateFrom <= redDate && x.DateTo >= redDate);
            if (selectedVersion == null) selectedVersion = ranges.OrderBy(x => x.DateTo).LastOrDefault();
            if (selectedVersion == null)
                throw new Exception("Unable to select InRule rule set version. Please check ARUM settings.");
            ranges.Clear();

            List<ProviderRateResponse> responses = new List<ProviderRateResponse>();

            //We need to handle the numbers for the rate packages.Since we may have real and fake ones in
            //the array, but we use the Ids for reference, we need to ensure that the Ids are unique.
            string sJsonSubmission,
                sResponse,
                logDate = lookupYear.LookUpDate.ToString("yyyyMMdd");

            ratePackages = RateBL.VerifyRateCostReportsForRatePackages(ratePackages, username);

            try
            {
                switch (SimplifiedType)
                {
                    //case "NF":
                    //    sJsonSubmission = QualityCaclulationSubmissionNF(year, qualityCalculation, ratePackages, providerQualityCalculations);

                    //    if (string.IsNullOrWhiteSpace(sJsonSubmission)) return "No cost report data found for Base Year operation.";

                    //    if (internalLogging) System.IO.File.WriteAllText(Path.Combine(Path.GetTempPath(), $"test.NF_QualityIncentive_Calculation.v{selectedVersion.Version}.listing.{logDate}.json"), sJsonSubmission);

                    //    sResponse = SubmitInRuleData(OHFISession.BaseYearInRuleApp, selectedVersion.Version,
                    //            "NF_QualityIncentive_Calculation", sJsonSubmission, logDate);

                    //    if (internalLogging) System.IO.File.WriteAllText(Path.Combine(Path.GetTempPath(), $"test.NF_QualityIncentive_Calculation.v{selectedVersion.Version}.response.{logDate}.json"), sResponse);

                    //    // Save results back down to database records.
                    //    jsonRootNF = System.Text.Json.JsonSerializer.Deserialize<BL.JsonObjects.JsonInRuleResponseBaseYearNF.JsonInRuleBaseYearResponseNfRoot2023>(sResponse);

                    //    RateBL.SaveNfQualityCalculation(qualityCalculation, jsonRootNF, username);
                    //    break;

                    case "ICF":
                        sJsonSubmission = QualityCaclulationSubmissionICF(year, lookupYear, providers, ratePackages);

                        if (string.IsNullOrWhiteSpace(sJsonSubmission))
                            return "No cost report data found for Quality Calculation operation.";

#if DEBUG
                        System.IO.File.WriteAllText(
                            Path.Combine(Path.GetTempPath(),
                                $"test.ICF_QualityIncentive_Calculation.v{selectedVersion.Version}.listing.{logDate}.json"),
                            sJsonSubmission);
#endif

                        sResponse = SubmitInRuleData(OHFISession.StandardRateSettingInRuleApp, selectedVersion.Version,
                            "ICF_QualityIncentive_Calculation", sJsonSubmission, logDate);

#if DEBUG
                        System.IO.File.WriteAllText(
                            Path.Combine(Path.GetTempPath(),
                                $"test.ICF_QualityIncentive_Calculation.v{selectedVersion.Version}.response.{logDate}.json"),
                            sResponse);
#endif

                        // Save results back down to database records.
                        IJsonInRuleRateSettingResponseICF jsonRootIcf =
                            JsonVersioningBL.DeserializeIcfRateSettingResponse(sResponse, redDate);

                        // Now that we have data to save, remove the old data.
                        DatabaseLookupGroupBL.ClearDatabaseLookupGroupYearCalculationData(lookupYear);

                        RateBL.SaveIcfQualityPointsCalculation(lookupYear, jsonRootIcf, username);
                        break;

                    default:
                        return "Provider type does not support Quality Points Calculation operation.";
                }

                return $"Quality Points Calculation information for {redDate.ToString("MM/dd/yyyy")} is set.";
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                throw;
            }
            finally
            {
                sJsonSubmission = string.Empty;
                sResponse = string.Empty;
            }
        }

