        private string ProcessQualityCalculations(QualityCalculation qualityCalculation,
            AnnualRateSettingEnum annualRateSettingEnum)
        {
            List<RateSettingPackage.ProviderPackage> providers = null;
            List<RateSettingPackage> ratePackages = null;
            List<ProviderQualityCalculation> providerQualityCalculations = null;
            List<MSLC.ProviderProxy.Interfaces.Models.ChowReview> chows = null;

            try
            {
                // Date this quality calculation is usable by rates
                DateTime redDate = qualityCalculation.EffectiveDate;

                // Get cost report data for the proper period year.
                int costReportPeriodYear = qualityCalculation.EffectiveDate.Month >= 7
                    ? qualityCalculation.EffectiveDate.Year -
                      1 // If the effective date month is 7 or higher, it will be previous year.
                    : qualityCalculation.EffectiveDate.Year -
                      2; // If the effective date month is less than 7, it will be two years back.

                // Cost reports submitted after this date cannot be used
                // for this base year processing.
                DateTime cutoffDate = DatabaseLookupGroupBL.GetDatabaseLookupCostReportCutoff(redDate);

                switch (annualRateSettingEnum)
                {
                    case AnnualRateSettingEnum.QualityCalcPeerGroup:
                        // Base providers off of cutoff date
                        providers = GetActiveProviders(cutoffDate);

                        // Get all the information from the database.
                        ratePackages = RateBL.GetRateSettingData(redDate, SimplifiedType);
                        if (ratePackages.Count == 0)
                            throw new Exception("There are no Rate Packages for this RED.");

                        // Ensure that we only have active providers as of the RED.
                        ratePackages = ratePackages
                            .Where(x => providers.Any(p => p.ProviderId == x.Provider.ProviderId)).ToList();

                        List<RateSettingPackage.ProviderPackage> providerList = providers
                            .Where(x => ratePackages.Any(p => p.Provider.ProviderId == x.ProviderId)).ToList();

                        chows = new List<MSLC.ProviderProxy.Interfaces.Models.ChowReview>();
                        foreach (var package in ratePackages)
                        {
                            // If this package is a CHOP rate, then we need to get the service call for the CHOP information.
                            if (package.RateTypeId == (int)RateTypeEnumExtended.CHOP)
                            {
                                MSLC.ProviderProxy.Interfaces.IArumChowReviewChain arum_CHOP =
                                    _providerServiceProxy.GetChowReviewChainByNewProviderID(
                                        RetrieveSession.Classification.ARUMToken, package.Provider.ProviderId,
                                        "Rate/Provider");
                                // Ensure, if there is CHOP data, that this is after the cost report end date - which would make this the "first" time the provider is rated, even if it is chopped later in the year.
                                MSLC.ProviderProxy.Interfaces.Models.ChowReview anyChopsBeforePeriodEnd = arum_CHOP
                                    .ChowReviews
                                    .Where(x => x.ApproveDate.Value <= redDate)
                                    .OrderByDescending(x => x.ApproveDate)
                                    .FirstOrDefault();
                                if (anyChopsBeforePeriodEnd != null) chows.Add(anyChopsBeforePeriodEnd);
                            }

                            package.Provider.EffectiveDates = providerList
                                .FirstOrDefault(x => x.ProviderId == package.Provider.ProviderId)
                                .EffectiveDates;
                        }

                        break;

                    case AnnualRateSettingEnum.AnnualMedianCaseMixCalculation:
                        // This will get all providers regardless of termination below.
                        break;
                }

                //reset providers to that all are available
                providers = GetActiveProviders();

                providerQualityCalculations =
                    DatabaseLookupGroupBL.GetProviderQualityCalculations(qualityCalculation.QualityCalculationId);

                string ret = string.Empty;

                if (annualRateSettingEnum == AnnualRateSettingEnum.AnnualMedianCaseMixCalculation)
                {
                    ret = ProcessAnnualCMICalculations(costReportPeriodYear, qualityCalculation, providers);
                }
                else if (annualRateSettingEnum == AnnualRateSettingEnum.QualityCalcPeerGroup)
                {
                    List<ProviderList> providerLists = GetAllTypeActiveProviders(providers, null);
                    ret = ProcessQualityCalculations(costReportPeriodYear, qualityCalculation, providers, ratePackages,
                        providerQualityCalculations, chows, providerLists);
                }

                return ret;
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                throw;
            }
            finally
            {
                if (providers != null)
                {
                    providers.ForEach(x => x.Dispose());
                    providers.Clear();
                }

                if (ratePackages != null)
                {
                    ratePackages.ForEach(x => x.Dispose());
                    ratePackages.Clear();
                }

                if (providerQualityCalculations != null) providerQualityCalculations.Clear();
            }
        }

        private string ProcessAnnualCMICalculations(int year, QualityCalculation qualityCalculation,
            List<RateSettingPackage.ProviderPackage> providers)
        {
            ARUMHandler.ClearCache();
            MSLC.ArumProxy.Models.ARUMProxy_User myUser = RetrieveSession.ARUMUser;
            string username = $"{myUser.FirstName} {myUser.LastName}";

            List<RexVersionDateRange> ranges =
                RexRequestHelper.ParseInRuleAppVersionRanges(OHFISession.BaseYearInRuleAppVersions);
            DateTime redDate = qualityCalculation.EffectiveDate;
            RexVersionDateRange selectedVersion =
                ranges.FirstOrDefault(x => x.DateFrom <= redDate && x.DateTo >= redDate);
            if (selectedVersion == null) selectedVersion = ranges.OrderBy(x => x.DateTo).LastOrDefault();
            if (selectedVersion == null)
                throw new Exception("Unable to select InRule rule set version. Please check ARUM settings.");
            ranges.Clear();

            List<ProviderRateResponse> responses = new List<ProviderRateResponse>();

            // We need to handle the numbers for the rate packages. Since we may have real and fake ones in
            // the array, but we use the Ids for reference, we need to ensure that the Ids are unique.
            string sJsonSubmission,
                sResponse,
                logDate = qualityCalculation.EffectiveDate.ToString("yyyyMMdd");
            BL.JsonObjects.NF.IJsonInRuleCMIResponseNF jsonRootNF = null;

            try
            {
                switch (SimplifiedType)
                {
                    case "NF":
                        sJsonSubmission = AnnualCmiSubmissionNF(year, qualityCalculation, providers);

                        if (string.IsNullOrWhiteSpace(sJsonSubmission))
                            return "No cost report data found for Annual CMI operation.";

#if DEBUG
                        System.IO.File.WriteAllText(
                            Path.Combine(Path.GetTempPath(),
                                $"test.NF_CMI_Calculation.v{selectedVersion.Version}.listing.{logDate}.json"),
                            sJsonSubmission);
#endif

                        sResponse = SubmitInRuleData(OHFISession.BaseYearInRuleApp, selectedVersion.Version,
                            "NF_CMI_Calculation", sJsonSubmission, logDate);

#if DEBUG
                        System.IO.File.WriteAllText(
                            Path.Combine(Path.GetTempPath(),
                                $"test.NF_CMI_Calculation.v{selectedVersion.Version}.response.{logDate}.json"),
                            sResponse);
#endif

                        // Save results back down to database records.
                        jsonRootNF = JsonVersioningBL.DeserializeNfCMIResponse(sResponse, redDate);

                        // Now that we have data to save, we can delete old data.
                        RateBL.DeleteQualityCalculationData(qualityCalculation);

                        RateBL.SaveNfAnnualCMICalculation(qualityCalculation, jsonRootNF, username);
                        break;

                    //case "ICF":
                    //    sJsonSubmission = QualityCaclulationSubmissionICF(year, qualityCalculation, ratePackages, providerQualityCalculations);

                    //    if (string.IsNullOrWhiteSpace(sJsonSubmission)) return "No cost report data found for Base Year operation.";

                    //    if (internalLogging) System.IO.File.WriteAllText(Path.Combine(Path.GetTempPath(), $"test.ICF_QualityIncentive_Calculation.v{selectedVersion.Version}.listing.{logDate}.json"), sJsonSubmission);

                    //    sResponse = SubmitInRuleData(OHFISession.BaseYearInRuleApp, selectedVersion.Version,
                    //            "NF_QualityIncentive_Calculation", sJsonSubmission, logDate);

                    //    if (internalLogging) System.IO.File.WriteAllText(Path.Combine(Path.GetTempPath(), $"test.ICF_QualityIncentive_Calculation.v{selectedVersion.Version}.response.{logDate}.json"), sResponse);

                    //    // Save results back down to database records.
                    //    jsonRootICF = System.Text.Json.JsonSerializer.Deserialize<BL.JsonObjects.JsonInRuleResponseBaseYearICF.JsonInRuleResponseBaseYearIcfRoot2023>(sResponse);

                    //    RateBL.SaveIcfQualityCalculation(qualityCalculation, jsonRootICF, username);
                    //    break;

                    default:
                        return "Provider type does not support Base Year operation.";
                }

                return $"Base Year information for {redDate.ToString("MM/dd/yyyy")} is set.";
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                throw;
            }
            finally
            {
                sJsonSubmission = string.Empty;
                sResponse = string.Empty;
                jsonRootNF?.Dispose();
            }
        }

