        #region Process Occupancy Percentage for LOA Rate Calculation

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult ProcessLOAOccupancyRate(string occupancyPercentageLOARateId,
            AnnualRateSettingEnum annualRateSettingEnum)
        {
            //List<RateSettingPackage.ProviderPackage> providers = null;
            //List<RateSettingPackage> ratePackages = null;

            List<RateSettingPackage.ProviderPackage> providers = null;
            List<RateSettingPackage> ratePackages = null;
            //List<ProviderQualityCalculation> providerQualityCalculations = null;
            List<MSLC.ProviderProxy.Interfaces.Models.ChowReview> chows = null;

            try
            {
                ARUMHandler.ClearCache();

                if (!int.TryParse(
                        ClientMapping.GetInternalIdFromClientId(occupancyPercentageLOARateId, "dblookupgroupyear"),
                        out int id))
                    return Json(new { Success = false, Message = "Unable to find specified quality records." },
                        JsonRequestBehavior.AllowGet);

                DatabaseLookupGroupYear lookupYear = DatabaseLookupGroupBL.GetDatabaseLookupGroupYearById(id);

                using (ProjectSpecificDbContext db = new ProjectSpecificDbContext(Functions.DatabaseConnection))
                {
                    // Date this quality points calculation is usable by rates
                    DateTime redDate = lookupYear.LookUpDate;

                    // Get cost report data for the proper period year.
                    int costReportPeriodYear = lookupYear.LookUpDate.Month >= 7
                        ? lookupYear.LookUpDate.Year -
                          1 // If the effective date month is 7 or higher, it will be previous year.
                        : lookupYear.LookUpDate.Year -
                          2; // If the effective date month is less than 7, it will be two years back.

                    // Cost reports submitted after this date cannot be used
                    // for this base year processing.
                    DateTime cutoffDate = new DateTime(costReportPeriodYear, 12, 31);

                    // Base providers off of cutoff date
                    providers = GetActiveProviders(cutoffDate);

                    // Get all the information from the database.
                    ratePackages = RateBL.GetLOAOccupancyRateData(db, costReportPeriodYear); //cleared and 4.1

                    if (ratePackages.Count == 0)
                        throw new Exception("There are no Rate Packages for this RED.");

                    // Ensure that we only have active providers as of the RED.
                    ratePackages = ratePackages.Where(x => providers.Any(p => p.ProviderId == x.Provider.ProviderId))
                        .ToList();

                    List<RateSettingPackage.ProviderPackage> providerList = providers
                        .Where(x => ratePackages.Any(p => p.Provider.ProviderId == x.ProviderId)).ToList();

                    chows = new List<MSLC.ProviderProxy.Interfaces.Models.ChowReview>();
                    foreach (var package in ratePackages)
                    {
                        // If this package is a CHOP rate, then we need to get the service call for the CHOP information.
                        if (package.RateTypeId == (int)RateTypeEnumExtended.CHOP)
                        {
                            MSLC.ProviderProxy.Interfaces.IArumChowReviewChain arum_CHOP =
                                _providerServiceProxy.GetChowReviewChainByNewProviderID(
                                    RetrieveSession.Classification.ARUMToken, package.Provider.ProviderId,
                                    "Rate/Provider");
                            // Ensure, if there is CHOP data, that this is after the cost report end date - which would make this the "first" time the provider is rated, even if it is chopped later in the year.
                            MSLC.ProviderProxy.Interfaces.Models.ChowReview anyChopsBeforePeriodEnd = arum_CHOP
                                .ChowReviews
                                .Where(x => x.ApproveDate.Value <= redDate)
                                .OrderByDescending(x => x.ApproveDate)
                                .FirstOrDefault();
                            if (anyChopsBeforePeriodEnd != null) chows.Add(anyChopsBeforePeriodEnd);
                        }

                        package.Provider.EffectiveDates = providerList
                            .FirstOrDefault(x => x.ProviderId == package.Provider.ProviderId)
                            .EffectiveDates;
                    }

                    //reset providers list to get all providers, even terminated ones
                    providers = GetActiveProviders();

                    string ret = ProcessLOAOccupancyRateCalculation(costReportPeriodYear, lookupYear, providers,
                        ratePackages, chows);
                    db.Dispose();
                }

                return Json(new
                {
                    Success = true
                }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message });
            }
            finally
            {
                if (providers != null)
                {
                    providers.ForEach(x => x.Dispose());
                    providers.Clear();
                }

                if (ratePackages != null)
                {
                    ratePackages.ForEach(x => x.Dispose());
                    ratePackages.Clear();
                }
            }
        }

