#if DEBUG
                        System.IO.File.WriteAllText(
                            Path.Combine(Path.GetTempPath(),
                                $"test.NF_LOACR_Occupancy.v{selectedVersion.Version}.response.{logDate}.json"),
                            sResponse);
#endif

                        // Save results back down to database records.
                        jsonRootNF = JsonVersioningBL.DeserializeNfBaseYearResponse(sResponse, redDate);

                        RateBL.SaveNFLOAOccupancyRateCalculation(lookupYear, jsonRootNF, username);
                        break;

                    //case "ICF":
                    //sJsonSubmission = LOAOccupancyRateCaclulationSubmissionICF(year, lookupYear, providers, ratePackages, chows);

                    //if (string.IsNullOrWhiteSpace(sJsonSubmission)) return "No cost report data found for Occupancy Percentage LOA Rate operation.";

                    //if (internalLogging) System.IO.File.WriteAllText(Path.Combine(Path.GetTempPath(), $"test.ICF_LOACR_Occupancy.v{selectedVersion.Version}.listing.{logDate}.json"), sJsonSubmission);

                    //sResponse = SubmitInRuleData(OHFISession.BaseYearInRuleApp, selectedVersion.Version,
                    //        "ICF_LOACR_Occupancy", sJsonSubmission, logDate);

                    //if (internalLogging) System.IO.File.WriteAllText(Path.Combine(Path.GetTempPath(), $"test.ICF_LOACR_Occupancy.v{selectedVersion.Version}.response.{logDate}.json"), sResponse);

                    //// Save results back down to database records.
                    //jsonRootICF = JsonVersioningBL.DeserializeNfBaseYearResponse(sResponse, redDate);

                    //// Now that we have data to save, remove the old data.
                    //RateBL.ClearLOAOccupancyRateCalculationData(lookupYear);

                    //RateBL.SaveICFLOAOccupancyRateCalculation(lookupYear, jsonRootICF, username);
                    //break;

                    default:
                        return "Provider type does not support Base Year operation.";
                }

                return
                    $"Occupancy Percentage LOA Rate Calculation information for {redDate.ToString("MM/dd/yyyy")} is set.";
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                throw;
            }
        }

        private string LOAOccupancyRateCaclulationSubmissionNF(int year, DatabaseLookupGroupYear lookupYear,
            List<RateSettingPackage.ProviderPackage> providers, List<RateSettingPackage> ratePackages,
            List<MSLC.ProviderProxy.Interfaces.Models.ChowReview> chows, List<ProviderList> providerLists)
        {
            // This is possible because the submission ratePackage for Quality Calculation is identical to Rate Setting
            // NOTE: We DO NOT want to suppress quality calculations - this is the whole point of this call!
            var nfProviders = providerLists.FirstOrDefault(x => x.Type == "NF").Providers;
            return RateBL.RateSettingSubmissionNF(year, lookupYear.LookUpDate, providers, ratePackages,
                new List<ProviderQualityCalculation>(), chows, RateSettingOperations.QUALITYCALC, nfProviders);
        }

