        #region SpecialFocusFacilities

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public ActionResult SpecialFocusFacilities()
        {
            DatabaseLookupViewModel lookupViewModel = new DatabaseLookupViewModel();
            Dictionary<int, DateTime> dates =
                DatabaseLookupVariableBL.GetLookupSelectListDictionary(AnnualRateSettingEnum.SpecialFocusFacilities);
            var ItemList = new List<SelectListItem>();
            foreach (int key in dates.Keys)
            {
                if (dates.TryGetValue(key, out DateTime date))
                {
                    ItemList.Add(new SelectListItem
                    {
                        Text = date.Year.ToString(),
                        Value = ClientMapping.MapInternalIdToClientId(key.ToString(), "dblookup"),
                    });
                }
            }

            lookupViewModel.RedDateList = ItemList;
            lookupViewModel.AnnualRateSettingEnum = nameof(AnnualRateSettingEnum.SpecialFocusFacilities);

            lookupViewModel.HeaderText = AnnualRateSettingEnum.SpecialFocusFacilities.GetDescription();
            lookupViewModel.DateText = AnnualRateSettingEnum.SpecialFocusFacilities.GetDateType().GetDateMnemonic();

            return PartialView("AnnualRateSetting/_SpecialFocusFacilities", lookupViewModel);
        }

        [ARUMFeatureActionFilter(RateSettingPermissions.AnnualRateSettingEdit)]
        public JsonResult ExportSpecialFocusFacilities(string fiscalYear, AnnualRateSettingEnum annualRateSettingEnum)
        {
            try
            {
                DateTime dateTime = RateSettingLookupDateType.GetLookupDateByType(annualRateSettingEnum, fiscalYear);

                // Default column name for group data is FYE (basically calendar year end)
                string dateColumnName = RateSettingLookupDateType.GetLookupDateTypeString(annualRateSettingEnum);

                string fullPath = "";
                string dateType = RateSettingLookupDateType.GetLookupDateTypeString(annualRateSettingEnum);
                string fileName = $"{dateType}{dateTime.Year}_{annualRateSettingEnum.ToString()}Report.xlsx";
                using (ExcelEngine excelEngine = new ExcelEngine())
                {
                    //Save the file to the path of the current user's temporary folder
                    fullPath = Path.Combine(Path.GetTempPath(), fileName);
                    //Instantiate the excel application object.
                    Syncfusion.XlsIO.IApplication application = excelEngine.Excel;
                    application.DefaultVersion = ExcelVersion.Xlsx;

                    //The workbook is created
                    IWorkbook workbook = application.Workbooks.Create(1);

                    //The first worksheet object in the worksheets collection is accessed
                    IWorksheet worksheet = workbook.Worksheets[0];

                    // Import Data
                    DataTable dataTable = GenerateDataTableForReport(fiscalYear, annualRateSettingEnum);

                    var row = 1;
                    var column = 1;
                    var dataCol = 0;
                    var dataColumns = dataTable.Columns;
                    foreach (DataRow rowData in dataTable.Rows)
                    {
                        if (row == 1)
                        {
                            foreach (var heading in dataColumns)
                            {
                                // headings. do not include column 0 (Variable)
                                if (dataCol == 0)
                                {
                                    worksheet.Range[row, column++].Text = dateColumnName; // Date
                                    dataCol++;

                                    continue;
                                }

                                worksheet.Range[row, column++].Text = dataColumns[dataCol++].Caption; // Provider
                            }

                            row++;
                        }

                        dataCol = 0;
                        column = 1;
                        worksheet.Range[row, column++].Number =
                            ConvertToDouble(rowData[dataColumns[dataCol++]].ToString()); // Date
                        worksheet.Range[row, column++].Text = rowData[dataColumns[dataCol++]].ToString(); // Provider

                        row++;
                    }

                    worksheet.Columns[0].NumberFormat = "0000"; // Date
                    worksheet.Columns[1].NumberFormat = "0000000"; // Provider Number
                    worksheet.Columns[1].HorizontalAlignment = ExcelHAlign.HAlignRight;


                    //Saving the workbook as stream
                    FileStream file = new FileStream(fullPath, FileMode.Create, FileAccess.ReadWrite);
                    worksheet.UsedRange.AutofitColumns();

                    worksheet.PageSetup.FitToPagesTall = 0;
                    worksheet.PageSetup.FitToPagesWide = 1;
                    worksheet.PageSetup.Orientation = ExcelPageOrientation.Landscape;


                    workbook.SaveAs(file);
                    file.Dispose();
                }

                return Json(new { Success = true, fileName = HttpUtility.UrlEncode(fileName) },
                    JsonRequestBehavior.AllowGet);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                return Json(new { Success = false, Message = e.Message }, JsonRequestBehavior.AllowGet);
            }
        }

        #endregion

        #region Utility Methods

        #region Common methods for Zip, Delete, Download

        private string ZipFiles(List<string> fileList, string zipFileName)
        {
            try
            {
                DateTime currDate = DateTime.Now;

                if (fileList.Count > 0)
                {
                    List<FileStream> fileStreams = new List<FileStream>();
                    using (MemoryStream stream = new MemoryStream())
                    {
                        ZipArchive zipArchive = new ZipArchive();
                        zipArchive.DefaultCompressionLevel = Syncfusion.Compression.CompressionLevel.Best;
                        foreach (string fileName in fileList)
                        {
                            //Get the file path of the current user's temporary folder
                            string fullPath = Path.Combine(Path.GetTempPath(), fileName);

                            FileStream outputStream = new FileStream(fullPath, FileMode.Open, FileAccess.ReadWrite);
                            zipArchive.AddItem(fileName, outputStream, false,
                                Syncfusion.Compression.FileAttributes.Normal);
                            fileStreams.Add(outputStream);
                        }

                        // Save files to stream.
                        string zipFilePath = Path.Combine(Path.GetTempPath(), zipFileName);
                        zipArchive.Save(stream, false);

                        //Create Zip file
                        System.IO.File.WriteAllBytes(zipFilePath, stream.ToArray());
                        zipArchive.Close();
                        stream.Close();
                        fileStreams.ForEach(x => x.Close()); //If any of the file streams are closed before zip is saved, it will throw exception
                    }
                }

                return zipFileName;
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                throw;
            }
        }

        private void DeleteFiles(List<string> fileList)
        {
            try
            {
                if (fileList.Count > 0)
                {
                    foreach (string fileName in fileList)
                    {
                        //Get the file path of the current user's temporary folder
                        string fullPath = Path.Combine(Path.GetTempPath(), fileName);

                        System.GC.Collect();
                        System.GC.WaitForPendingFinalizers();
                        //Delete the file
                        System.IO.File.Delete(fullPath);
                    }
                }
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);
                throw;
            }
        }

        [ARUMFeatureActionFilter("RateSetting:View")]
        public ActionResult Download(string fileName)
        {
            try
            {
                //Get the file path of the current user's temporary folder
                string fullPath = Path.Combine(Path.GetTempPath(), Path.GetFileName(fileName));
                byte[] fileByteArray = System.IO.File.ReadAllBytes(fullPath);
                System.IO.File.Delete(fullPath);
                //Get  the file extension to determine download MIME Type
                string extn = Path.GetExtension(fileName);
                string fileMIMEType = "";
                if (extn.Equals(".xlsx"))
                {
                    fileMIMEType = "application/vnd.ms-excel";
                }
                else if (extn.Equals(".txt"))
                {
                    fileMIMEType = "text/plain";
                }
                else if (extn.Equals(".zip"))
                {
                    fileMIMEType = "application/zip";
                }
                else if (extn.Equals(".csv"))
                {
                    fileMIMEType = "text/csv";
                }
                else if (extn.Equals(".pdf"))
                {
                    fileMIMEType = "application/pdf";
                }

                // Inherit Request Origin Header to allow Barracuda proxy.
                string originHeader = Request.Headers.Get("Access-Control-Allow-Origin");
                if (!string.IsNullOrWhiteSpace(originHeader))
                {
                    Response.Headers.Add("Access-Control-Allow-Origin", originHeader);
                }

                return File(fileByteArray, fileMIMEType, fileName);
            }
            catch (Exception e)
            {
                _logger.Error(e, e.Message);

                throw;
            }
        }

		#endregion

		public string GetChartOfAccountNumber(string name, List<ChartOfAccount> accounts)
		{
			var acctNum = accounts.Where(x => x.Description == name).Select(x => x.AccountNumber).FirstOrDefault();
            return acctNum != null ? acctNum : string.Empty;
		}

		public string GetDescriptionLong(string name, List<ChartOfAccount> accounts)
		{
			var accountNumbers = accounts.Select(x => x.AccountNumber).ToList();
			return accountNumbers.Contains(name) ? accounts.FirstOrDefault(x => x.AccountNumber == name)?.Description : name;
		}

		private string GenerateExcelFileName(AnnualRateSettingEnum annualRateSettingEnum, DateTime time)
        {
            string dateType = RateSettingLookupDateType.GetLookupDateTypeString(annualRateSettingEnum);
            string reportType = annualRateSettingEnum.GetDescription().Replace(" ", "");
            string report = string.Empty;
            switch (annualRateSettingEnum)
            {
                case AnnualRateSettingEnum.AnnualCaseMixScores:
                case AnnualRateSettingEnum.QuarterlyCaseMixScoresSFY:
                    break;
                default:
                    report = "Report";
                    break;
            }

            return $"{dateType}{time.Year}_{reportType}{report}.xlsx".ToSafeFileName();
        }

        private void AppendRateResponseMessage(ProviderRateResponseViewModel response, string message)
        {
            response.Message = AppendRateResponseMessage(response.Message, message);
        }

        private string AppendRateResponseMessage(string message, string newText)
        {
            if (!string.IsNullOrEmpty(message) && message.Contains(newText)) return message;
            return $"{newText} {message}";
        }

        private bool IsRatePackageFinalized(ProviderRatePackage ratePackage)
        {
            return
                ratePackage.Issuance
                    .HasValue && // The issuance date has a value - the locked date for the rate. **AND**
                (
                    !string.IsNullOrWhiteSpace(ratePackage.FinalRateAmount) && // There is a final amount value **AND**
                    (
                        decimal.Parse(ratePackage.FinalRateAmount) > 0 || // That value is more than 0 **OR**
                        !string.IsNullOrWhiteSpace(ratePackage
                            .Messages) // There is a message; rate may be have been locked at 0 until it is fixed.
                    )
                );
        }

        /// <summary>
        /// Values need to be 4 decimals after the period. So if the last digit is a 0 it may get dropped in the CSV file and needs to be populated
        /// </summary>
        /// <param name="value"></param>
        /// <returns></returns>
        public string PopulateDecimalValue(string value)
        {
            if (decimal.TryParse(value.Replace("$", "").Replace(",", ""), out decimal number))
                return number.ToString("0.0000");
            else
                return "0.0000";
        }

        public string PopulateCurrencyValue(string value)
        {
            if (decimal.TryParse(value.Replace("$", "").Replace(",", ""), out decimal number))
                return number.ToString("0.00");
            else
                return "0.00";
        }

        public double ConvertToDouble(string reportData)
        {
            if (string.IsNullOrWhiteSpace(reportData))
                return 0.0;
            var goodValue = Double.TryParse(reportData, out double doubleData);
            if (goodValue)
                return doubleData;
            else
                return 0.0;
        }

        public int ConvertToInteger(string reportData)
        {
            if (string.IsNullOrWhiteSpace(reportData))
                return 0;
            else
            {
                var goodValue = int.TryParse(reportData, out int integerData);
                if (goodValue)
                    return integerData;
                else
                    return 0;
            }
        }

        protected DateTime ConvertToDateTime(string reportData)
        {
            if (!DateTime.TryParse(reportData, out DateTime date))
                date = DateTime.MinValue;
            return date;
        }

        public string GetConditional(int reqValue)
        {
            string conditional = string.Empty;
            switch (reqValue)
            {
                case 1:
                    conditional = "R";
                    break;
                case 2:
                    conditional = "O";
                    break;
                case 3:
                    conditional = "C";
                    break;
                default:
                    conditional = "N/A";
                    break;
            }

            return conditional;
        }

        #endregion
    }

